module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
    reg [7:0] counter;
    reg tick_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 8'b0;
            tick_reg <= 1'b0;
        end else begin
            if (counter == div - 1) begin
                counter <= 8'b0;
                tick_reg <= ~tick_reg;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign tick = tick_reg;
endmodule

