module alu(
    input var [32:0]in_a,
    input var [32:0]in_b,
    input var [4:0]alu_op,

    output [31:0]rd_val_out,
    output lt,
    output ltu,
    output eq
    );

    wire [32:0] in_b_twos_complement;
    wire [32:0] result;
    wire [32:0] in_a_and_b;
    wire [32:0] in_a_or_b;
    wire [32:0] in_a_xor_b;
    wire [32:0] in_a_plus_in_b;
    wire [32:0] in_a_minus_in_b;
    wire [32:0] in_a_lui;

    // Convert in_b to two's complement if it's a signed operation
    assign in_b_twos_complement = (alu_op == 5'b00001 || alu_op == 5'b00010) ? ~in_b + 1 : in_b;

    // Perform the selected operation
    always_comb begin
        case (alu_op)
            5'b00000: result = in_a_plus_in_b; // Addition
            5'b00001: result = in_a_minus_in_b; // Subtraction
            5'b00010: result = in_a_twos_complement < in_b_twos_complement; // Signed less than
            5'b00011: result = in_a < in_b; // Unsigned less than
            5'b00100: result = in_a_xor_b; // XOR
            5'b00101: result = in_a_or_b; // OR
            5'b00110: result = in_a_and_b; // AND
            5'b00111: result = in_a_lui; // LUI
            default: result = 32'b0;
        endcase
    end

    // Intermediate calculations
    assign in_a_and_b = in_a & in_b;
    assign in_a_or_b = in_a | in_b;
    assign in_a_xor_b = in_a ^ in_b;
    assign in_a_plus_in_b = in_a + in_b_twos_complement;
    assign in_a_minus_in_b = in_a + (~in_b_twos_complement + 1);
    assign in_a_lui = {in_a[31:12], 12'b0};

    // Output the result and status flags
    assign rd_val_out = result[31:0];
    assign lt = result[32];
    assign ltu = (alu_op == 5'b00011) ? (in_a[31] == in_b[31] && result[32]) : (alu_op == 5'b00010) ? result[32] : 1'b0;
    assign eq = (alu_op == 5'b00011) ? (in_a[31] == in_b[31] && !result[32]) : (alu_op == 5'b00010) ? !result[32] : (alu_op == 5'b00000 || alu_op == 5'b00001) ? !result[32] : (alu_op == 5'b00100 || alu_op == 5'b00101 || alu_op == 5'b00110) ? (result == 32'b0) : 1'b0;

endmodule

module addmuladd_2_stage_signed_16_bit(
