module fsm_global
(   
	input wire					clk,
	input wire 					rst_n,
	input wire					clk_cam,

	input wire		[9:0]		input_wrusedw,
	input wire		[11:0]		output_rdusedw,
	input wire					VSYNC_cam,
	input wire					HREF_cam,
	output wire					p_VSYNC_cam,

	input wire					wr_input_fifo,
	output wire					rd_input_fifo,

	output wire					wr_strobe,
	output wire					rd_strobe,
	output wire					write_strobe,
	output wire					read_strobe,
	output wire					wait_strobe,
	output wire					idle_strobe,

	input wire					sd_ready,
	input wire					valid_data,

	input wire					STOP_capt
);

typedef enum reg [1:0] {
	IDLE,
	WAIT,
	READ,
	WRITE
} state_t;

state_t state, next_state;

reg [9:0] input_wrusedw_reg;
reg [11:0] output_rdusedw_reg;
reg VSYNC_cam_reg;
reg HREF_cam_reg;
reg wr_input_fifo_reg;
reg rd_input_fifo_reg;
reg sd_ready_reg;
reg valid_data_reg;
reg STOP_capt_reg;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		state <= IDLE;
		input_wrusedw_reg <= 10'b0;
		output_rdusedw_reg <= 12'b0;
		VSYNC_cam_reg <= 1'b0;
		HREF_cam_reg <= 1'b0;
		wr_input_fifo_reg <= 1'b0;
		rd_input_fifo_reg <= 1'b0;
		sd_ready_reg <= 1'b0;
		valid_data_reg <= 1'b0;
		STOP_capt_reg <= 1'b0;
	end else begin
		state <= next_state;
		input_wrusedw_reg <= input_wrusedw;
		output_rdusedw_reg <= output_rdusedw;
		VSYNC_cam_reg <= VSYNC_cam;
		HREF_cam_reg <= HREF_cam;
		wr_input_fifo_reg <= wr_input_fifo;
		rd_input_fifo_reg <= rd_input_fifo;
		sd_ready_reg <= sd_ready;
		valid_data_reg <= valid_data;
		STOP_capt_reg <= STOP_capt;
	end
end

always @(*) begin
	next_state = state;
	wr_strobe = 1'b0;
	rd_strobe = 1'b0;
	write_strobe = 1'b0;
	read_strobe = 1'b0;
	wait_strobe = 1'b0;
	idle_strobe = 1'b0;
	p_VSYNC_cam = VSYNC_cam_reg;

	case (state)
		IDLE: begin
			if (wr_input_fifo_reg && sd_ready_reg && valid_data_reg && !STOP_capt_reg) begin
				next_state = READ;
				idle_strobe = 1'b1;
			end
		end
		WAIT: begin
			if (wr_input_fifo_reg && sd_ready_reg && valid_data_reg && !STOP_capt_reg) begin
				next_state = READ;
				wait_strobe = 1'b1;
			end
		end
		READ: begin
			if (wr_input_fifo_reg && sd_ready_reg && valid_data_reg && !STOP_capt_reg) begin
				next_state = WRITE;
				read_strobe = 1'b1;
			end
		end
		WRITE: begin
			if (wr_input_fifo_reg && sd_ready_reg && valid_data_reg && !STOP_capt_reg) begin
				next_state = IDLE;
				write_strobe = 1'b1;
			end
		end
	default: begin
		next_state = IDLE;
	end
	endcase
end

endmodule

module mulsub_3_stage_signed_18_bit(
	input signed [17:0] a,
	input signed [17:0] b,
	input signed [17:0] c,
	output [17:0] out,
	input clk);

reg [35:0] stage0;
reg [35:0] stage1;
reg [35:0] stage2;

always @(posedge clk) begin
    // Stage 0: Compute the product of a and b, then subtract c
    stage0 <= {a, 18'b0} * {b, 18'b0} - {c, 18'b0};

    // Stage 1: Pass the result through (no operation)
    stage1 <= stage0;

    // Stage 2: Pass the result through (no operation)
    stage2 <= stage1;
end

assign out = stage2[35:18]; // Extract the 18-bit result from the 36-bit register

endmodule

