	output [11:0] out,
	input clk);

reg [23:0] reg1, reg2;
reg [11:0] temp_out;

always @(posedge clk) begin
	// Stage 1: Addition and Multiplication
	reg1 <= $signed(a) + $signed(b);
	reg2 <= $signed(c) * $signed(d);
end

