module presubmul_2_stage_unsigned_8_bit(
	input  [7:0] a,
	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);

	// Internal 16-bit registers to handle the intermediate results
	reg [15:0] stage0;
	reg [15:0] stage1;

	// Intermediate result of the subtraction
	wire [15:0] sub_result = d - a;

	// Intermediate result of the multiplication
	wire [15:0] mul_result = sub_result * b;

	// Sequential logic to update the registers on the rising edge of the clock
	always @(posedge clk) begin
		// First stage: store the multiplication result in stage0
		stage0 <= mul_result;

		// Second stage: store the result from stage0 in stage1
		stage1 <= stage0;
	end

	// Output the result from the second stage register
	assign out = stage1[7:0];
endmodule

