module std_mem_d3_32_16_16_16_4_4_4 #(
    parameter WIDTH = 32,
    parameter D0_SIZE = 16,
    parameter D1_SIZE = 16,
    parameter D2_SIZE = 16,
    parameter D0_IDX_SIZE = 4,
    parameter D1_IDX_SIZE = 4,
    parameter D2_IDX_SIZE = 4
) (
   input wire                logic [D0_IDX_SIZE-1:0] addr0,
   input wire                logic [D1_IDX_SIZE-1:0] addr1,
   input wire                logic [D2_IDX_SIZE-1:0] addr2,
   input wire                logic [ WIDTH-1:0] write_data,
   input wire                logic write_en,
   input wire                logic clk,
   output logic [ WIDTH-1:0] read_data,
   output logic              done
);

    // 3D memory array
    logic [WIDTH-1:0] mem [D0_SIZE-1:0][D1_SIZE-1:0][D2_SIZE-1:0];

    // Internal signals
    logic [WIDTH-1:0] mem_data;
    logic mem_write_en;

    // Read operation
    assign read_data = mem[addr0][addr1][addr2];

    // Write operation
    always_ff @(posedge clk) begin
        if (write_en) begin
            if (addr0 < D0_SIZE && addr1 < D1_SIZE && addr2 < D2_SIZE) begin
                mem[addr0][addr1][addr2] <= write_data;
                mem_write_en <= 1;
            end else begin
                // Error handling for out-of-bounds access
                $display("Error: Out-of-bounds write access at addr0=%0d, addr1=%0d, addr2=%0d", addr0, addr1, addr2);
                mem_write_en <= 0;
            end
        end else begin
            mem_write_en <= 0;
        end
    end

    // Done signal
    assign done = mem_write_en;

endmodule

module mulsub_2_stage_unsigned_18_bit_xor_reduction(
	input  [17:0] a,
	input  [17:0] b,
	input  [17:0] c,
	output [17:0] out,
	input clk);

reg [35:0] stage0;
reg [35:0] stage1;
reg [35:0] xor_result;

always @(posedge clk) begin
    // First stage: Multiply a and b, then subtract c
    stage0 <= a * b - c;
end

always @(posedge clk) begin
    // Second stage: Store the result from the first stage
    stage1 <= stage0;
end

always @(posedge clk) begin
    // XOR reduction of the 36-bit value stored in stage1
    xor_result <= stage1[35] ^ stage1[34] ^ stage1[33] ^ stage1[32] ^
                   stage1[31] ^ stage1[30] ^ stage1[29] ^ stage1[28] ^
                   stage1[27] ^ stage1[26] ^ stage1[25] ^ stage1[24] ^
                   stage1[23] ^ stage1[22] ^ stage1[21] ^ stage1[20] ^
                   stage1[19] ^ stage1[18] ^ stage1[17] ^ stage1[16] ^
                   stage1[15] ^ stage1[14] ^ stage1[13] ^ stage1[12] ^
                   stage1[11] ^ stage1[10] ^ stage1[9]  ^ stage1[8]  ^
                   stage1[7]  ^ stage1[6]  ^ stage1[5]  ^ stage1[4]  ^
                   stage1[3]  ^ stage1[2]  ^ stage1[1]  ^ stage1[0];
end

assign out = xor_result[0] ? 18'b1 : 18'b0;

endmodule

