module top_properties (input logic clock, read, write, ready);

  // Property to check mutually exclusive read and write conditions
  property mutually_exclusive;
    @(posedge clock) disable iff (!reset)
      !(read && write);
  endproperty

  // Assertion to enforce the mutually exclusive property
  assert property (mutually_exclusive)
    else $error("Read and write signals asserted simultaneously");

  // Property to check the timing relationship between write and ready signals
  property write_ready_timing;
    @(posedge clock) disable iff (!reset)
      (write && !ready) |-> ##[1:$] ready;
  endproperty

  // Assertion to enforce the write and ready timing property
  assert property (write_ready_timing)
    else $error("Ready signal not set after write operation");

  // Reset signal for assertions
  input logic reset;
  default clocking @(posedge clock);
    input read, write, ready, reset;
  endclocking

endmodule

