module AddressDecoder_Resp_BRIDGE
#(
    parameter ID_WIDTH   = 20, 
    parameter N_MASTER   = 20  
)
(
    input  logic                         data_r_valid_i,
    input  logic [ID_WIDTH-1:0]          data_ID_i,
    output logic [N_MASTER-1:0]          data_r_valid_o
);

    // Create a vector of ID_WIDTH bits from data_r_valid_i
    logic [ID_WIDTH-1:0] data_r_valid_vec;

    // Assign data_r_valid_i to the vector
    assign data_r_valid_vec = data_r_valid_i;

