module UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);

// States for transmitter
typedef enum reg [1:0] {
	TxIdle,
	Sending,
	TxDone
} TxStateType;

// States for receiver
typedef enum reg [1:0] {
	RxIdle,
	Receiving,
	RxDone
} RxStateType;

// Internal registers
reg [1:0] TxState;
reg [1:0] RxState;
reg [7:0] TxData;
reg [7:0] RxData;
reg [8:0] TxBdCount;
reg [8:0] RxBdCount;

// Internal signals
reg TxStartBit;
reg RxStartBit;
reg [2:0] BitCount;

// FSM for transmitter
always @(posedge ipClk or posedge ipReset) begin
	if (ipReset) begin
		TxState <= TxIdle;
		TxBusy <= 0;
		TxData <= 0;
		TxBdCount <= 0;
	end else begin
		case (TxState)
			TxIdle: begin
				if (ipTxSend) begin
					TxData <= ipTxData;
					TxState <= Sending;
					TxBusy <= 1;
					TxBdCount <= 0;
				end
			end
			Sending: begin
				if (TxBdCount < 433) begin
					TxBdCount <= TxBdCount + 1;
				end else begin
					TxBdCount <= 0;
					TxBusy <= 0;
					TxState <= TxDone;
				end
			end
			TxDone: begin
				TxState <= TxIdle;
			end
		endcase
	end
end

// FSM for receiver
always @(posedge ipClk or posedge ipReset) begin
	if (ipReset) begin
		RxState <= RxIdle;
		RxData <= 0;
		RxBdCount <= 0;
		RxValid <= 0;
	end else begin
		case (RxState)
			RxIdle: begin
				if (!ipRx) begin
					RxStartBit <= 1;
					RxState <= Receiving;
					RxBdCount <= 0;
				end
			end
			Receiving: begin
				if (RxBdCount < 433) begin
					RxBdCount <= RxBdCount + 1;
				end else begin
					RxBdCount <= 0;
					RxData <= {RxData[6:0], ipRx};
					if (RxBdCount == 432) begin
						RxValid <= 1;
						RxState <= RxDone;
					end
				end
			end
			RxDone: begin
				RxState <= RxIdle;
				RxValid <= 0;
			end
		endcase
	end
end

// Output logic
assign opTx = (TxState == Sending) ? (TxStartBit ? 0 : TxData[7]) : 1;
assign opRxData = RxData;
assign opRxValid = RxValid;

endmodule

module submulxor_2_stage_signed_10_bit_xor_reduction(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	input signed [9:0] d,
	output [9:0] out,
	input clk);

reg [19:0] stage0;
reg [19:0] stage1;
reg [9:0] xor_result;

always @(posedge clk) begin
    // Stage 0: Subtraction and Multiplication
    stage0 <= (a - b) * (c - d);

    // Stage 1: XOR reduction
    stage1 <= stage0;
    xor_result <= 0;
    for (integer i = 0; i < 20; i = i + 1) begin
        xor_result = xor_result ^ stage1[i];
    end
end

assign out = xor_result;

endmodule

module mulsub_3_stage_unsigned_9_bit(
	input  [8:0] a,
	input  [8:0] b,
	input  [8:0] c,
	output [8:0] out,
	input clk);

reg [17:0] stage0;
reg [17:0] stage1;
reg [17:0] stage2;

always @(posedge clk) begin
    // Stage 0: Perform multiplication and subtraction
    stage0 <= (a * b) - c;
end

always @(posedge clk) begin
    // Stage 1: Hold the result for the next cycle
    stage1 <= stage0;
end

always @(posedge clk) begin
    // Stage 2: Hold the result for the next cycle
    stage2 <= stage1;
end

// Output the result after three clock cycles
assign out = stage2[8:0];

endmodule

module submuladd_3_stage_signed_8_bit_xor_reduction(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	input signed [7:0] d,
	output [7:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;
reg [15:0] stage2;

always @(posedge clk) begin
    // Stage 0: Perform subtraction and multiplication
    stage0 <= (d - a) * b;

    // Stage 1: Add c to the result of stage0
    stage1 <= stage0 + c;

    // Stage 2: Store the final result
    stage2 <= stage1;
end

// XOR reduction of the 16-bit result to produce an 8-bit output
assign out = stage2[15] ^ stage2[14] ^ stage2[13] ^ stage2[12] ^ stage2[11] ^ stage2[10] ^ stage2[9] ^ stage2[8] ^ stage2[7] ^ stage2[6] ^ stage2[5] ^ stage2[4] ^ stage2[3] ^ stage2[2] ^ stage2[1] ^ stage2[0];

endmodule

