always @(posedge clk) begin
    // First stage: Multiply a and b
    stage0 <= a * b;
end

always @(posedge clk) begin
    // Second stage: Combine the result with c using bitwise OR
    stage1 <= stage0 | c;
end

assign out = stage1[7:0]; // Output the lower 8 bits of the final result

endmodule

