module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
    // Array of keypress values
    reg [9:0] keypress_values [0:4] = '{8'h01, 8'h02, 8'h03, 8'h04, 8'h05};

    // Counter for delaying keypresses
    reg [4:0] counter;

    // Index for tracking the current key
    reg [2:0] index;

    // Internal state to track if the last key has been reached
    reg last_key_reached;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all internal states
            counter <= 5'd0;
            index <= 3'd0;
            last_key_reached <= 1'b0;
            keypress <= 10'd0;
        end else begin
            if (counter < 5'd20) begin
                // Increment counter if not at the delay limit
                counter <= counter + 1;
            end else begin
                // Output the current keypress value
                keypress <= keypress_values[index];

                // Increment index and check if it has reached the last key
                if (index < 3'd4) begin
                    index <= index + 1;
                end else begin
                    last_key_reached <= 1'b1;
                end

                // Reset counter after outputting a keypress
                counter <= 5'd0;
            end
        end
    end
endmodule

