module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);

logic [WIDTH-1:0] dat0, dat1;
logic [1:0] state, next_state;

// State encoding
parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

// State transition logic
always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
	end else begin
		state <= next_state;
	end
end

// Next state logic
always_comb begin
	case (state)
		S0: if (t0_valid && i0_ready) next_state = S1;
		S1: if (t0_valid && i0_ready) next_state = S2;
		S2: if (t0_valid && i0_ready) next_state = S3;
		S3: next_state = S0;
		default: next_state = S0;
	endcase
end

// Data capture logic
always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= 0;
		dat1 <= 0;
	end else begin
		case (state)
			S1: dat0 <= t0_data;
			S2: dat1 <= t0_data;
			default: ;
		endcase
	end
end

// Output logic
always_comb begin
	case (state)
		S0: begin
			i0_data = 0;
			i0_valid = 0;
		end
		S1: begin
			i0_data = dat0;
			i0_valid = 1;
		end
		S2: begin
			i0_data = dat1;
			i0_valid = 1;
		end
		S3: begin
			i0_data = dat0;
			i0_valid = 1;
		end
		default: begin
			i0_data = 0;
			i0_valid = 0;
		end
	endcase
end

// Ready signal logic
always_comb begin
	case (state)
		S0: t0_ready = 1;
		S1: t0_ready = 1;
		S2: t0_ready = 1;
		S3: t0_ready = 0;
		default: t0_ready = 1;
	endcase
end

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [DEPTH-1:0] wr_ptr;
    reg [DEPTH-1:0] rd_ptr;
    reg [DEPTH-1:0] word_count;

    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            word_count <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            if (data_we && !full) begin
                mem[wr_ptr] <= data_i;
                wr_ptr <= wr_ptr + 1;
                word_count <= word_count + 1;
                if (word_count == DEPTH) begin
                    overflow <= 1;
                end
            end

            if (data_rd && !empty) begin
                rd_ptr <= rd_ptr + 1;
                word_count <= word_count - 1;
                if (word_count == 0) begin
                    underflow <= 1;
                end
            end

            if (word_count == DEPTH) begin
                full <= 1;
            end else begin
                full <= 0;
            end

            if (word_count == 0) begin
                empty <= 1;
            end else begin
                empty <= 0;
            end

            if (word_count == PROG_FULL) begin
                prog_full <= 1;
            end else begin
                prog_full <= 0;
            end

            if (overflow) begin
                overflow <= 1;
            end else if (data_we && !full) begin
                overflow <= 0;
            end

            if (underflow) begin
                underflow <= 1;
            end else if (data_rd && !empty) begin
                underflow <= 0;
            end
        end
    end

    assign data_o = mem[rd_ptr];

endmodule

