module vga_ctrl(
    input wire pixel_clk,
    output wire hsync,
    output wire vsync,
    output wire [9:0] pixel_x,
    output wire [9:0] pixel_y,
    output wire visible_region
);
    // Parameters for VGA timing
    parameter TOTAL_PIXELS_H = 800; // Total horizontal pixels
    parameter TOTAL_LINES_V = 525;  // Total vertical lines
    parameter HSYNC_PULSES = 96;    // Horizontal sync pulses
    parameter HBLANKING = 160;      // Horizontal blanking interval
    parameter VSYNC_PULSES = 2;     // Vertical sync pulses
    parameter VBLANKING = 23;       // Vertical blanking interval
    parameter ACTIVE_VIDEO_H = 640;  // Active video horizontal pixels
    parameter ACTIVE_VIDEO_V = 480;  // Active video vertical lines

    reg [9:0] hcount; // Horizontal counter
    reg [9:0] vcount; // Vertical counter

    // Horizontal sync generation
    assign hsync = (hcount >= TOTAL_PIXELS_H - HSYNC_PULSES) && (hcount < TOTAL_PIXELS_H);

    // Vertical sync generation
    assign vsync = (vcount >= TOTAL_LINES_V - VSYNC_PULSES) && (vcount < TOTAL_LINES_V);

    // Pixel coordinates
    assign pixel_x = hcount;
    assign pixel_y = vcount;

    // Visible region detection
    assign visible_region = (hcount < ACTIVE_VIDEO_H) && (vcount < ACTIVE_VIDEO_V);

    // Counter logic
    always @(posedge pixel_clk) begin
        if (hcount == TOTAL_PIXELS_H - 1) begin
            hcount <= 0;
            if (vcount == TOTAL_LINES_V - 1) begin
                vcount <= 0;
            end else begin
                vcount <= vcount + 1;
            end
        end else begin
            hcount <= hcount + 1;
        end
    end
endmodule

