  reg [35:0] p_reg;
  reg [17:0] acin_reg, bcin_reg;

  // Instantiate the 18x18 multiplier core
  EG_PHY_MULT18_CORE #(
    .ENABLE_INPUT_REGISTERS(sourcea && sourceb),
    .ENABLE_OUTPUT_REGISTERS(1'b1),
    .RESET_MODE("ASYNC"),
    .SOURCE_A(sourcea),
    .SOURCE_B(sourceb)
  ) mult_core (
    .acout(acout_reg),
    .bcout(bcout_reg),
    .p(p_reg),
    .a(signeda ? a_reg : a),
    .b(signedb ? b_reg : b),
    .acin(acin_reg),
    .bcin(bcin_reg),
    .cea(cea),
    .ceb(ceb),
    .cepd(cepd),
    .clk(clk),
    .rstan(rstan),
    .rstbn(rstbn),
    .rstpdn(rstpdn)
  );

  // Register inputs if sourcea and sourceb are set
  always @(posedge clk or negedge rstbn) begin
    if (!rstbn) begin
      a_reg <= 18'b0;
      b_reg <= 18'b0;
      acin_reg <= 18'b0;
      bcin_reg <= 18'b0;
    end else if (sourcea) begin
      a_reg <= a;
    end
    if (sourceb) begin
      b_reg <= b;
    end
    acin_reg <= acin;
    bcin_reg <= bcin;
  end

  // Assign outputs
  assign acout = acout_reg;
  assign bcout = bcout_reg;
  assign p = p_reg;

endmodule

