module regFile #(parameter REG_SIZE=16, CCR_SIZE=16, parameter REG_NUMBER=8) (
    Data_write1, sp_write, Src1, Src2, read_sp, read_pc, read_ccr,
    write_sp_data, write_pc_data, write_ccr, write_data1, clk, rst,
    Opd1_Add, Opd2_Add, write_addr1
);

    input Data_write1, sp_write, clk, rst;
    input [2:0] Opd2_Add;
    input [3:0] Opd1_Add, write_addr1;
    input [REG_SIZE-1:0] write_data1;
    input [31:0] write_sp_data, write_pc_data;
    input [CCR_SIZE-1 : 0] write_ccr;

    output [REG_SIZE-1:0] Src1, Src2;
    output [31:0] read_sp, read_pc;
    output [CCR_SIZE-1 : 0] read_ccr;

    reg [REG_SIZE-1:0] reg_file [0:REG_NUMBER-1];
    reg [31:0] pc_reg1, pc_reg2;
    reg [CCR_SIZE-1:0] ccr_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            reg_file <= {REG_NUMBER{0}};
            pc_reg1 <= 16'h0000;
            pc_reg2 <= 16'h0000;
            ccr_reg <= 0;
        end else begin
            if (Data_write1) begin
                reg_file[write_addr1] <= write_data1;
            end
            if (sp_write) begin
                pc_reg1 <= pc_reg2;
                pc_reg2 <= write_sp_data[31:16];
                ccr_reg <= write_ccr;
            end
        end
    end

    assign Src1 = reg_file[Opd1_Add];
    assign Src2 = reg_file[Opd2_Add];
    assign read_sp = {pc_reg2, pc_reg1};
    assign read_pc = {pc_reg2, pc_reg1};
    assign read_ccr = ccr_reg;

endmodule

module decode(icode,clk,rA,rB,cnd,valE,valM,regmem0,regmem1,regmem2,regmem3,regmem4,regmem5,regmem6,regmem7,regmem8,regmem9,
               regmem10,regmem11,regmem12,regmem13,regmem14,regmem15,valA,valB);

input[3:0] icode,rA,rB;
input [63:0] valE,valM;
output reg [63:0] valA,valB;
input clk,cnd;
output reg [63:0] regmem0,regmem1,regmem2,regmem3,regmem4,regmem5,regmem6,regmem7,regmem8,regmem9,regmem10,regmem11;
output reg [63:0] regmem12,regmem13,regmem14,regmem15;

reg [63:0] reg_mem [0:15];

always @(*) begin
    // Combinational logic to determine valA and valB
    case (icode)
        4'b0000: begin // No operation
            valA = 64'b0;
            valB = 64'b0;
        end
        4'b0001: begin // Read rA
            valA = reg_mem[rA];
            valB = 64'b0;
        end
        4'b0010: begin // Read rA and rB
            valA = reg_mem[rA];
            valB = reg_mem[rB];
        end
        4'b0011: begin // Read rB
            valA = 64'b0;
            valB = reg_mem[rB];
        end
        4'b0100: begin // Write valE to rB
            valA = 64'b0;
            valB = valE;
        end
        4'b0101: begin // Conditional write valE to rB
            valA = 64'b0;
            valB = cnd ? valE : 64'b0;
        end
        4'b0110: begin // Write valM to rB
            valA = 64'b0;
            valB = valM;
        end
        4'b0111: begin // Conditional write valM to rB
            valA = 64'b0;
            valB = cnd ? valM : 64'b0;
        end
        4'b1000: begin // Write valE to rA
            valA = valE;
            valB = 64'b0;
        end
        4'b1001: begin // Conditional write valE to rA
            valA = cnd ? valE : 64'b0;
            valB = 64'b0;
        end
        4'b1010: begin // Write valM to rA
            valA = valM;
            valB = 64'b0;
        end
        4'b1011: begin // Conditional write valM to rA
            valA = cnd ? valM : 64'b0;
            valB = 64'b0;
        end
        4'b1100: begin // Write valE to rA and rB
            valA = valE;
            valB = valE;
        end
        4'b1101: begin // Conditional write valE to rA and rB
            valA = cnd ? valE : 64'b0;
            valB = cnd ? valE : 64'b0;
        end
        4'b1110: begin // Write valM to rA and rB
            valA = valM;
            valB = valM;
        end
        4'b1111: begin // Conditional write valM to rA and rB
            valA = cnd ? valM : 64'b0;
            valB = cnd ? valM : 64'b0;
        end
        default: begin
            valA = 64'b0;
            valB = 64'b0;
        end
    endcase
end

always @(posedge clk) begin
    // Sequential logic to update register file
    case (icode)
        4'b0100: reg_mem[rB] <= valE;
        4'b0101: if (cnd) reg_mem[rB] <= valE;
        4'b0110: reg_mem[rB] <= valM;
        4'b0111: if (cnd) reg_mem[rB] <= valM;
        4'b1000: reg_mem[rA] <= valE;
        4'b1001: if (cnd) reg_mem[rA] <= valE;
        4'b1010: reg_mem[rA] <= valM;
        4'b1011: if (cnd) reg_mem[rA] <= valM;
        4'b1100: begin
            reg_mem[rA] <= valE;
            reg_mem[rB] <= valE;
        end
        4'b1101: begin
            if (cnd) begin
                reg_mem[rA] <= valE;
                reg_mem[rB] <= valE;
            end
        end
        4'b1110: begin
            reg_mem[rA] <= valM;
            reg_mem[rB] <= valM;
        end
        4'b1111: begin
            if (cnd) begin
                reg_mem[rA] <= valM;
                reg_mem[rB] <= valM;
            end
        end
        default: begin
            // No update
        end
    endcase
end

assign regmem0 = reg_mem[0];
assign regmem1 = reg_mem[1];
assign regmem2 = reg_mem[2];
assign regmem3 = reg_mem[3];
assign regmem4 = reg_mem[4];
assign regmem5 = reg_mem[5];
assign regmem6 = reg_mem[6];
assign regmem7 = reg_mem[7];
assign regmem8 = reg_mem[8];
assign regmem9 = reg_mem[9];
assign regmem10 = reg_mem[10];
assign regmem11 = reg_mem[11];
assign regmem12 = reg_mem[12];
assign regmem13 = reg_mem[13];
assign regmem14 = reg_mem[14];
assign regmem15 = reg_mem[15];

endmodule

module wideexpr_00770(
  input [7:0] ctrl,
  input [0:0] u0,
  input [1:0] u1,
  input [2:0] u2,
  input [3:0] u3,
  input [4:0] u4,
  input [5:0] u5,
  input [6:0] u6,
  input [7:0] u7,
  input signed [0:0] s0,
  input signed [1:0] s1,
  input signed [2:0] s2,
  input signed [3:0] s3,
  input signed [4:0] s4,
  input signed [5:0] s5,
  input signed [6:0] s6,
  input signed [7:0] s7,
  output [127:0] y
);

  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  assign y0 = (ctrl[0]) ? (u0 + s0) : (u0 & s0);
  assign y1 = (ctrl[1]) ? (u1 << u2) : (u1 | s1);
  assign y2 = (ctrl[2]) ? (u3 * s3) : (u3 ^ s3);
  assign y3 = (ctrl[3]) ? (u4 >> u5) : (u4 + s4);
  assign y4 = (ctrl[4]) ? (u6 - s6) : (u6 & s6);
  assign y5 = (ctrl[5]) ? (u7 << u8) : (u7 | s7);
  assign y6 = (ctrl[6]) ? (u9 * s9) : (u9 ^ s9);
  assign y7 = (ctrl[7]) ? (u10 >> u11) : (u10 + s10);

  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

