module im2_control(
    input wire i_CLK_CPU,
    input wire i_reset,
    input wire i_m1_n,
    input wire i_mreq_n,
    input wire i_iorq_n,
    input wire i_rfsh_n,
    input wire [7:0] i_cpu_d,
    output wire o_reti_decode,
    output wire o_reti_seen
);

    // Define states
    parameter S_0 = 2'b00;
    parameter S_ED_T4 = 2'b01;
    parameter S_4D_T4 = 2'b10;
    parameter S_CB_T4 = 2'b11;

    // Internal signals
    reg [1:0] state, next_state;
    reg [7:0] cpu_opcode;
    reg ifetch, ifetch_cancel;
    reg o_reti_decode_reg, o_reti_seen_reg;

    // State register
    always @(posedge i_CLK_CPU or posedge i_reset) begin
        if (i_reset) begin
            state <= S_0;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state and outputs
    always @(*) begin
        next_state = state;
        o_reti_decode_reg = 0;
        o_reti_seen_reg = 0;

        case (state)
            S_0:
                if (i_m1_n && i_mreq_n && i_iorq_n && i_rfsh_n) begin
                    cpu_opcode = i_cpu_d;
                    if (cpu_opcode == 8'hED) begin
                        next_state = S_ED_T4;
                    end else if (cpu_opcode == 8'h4D) begin
                        next_state = S_4D_T4;
                    end else if (cpu_opcode == 8'hCB) begin
                        next_state = S_CB_T4;
                    end
                end
            S_ED_T4:
                if (i_m1_n && i_mreq_n && i_iorq_n && i_rfsh_n) begin
                    next_state = S_0;
                    o_reti_decode_reg = 1;
                end
            S_4D_T4:
                if (i_m1_n && i_mreq_n && i_iorq_n && i_rfsh_n) begin
                    next_state = S_0;
                    o_reti_decode_reg = 1;
                end
            S_CB_T4:
                if (i_m1_n && i_mreq_n && i_iorq_n && i_rfsh_n) begin
                    next_state = S_0;
                    o_reti_decode_reg = 1;
                end
        endcase
    end

    // Output register
    always @(posedge i_CLK_CPU) begin
        o_reti_decode <= o_reti_decode_reg;
        o_reti_seen <= o_reti_seen_reg;
    end

endmodule

module MUX_Rd(
