module partsel_00515(
  input [3:0] ctrl,
  input [2:0] s0,
  input [2:0] s1,
  input [2:0] s2,
  input [2:0] s3,
  input [31:0] x0,
  input signed [31:0] x1,
  input [31:0] x2,
  input signed [31:0] x3,
  output [127:0] y
);

  // Define constants
  parameter A = 32'd10;
  parameter B = 32'd20;
  parameter C = 32'd30;
  parameter D = 32'd40;

  // Intermediate signals
  wire [31:0] temp1, temp2, temp3, temp4;
  wire [31:0] temp5, temp6, temp7, temp8;
  wire [127:0] final_output;

  // Combinational logic based on control signals
  always @(*) begin
    case (ctrl)
      4'd0: begin
        temp1 = x0 + A;
        temp2 = x1 - B;
        temp3 = x2 * C;
        temp4 = x3 / D;
      end
      4'd1: begin
        temp1 = x0 & s0;
        temp2 = x1 | s1;
        temp3 = x2 ^ s2;
        temp4 = x3 << s3;
      end
      4'd2: begin
        temp1 = x0 >> s0;
        temp2 = x1 >>> s1;
        temp3 = x2 == s2;
        temp4 = x3 != s3;
      end
      4'd3: begin
        temp1 = x0 + x1;
        temp2 = x2 - x3;
        temp3 = x0 * x1;
        temp4 = x2 / x3;
      end
      default: begin
        temp1 = 32'd0;
        temp2 = 32'd0;
        temp3 = 32'd0;
        temp4 = 32'd0;
      end
    endcase

    // Combine intermediate results
    final_output = {temp1, temp2, temp3, temp4};
  end

  // Assign final output
  assign y = final_output;

endmodule

