module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);

    parameter CLK_FREQ = 50000000;
    parameter BAUD_RATE = 9600;
    parameter SAMPLE_DIV = CLK_FREQ / (BAUD_RATE * 16);

    reg [7:0] tx_shift_reg;
    reg [3:0] tx_counter;
    reg tx_start;
    reg [7:0] rx_shift_reg;
    reg [3:0] rx_counter;
    reg rx_start;
    reg [1:0] rx_sample_reg;
    reg [1:0] rx_sample_counter;
    reg [1:0] rx_sample_valid;
    reg rx_sample_error;

    // Transmission logic
    always @(posedge clk_50 or posedge rst) begin
        if (rst) begin
            tx_busy <= 0;
            tx_shift_reg <= 0;
            tx_counter <= 0;
            tx_start <= 0;
        end else begin
            if (tx_vld && !tx_busy) begin
                tx_shift_reg <= tx_data;
                tx_counter <= 0;
                tx_start <= 1;
                tx_busy <= 1;
            end else if (tx_start) begin
                if (tx_counter < 10) begin
                    uart_tx <= tx_shift_reg[7];
                    tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
                    tx_counter <= tx_counter + 1;
                end else begin
                    tx_start <= 0;
                    tx_busy <= 0;
                end
            end
        end
    end

    // Reception logic
    always @(posedge clk_50 or posedge rst) begin
        if (rst) begin
            rx_vld <= 0;
            rx_data <= 0;
            rx_frame_error <= 0;
            rx_shift_reg <= 0;
            rx_counter <= 0;
            rx_start <= 0;
            rx_sample_reg <= 0;
            rx_sample_counter <= 0;
            rx_sample_valid <= 0;
            rx_sample_error <= 0;
        end else begin
            if (uart_rx && !rx_start) begin
                rx_start <= 1;
                rx_counter <= 0;
                rx_sample_counter <= 0;
                rx_sample_valid <= 0;
                rx_sample_error <= 0;
            end else if (rx_start) begin
                if (rx_sample_counter < SAMPLE_DIV) begin
                    rx_sample_reg[rx_sample_counter % 2] <= uart_rx;
                    rx_sample_counter <= rx_sample_counter + 1;
                end else begin
                    rx_sample_counter <= 0;
                    if (rx_sample_reg[0] == rx_sample_reg[1]) begin
                        rx_shift_reg[rx_counter] <= rx_sample_reg[0];
                        rx_counter <= rx_counter + 1;
                        if (rx_counter == 7) begin
                            rx_vld <= 1;
                            rx_data <= rx_shift_reg;
                            rx_counter <= 0;
                            rx_start <= 0;
                        end
                    end else begin
                        rx_sample_error <= 1;
                    end
                end
            end
        end
    end

endmodule

