module mode0(
    input wire clk_i,
    input wire [9:0] pix_x_i,
    input wire [9:0] pix_y_i,
    output reg [16:0] vram_addr_o,
    input wire [7:0] vram_rd_data_i,
    output reg [7:0] pal_addr_o,
    input wire [11:0] pal_rd_data_i,
    input wire [16:0] mapbase_i,
    input wire [16:0] tilebase_i,
    output reg [11:0] col_o,
    output reg [9:0] delay_o
);

    reg [9:0] pix_x_0r, pix_x_1r, pix_x_2r, pix_x_3r, pix_x_4r;
    reg [9:0] pix_y_0r, pix_y_1r, pix_y_2r, pix_y_3r, pix_y_4r;
    reg [16:0] map_addr, tile_addr, color_addr;
    reg [11:0] map_data, tile_data, color_data;

    always @(posedge clk_i) begin
        // Pipeline registers
        pix_x_0r <= pix_x_i;
        pix_y_0r <= pix_y_i;
        pix_x_1r <= pix_x_0r;
        pix_y_1r <= pix_y_0r;
        pix_x_2r <= pix_x_1r;
        pix_y_2r <= pix_y_1r;
        pix_x_3r <= pix_x_2r;
        pix_y_3r <= pix_y_2r;
        pix_x_4r <= pix_x_3r;
        pix_y_4r <= pix_y_3r;
    end

    always @(posedge clk_i) begin
        // Compute addresses
        case (pix_x_4r[2:0])
            3'b000: begin // Map mode
                map_addr <= mapbase_i + (pix_x_4r << 1) + (pix_y_4r << 10);
                tile_addr <= 0;
                color_addr <= 0;
            end
            3'b001: begin // Tile mode
                map_addr <= 0;
                tile_addr <= tilebase_i + (pix_x_4r << 1) + (pix_y_4r << 10);
                color_addr <= 0;
            end
            3'b010: begin // Color mode
                map_addr <= 0;
                tile_addr <= 0;
                color_addr <= (pix_x_4r << 1) + (pix_y_4r << 10);
            end
            default: begin
                map_addr <= 0;
                tile_addr <= 0;
                color_addr <= 0;
            end
        endcase
    end

    always @(posedge clk_i) begin
        // Fetch data from VRAM
        map_data <= vram_rd_data_i;
        tile_data <= vram_rd_data_i;
        color_data <= vram_rd_data_i;
    end

    always @(posedge clk_i) begin
        // Compute palette address
        pal_addr_o <= (tile_data << 2) + (map_data << 4) + color_data;
    end

    always @(posedge clk_i) begin
        // Output color and delay
        col_o <= pal_rd_data_i;
        delay_o <= pix_x_4r;
    end

endmodule

