module hardcopyiv_hssi_aux_clock_div (
    input clk,     
    input reset,   
    input enable_d, 
    input [7:0] d,
    output clkout   
);
    parameter CLK_DIVIDE_BY = 8;
    parameter EXTRA_LATENCY = 0;

    reg [7:0] div_factor;
    reg [31:0] counter;
    reg [31:0] output_counter;
    reg clkout_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            div_factor <= CLK_DIVIDE_BY;
            counter <= 0;
            output_counter <= 0;
            clkout_reg <= 0;
        end else if (enable_d) begin
            div_factor <= d;
            counter <= 0;
            output_counter <= 0;
            clkout_reg <= 0;
        end else if (counter == div_factor - 1) begin
            counter <= 0;
            output_counter <= output_counter + 1;
            if (output_counter == (1 << EXTRA_LATENCY) - 1) begin
                output_counter <= 0;
                clkout_reg <= ~clkout_reg;
            end
        end else begin
            counter <= counter + 1;
        end
    end

    assign clkout = clkout_reg;
endmodule

