module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;

input [7:0] request_floor; 
input [7:0] in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 

output reg direction; 
output reg complete;
output reg door_alert;
output reg weight_alert;
output reg [7:0] out_current_floor;

reg [7:0] current_floor;
reg [7:0] target_floor;
reg moving_up;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_floor <= in_current_floor;
        target_floor <= in_current_floor;
        moving_up <= 0;
        complete <= 0;
        direction <= 0;
        door_alert <= 0;
        weight_alert <= 0;
    end else begin
        if (over_time || over_weight) begin
            // Safety conditions override normal operation
            door_alert <= 1;
            weight_alert <= 1;
            moving_up <= 0;
            complete <= 0;
        end else begin
            if (request_floor != current_floor) begin
                if (request_floor > current_floor) begin
                    moving_up <= 1;
                    direction <= 1;
                end else begin
                    moving_up <= 0;
                    direction <= 0;
                end
                target_floor <= request_floor;
            end else begin
                moving_up <= 0;
                direction <= 0;
                complete <= 1;
            end
        end
        if (moving_up && current_floor < target_floor) begin
            current_floor <= current_floor + 1;
        end else if (!moving_up && current_floor > target_floor) begin
            current_floor <= current_floor - 1;
        end
        out_current_floor <= current_floor;
    end
end

endmodule

