module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers for data buffering
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;

    // State definitions
    typedef enum reg [1:0] {ZERO, ONE, TWO} state_t;
    state_t state, next_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            ZERO: begin
                if (s_valid && m_ready) begin
                    next_state = ONE;
                end
            end
            ONE: begin
                if (m_ready) begin
                    next_state = TWO;
                end
            end
            TWO: begin
                if (s_valid) begin
                    next_state = ONE;
                end else begin
                    next_state = ZERO;
                end
            end
        endcase
    end

    // Data flow logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_p1 <= 0;
            data_p2 <= 0;
            s_ready <= 1;
            m_valid <= 0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        data_p1 <= s_data;
                        s_ready <= 0;
                        m_valid <= 1;
                    end
                end
                ONE: begin
                    if (m_ready) begin
                        data_p2 <= data_p1;
                        m_valid <= 0;
                    end
                end
                TWO: begin
                    if (s_valid) begin
                        data_p1 <= s_data;
                    end else begin
                        s_ready <= 1;
                    end
                end
            endcase
        end
    end

    // Output assignment
    assign m_data = data_p2;

endmodule

