module AXI_WRITE_DATA_CHANNEL_model(
    input wire clk,
    input wire resetn,
    input wire [31:0] data,
    input wire go,
    output reg done,
    output wire [31:0] WDATA,
    output reg [3:0] WSTRB,
    output reg WVALID,
    input wire WREADY
);

    // Define states
    typedef enum reg [1:0] {
        RESET,
        IDLE,
        RUNNING,
        COMPLETE
    } state_t;

    // State registers
    state_t current_state, next_state;

    // Sequential logic for state transition
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= RESET;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational logic to determine next state and outputs
    always @(*) begin
        next_state = current_state;
        WDATA = 32'b0;
        WSTRB = 4'b0;
        WVALID = 1'b0;
        done = 1'b0;

        case (current_state)
            RESET: begin
                if (go) begin
                    next_state = IDLE;
                end
            end
            IDLE: begin
                if (go && WREADY) begin
                    next_state = RUNNING;
                    WDATA = data;
                    WSTRB = 4'b1111;
                    WVALID = 1'b1;
                end
            end
            RUNNING: begin
                if (WREADY) begin
                    WDATA = data;
                    WSTRB = 4'b1111;
                    WVALID = 1'b1;
                end else begin
                    WVALID = 1'b0;
                end
                if (!WREADY) begin
                    next_state = IDLE;
                end else if (go && !WREADY) begin
                    next_state = RUNNING;
                end else if (!go && WREADY) begin
                    next_state = COMPLETE;
                end
            end
            COMPLETE: begin
                done = 1'b1;
                next_state = IDLE;
            end
        endcase
    end

endmodule

