module reg_map (
    input               i_clk,
    input               i_rst_n,
    input       [15:0]  i_addr,
    input       [15:0]  i_wdata,
    input               i_wen,
    output  reg [15:0]  o_q,
    output  reg [15:0]  o_reg0000,
    output  reg [15:0]  o_reg0002,
    output  reg [15:0]  o_reg0004,
    output  reg [15:0]  o_reg0006
    );

    // Internal registers
    reg [15:0] reg0000;
    reg [15:0] reg0002;
    reg [15:0] reg0004;
    reg [15:0] reg0006;

    // Decode logic to determine which register to update or read
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            // Reset all registers to zero
            reg0000 <= 16'b0;
            reg0002 <= 16'b0;
            reg0004 <= 16'b0;
            reg0006 <= 16'b0;
        end else begin
            if (i_wen) begin
                // Write operation
                case (i_addr)
                    16'h0000: reg0000 <= i_wdata;
                    16'h0002: reg0002 <= i_wdata;
                    16'h0004: reg0004 <= i_wdata;
                    16'h0006: reg0006 <= i_wdata;
                    default: ; // Do nothing for other addresses
                endcase
            end
        end
    end

    // Multiplex the data from the addressed register to the output
    always @(*) begin
        case (i_addr)
            16'h0000: o_q = reg0000;
            16'h0002: o_q = reg0002;
            16'h0004: o_q = reg0004;
            16'h0006: o_q = reg0006;
            default: o_q = 16'b0; // Default to zero for unknown addresses
        endcase
    end

    // Assign the internal registers to the output ports
    assign o_reg0000 = reg0000;
    assign o_reg0002 = reg0002;
    assign o_reg0004 = reg0004;
    assign o_reg0006 = reg0006;

endmodule

