module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

  // State definitions
  localparam IDLE = 2'b00,
             DATA0 = 2'b01,
             DATA1 = 2'b10;

  // Internal signals
  reg [1:0] state;
  reg [35:0] data_reg;
  reg src0_rdy_reg, src1_rdy_reg;

  // Combinational logic for state transitions and data routing
  always @(*) begin
    state = IDLE;
    data_reg = data_i;
    src0_rdy_reg = 1'b0;
    src1_rdy_reg = 1'b0;
    dst_rdy_o = 1'b0;

    case (state)
      IDLE: begin
        if (src_rdy_i && (data_i & match_mask) == match_data) begin
          if (dst0_rdy_i) begin
            state = DATA0;
          end else if (dst1_rdy_i) begin
            state = DATA1;
          end
        end
      end
      DATA0: begin
        data0_o = data_reg;
        src0_rdy_reg = 1'b1;
        if (dst0_rdy_i) begin
          state = IDLE;
        end
      end
      DATA1: begin
        data1_o = data_reg;
        src1_rdy_reg = 1'b1;
        if (dst1_rdy_i) begin
          state = IDLE;
        end
      end
    endcase
  end

  // Sequential logic for state management
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset || clear) begin
      state <= IDLE;
      src0_rdy_reg <= 1'b0;
      src1_rdy_reg <= 1'b0;
    end else begin
      state <= state;
      src0_rdy_o <= src0_rdy_reg;
      src1_rdy_o <= src1_rdy_reg;
      dst_rdy_o <= (state == IDLE);
    end
  end

endmodule

