module sep32_cnt(
    input           clk,
    input           cen,
    input           zero,
    output reg [4:0]    cnt
    );

reg last_zero;

always @(posedge clk) begin
    if (!cen) begin
        // Reset the counter and last_zero when cen is low
        cnt <= 5'b00001;
        last_zero <= zero;
    end else begin
        // Detect when zero transitions from low to high
        if (!last_zero && zero) begin
            cnt <= 5'b00001;
        end else if (zero) begin
            // Increment the counter if zero is high and cen is high
            if (cnt < 5'b11111) begin
                cnt <= cnt + 1;
            end
        end
        // Update last_zero to the current state of zero
        last_zero <= zero;
    end
end

endmodule

