  reg [23:0] cycle_count;
  reg [7:0] seg_x_reg, seg_y_reg;
  reg [3:0] sel_x_reg, sel_y_reg;

  parameter IDLE = 3'b000;
  parameter SEG_A = 3'b001;
  parameter SEG_B = 3'b010;
  parameter SEG_C = 3'b011;
  parameter SEG_D = 3'b100;
  parameter SEG_E = 3'b101;
  parameter SEG_F = 3'b110;
  parameter SEG_G = 3'b111;

  always @(posedge sys_clock or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      cycle_count <= 0;
      seg_x_reg <= 0;
      seg_y_reg <= 0;
      sel_x_reg <= 0;
      sel_y_reg <= 0;
    end else begin
      case (state)
        IDLE: begin
          cycle_count <= cycle_count + 1;
