          seg_y_reg <= seg7_dot64[rk_c];
          sel_y_reg <= {rk_c, 1'b0};
          state <= SEG_D;
        end
        SEG_D: begin
          seg_x_reg <= seg7_d[rk_d];
          sel_x_reg <= rk_d;
          seg_y_reg <= seg7_dot64[rk_d];
          sel_y_reg <= {rk_d, 1'b0};
          state <= SEG_E;
        end
        SEG_E: begin
          seg_x_reg <= seg7_e[rk_e];
          sel_x_reg <= rk_e;
