        end
        SEG_H: begin
          seg_x_reg <= seg7_h[rk_h];
          sel_x_reg <= rk_h;
          seg_y_reg <= seg7_dot64[rk_h];
          sel_y_reg <= {rk_h, 1'b0};
          state <= IDLE;
        end
      endcase
    end
  end

  assign seg_a = seg_x_reg;
  assign seg_b = seg_x_reg;
  assign seg_c = seg_x_reg;
  assign seg_d = seg_x_reg;
  assign seg_e = seg_x_reg;
  assign seg_f = seg_x_reg;
