module receiver(
    input wire rx,
    output reg rdy,
    input wire rdy_clr,
    input wire clk_50m,
    input wire rst,
    input wire clken,
    output reg [7:0] data
);

    // State definitions
    localparam START = 2'b00,
               DATA  = 2'b01,
               STOP  = 2'b10;

    // Internal signals
    reg [2:0] state;
    reg [2:0] bit_cnt;
    reg [7:0] received_data;
    reg bit_sampled;

    // State machine
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            state <= START;
            bit_cnt <= 3'b000;
            received_data <= 8'b00000000;
            rdy <= 1'b0;
            bit_sampled <= 1'b0;
        end else if (clken) begin
            case (state)
                START: begin
                    if (!rx) begin
                        state <= DATA;
                        bit_cnt <= 3'b000;
                        received_data <= 8'b00000000;
                    end
                end
                DATA: begin
                    if (bit_cnt < 3'b100) begin
                        bit_sampled <= rx;
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    if (rx) begin
                        state <= START;
                        rdy <= 1'b1;
                        data <= received_data;
                    end
                end
            endcase
        end
    end

    // Clear ready signal
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            rdy <= 1'b0;
        end else if (rdy_clr) begin
            rdy <= 1'b0;
        end
    end

endmodule

module arriaiigz_ff (
    d, 
    clk, 
    clrn, 
    aload, 
    sclr, 
    sload, 
    asdata, 
    ena, 
    devclrn, 
    devpor, 
    q
    );

    parameter INIT = 0; // Initial power-up state (0 or 1)
    parameter VIOLATION_RESPONSE = 0; // 0 for hold, 1 for set

    input d;
    input clk;
    input clrn;
    input aload; 
    input sclr; 
    input sload; 
    input asdata; 
    input ena; 
    input devclrn; 
    input devpor; 

    output q;

    reg q_reg;
    reg violation_flag;

    always @(posedge clk or negedge clrn) begin
        if (!clrn) begin
            q_reg <= INIT;
            violation_flag <= 0;
        end else begin
            if (devclrn) begin
                if (devpor) begin
                    if (sclr) begin
                        q_reg <= INIT;
                        violation_flag <= 0;
                    end else if (sload) begin
                        q_reg <= asdata;
                        violation_flag <= 0;
                    end else if (aload) begin
                        q_reg <= asdata;
                        violation_flag <= 0;
                    end else if (ena) begin
                        if (violation_flag) begin
                            q_reg <= VIOLATION_RESPONSE ? 1 : 0;
                        end else begin
                            q_reg <= d;
                        end
                    end
                end
            end
        end
    end

    assign q = q_reg;

endmodule

