module CCarryLookaheadBlock_5_5_5_InOutT(pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, r4,r3,r2,r1,r0, cIn, cOut);

input pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, cIn;
output r4,r3,r2,r1,r0, cOut;

