assign {cA1, r1} = pA1 + pB1 + cA0;
assign {cA2, r2} = pA2 + pB2 + cA1;
assign {cA3, r3} = pA3 + pB3 + cA2;
assign {cA4, r4} = pA4 + pB4 + cA3;

// Lookahead carry calculation
