assign cL1 = cA1 | (cA0 & cL0);
assign cL2 = cA2 | (cA1 & cL1) | (cA0 & cA1 & cL0);
assign cL3 = cA3 | (cA2 & cL2) | (cA1 & cA2 & cL1) | (cA0 & cA1 & cA2 & cL0);
assign cL4 = cA4 | (cA3 & cL3) | (cA2 & cA3 & cL2) | (cA1 & cA2 & cA3 & cL1) | (cA0 & cA1 & cA2 & cA3 & cL0);

// Final carry-out
assign cOut = cL4;

endmodule

