module CLG4(x1, y1, x2, y2, x3, y3, x4, y4, c1,
            s1, s2, s3, s4, c5);
input x1, y1, x2, y2, x3, y3, x4, y4, c1;
output s1, s2, s3, s4, c5;

// Intermediate signals
wire p1, g1, p2, g2, p3, g3, p4, g4;
wire c2, c3, c4;

// XOR and AND operations for the first pair
assign p1 = x1 ^ y1;
assign g1 = x1 & y1;

// XOR and AND operations for the second pair
assign p2 = x2 ^ y2;
assign g2 = x2 & y2;

// XOR and AND operations for the third pair
assign p3 = x3 ^ y3;
assign g3 = x3 & y3;

// XOR and AND operations for the fourth pair
assign p4 = x4 ^ y4;
assign g4 = x4 & y4;

// Carry generation for the second bit
assign c2 = g1 | (p1 & c1);

// Carry generation for the third bit
assign c3 = g2 | (p2 & c2);

// Carry generation for the fourth bit
assign c4 = g3 | (p3 & c3);

// Final carry-out
assign c5 = g4 | (p4 & c4);

// Sum bits computation
assign s1 = p1 ^ c1;
assign s2 = p2 ^ c2;
assign s3 = p3 ^ c3;
assign s4 = p4 ^ c4;

endmodule

