module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
    reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [1:0] subaddr;
    reg good;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
            req <= 0;
            data_ok <= 0;
        end else if (clr) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
            req <= 0;
            data_ok <= 0;
        end else begin
            if (addr_ok) begin
                addr_req <= {addr, {22-AW{1'b0}}};
            end

            if (we && addr_ok) begin
                if (addr_req == cached_addr0) begin
                    cached_data0 <= din;
                end else if (addr_req == cached_addr1) begin
                    cached_data1 <= din;
                end
            end

            if (addr_req == cached_addr0) begin
                dout <= cached_data0;
                subaddr <= 0;
            end else if (addr_req == cached_addr1) begin
                dout <= cached_data1;
                subaddr <= 1;
            end else begin
                dout <= 0;
                subaddr <= 0;
            end

            if (addr_ok && (addr_req != cached_addr0) && (addr_req != cached_addr1)) begin
                req <= 1;
                data_ok <= 0;
                if (good) begin
                    if (addr_req == cached_addr0) begin
                        cached_addr0 <= addr_req;
                        cached_data0 <= din;
                    end else if (addr_req == cached_addr1) begin
                        cached_addr1 <= addr_req;
                        cached_data1 <= din;
                    end
                end
            end else begin
                req <= 0;
                data_ok <= 1;
            end

            if (addr_ok && (addr_req == cached_addr0) || (addr_req == cached_addr1)) begin
                good <= 1;
            end else begin
                good <= 0;
            end
        end
    end

    assign sdram_addr = addr_req + offset;
endmodule

module partsel_00075(
  input [3:0] ctrl,
  input [2:0] s0,
  input [2:0] s1,
  input [2:0] s2,
  input [2:0] s3,
  input signed [31:0] x0,
  input signed [31:0] x1,
  input signed [31:0] x2,
  input signed [31:0] x3,
  output [127:0] y
);

  // Local parameters for constants
  localparam [31:0] p0 = 32'd10;
  localparam [31:0] p1 = 32'd20;
  localparam [31:0] p2 = 32'd30;
  localparam [31:0] p3 = 32'd40;

  // Internal wires for intermediate results
  wire [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;

  // Combinational logic based on control and selection signals
  always @(*) begin
    case (ctrl)
      4'd0: begin
        x4 = x0 + p0;
        x5 = x1 - p1;
        x6 = x2 ^ p2;
        x7 = x3 & p3;
      end
      4'd1: begin
        x4 = x0 - p0;
        x5 = x1 + p1;
        x6 = x2 | p2;
        x7 = x3 ^ p3;
      end
      4'd2: begin
        x4 = x0 & p0;
        x5 = x1 | p1;
        x6 = x2 ^ p2;
        x7 = x3 & p3;
      end
      4'd3: begin
        x4 = x0 | p0;
        x5 = x1 ^ p1;
        x6 = x2 & p2;
        x7 = x3 | p3;
      end
      default: begin
        x4 = 32'd0;
        x5 = 32'd0;
        x6 = 32'd0;
        x7 = 32'd0;
      end
    endcase

    // Further processing based on selection signals
    x8 = (s0 == 3'b000) ? x4 : x5;
    x9 = (s1 == 3'b000) ? x6 : x7;
    x10 = (s2 == 3'b000) ? x8 : x9;
