module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
  // State definitions
  localparam IDLE = 4'b0000;
  localparam START = 4'b0001;
  localparam DATA = 4'b0010;
  localparam STOP = 4'b0011;

  // State register
  reg [3:0] state;

  // Data register
  reg [7:0] data_reg;

  // Bit counter
  reg [2:0] bit_count;

  // Shift register for data transmission
  reg [7:0] shift_reg;

  // Output signals
  assign io_ready = (state == IDLE);

  // State machine logic
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      data_reg <= 8'b0;
      bit_count <= 3'b0;
      shift_reg <= 8'b0;
      tx <= 1'b1; // Idle state, tx line high
    end else begin
      case (state)
        IDLE: begin
          if (io_valid) begin
            data_reg <= io_bits;
            shift_reg <= {1'b0, data_reg}; // Start bit
            bit_count <= 3'b100; // 8 data bits + 1 start bit
            state <= START;
          end
        end
        START: begin
          tx <= shift_reg[0]; // Send start bit
          shift_reg <= {shift_reg[7:1], 1'b0}; // Shift right
          bit_count <= bit_count - 1;
          if (bit_count == 3'b0) begin
            state <= DATA;
          end
        end
        DATA: begin
          tx <= shift_reg[0]; // Send data bit
          shift_reg <= {shift_reg[7:1], 1'b0}; // Shift right
          bit_count <= bit_count - 1;
          if (bit_count == 3'b0) begin
            state <= STOP;
          end
        end
        STOP: begin
          tx <= 1'b1; // Send stop bit
          bit_count <= 3'b100; // 1 stop bit
          state <= IDLE;
        end
        default: state <= IDLE;
      endcase
    end
  end
endmodule

