module buart #(
  parameter FREQ_MHZ = 2,
  parameter BAUDS    = 115200	       
) (
    input clk,
    input resetq,
    output tx,
    input  rx,
    input  wr,
    input  rd,
    input  [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output valid
);

  // Calculate the divider for the baud rate
  parameter BAUD_DIV = (FREQ_MHZ * 1000000) / (BAUDS * 16);

  // Internal registers and signals
  reg [7:0] recv_pattern;
  reg [2:0] recv_divcnt;
  reg recv_start;
  reg [7:0] recv_buf_data;
  reg recv_buf_valid;

  reg [7:0] send_pattern;
  reg [2:0] send_divcnt;
  reg send_start;
  reg [7:0] tx_data_reg;
  reg tx_start;
  reg tx_done;

  // State definitions for receive state machine
  typedef enum reg [1:0] {IDLE, RECEIVE, DONE} recv_state_t;
  recv_state_t recv_state, recv_next_state;

  // State definitions for transmit state machine
  typedef enum reg [1:0] {IDLE, SEND, STOP} send_state_t;
  send_state_t send_state, send_next_state;

  // Assign outputs
  assign tx = (send_state == SEND) ? (send_divcnt == 0) : 1'b1;
  assign rx_data = recv_buf_data;
  assign busy = (send_state != IDLE);
  assign valid = recv_buf_valid;

  // Receive state machine
  always @(posedge clk or posedge resetq) begin
    if (resetq) begin
      recv_state <= IDLE;
      recv_divcnt <= 3'b000;
      recv_start <= 1'b0;
      recv_buf_data <= 8'b0;
      recv_buf_valid <= 1'b0;
    end else begin
      recv_state <= recv_next_state;
      if (recv_state == RECEIVE) begin
        recv_divcnt <= recv_divcnt + 1;
        if (recv_divcnt == BAUD_DIV - 1) begin
          recv_divcnt <= 3'b000;
          recv_pattern <= {recv_pattern[6:0], rx};
          if (recv_divcnt == BAUD_DIV - 2) begin
            recv_buf_data <= recv_pattern;
            recv_buf_valid <= 1'b1;
          end
        end
      end else if (recv_state == DONE) begin
        recv_buf_valid <= 1'b0;
      end
    end
  end

  always @(*) begin
    recv_next_state = recv_state;
    case (recv_state)
      IDLE: begin
        if (rx == 1'b0) begin
          recv_start <= 1'b1;
          recv_next_state = RECEIVE;
        end
      end
      RECEIVE: begin
        if (recv_divcnt == BAUD_DIV - 2) begin
          recv_next_state = DONE;
        end
      end
      DONE: begin
        recv_next_state = IDLE;
      end
    endcase
  end

  // Transmit state machine
  always @(posedge clk or posedge resetq) begin
    if (resetq) begin
      send_state <= IDLE;
      send_divcnt <= 3'b000;
      send_start <= 1'b0;
      tx_data_reg <= 8'b0;
      tx_start <= 1'b0;
      tx_done <= 1'b0;
    end else begin
      send_state <= send_next_state;
      if (send_state == SEND) begin
        send_divcnt <= send_divcnt + 1;
        if (send_divcnt == BAUD_DIV - 1) begin
          send_divcnt <= 3'b000;
          tx <= send_pattern[7];
          send_pattern <= {send_pattern[6:0], 1'b0};
          if (send_divcnt == BAUD_DIV - 2) begin
            send_next_state = STOP;
          end
        end
      end else if (send_state == STOP) begin
        send_divcnt <= send_divcnt + 1;
        if (send_divcnt == BAUD_DIV - 1) begin
          send_divcnt <= 3'b000;
          tx <= 1'b1;
          send_next_state = IDLE;
          tx_done <= 1'b1;
        end
      end
    end
  end

  always @(*) begin
    send_next_state = send_state;
    case (send_state)
      IDLE: begin
        if (wr) begin
          tx_data_reg <= tx_data;
          send_start <= 1'b1;
          send_next_state = SEND;
        end
      end
      SEND: begin
        if (send_divcnt == BAUD_DIV - 2) begin
          send_next_state = STOP;
        end
      end
      STOP: begin
        if (send_divcnt == BAUD_DIV - 2) begin
          send_next_state = IDLE;
        end
      end
    endcase
  end

endmodule

module partsel_00815(
  input [3:0] ctrl,
