  assign c = a * b;
  assign d = c >> 16;
  assign e = c << 16;
  assign f = d | e;
  assign g = f & C0;
  assign h = g ^ C1;
  assign i = h + C2;
  assign j = i - C3;
  assign k = j * j;
  assign l = k >> 8;
  assign m = k << 8;
  assign n = l | m;
  assign o = n & C0;
  assign p = o ^ C1;
  assign q = p + C2;
  assign r = q - C3;
  assign s = r * s;
  assign t = s >> 24;
  assign u = s << 24;
  assign v = t | u;
  assign w = v & C0;
  assign x = w ^ C1;
  assign y0 = x + C2;
  assign y1 = y0 - C3;
  assign y2 = y1 * y1;
  assign y3 = y2 >> 16;
  assign y4 = y2 << 16;
  assign y5 = y3 | y4;
  assign y6 = y5 & C0;
  assign y7 = y6 ^ C1;
  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

