module CW_REGISTER(
    input wire [2:0] D,
    input wire [2:0] A,
    input wire WR,
    input wire RD,
    input wire CLK,
    input wire RST,
    output wire WCTRL,
    output reg [6:0] Y
);

    // Internal registers to store current and next states
    reg [2:0] data_reg;
    reg [2:0] next_data;
    reg [2:0] control_reg;
    reg [2:0] next_control;

    // Combinational logic to determine next states
    always @(*) begin
        next_data = data_reg;
        next_control = control_reg;
        if (WR) begin
            next_data = D;
            next_control = A;
        end
        if (RD) begin
            next_data = data_reg;
            next_control = A;
        end
    end

    // Sequential logic to update registers on clock edges
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            data_reg <= 3'b000;
            control_reg <= 3'b000;
        end else begin
            data_reg <= next_data;
            control_reg <= next_control;
        end
    end

    // Combinational logic to convert stored data into a one-hot encoded output
    always @(*) begin
        Y = 7'b0000000;
        case (control_reg)
            3'b000: Y[0] = 1'b1;
            3'b001: Y[1] = 1'b1;
            3'b010: Y[2] = 1'b1;
            3'b011: Y[3] = 1'b1;
            3'b100: Y[4] = 1'b1;
            3'b101: Y[5] = 1'b1;
            3'b110: Y[6] = 1'b1;
            default: Y = 7'b0000000;
        endcase
    end

    // Output the write control signal
    assign WCTRL = WR;

endmodule

