module wideexpr_00654(
  input [7:0] ctrl,
  input [0:0] u0,
  input [1:0] u1,
  input [2:0] u2,
  input [3:0] u3,
  input [4:0] u4,
  input [5:0] u5,
  input [6:0] u6,
  input [7:0] u7,
  input signed [0:0] s0,
  input signed [1:0] s1,
  input signed [2:0] s2,
  input signed [3:0] s3,
  input signed [4:0] s4,
  input signed [5:0] s5,
  input signed [6:0] s6,
  input signed [7:0] s7,
  output [127:0] y
);

  reg [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  always @(*) begin
    // y0: Check if s5 is not equal to specific negative values
    if (s5 != -1 && s5 != -2 && s5 != -3)
      y0 = 16'hFFFF;
    else
      y0 = 16'h0000;

    // y1: Compute a value based on s2 and s3
    y1 = s2 * s3;

    // y2: Multiplexer using ctrl bits to select between shifted values
    if (ctrl[0])
      y2 = u3 << 4;
    else
      y2 = u4 << 2;

    // y3: Conditionally compute different expressions based on multiple ctrl bits and apply an XOR
    if (ctrl[1] && ctrl[2])
      y3 = (u5 + u6) ^ s7;
    else if (ctrl[1])
      y3 = u5 ^ s6;
    else
      y3 = u6 ^ s5;

    // y4: Extend and negate s7
    y4 = ~s7;

    // y5: Compare complex expressions involving s1, s5, u3, u4, and s6
    if (s1 + s5 > u3 + u4 && s6 < s7)
      y5 = 16'hAAAA;
    else
      y5 = 16'h5555;

    // y6: Select between s4, a constant, or s0 based on ctrl bits
    if (ctrl[3])
      y6 = 16'h1234;
    else if (ctrl[4])
      y6 = s4;
    else
      y6 = s0;

    // y7: Constant
    y7 = 16'hDEAD;
  end

  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

