module io_ps2_keyboard(
    input wire clk,
    input wire kbd_clk,
    input wire kbd_dat,
    output reg interrupt,
    output reg [7:0] scanCode
);

    parameter CLK_SPEED = 50_000_000; // 50 MHz system clock
    parameter TIMEOUT_CONST = CLK_SPEED / 1000; // 1 ms timeout
    parameter DEBOUNCE_CONST = CLK_SPEED / 10000; // 10 ms debounce

    reg [7:0] shift_reg;
    reg clk_filter;
    reg timeout;
    reg [2:0] bitsCount;
    reg [15:0] timeout_counter;
    reg [15:0] debounce_counter;

    always @(posedge clk) begin
        // Debounce logic
        if (kbd_clk) begin
            debounce_counter <= debounce_counter + 1;
        end else begin
            debounce_counter <= 0;
        end

        if (debounce_counter >= DEBOUNCE_CONST) begin
            clk_filter <= kbd_clk;
        end

        // Timeout logic
        if (clk_filter) begin
            timeout_counter <= timeout_counter + 1;
        end else begin
            timeout_counter <= 0;
        end

        if (timeout_counter >= TIMEOUT_CONST) begin
            timeout <= 1;
        end else begin
            timeout <= 0;
        end

        // Data shifting and bit counting
        if (clk_filter && !timeout) begin
            shift_reg <= {shift_reg[6:0], kbd_dat};
            bitsCount <= bitsCount + 1;

            if (bitsCount == 8) begin
                scanCode <= shift_reg;
                interrupt <= 1;
                bitsCount <= 0;
                shift_reg <= 0;
                timeout_counter <= 0;
                debounce_counter <= 0;
            end
        end else begin
            interrupt <= 0;
        end
    end

endmodule

