module inv_shiftrows(
    input wire [127:0] shiftin,
    output wire [127:0] shiftout
);
    // Internal registers to hold each byte of the input
    reg [7:0] r0, r1, r2, r3, r4, r5, r6, r7;
    reg [7:0] r8, r9, r10, r11, r12, r13, r14, r15;

    // Assign each byte of the input to the internal registers based on the fixed pattern
    assign r0 = shiftin[7:0];
    assign r1 = shiftin[15:8];
    assign r2 = shiftin[23:16];
    assign r3 = shiftin[31:24];
    assign r4 = shiftin[39:32];
    assign r5 = shiftin[47:40];
    assign r6 = shiftin[55:48];
    assign r7 = shiftin[63:56];
    assign r8 = shiftin[71:64];
    assign r9 = shiftin[79:72];
    assign r10 = shiftin[87:80];
    assign r11 = shiftin[95:88];
    assign r12 = shiftin[103:96];
    assign r13 = shiftin[111:104];
    assign r14 = shiftin[119:112];
    assign r15 = shiftin[127:120];

    // Concatenate the internal registers into the output in the specified order
    assign shiftout = {r15, r13, r11, r9, r7, r5, r3, r1, r0, r2, r4, r6, r8, r10, r12, r14};
endmodule

module wideexpr_00723(
  input [7:0] ctrl,
  input [0:0] u0,
  input [1:0] u1,
  input [2:0] u2,
  input [3:0] u3,
  input [4:0] u4,
  input [5:0] u5,
  input [6:0] u6,
  input [7:0] u7,
  input signed [0:0] s0,
  input signed [1:0] s1,
  input signed [2:0] s2,
  input signed [3:0] s3,
  input signed [4:0] s4,
  input signed [5:0] s5,
  input signed [6:0] s6,
  input signed [7:0] s7,
  output [127:0] y
);

  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  assign y0 = (ctrl[0]) ? (u0 + u1) : (u0 - u1);
  assign y1 = (ctrl[1]) ? (u2 << 2) : (u2 >> 2);
  assign y2 = (ctrl[2]) ? (s0 * s1) : (s0 / s1);
  assign y3 = (ctrl[3]) ? (u3 & u4) : (u3 | u4);
  assign y4 = (ctrl[4]) ? (s2 ^ s3) : (~s2);
  assign y5 = (ctrl[5]) ? (u5[3:0] + u6[3:0]) : (u5[3:0] - u6[3:0]);
  assign y6 = (ctrl[6]) ? (s4[5:0] << 4) : (s4[5:0] >> 4);
  assign y7 = (ctrl[7]) ? (u7[7:0] * u7[7:0]) : (u7[7:0] / u7[7:0]);

  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

