module vga_controller(
    input wire RST,
    input wire CLK,
    output wire H_SYNC,
    output wire V_SYNC,
    output wire [10:0] X,
    output wire [10:0] Y,
    output wire DISP_EN
);

    // Parameters for VGA timing
    parameter H_ACTIVE = 1280;
    parameter H_FRONT_PORCH = 160;
    parameter H_SYNC_WIDTH = 96;
    parameter H_BACK_PORCH = 48;
    parameter H_TOTAL = H_ACTIVE + H_FRONT_PORCH + H_SYNC_WIDTH + H_BACK_PORCH;

    parameter V_ACTIVE = 720;
    parameter V_FRONT_PORCH = 20;
    parameter V_SYNC_WIDTH = 5;
    parameter V_BACK_PORCH = 22;
    parameter V_TOTAL = V_ACTIVE + V_FRONT_PORCH + V_SYNC_WIDTH + V_BACK_PORCH;

    // Internal registers
    reg [10:0] h_counter;
    reg [10:0] v_counter;
    reg [10:0] x;
    reg [10:0] y;
    reg h_sync;
    reg v_sync;
    reg disp_en;

    // Sequential logic
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            h_counter <= 0;
            v_counter <= 0;
            x <= 0;
            y <= 0;
            h_sync <= 1;
            v_sync <= 1;
            disp_en <= 0;
        end else begin
            // Horizontal sync generation
            if (h_counter < H_TOTAL - 1) begin
                h_counter <= h_counter + 1;
                if (h_counter >= H_ACTIVE + H_FRONT_PORCH && h_counter < H_ACTIVE + H_FRONT_PORCH + H_SYNC_WIDTH) begin
                    h_sync <= 0;
                end else begin
                    h_sync <= 1;
                end
            end else begin
                h_counter <= 0;
                h_sync <= 1;
            end

            // Vertical sync generation
            if (h_counter == 0) begin
                if (v_counter < V_TOTAL - 1) begin
                    v_counter <= v_counter + 1;
                    if (v_counter >= V_ACTIVE + V_FRONT_PORCH && v_counter < V_ACTIVE + V_FRONT_PORCH + V_SYNC_WIDTH) begin
                        v_sync <= 0;
                    end else begin
                        v_sync <= 1;
                    end
                end else begin
                    v_counter <= 0;
                    v_sync <= 1;
                end
            end

            // Display enable generation
            if (h_counter >= H_ACTIVE && h_counter < H_TOTAL && v_counter >= V_ACTIVE && v_counter < V_TOTAL) begin
                disp_en <= 1;
            end else begin
                disp_en <= 0;
            end

            // Pixel position tracking
            if (h_counter == H_TOTAL - 1) begin
                x <= x + 1;
                if (x == H_ACTIVE - 1) begin
                    x <= 0;
                    y <= y + 1;
                    if (y == V_ACTIVE - 1) begin
                        y <= 0;
                    end
                end
            end
        end
    end

    // Output assignments
    assign H_SYNC = h_sync;
    assign V_SYNC = v_sync;
    assign DISP_EN = disp_en;
    assign X = x;
    assign Y = y;

endmodule

