module tx_add_preamble(
    input wire clk,
    input wire data_valid_in,
    input wire [7:0] data_in,
    output reg data_valid_out,
    output reg [7:0] data_out
);

reg [63:0] delay_data;
reg [7:0] delay_data_valid;
reg [2:0] state;

parameter IDLE = 3'b000;
parameter SEND_PREAMBLE_1 = 3'b001;
parameter SEND_PREAMBLE_2 = 3'b010;
parameter SEND_DATA = 3'b011;

always @(posedge clk) begin
    case (state)
        IDLE:
            if (data_valid_in) begin
                state <= SEND_PREAMBLE_1;
                delay_data_valid[1] <= 1;
                delay_data[7:0] <= 8'b01010101;
            end
        SEND_PREAMBLE_1:
            state <= SEND_PREAMBLE_2;
            delay_data_valid[0] <= 1;
            delay_data[15:8] <= 8'b11010101;
        SEND_PREAMBLE_2:
            state <= SEND_DATA;
            delay_data_valid[7:2] <= delay_data_valid[6:1];
            delay_data[63:56] <= delay_data[55:48];
            delay_data[47:40] <= delay_data[39:32];
            delay_data[31:24] <= delay_data[23:16];
            delay_data[23:16] <= delay_data[15:8];
            delay_data[15:8] <= delay_data[7:0];
            delay_data[7:0] <= data_in;
        SEND_DATA:
            if (delay_data_valid[0] == 0) begin
                state <= IDLE;
            end else begin
                delay_data_valid[7:1] <= delay_data_valid[6:0];
                delay_data[63:56] <= delay_data[55:48];
                delay_data[47:40] <= delay_data[39:32];
                delay_data[31:24] <= delay_data[23:16];
                delay_data[23:16] <= delay_data[15:8];
                delay_data[15:8] <= delay_data[7:0];
                delay_data[7:0] <= 8'b0;
            end
    endcase
end

always @(*) begin
    data_valid_out = 0;
    data_out = 0;
    if (state == SEND_PREAMBLE_1) begin
        data_valid_out = 1;
        data_out = 8'b11010101;
    end else if (state == SEND_PREAMBLE_2) begin
        data_valid_out = 1;
        data_out = 8'b01010101;
    end else if (state == SEND_DATA) begin
        data_valid_out = delay_data_valid[0];
        data_out = delay_data[7:0];
    end
end

endmodule

