module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);

    reg [7:0] scan_code_reg;
    reg [3:0] bit_count;
    reg scan_ready_reg;
    reg parity_error;

    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            scan_code_reg <= 8'b0;
            bit_count <= 4'b0;
            scan_ready_reg <= 1'b0;
            parity_error <= 1'b0;
        end else begin
            if (bit_count < 4'b1000) begin
                if (i_clock'event && i_clock == 1'b0) begin
                    scan_code_reg <= {scan_code_reg[6:0], i_data};
                    bit_count <= bit_count + 1;
                end
            end else begin
                if (i_clock'event && i_clock == 1'b0) begin
                    parity_error <= (i_data != ^scan_code_reg);
                    scan_ready_reg <= 1'b1;
                end
            end
        end
    end

    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            scan_ready <= 1'b0;
        end else begin
            scan_ready <= scan_ready_reg;
        end
    end

    assign scan_code = scan_code_reg;

endmodule

