module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);

	// Internal 42-bit registers to prevent overflow
	reg signed [41:0] a_r_reg, a_i_reg, b_r_reg, b_i_reg, w_r_reg, w_i_reg;
	reg signed [41:0] temp_r, temp_i;

	always @(*) begin
		case (state)
			2'b00, 2'b11: begin
				outvalid = 0;
				op_r = 0;
				op_i = 0;
				delay_r = 0;
				delay_i = 0;
			end
			2'b01: begin
				outvalid = 1;
				a_r_reg = {14'b0, din_a_r};
				a_i_reg = {14'b0, din_a_i};
				b_r_reg = {14'b0, din_b_r};
				b_i_reg = {14'b0, din_b_i};
				temp_r = a_r_reg + b_r_reg;
				temp_i = a_i_reg + b_i_reg;
				op_r = temp_r[41:18];
				op_i = temp_i[41:18];
				delay_r = temp_r[17:0];
				delay_i = temp_i[17:0];
			end
			2'b10: begin
				outvalid = 1;
				a_r_reg = {14'b0, din_a_r};
				a_i_reg = {14'b0, din_a_i};
				w_r_reg = {14'b0, w_r};
				w_i_reg = {14'b0, w_i};
				temp_r = a_r_reg * w_r_reg - a_i_reg * w_i_reg;
				temp_i = a_r_reg * w_i_reg + a_i_reg * w_r_reg;
				op_r = temp_r[41:18];
				op_i = temp_i[41:18];
				delay_r = temp_r[17:0];
				delay_i = temp_i[17:0];
			end
			default: begin
				outvalid = 0;
				op_r = 0;
				op_i = 0;
				delay_r = 0;
				delay_i = 0;
			end
		endcase
	end

endmodule

module AMSG_kirsch_e(
  input [7:0] p1, p2, p3, p4, p6, p7, p8, p9,
  output reg [7:0] y1
    );

  // Intermediate sums
  wire [15:0] sum1 = p1 + p2 + p3;
  wire [15:0] sum2 = p4 + p6 + p9;
  wire [15:0] sum3 = p2 + p3 + p6;
  wire [15:0] sum4 = p3 + p6 + p7;
  wire [15:0] sum5 = p6 + p7 + p8;
  wire [15:0] sum6 = p7 + p8 + p9;
  wire [15:0] sum7 = p1 + p4 + p7;
  wire [15:0] sum8 = p2 + p5 + p8;

  // Weighted sums
  wire [15:0] weighted_sum1 = sum1 * 2;
  wire [15:0] weighted_sum2 = sum2 * 3;
  wire [15:0] weighted_sum3 = sum3 * 4;
  wire [15:0] weighted_sum4 = sum4 * 5;
  wire [15:0] weighted_sum5 = sum5 * 6;
  wire [15:0] weighted_sum6 = sum6 * 7;
  wire [15:0] weighted_sum7 = sum7 * 8;
  wire [15:0] weighted_sum8 = sum8 * 9;

  // Weighted subtraction
  wire [15:0] weighted_diff = weighted_sum1 - weighted_sum2;

  // Clamping to 8 bits
  assign y1 = (weighted_diff > 255) ? 255 : (weighted_diff < 0) ? 0 : weighted_diff[7:0];

endmodule

