module controller_mm_interconnect_0_rsp_demux_005
(
    input  [1-1      : 0]   sink_valid,
    input  [76-1    : 0]   sink_data, 
    input  [10-1 : 0]   sink_channel, 
    input                         sink_startofpacket,
    input                         sink_endofpacket,
    output                        sink_ready,

    output reg                      src0_valid,
    output reg [76-1    : 0] src0_data, 
    output reg [10-1 : 0] src0_channel, 
    output reg                      src0_startofpacket,
    output reg                      src0_endofpacket,
    input                           src0_ready,

    output reg                      src1_valid,
    output reg [76-1    : 0] src1_data, 
    output reg [10-1 : 0] src1_channel, 
    output reg                      src1_startofpacket,
    output reg                      src1_endofpacket,
    input                           src1_ready,

    input clk,
    input reset
);

    reg [1:0] valid_destinations;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            src0_valid <= 0;
            src0_data <= 0;
            src0_channel <= 0;
            src0_startofpacket <= 0;
            src0_endofpacket <= 0;
            src1_valid <= 0;
            src1_data <= 0;
            src1_channel <= 0;
            src1_startofpacket <= 0;
            src1_endofpacket <= 0;
            sink_ready <= 1;
        end else begin
            src0_valid <= 0;
            src0_data <= 0;
            src0_channel <= 0;
            src0_startofpacket <= 0;
            src0_endofpacket <= 0;
            src1_valid <= 0;
            src1_data <= 0;
            src1_channel <= 0;
            src1_startofpacket <= 0;
            src1_endofpacket <= 0;
            sink_ready <= 1;

            if (sink_valid) begin
                valid_destinations <= 0;
                if (sink_channel == 0 && src0_ready) begin
                    valid_destinations[0] <= 1;
                end
                if (sink_channel == 1 && src1_ready) begin
                    valid_destinations[1] <= 1;
                end

                if (valid_destinations[0]) begin
                    src0_valid <= 1;
                    src0_data <= sink_data;
                    src0_channel <= sink_channel;
                    src0_startofpacket <= sink_startofpacket;
                    src0_endofpacket <= sink_endofpacket;
                    sink_ready <= 0;
                end else if (valid_destinations[1]) begin
                    src1_valid <= 1;
                    src1_data <= sink_data;
                    src1_channel <= sink_channel;
                    src1_startofpacket <= sink_startofpacket;
                    src1_endofpacket <= sink_endofpacket;
                    sink_ready <= 0;
                end
            end
        end
    end

endmodule

