module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers for pipeline stages
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;

    // Control signals
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;

    // State machine states
    typedef enum reg [1:0] {ZERO, ONE, TWO} state_t;
    state_t state, next_state;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        load_p1 = 1'b0;
        load_p2 = 1'b0;
        load_p1_from_p2 = 1'b0;

        case (state)
            ZERO: begin
                if (s_valid && m_ready) begin
                    next_state = ONE;
                    load_p1 = 1'b1;
                end
            end
            ONE: begin
                if (m_ready) begin
                    next_state = TWO;
                    load_p2 = 1'b1;
                end
            end
            TWO: begin
                if (m_ready) begin
                    next_state = ZERO;
                    load_p1_from_p2 = 1'b1;
                end
            end
        endcase
    end

    // Data pipeline logic
    always @(posedge clk) begin
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= data_p1;
        end
        if (load_p1_from_p2) begin
            data_p1 <= data_p2;
        end
    end

    // Handshake signals
    assign s_ready = (state == ZERO);
    assign m_valid = (state == TWO);

    // Output data
    assign m_data = data_p2;

endmodule

