    input [5:0] opcode,
    output reg RegDst, Jump, Branch, bne, MemRead, MemtoReg, MemWrite, ALUsrc, RegWrite,
    output reg [1:0] ALUop
);
    always @(*) begin
        // Initialize all control signals to default state
        RegDst = 0;
        Jump = 0;
        Branch = 0;
        bne = 0;
        MemRead = 0;
        MemtoReg = 0;
        MemWrite = 0;
        ALUsrc = 0;
        RegWrite = 0;
        ALUop = 2'b00; // Default ALU operation (add)

        // Decode the opcode and set the appropriate control signals
        case (opcode)
            6'b000000: begin // R-type instruction
                RegDst = 1;
                Jump = 0;
                Branch = 0;
                bne = 0;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 0;
                ALUsrc = 0;
                RegWrite = 1;
                ALUop = 2'b00; // Add
            end
            6'b001000: begin // I-type lw
                RegDst = 0;
                Jump = 0;
                Branch = 0;
                bne = 0;
                MemRead = 1;
                MemtoReg = 1;
                MemWrite = 0;
                ALUsrc = 1;
                RegWrite = 1;
                ALUop = 2'b00; // Add
            end
            6'b001010: begin // I-type sw
                RegDst = 0;
                Jump = 0;
                Branch = 0;
                bne = 0;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 1;
                ALUsrc = 1;
                RegWrite = 0;
                ALUop = 2'b00; // Add
            end
            6'b000100: begin // I-type beq
                RegDst = 0;
                Jump = 0;
                Branch = 1;
                bne = 0;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 0;
                ALUsrc = 0;
                RegWrite = 0;
                ALUop = 2'b00; // Add
            end
            6'b000101: begin // I-type bne
                RegDst = 0;
                Jump = 0;
                Branch = 1;
                bne = 1;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 0;
                ALUsrc = 0;
                RegWrite = 0;
                ALUop = 2'b00; // Add
            end
            6'b000010: begin // J-type jump
                RegDst = 0;
                Jump = 1;
                Branch = 0;
                bne = 0;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 0;
                ALUsrc = 0;
                RegWrite = 0;
                ALUop = 2'b00; // Add
            end
            default: begin
                // Default case, should not happen for valid MIPS instructions
                RegDst = 0;
                Jump = 0;
                Branch = 0;
                bne = 0;
                MemRead = 0;
                MemtoReg = 0;
                MemWrite = 0;
                ALUsrc = 0;
                RegWrite = 0;
                ALUop = 2'b00; // Add
            end
        endcase
    end
endmodule

module Mapper66(input clk, input ce, input reset,
                input [31:0] flags,
                input [15:0] prg_ain, output [21:0] prg_aout,
                input prg_read, prg_write,                   
                input [7:0] prg_din,
                output prg_allow,                            
                input [13:0] chr_ain, output [21:0] chr_aout,
                output chr_allow,                      
                output vram_a10,                             
                output vram_ce);

    reg [15:0] prg_bank;
    reg [15:0] chr_bank;
    reg [21:0] prg_aout_reg;
    reg [21:0] chr_aout_reg;
    reg prg_allow_reg;
    reg chr_allow_reg;
    reg vram_a10_reg;
    reg vram_ce_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prg_bank <= 16'h0000;
            chr_bank <= 16'h0000;
            prg_aout_reg <= 22'h00000;
            chr_aout_reg <= 22'h00000;
            prg_allow_reg <= 1'b0;
            chr_allow_reg <= 1'b0;
            vram_a10_reg <= 1'b0;
            vram_ce_reg <= 1'b0;
        end else if (ce) begin
            if (prg_write) begin
                case (flags[31:28])
                    4'b0000: prg_bank <= prg_din;
                    4'b0001: chr_bank <= prg_din;
                    default: ; // No action for other flags
                endcase
            end

            prg_aout_reg <= (prg_ain[15:0] + prg_bank) << 1;
            chr_aout_reg <= (chr_ain[13:0] + chr_bank) << 1;
            prg_allow_reg <= 1'b1;
            chr_allow_reg <= 1'b1;
            vram_a10_reg <= prg_ain[16];
            vram_ce_reg <= 1'b1;
        end
    end

    assign prg_aout = prg_aout_reg;
    assign chr_aout = chr_aout_reg;
    assign prg_allow = prg_allow_reg;
    assign chr_allow = chr_allow_reg;
    assign vram_a10 = vram_a10_reg;
    assign vram_ce = vram_ce_reg;

endmodule

