module add8se_8UN (
    A,
    B,
    O
);

input [7:0] A;
input [7:0] B;
output [8:0] O;

// Intermediate signals for carry generation and propagation
wire sig_46, sig_47, sig_48, sig_49, sig_50, sig_51, sig_52, sig_53, sig_54;

// Full adder logic for each bit position
assign sig_46 = A[0] ^ B[0];
assign sig_47 = A[1] ^ B[1] ^ sig_46;
assign sig_48 = A[2] ^ B[2] ^ sig_47;
assign sig_49 = A[3] ^ B[3] ^ sig_48;
assign sig_50 = A[4] ^ B[4] ^ sig_49;
assign sig_51 = A[5] ^ B[5] ^ sig_50;
assign sig_52 = A[6] ^ B[6] ^ sig_51;
assign sig_53 = A[7] ^ B[7] ^ sig_52;

// Final carry-out
assign sig_54 = A[7] & B[7] | sig_52 & sig_53 | sig_50 & sig_51 | sig_48 & sig_49 | sig_46 & sig_47;

// Output bits
assign O[8] = sig_54; // Carry-out
assign O[7] = A[7] ^ B[7] ^ sig_54;
assign O[6] = A[6] ^ B[6] ^ sig_53;
assign O[5] = A[5] ^ B[5] ^ sig_52;
assign O[4] = A[4] ^ B[4] ^ sig_51;
assign O[3] = A[3] ^ B[3] ^ sig_50;
assign O[2] = A[2] ^ B[2] ^ sig_49;
assign O[1] = A[1] ^ B[1] ^ sig_48;
assign O[0] = A[0] ^ B[0] ^ sig_47;

endmodule

