module gf180mcu_fd_sc_mcu7t5v0__xor2_4( A2, A1, Z, VDD, VSS );
input A1, A2;
output Z;

inout VDD, VSS;

wire not_A1, not_A2, and_out, or_out;

// Invert A1 and A2
not (not_A1, A1);
not (not_A2, A2);

// AND the inverted inputs
and (and_out, not_A1, not_A2);

// OR the original inputs
or (or_out, A1, A2);

// XOR output is the OR of the AND of inverted inputs and the OR of original inputs
and (Z, and_out, or_out);

// Power supply connections
assign VDD = 1'b1;
assign VSS = 1'b0;
endmodule

module cnt_8_60(
