    wire w_OF;
    wire w_CNT_CHECK;

    // Internal logic to manage overflow and counting enable
    assign w_OF = (reg_COUNTER == 6'd60);
    assign w_CNT_CHECK = ~w_OF & pi_enable;

    // Sequential logic to update the counter
    always @(posedge clk or posedge rst or posedge pi_cnt_rst) begin
        if (rst || pi_cnt_rst) begin
            reg_COUNTER <= 6'd8; // Reset to 8 (binary 001000)
        end else if (w_CNT_CHECK) begin
            reg_COUNTER <= reg_COUNTER + 1; // Increment counter if not in overflow and enabled
        end
    end

    // Output the current count value
    assign po_data = reg_COUNTER;

endmodule

