module alu
  (
   alu_src1,
   alu_src2,
   alu_opcode,
   minus_is_zero,
   less_than,
   less_than_unsigned,
   alu_result
   );
input wire [31:0]       alu_src1;
input wire [31:0]       alu_src2;
input wire [3:0]       alu_opcode;
output reg [31:0]       alu_result;
output reg             minus_is_zero;
output reg             less_than;
output reg             less_than_unsigned;

always @(*) begin
  case (alu_opcode)
    4'b0000: begin // ADD
      alu_result = alu_src1 + alu_src2;
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_src1 < alu_src2);
      less_than_unsigned = (alu_src1 < alu_src2);
    end
    4'b0001: begin // SUB
      alu_result = alu_src1 - alu_src2;
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_src1 < alu_src2);
      less_than_unsigned = (alu_src1 < alu_src2);
    end
    4'b0010: begin // OR
      alu_result = alu_src1 | alu_src2;
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    4'b0011: begin // AND
      alu_result = alu_src1 & alu_src2;
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    4'b0100: begin // XOR
      alu_result = alu_src1 ^ alu_src2;
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    4'b0101: begin // SLL
      alu_result = alu_src1 << alu_src2[4:0];
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    4'b0110: begin // SRL
      alu_result = alu_src1 >> alu_src2[4:0];
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    4'b0111: begin // SRA
      alu_result = $signed(alu_src1) >>> alu_src2[4:0];
      minus_is_zero = (alu_result == 32'b0);
      less_than = (alu_result < 32'b0);
      less_than_unsigned = (alu_result < 32'b0);
    end
    default: begin
      alu_result = 32'b0;
      minus_is_zero = 1'b1;
      less_than = 1'b0;
      less_than_unsigned = 1'b0;
    end
  endcase
end

endmodule

