    assign full_n = (count == DEPTH);

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            count <= 0;
        end else begin
            if (write && !full_n) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 1;
                count <= count + 1;
            end
            if (read && !empty_n) begin
                rd_ptr <= rd_ptr + 1;
                count <= count - 1;
            end
        end
    end

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            dout <= 0;
        end else begin
            if (!empty_n) begin
                dout <= mem[rd_ptr];
            end
        end
    end
