module wideexpr_00744(
  input [7:0] ctrl,
  input [0:0] u0,
  input [1:0] u1,
  input [2:0] u2,
  input [3:0] u3,
  input [4:0] u4,
  input [5:0] u5,
  input [6:0] u6,
  input [7:0] u7,
  input signed [0:0] s0,
  input signed [1:0] s1,
  input signed [2:0] s2,
  input signed [3:0] s3,
  input signed [4:0] s4,
  input signed [5:0] s5,
  input signed [6:0] s6,
  input signed [7:0] s7,
  output [127:0] y
);

  // Intermediate signals
  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  // Assign statements for each intermediate signal based on ctrl and inputs
  assign y0 = (ctrl[0]) ? (u0 << u1) : (u0 | u1);
  assign y1 = (ctrl[1]) ? (u2 & u3) : (u2 + u3);
  assign y2 = (ctrl[2]) ? (u4 ^ u5) : (u4 - u5);
  assign y3 = (ctrl[3]) ? (u6 >> u7) : (u6 * u7);
  assign y4 = (ctrl[4]) ? (s0 + s1) : (s0 - s1);
  assign y5 = (ctrl[5]) ? (s2 * s3) : (s2 / s3);
  assign y6 = (ctrl[6]) ? (s4 ^ s5) : (s4 & s5);
  assign y7 = (ctrl[7]) ? (s6 + s7) : (s6 - s7);

  // Concatenate the intermediate signals to form the output
  assign y = {y0, y1, y2, y3, y4, y5, y6, y7};

endmodule

module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output reg [31:0] result, 
	output reg [31:0] remainder,
	output reg done 
);
reg [31:0] internal_dividend;
reg [31:0] internal_divisor;
reg [31:0] internal_remainder;
reg [31:0] internal_result;
reg start_new_division;
reg [4:0] counter;

always @(posedge CLK) begin
	if (start_new_division) begin
		internal_dividend <= Divider;
		internal_divisor <= Divisor;
		internal_remainder <= Divider;
		internal_result <= 0;
		counter <= 0;
		done <= 0;
	end else if (counter < 32) begin
		if (internal_remainder >= internal_divisor) begin
			internal_remainder <= internal_remainder - internal_divisor;
			internal_result <= internal_result + 1;
		end
		counter <= counter + 1;
	end else begin
		result <= internal_result;
		remainder <= internal_remainder;
		done <= 1;
	end
end

always @(posedge CLK) begin
	if (Divisor != 0 && Divider != 0 && (Divisor != internal_divisor || Divider != internal_divisor)) begin
		start_new_division <= 1;
	end else begin
		start_new_division <= 0;
	end
end

endmodule

