   reg [15:0] mem [0:63];
   reg        loaded;
   reg [16:0] largest;
   reg [31:0] rand_pat;
   wire       ready;
   wire       muxSel;

   assign CacheHit = 0;
   assign DataOut = (err) ? mem[Addr[5:0]] : mem[Addr[5:0]];
   assign Done = (Wr | Rd) & ~Stall;
   assign Stall = ~ready & (Wr | Rd);
   assign err = ready & (Addr[0] == 1);

   always @(posedge clk or posedge rst) begin
      if (rst) begin
         loaded <= 0;
         largest <= 0;
         rand_pat <= 32'h0;
      end else begin
         if (Wr) begin
            mem[Addr[5:0]] <= DataIn;
            largest <= (Addr > largest) ? Addr : largest;
         end
         rand_pat <= {rand_pat[30:0], 1'b0};
         #1;
      end
   end

   always @(*) begin
      ready = (Wr | Rd) & (rand_pat[0] == 0);
      muxSel = ready & Wr;
   end

endmodule

module ldrw
  (
   input [7:0] 	 cell0,
   input [7:0] 	 cell1,
   input [7:0] 	 cell2,
   input [7:0] 	 cell3,
   output [31:0] argb
   );

  wire [7:0] count;
  wire [7:0] sum_low_bits;
  wire [7:0] argb_pattern;

  // Calculate the sum of the lower 7 bits of each input cell
  assign sum_low_bits = (cell0[6] + cell1[6] + cell2[6] + cell3[6]) & 7;

  // Shift the sum left by 3 bits to create the count value
  assign count = sum_low_bits << 3;

  // Create the pattern for argb when the 8th bits are set
  assign argb_pattern = 8'h77;

  // Determine the final argb value based on the state of the 8th bits
  assign argb = (cell0[7] | cell1[7] | cell2[7] | cell3[7]) ? 
                {8'b0, 8'b0, 8'b0, argb_pattern} : 
                {count, count, count, 8'b0};

endmodule

