module FixedRoundSigned(
	clk,
	fixed_num,
	round,
	overflow
	);

	input clk;
	input signed [num_width - 1 : 0] fixed_num;
	output reg signed [res_width : 0] round;
	output reg overflow;

	parameter num_width = 16; // Width of the input fixed-point number
	parameter fixed_point_pos = 8; // Position of the fixed point
	parameter res_width = 16; // Width of the result

	// Internal registers
	reg signed [num_width - 1 : 0] original_num;
	reg signed [num_width - 1 : 0] rounded_value;
	reg [num_width - fixed_point_pos - 1 : 0] fractional_part;
	reg [num_width - fixed_point_pos - 2 : 0] adjusted_fractional_part;
	reg [num_width - fixed_point_pos - 1 : 0] overflow_bits;

	always @(posedge clk) begin
		original_num <= fixed_num;
		fractional_part <= original_num & ((1 << (num_width - fixed_point_pos)) - 1);
		adjusted_fractional_part <= fractional_part >> 1;

		case (original_num[fixed_point_pos - 1])
			1'b0: // Positive number
				rounded_value <= original_num - adjusted_fractional_part;
			1'b1: // Negative number
				rounded_value <= original_num + adjusted_fractional_part;
		endcase

		overflow_bits <= original_num >> (num_width - fixed_point_pos);
		overflow <= |overflow_bits;

		round <= rounded_value;
	end

endmodule

