module CLG4_3(x1, y1, x2, y2, x3, y3, x4, y4, c1,
            s1, s2, s3, s4);
input x1, y1, x2, y2, x3, y3, x4, y4, c1;
output s1, s2, s3, s4;

// Internal signals
wire p1, p2, p3, p4; // Sum without carry
wire g1, g2, g3, g4; // Carry generate
wire c2, c3, c4;   // Intermediate carries

// Calculate p and g for each bit pair
assign p1 = x1 ^ y1;
assign g1 = x1 & y1;

assign p2 = x2 ^ y2;
assign g2 = x2 & y2;

assign p3 = x3 ^ y3;
assign g3 = x3 & y3;

assign p4 = x4 ^ y4;
assign g4 = x4 & y4;

// Calculate intermediate carries using ripple carry logic
assign c2 = g1 | (p1 & c1);
assign c3 = g2 | (p2 & (c1 | c2));
assign c4 = g3 | (p3 & (c1 | c2 | c3));

// Calculate final sum bits
assign s1 = p1 ^ c1;
assign s2 = p2 ^ (c1 | c2);
assign s3 = p3 ^ (c1 | c2 | c3);
assign s4 = p4 ^ (c1 | c2 | c3 | c4);

endmodule

