module StreamingDataWidthConverter_Batch_5_regslice_both_w1
#(parameter 
    DataWidth=1
)(
    input ap_clk ,
    input ap_rst,

    input data_in , 
    input vld_in , 
    output ack_in ,
    output data_out, 
    output vld_out,
    input ack_out,
    output apdone_blk
);

    // Internal registers
    reg [1:0] B_V_data_1_state;
    reg [DataWidth-1:0] payload_A;
    reg [DataWidth-1:0] payload_B;
    reg sel_rd;
    reg sel_wr;
    reg [1:0] state;

    // Internal wires
    wire [1:0] next_state;
    wire [DataWidth-1:0] data_out_reg;
    wire vld_out_reg;
    wire ack_in_reg;
    wire apdone_blk_reg;

    // State definitions
    parameter IDLE = 2'b00;
    parameter LOAD_A = 2'b01;
    parameter LOAD_B = 2'b10;
    parameter TRANSFER = 2'b11;

    // State transition logic
    always @(posedge ap_clk or posedge ap_rst) begin
        if (ap_rst) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (vld_in && !ack_out) begin
                    next_state = LOAD_A;
                end
            end
            LOAD_A: begin
                next_state = LOAD_B;
            end
            LOAD_B: begin
                next_state = TRANSFER;
            end
            TRANSFER: begin
                if (ack_out) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Data handling logic
    always @(posedge ap_clk or posedge ap_rst) begin
        if (ap_rst) begin
            payload_A <= 0;
            payload_B <= 0;
            sel_rd <= 0;
            sel_wr <= 0;
        end else begin
            case (state)
                IDLE: begin
                    sel_wr <= 0;
                end
                LOAD_A: begin
                    payload_A <= data_in;
                    sel_wr <= 1;
                end
                LOAD_B: begin
                    payload_B <= data_in;
                    sel_wr <= 1;
                end
                TRANSFER: begin
                    if (sel_rd == 0) begin
                        data_out_reg <= payload_A;
                        sel_rd <= 1;
                    end else begin
                        data_out_reg <= payload_B;
                        sel_rd <= 0;
                    end
                end
            endcase
        end
    end

    // Output logic
    assign data_out = data_out_reg;
    assign vld_out = (state == TRANSFER) && (sel_rd == 0);
    assign ack_in = (state == TRANSFER) && (sel_rd == 1);
