module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);

  reg [3:0] maybe_full;
  reg [3:0] enq_count;
  reg [3:0] deq_count;
  reg [3:0] state_size;
  reg [1:0] state_source;

  assign io_enq_ready = (maybe_full < 4'h10); // Queue not full
  assign io_deq_valid = (enq_count > deq_count); // Queue not empty

  always @(posedge clock or posedge reset) begin
    if (reset) begin
      maybe_full <= 4'b0000;
      enq_count <= 4'b0000;
      deq_count <= 4'b0000;
      state_size <= 4'b0000;
      state_source <= 2'b00;
    end else begin
      if (io_enq_valid && io_enq_ready && do_enq) begin
        enq_count <= enq_count + 1;
        state_size <= io_enq_bits_tl_state_size;
        state_source <= io_enq_bits_tl_state_source;
      end
      if (io_deq_valid && io_deq_ready && do_deq) begin
        deq_count <= deq_count + 1;
      end
      maybe_full <= enq_count - deq_count;
    end
  end

  reg do_enq;
  reg do_deq;

  assign do_enq = io_enq_valid && io_enq_ready;
  assign do_deq = io_deq_valid && io_deq_ready;

  assign io_deq_bits_tl_state_size = state_size;
  assign io_deq_bits_tl_state_source = state_source;

endmodule

module ADDFHXL ( S, CO, A, B, CI);
output S, CO;
input A, B, CI;

// Internal signals for intermediate calculations
wire sum_xor, carry_and1, carry_and2, carry_and3;

// XOR gate to calculate the sum
assign sum_xor = A ^ B ^ CI;

// AND gates to calculate the carry-out
assign carry_and1 = A & B;
assign carry_and2 = A & CI;
assign carry_and3 = B & CI;

// OR gate to combine all carry-generating conditions
assign CO = carry_and1 | carry_and2 | carry_and3;

// Output the sum
assign S = sum_xor;

// Specify block for timing constraints
specify
  // Timing for sum calculation
  S = (A, B, CI) => #1 sum_xor;
  // Timing for carry-out calculation
  CO = (A, B, CI) => #2 CO;
endspecify

endmodule

module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);

  // Internal registers to store intermediate results
  reg [NBITS-1:0] rdata_reg1;
  reg [NBITS-1:0] rdata_reg2;
  reg [NBITS-1:0] rdata_reg3;
  reg [NBITS-1:0] rdata_reg4;

  // Internal signals to store intermediate results
  wire [NBITS-1:0] intermediate1;
  wire [NBITS-1:0] intermediate2;
  wire [NBITS-1:0] intermediate3;
  wire [NBITS-1:0] intermediate4;

  // Process the input data and store intermediate results
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata_reg1 <= 0;
      rdata_reg2 <= 0;
      rdata_reg3 <= 0;
      rdata_reg4 <= 0;
    end else if (valid_rd) begin
      rdata_reg1 <= rdata[0];
      rdata_reg2 <= rdata[256];
      rdata_reg3 <= rdata[512];
      rdata_reg4 <= rdata[768];
    end
  end

  // Combine intermediate results using OR operations
  assign intermediate1 = rdata_reg1 | rdata_reg2;
  assign intermediate2 = rdata_reg3 | rdata_reg4;
  assign intermediate3 = intermediate1 | intermediate2;

  // Final output combining all intermediate results
  assign hrdata = intermediate3;

endmodule

