module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;

    // State encoding
    localparam ZERO = 2'b00;
    localparam ONE = 2'b01;
    localparam TWO = 2'b10;

    // State register
    reg [1:0] state;

    // Internal signals
    reg load_p1;
    reg load_p2;
    reg [1:0] next_state;

    // Combinational logic for state transition and control signals
    always @(*) begin
        case (state)
            ZERO: begin
                if (s_valid && !m_ready) begin
                    next_state = ONE;
                    load_p1 = 1;
                end else if (s_valid && m_ready) begin
                    next_state = TWO;
                    load_p1 = 1;
                end else begin
                    next_state = ZERO;
                    load_p1 = 0;
                end
            end
            ONE: begin
                if (s_valid && !m_ready) begin
                    next_state = ONE;
                    load_p2 = 1;
                end else if (s_valid && m_ready) begin
                    next_state = TWO;
                    load_p2 = 0;
                end else begin
                    next_state = ZERO;
                    load_p2 = 0;
                end
            end
            TWO: begin
                if (s_valid && !m_ready) begin
                    next_state = TWO;
                    load_p1 = 1;
                end else if (s_valid && m_ready) begin
                    next_state = ZERO;
                    load_p1 = 0;
                end else begin
                    next_state = ZERO;
                    load_p1 = 0;
                end
            end
            default: begin
                next_state = ZERO;
                load_p1 = 0;
                load_p2 = 0;
            end
        endcase
    end

    // Sequential logic for state and register updates
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
        end else begin
            state <= next_state;
            if (load_p1) begin
                data_p1 <= s_data;
            end
            if (load_p2) begin
                data_p2 <= s_data;
            end
        end
    end

    // Output logic
    assign m_data = (state == TWO) ? data_p1 : data_p2;
    assign m_valid = (state == TWO) ? 1 : 0;
    assign s_ready = (state == ZERO) ? 1 : 0;

endmodule

