module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );

    // Internal registers for intermediate results
    reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    // Combinational logic to compute the G function
    always @* begin
        // Step 1: a0 = a + b + m0
        a0 = a + b + m0;

        // Step 2: b0 = (a0 << 1) ^ b
        b0 = (a0 << 1) ^ b;

        // Step 3: c0 = c + d + m1
        c0 = c + d + m1;

        // Step 4: d0 = (c0 << 1) ^ d
        d0 = (c0 << 1) ^ d;

        // Step 5: a1 = a0 + b0
        a1 = a0 + b0;

        // Step 6: b1 = (a1 << 1) ^ b0
        b1 = (a1 << 1) ^ b0;

        // Step 7: c1 = c0 + d0
        c1 = c0 + d0;

        // Step 8: d1 = (c1 << 1) ^ d0
        d1 = (c1 << 1) ^ d0;

        // Step 9: a2 = a1 + b1
        a2 = a1 + b1;

        // Step 10: b2 = (a2 << 1) ^ b1
        b2 = (a2 << 1) ^ b1;

        // Step 11: c2 = c1 + d1
        c2 = c1 + d1;

        // Step 12: d2 = (c2 << 1) ^ d1
        d2 = (c2 << 1) ^ d1;

        // Step 13: a3 = a2 + b2
        a3 = a2 + b2;

        // Step 14: b3 = (a3 << 1) ^ b2
        b3 = (a3 << 1) ^ b2;

        // Step 15: c3 = c2 + d2
        c3 = c2 + d2;

        // Step 16: d3 = (c3 << 1) ^ d2
        d3 = (c3 << 1) ^ d2;

        // Final output values
        a_prim = a3;
        b_prim = b3;
        c_prim = c3;
        d_prim = d3;
    end

endmodule

module NAND5B4 (O, I0, I1, I2, I3, I4);

    output O;

    input  I0, I1, I2, I3, I4;

