    // Invert the first four inputs
    not (not_I0, I0);
    not (not_I1, I1);
    not (not_I2, I2);
    not (not_I3, I3);

    // Perform the NAND operation with the inverted inputs and the fifth input
    assign O = not (not_I0 & not_I1 & not_I2 & not_I3 & I4);

endmodule

