module sincf #(parameter win=1, wout=5)
(
	input clk,
	input [win-1:0] din,
	output reg [wout-1:0] dout
);
reg [win-1:0] mem [0:win-1]; // Shift register to store the input history
reg [wout:0] sum; // Accumulator to store the sum of the inputs

always @(posedge clk) begin
	// Shift the register to the right and load the new input
	mem <= {mem[win-2:0], din};

	// Update the sum by subtracting the oldest input and adding the newest input
	sum <= sum - mem[0] + din;

	// Ensure the sum does not exceed the output width
	if (sum > (1 << wout) - 1)
		sum <= (1 << wout) - 1;
	else if (sum < 0)
		sum <= 0;
end

// Assign the sum to the output
assign dout = sum[win-1:0];
endmodule

