    input [15:0] w_r,
    input [15:0] w_i,
    output [15:0] x_r,
    output [15:0] x_i,
    output [15:0] y_r,
    output [15:0] y_i
);

    // Internal wires for larger intermediate values
    wire [31:0] sum_r, sum_i;
    wire [31:0] diff_r, diff_i;
    wire [31:0] prod_r, prod_i;

    // Addition of two complex numbers
    assign sum_r = a_r + b_r;
    assign sum_i = a_i + b_i;

    // Subtraction of two complex numbers
    assign diff_r = a_r - b_r;
    assign diff_i = a_i - b_i;

    // Multiplication of the result with another complex number
    assign prod_r = diff_r * w_r - diff_i * w_i;
    assign prod_i = diff_r * w_i + diff_i * w_r;

    // Scaling the final outputs by selecting higher bits
    assign x_r = sum_r[30:15];
    assign x_i = sum_i[30:15];
    assign y_r = prod_r[30:15];
    assign y_i = prod_i[30:15];

endmodule

