module sbox(
	output [7:0] SubByte,
	input [7:0] num
	);

	// Intermediate signals
	wire [7:0] y, t, z, tc;

	// First layer of XOR operations
	y = num ^ 8'b10000000;

	// Second layer of XOR and AND operations
	t = y ^ 8'b01010101;
	z = t & 8'b11110000;
	tc = t & 8'b00001111;

	// Final output
	SubByte = (z >> 4) | (tc << 4);

endmodule

