module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
  // Parameters
  parameter CLK_FREQ = 50000000; // System clock frequency in Hz
  parameter UART_BPS = 9600;     // Desired baud rate in bits per second
  parameter BPS_CNT = CLK_FREQ / UART_BPS; // Baud rate counter value

  // Registers and counters
  reg [7:0] tx_data; // Data register
  reg tx_flag;       // Transmission flag
  reg [2:0] tx_cnt;  // Bit counter
  reg [15:0] clk_cnt; // Clock counter

  // State machine states
  typedef enum reg [1:0] {IDLE, START, DATA, STOP} state_t;
  state_t state, next_state;

  // Next state logic
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // State transition logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (uart_en) begin
          tx_data <= uart_din;
          tx_flag <= 1;
          next_state = START;
        end
      end
      START: begin
        uart_txd <= 0;
        tx_cnt <= 0;
        clk_cnt <= 0;
        next_state = DATA;
      end
      DATA: begin
        if (clk_cnt == BPS_CNT - 1) begin
          uart_txd <= tx_data[7 - tx_cnt];
          tx_cnt <= tx_cnt + 1;
          clk_cnt <= 0;
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
        if (tx_cnt == 7) begin
          next_state = STOP;
        end
      end
      STOP: begin
        uart_txd <= 1;
        clk_cnt <= 0;
        if (clk_cnt == BPS_CNT - 1) begin
          tx_flag <= 0;
          next_state = IDLE;
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
      end
    endcase
  end

  // Output logic
  assign uart_txd = (tx_flag && (state == DATA || state == STOP)) ? uart_txd : 1;

endmodule

