module boardSynchroniser(
    input clk,
    input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );

    reg [1:0] counter;
    reg synch;
    wire syncInOutWire;

    // Tri-state buffer for syncInOut
    assign syncInOut = (opMode == 1'b0) ? syncInOutWire : 'Z;

    always @(posedge clk) begin
        if (!synch_en) begin
            counter <= 2'b00;
            synch <= 1'b0;
        end else begin
            if (toggle_en) begin
                if (counter == cnt_n) begin
                    synch <= 1'b1;
                end else if (counter == cnt_m) begin
                    synch <= 1'b0;
                end
                counter <= counter + 1;
                if (counter > cnt_m) begin
                    counter <= 2'b00;
                end
            end
        end
    end

    assign syncInOutWire = synch;

    always @(posedge clk) begin
        if (opMode == 1'b1) begin
            synchroStatus <= synch;
        end else begin
            synchroStatus <= syncInOutWire;
        end
    end

endmodule

