module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);

    localparam SHIFT_AMOUNT = SHIFT_VALUE;

    reg [DATA_WIDTH-1:0] shift_reg;
    wire [DATA_WIDTH-1:0] shifted_data;
    wire [1:0] overflow;

    generate
        if (DATA_TYPE == "unsigned") begin : unsigned_shift
            assign shifted_data = din >> SHIFT_AMOUNT;
            assign overflow = (din[DATA_WIDTH-1] == 1'b1 && din[DATA_WIDTH-SHIFT_AMOUNT-1:0] != 0) ? 2'b01 : 2'b00;
        end else begin : signed_shift
            assign shifted_data = din >> SHIFT_AMOUNT;
            assign overflow = (din[DATA_WIDTH-1] == 1'b1 && din[DATA_WIDTH-SHIFT_AMOUNT-1:0] != 0) ? 2'b01 : (din[DATA_WIDTH-1] == 1'b0 && din[DATA_WIDTH-SHIFT_AMOUNT:0] != 0) ? 2'b10 : 2'b00;
        end
    endgenerate

    if (ASYNC == 0) begin : synchronous_mode
        always @(posedge clk) begin
            shift_reg <= shifted_data;
        end
        assign dout = shift_reg;
        assign warning = overflow;
    end else begin : asynchronous_mode
        assign dout = shifted_data;
        assign warning = overflow;
    end

endmodule

