module alu_32 (
  input wire [31:0] input_a,
  input wire [31:0] input_b,
  input wire [3:0] control,
  output wire zero, 
  output reg cout,
  output reg err_overflow,
  output reg err_invalid_control,
  output reg [31:0] result
); 

parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b0110;

always @(*) begin
  zero = 1'b0;
  cout = 1'b0;
  err_overflow = 1'b0;
  err_invalid_control = 1'b0;
  result = 32'b0;

  case (control)
    AND: begin
      result = input_a & input_b;
      zero = (result == 32'b0);
    end
    OR: begin
      result = input_a | input_b;
      zero = (result == 32'b0);
    end
    ADD: begin
      result = input_a + input_b;
      cout = (result < input_a);
      err_overflow = (result < input_a);
      zero = (result == 32'b0);
    end
    ADD_UNSIGNED: begin
      result = input_a + input_b;
      cout = (result < input_a);
      zero = (result == 32'b0);
    end
    SUB: begin
      result = input_a - input_b;
      cout = (input_a < input_b);
      err_overflow = (input_a < input_b);
      zero = (result == 32'b0);
    end
    SLT: begin
      result = (input_a < input_b) ? 32'b1 : 32'b0;
      zero = (result == 32'b0);
    end
    NOR: begin
      result = ~(input_a | input_b);
      zero = (result == 32'b0);
    end
    default: begin
      err_invalid_control = 1'b1;
    end
  endcase
end

endmodule

