  wire [4:0] y1 = a1 | p1;
  wire [5:0] y2 = a2 ^ p2;
  wire [3:0] y3 = a3 + p3;
  wire [4:0] y4 = a4 - p4;
  wire [5:0] y5 = a5 * p5;
  wire [3:0] y6 = b0 & p6;
  wire [4:0] y7 = b1 | p7;
  wire [5:0] y8 = b2 ^ p8;
  wire [3:0] y9 = b3 + p9;
  wire [4:0] y10 = b4 - p10;
  wire [5:0] y11 = b5 * p11;
  wire [3:0] y12 = y0 + y6;
  wire [4:0] y13 = y1 + y7;
  wire [5:0] y14 = y2 + y8;
  wire [3:0] y15 = y3 + y9;
  wire [4:0] y16 = y4 + y10;
  wire [5:0] y17 = y5 + y11;

  // Final output
  assign y = {y17, y16, y15, y14, y13, y12, y11, y10, y9, y8, y7, y6, y5, y4, y3, y2, y1, y0};
endmodule

