module axi_bram_reader #
(
  parameter integer AXI_DATA_WIDTH = 32,
  parameter integer AXI_ADDR_WIDTH = 16,
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 10
)
(
  input  wire                       aclk,
  input  wire                       aresetn,

  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_awaddr,  
  input  wire                       s_axi_awvalid, 
  output wire                       s_axi_awready, 
  input  wire [AXI_DATA_WIDTH-1:0]  s_axi_wdata,   
  input  wire                       s_axi_wvalid,  
  output wire                       s_axi_wready,  
  output wire [1:0]                 s_axi_bresp,   
  output wire                       s_axi_bvalid,  
  input  wire                       s_axi_bready,  
  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_araddr,  
  input  wire                       s_axi_arvalid, 
  output wire                       s_axi_arready, 
  output wire [AXI_DATA_WIDTH-1:0]  s_axi_rdata,   
  output wire [1:0]                 s_axi_rresp,   
  output wire                       s_axi_rvalid,  
  input  wire                       s_axi_rready,  

  output wire                       bram_porta_clk,
  output wire                       bram_porta_rst,
  output wire [BRAM_ADDR_WIDTH-1:0] bram_porta_addr,
  input  wire [BRAM_DATA_WIDTH-1:0] bram_porta_rddata
);

  // Internal signals
  reg [AXI_ADDR_WIDTH-1:0] axi_read_addr;
  reg [AXI_ADDR_WIDTH-1:0] bram_addr;
  reg [AXI_DATA_WIDTH-1:0] bram_data;
  reg s_axi_arready_reg;
  reg s_axi_rvalid_reg;
  reg [AXI_DATA_WIDTH-1:0] s_axi_rdata_reg;
  reg [1:0] s_axi_rresp_reg;

  // State machine states
  typedef enum reg [1:0] {IDLE, ADDR, DATA} state_t;
  state_t state, next_state;

  // Address conversion
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      bram_addr <= 0;
    end else begin
      bram_addr <= axi_read_addr;
    end
  end

  // State machine logic
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    next_state = state;
    s_axi_arready_reg = 0;
    s_axi_rvalid_reg = 0;
    s_axi_rdata_reg = 0;
    s_axi_rresp_reg = 0;
    bram_porta_clk = aclk;
    bram_porta_rst = ~aresetn;

    case (state)
      IDLE: begin
        if (s_axi_arvalid) begin
          axi_read_addr <= s_axi_araddr;
          next_state = ADDR;
        end
      end
      ADDR: begin
        s_axi_arready_reg = 1;
        next_state = DATA;
      end
      DATA: begin
        s_axi_rdata_reg = bram_porta_rddata;
        s_axi_rvalid_reg = 1;
        s_axi_rresp_reg = 2'b00; // OKAY
        next_state = IDLE;
      end
    endcase
  end

  // Output assignments
  assign s_axi_awready = 0;
  assign s_axi_wready = 0;
  assign s_axi_bresp = 2'b00; // OKAY
  assign s_axi_bvalid = 0;
  assign s_axi_arready = s_axi_arready_reg;
  assign s_axi_rdata = s_axi_rdata_reg;
  assign s_axi_rresp = s_axi_rresp_reg;
  assign s_axi_rvalid = s_axi_rvalid_reg;

  // BRAM port assignments
  assign bram_porta_addr = bram_addr;

endmodule

module sky130_fd_sc_hd__or4bb (
    output X  ,
    input  A  ,
    input  B  ,
    input  C_N,
    input  D_N
);

    wire nand0_out;
    wire or0_out_X;

    // NAND gate to compute NOT(C AND D)
    nand nand0 (
        .A(C_N),
        .B(D_N),
        .Y(nand0_out)
    );

    // OR gate to compute A OR B OR (NOT (C AND D))
    or or0 (
        .A(A),
        .B(B),
        .C(nand0_out),
        .Y(or0_out_X)
    );

    // Buffer to drive the final output X
    buf buf0 (
        .I(or0_out_X),
        .O(X)
    );

endmodule

