module dffeas (
    input d,
    input clk,
    input ena,
    input clrn,
    input prn,
    input aload, 
    input asdata,  
    input sclr, 
    input sload, 
    input devclrn, 
    input devpor, 
    output q
);

parameter POWER_UP_STATE = 1'b0;
parameter WYSIWYG_MODE = 1'b0;
parameter VIOLATION_MODE = 1'b0;

reg q_tmp;
wire reset = ~clrn | ~devclrn;
wire aload_dly;
wire asdata_dly;
wire d_viol;
wire sclr_viol;

// Delay asynchronous data
always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        asdata_dly <= 1'b0;
    end else begin
        asdata_dly <= asdata;
    end
end

// Asynchronous load
always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        q_tmp <= POWER_UP_STATE;
    end else if (aload) begin
        q_tmp <= asdata_dly;
    end
end

// Synchronous clear
always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        q_tmp <= POWER_UP_STATE;
    end else if (sclr) begin
        q_tmp <= POWER_UP_STATE;
    end
end

// Synchronous load
always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        q_tmp <= POWER_UP_STATE;
    end else if (sload) begin
        q_tmp <= d;
    end
end

// Violation detection
assign d_viol = (ena && !clk) || (ena && !reset);
assign sclr_viol = (sclr && !clk) || (sclr && !reset);

// Main state transition
always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        q_tmp <= POWER_UP_STATE;
    end else if (ena && !reset) begin
        q_tmp <= d;
    end
end

// Output assignment
assign q = q_tmp;

endmodule

module scan_hex_led_disp(
    input clk, reset,
    input [3:0] hex3, hex2, hex1, hex0,
    input [3:0] dp,
    output reg [3:0] en, 
    output reg [7:0] sseg
    );

    reg [1:0] digit_counter;
    reg [3:0] current_hex;
    reg [3:0] current_dp;

    // Seven-segment display patterns for 0-9 and A-F
    localparam [7:0] seg_patterns [15:0] = {
        8'b11000000, // 0
        8'b11111001, // 1
        8'b10100100, // 2
        8'b10110000, // 3
        8'b10011000, // 4
        8'b10010010, // 5
        8'b10000010, // 6
        8'b11111000, // 7
        8'b10000000, // 8
        8'b10010000, // 9
        8'b10001000, // A
        8'b10000011, // B
        8'b11000110, // C
        8'b11011010, // D
        8'b11001000, // E
        8'b11000001  // F
    };

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            digit_counter <= 2'b00;
            current_hex <= 4'b0000;
            current_dp <= 4'b0000;
        end else begin
            // Update the current digit and decimal point
            case (digit_counter)
                2'b00: begin
                    current_hex <= hex0;
                    current_dp <= dp[0];
                end
                2'b01: begin
                    current_hex <= hex1;
                    current_dp <= dp[1];
                end
                2'b10: begin
                    current_hex <= hex2;
                    current_dp <= dp[2];
                end
                2'b11: begin
                    current_hex <= hex3;
                    current_dp <= dp[3];
                end
                default: begin
                    current_hex <= 4'b0000;
                    current_dp <= 4'b0000;
                end
            endcase

            // Increment the digit counter
            digit_counter <= digit_counter + 2'b01;
            if (digit_counter == 2'b11) begin
                digit_counter <= 2'b00;
            end
        end
    end

    // Assign the segment patterns and enable lines
    always @(*) begin
        sseg = seg_patterns[current_hex];
        en = 4'b1111;
        en[digit_counter] = 1'b0;
        if (current_dp[digit_counter]) begin
            sseg[7] = 1'b0; // Turn on decimal point
        end
    end

endmodule

module linear_layer (
    input [63:0] x0, x1, x2, x3, x4,
    output [63:0] o0, o1, o2, o3, o4
);
    // Define rotation constants
    parameter [5:0] ROT0 = 6'd1;
    parameter [5:0] ROT1 = 6'd2;
    parameter [5:0] ROT2 = 6'd3;
    parameter [5:0] ROT3 = 6'd4;
    parameter [5:0] ROT4 = 6'd5;

    // Rotate and XOR operations for each output
    assign o0 = (x0 << ROT0) | (x0 >> (64 - ROT0)) ^ x1;
    assign o1 = (x1 << ROT1) | (x1 >> (64 - ROT1)) ^ x2;
    assign o2 = (x2 << ROT2) | (x2 >> (64 - ROT2)) ^ x3;
    assign o3 = (x3 << ROT3) | (x3 >> (64 - ROT3)) ^ x4;
    assign o4 = (x4 << ROT4) | (x4 >> (64 - ROT4)) ^ x0;
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
    reg [16:0] tmp;

    always @(*) begin
        // Sign-extend data_i to 17 bits
        tmp = {data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13], data_i[13]};

        // Perform barrel shift based on shift_i
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
            default: data_o = tmp; // Default case should not occur
        endcase
    end
endmodule

module decoder_3to8 
