                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b0; // Should not happen due to 3-bit input
            endcase
        end
    end

endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output reg [31:0] read_data);

reg [31:0] mem [0:31]; // Memory array of 32 32-bit registers

initial begin
    // Initialize all memory locations to zero on power-up
    for (int i = 0; i < 32; i++) begin
        mem[i] = 32'b0;
    end
end

always @(posedge clk) begin
    if (MemWrite) begin
        // Write data to the specified memory address on the rising edge of the clock
        mem[addr] <= write_data;
    end
end

assign read_data = (MemRead) ? mem[addr] : 32'b0;
// Provide read data when MemRead is high, otherwise output zero

endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
    reg [BITS:0] cnt;
    wire [BITS:0] enable_wires;

    generate
        genvar i;
        for (i = 0; i < BITS; i = i + 1) begin : counter_bits
            assign enable_wires[i] = (i == 0) ? ena : enable_wires[i - 1];
        end
    endgenerate

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= {BITS{1'b0}};
        end else if (ena) begin
            if (updown) begin
                cnt <= cnt + 1;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    assign out = cnt[BITS - 1:0];
    assign ovf = (cnt == {BITS{1'b1}}) || (cnt == {BITS{1'b0}});

endmodule

module risc_v_32_mem(m_addr, d_f_mem, inst_decode, mem_out);
    input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
    output reg [31:0] mem_out;

    wire [1:0] load_type = inst_decode[36:35];
    wire [1:0] sign_ext = inst_decode[34:33];
    wire [1:0] addr_align = m_addr[1:0];

    always @(*) begin
        case ({load_type, addr_align})
            2'b00: mem_out = d_f_mem; // lw
            2'b01: mem_out = {16'b0, d_f_mem[7:0]}; // lbu
            2'b10: mem_out = {24'b0, d_f_mem[7:0]}; // lb
            2'b11: mem_out = {16'b0, d_f_mem[15:0]}; // lhu
            default: mem_out = 32'b0;
        endcase
        if (sign_ext == 2'b01) begin // lb
            mem_out = {24{mem_out[7]} | mem_out};
        end else if (sign_ext == 2'b10) begin // lhu
            mem_out = {16{mem_out[15]} | mem_out};
        end
    end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output [(DATA_WIDTH-1):0]  Read_Data_o
);

	// Define the memory array
	reg [DATA_WIDTH-1:0] memory [0:MEMORY_DEPTH-1];

	// Define the static base address
	parameter VAR_I = 32'h10010000;

	// Calculate the effective address
	wire [DATA_WIDTH-1:0] effective_address = (Address_i - VAR_I) >> 2;

	// Write operation on the positive edge of the clock
	always @(posedge clk) begin
		if (Write_Enable_i) begin
			memory[effective_address] <= Write_Data_i;
		end
	end

	// Combinational read operation
	assign Read_Data_o = memory[effective_address];

endmodule

