module wb_bridge_16_32
  #(parameter AWIDTH=16)
    (input wb_clk, input wb_rst,
     input A_cyc_i, input A_stb_i, input A_we_i, input [3:0] A_sel_i,
     input [AWIDTH-1:0] A_adr_i, input [31:0] A_dat_i, output [31:0] A_dat_o, output A_ack_o,
     output B_cyc_o, output B_stb_o, output B_we_o, output [1:0] B_sel_o,
     output [AWIDTH-1:0] B_adr_o, output [15:0] B_dat_o, input [15:0] B_dat_i, input B_ack_i
     );

  reg [1:0] state;
  reg [1:0] phase;
  reg [15:0] data_reg;
  reg [AWIDTH-1:0] addr_reg;
  reg [1:0] sel_reg;
  reg cyc_reg, stb_reg, we_reg;
  reg [1:0] sel_reg;

  parameter IDLE = 2'b00, READ_1 = 2'b01, READ_2 = 2'b10, WRITE_1 = 2'b11;

  always @(posedge wb_clk or posedge wb_rst) begin
    if (wb_rst) begin
      state <= IDLE;
      phase <= 2'b00;
      data_reg <= 16'b0;
      addr_reg <= 0;
      sel_reg <= 2'b00;
      cyc_reg <= 0;
      stb_reg <= 0;
      we_reg <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (A_cyc_i && A_stb_i) begin
            if (A_we_i) begin
              state <= WRITE_1;
              addr_reg <= A_adr_i;
              sel_reg <= A_sel_i;
              data_reg <= A_dat_i[15:0];
              cyc_reg <= 1;
              stb_reg <= 1;
              we_reg <= 1;
            end else begin
              state <= READ_1;
              addr_reg <= A_adr_i;
              sel_reg <= A_sel_i;
              cyc_reg <= 1;
              stb_reg <= 1;
              we_reg <= 0;
            end
          end
        end
        WRITE_1: begin
          B_cyc_o <= cyc_reg;
          B_stb_o <= stb_reg;
          B_we_o <= we_reg;
          B_sel_o <= sel_reg;
          B_adr_o <= addr_reg;
          B_dat_o <= data_reg;
          if (B_ack_i) begin
            state <= WRITE_2;
            data_reg <= A_dat_i[31:16];
          end
        end
        WRITE_2: begin
          B_cyc_o <= cyc_reg;
          B_stb_o <= stb_reg;
          B_we_o <= we_reg;
          B_sel_o <= sel_reg;
          B_adr_o <= addr_reg;
          B_dat_o <= data_reg;
          if (B_ack_i) begin
            state <= IDLE;
            A_dat_o <= {data_reg, data_reg};
            A_ack_o <= 1;
          end
        end
        READ_1: begin
          B_cyc_o <= cyc_reg;
          B_stb_o <= stb_reg;
          B_we_o <= we_reg;
          B_sel_o <= sel_reg;
          B_adr_o <= addr_reg;
          if (B_ack_i) begin
            state <= READ_2;
            data_reg <= B_dat_i;
          end
        end
        READ_2: begin
          B_cyc_o <= cyc_reg;
          B_stb_o <= stb_reg;
          B_we_o <= we_reg;
          B_sel_o <= sel_reg;
          B_adr_o <= addr_reg;
          if (B_ack_i) begin
            state <= IDLE;
            A_dat_o <= {data_reg, data_reg};
            A_ack_o <= 1;
          end
        end
      endcase
    end
  end

endmodule

