module peridot_ethio_cdb_signal (
	input wire			reset,
	input wire			clk,
	input wire			in_sig,
	output wire			out_sig,
	output wire			riseedge,
	output wire			falledge
);

reg [2:0] shift_reg;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		shift_reg <= 3'b000;
		out_sig <= 1'b0;
		riseedge <= 1'b0;
		falledge <= 1'b0;
	end else begin
		shift_reg <= {shift_reg[1:0], in_sig};
		out_sig <= shift_reg[2];
		riseedge <= (shift_reg[1] == 1'b0) && (shift_reg[2] == 1'b1);
		falledge <= (shift_reg[1] == 1'b1) && (shift_reg[2] == 1'b0);
	end
end

endmodule

module IB_ENDPOINT_OP_DONE_BUFFER(
    input wire CLK,
    input wire RESET,
    input wire [15:0] RD_COMPL_TAG,
