    input wire RD_COMPL_DONE,
    input wire [15:0] BM_TAG,
    input wire BM_DONE,
    output wire [15:0] OP_TAG,
    output wire OP_DONE
);

    reg [15:0] read_tag;
    reg read_active;
    reg [15:0] bm_tag;
    reg bm_valid;

    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            read_tag <= 16'b0;
            read_active <= 1'b0;
            bm_tag <= 16'b0;
            bm_valid <= 1'b0;
            OP_TAG <= 16'b0;
            OP_DONE <= 1'b0;
        end else begin
            if (RD_COMPL_START) begin
                read_tag <= RD_COMPL_TAG;
                read_active <= 1'b1;
            end else if (RD_COMPL_DONE) begin
                read_active <= 1'b0;
            end

            if (BM_DONE) begin
                bm_tag <= BM_TAG;
                bm_valid <= 1'b1;
            end

            if (read_active) begin
                OP_TAG <= read_tag;
                OP_DONE <= 1'b1;
            end else if (bm_valid) begin
                OP_TAG <= bm_tag;
                OP_DONE <= 1'b1;
            end else begin
                OP_DONE <= 1'b0;
            end
        end
    end

endmodule

