module mips_alu(zero, result, alu_op, first_data, second_data, shamt);
output reg zero;					
output reg [31:0] result;
input [31:0] first_data;		
input [31:0] second_data;		
input [3:0] alu_op;				
input [4:0] shamt;

always @(*) begin
    case (alu_op)
        4'b0000: begin // ADD
            result = first_data + second_data;
            zero = (result == 32'b0);
        end
        4'b0001: begin // SUB
            result = first_data - second_data;
            zero = (result == 32'b0);
        end
        4'b0010: begin // AND
            result = first_data & second_data;
            zero = (result == 32'b0);
        end
        4'b0011: begin // OR
            result = first_data | second_data;
            zero = (result == 32'b0);
        end
        4'b0100: begin // NOR
            result = ~(first_data | second_data);
            zero = (result == 32'b0);
        end
        4'b0101: begin // SLT (signed less than)
            result = (first_data < second_data) ? 32'b1 : 32'b0;
            zero = (result == 32'b0);
        end
        4'b0110: begin // SLTU (unsigned less than)
            result = (first_data < second_data) ? 32'b1 : 32'b0;
            zero = (result == 32'b0);
        end
        4'b0111: begin // SLL (shift left logical)
            result = first_data << shamt;
            zero = (result == 32'b0);
        end
        4'b1000: begin // SRL (shift right logical)
            result = first_data >> shamt;
            zero = (result == 32'b0);
        end
        4'b1001: begin // SRA (shift right arithmetic)
            result = $signed(first_data) >> shamt;
            zero = (result == 32'b0);
        end
        default: begin
            result = 32'b0;
            zero = 1'b1;
        end
    endcase
end

endmodule

module stratixiii_bias_logic (
    input  clk,
    input  shiftnld,
    input  captnupdt,

    output mainclk,
    output updateclk,
    output capture,
    output update
    );

reg temp_updateclk;
reg temp_capture;
reg temp_update;

always @(posedge clk or posedge shiftnld or posedge captnupdt) begin
    if (shiftnld) begin
        temp_updateclk <= 0;
        temp_capture <= 0;
        temp_update <= 0;
    end else begin
        case ({captnupdt, shiftnld})
            2'b10, 2'b11: begin
                temp_updateclk <= clk;
                temp_capture <= 1;
                temp_update <= 0;
            end
            2'b01: begin
                temp_updateclk <= clk;
                temp_capture <= 0;
                temp_update <= 0;
            end
            default: begin
                temp_updateclk <= 0;
                temp_capture <= 0;
                temp_update <= 1;
            end
        endcase
    end
end

assign mainclk = temp_updateclk & ~temp_capture & ~temp_update;
assign updateclk = temp_updateclk & temp_capture & ~temp_update;
assign capture = temp_capture & ~temp_updateclk & ~temp_update;
assign update = temp_update & ~temp_updateclk & ~temp_capture;

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);

    reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;

    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
            Pout_de_w <= 0;
            Pout_hs_w <= 0;
            Pout_vs_w <= 0;
            Rden_w <= 0;
        end else begin
            if (H_cnt == I_h_total - 1) begin
                H_cnt <= 0;
                V_cnt <= V_cnt + 1;
            end else begin
                H_cnt <= H_cnt + 1;
            end

            // Data Enable
            if (H_cnt >= I_h_sync && H_cnt < I_h_sync + I_h_res && V_cnt >= I_v_sync && V_cnt < I_v_sync + I_v_res) begin
                Pout_de_w <= 1;
            end else begin
                Pout_de_w <= 0;
            end

            // Horizontal Sync
            if (H_cnt == I_h_sync - 1) begin
                Pout_hs_w <= 1;
            end else begin
                Pout_hs_w <= 0;
            end

            // Vertical Sync
            if (V_cnt == I_v_sync - 1) begin
                Pout_vs_w <= 1;
            end else begin
                Pout_vs_w <= 0;
            end

            // Row Enable
            if (H_cnt == 0 && V_cnt >= I_v_sync && V_cnt < I_v_sync + I_v_res) begin
                Rden_w <= 1;
            end else begin
                Rden_w <= 0;
            end
        end
    end

    // Output assignment with polarity inversion
    assign O_rden = Rden_w;
    assign O_de = Pout_de_w;
    assign O_hs = I_hs_pol ? ~Pout_hs_w : Pout_hs_w;
    assign O_vs = I_vs_pol ? ~Pout_vs_w : Pout_vs_w;

endmodule

module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );

    always @(*) begin
        case (m)
            3'b000: begin // Addition
                y = a + b;
                cf = (a[WIDTH-1] & b[WIDTH-1] & ~y[WIDTH-1]) | (~a[WIDTH-1] & ~b[WIDTH-1] & y[WIDTH-1]);
                of = (a[WIDTH-1] & b[WIDTH-1] & y[WIDTH-1]) | (~a[WIDTH-1] & ~b[WIDTH-1] & ~y[WIDTH-1]);
            end
            3'b001: begin // Subtraction
                y = a - b;
                cf = (a[WIDTH-1] & ~b[WIDTH-1] & ~y[WIDTH-1]) | (~a[WIDTH-1] & b[WIDTH-1] & y[WIDTH-1]);
                of = (a[WIDTH-1] & ~b[WIDTH-1] & y[WIDTH-1]) | (~a[WIDTH-1] & b[WIDTH-1] & ~y[WIDTH-1]);
            end
            3'b010: begin // Bitwise AND
                y = a & b;
                cf = 0;
                of = 0;
            end
            3'b011: begin // Bitwise OR
                y = a | b;
                cf = 0;
                of = 0;
            end
            3'b100: begin // Bitwise XOR
                y = a ^ b;
                cf = 0;
                of = 0;
            end
            default: begin
                y = 0;
                cf = 0;
                of = 0;
            end
        endcase
        zf = (y == 0);
    end

endmodule

module arriaii_first_stage_add_sub(
                                 dataa,
                                 datab,
                                 sign,
                                 operation,
                                 dataout
                                );

parameter dataa_width = 36;
parameter datab_width = 36;
parameter fsa_mode = "add";

input [71  : 0 ] dataa;
input [71 : 0 ] datab;
input sign;
input [3:0] operation;

output [71: 0] dataout;

reg [71: 0] dataout_tmp;
reg [35: 0] abs_b;
reg [35: 0] abs_a;
reg sign_a;
reg sign_b;

always @(*) begin
    // Extract absolute values and signs
    abs_a = sign ? dataa[dataa_width-1] ? ~dataa[dataa_width-1 : 0] + 1 : dataa[dataa_width-1 : 0] : dataa[dataa_width-1 : 0];
    abs_b = sign ? datab[datab_width-1] ? ~datab[datab_width-1 : 0] + 1 : datab[datab_width-1 : 0] : datab[datab_width-1 : 0];
    sign_a = dataa[dataa_width-1];
    sign_b = datab[datab_width-1];

    // Perform operation based on operation code
    case (operation)
        4'b0000: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add
        4'b0001: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract
        4'b0010: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Special Add
        4'b0011: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Special Subtract
        4'b0100: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with carry
        4'b0101: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with borrow
        4'b0110: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with overflow
        4'b0111: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with underflow
        4'b1000: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with saturation
        4'b1001: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with saturation
        4'b1010: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with rounding
        4'b1011: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with rounding
        4'b1100: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with wrap
        4'b1101: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with wrap
        4'b1110: dataout_tmp = sign ? $signed(abs_a) + $signed(abs_b) : abs_a + abs_b; // Add with modulo
        4'b1111: dataout_tmp = sign ? $signed(abs_a) - $signed(abs_b) : abs_a - abs_b; // Subtract with modulo
        default: dataout_tmp = 72'b0;
    endcase
end

assign dataout = dataout_tmp;

endmodule

