module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
	// Internal registers and wires
	reg [31:0] sigma;
	reg [31:0] undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	// Edge-triggered logic for reset and clock
	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
		end else begin
			if (ock) begin
				// Phase accumulation logic
				if (sdi) begin
					sigma <= sigma + delta;
				end else begin
					sigma <= sigma - delta;
				end
			end
			if (uck) begin
				// Undersampling logic
				undersampled_sigma <= sigma;
			end
		end
	end

	// Derivative calculation for output
	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			deriv <= 0;
		end else begin
			deriv <= sigma - undersampled_sigma;
		end
	end

	// Output formatting based on signed_data
	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			dout <= 0;
		end else begin
			if (signed_data) begin
				dout <= $signed(deriv);
			end else begin
				dout <= deriv;
			end
		end
	end

	// Delta calculation based on signed_data
	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			delta <= 0;
		end else begin
			if (signed_data) begin
				delta <= $signed(1);
			end else begin
				delta <= 1;
			end
		end
	end
endmodule

