module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);

	// Internal registers and wires
	reg [31:0] counter;
	reg [31:0] step;
	reg auto_clk;
	reg wasReady;

	// Always block for clock and reset logic
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			counter <= 0;
			step <= 0;
			auto_clk <= 0;
			wasReady <= 0;
			clkdiv <= 0;
			Clk_CPU <= 0;
			readn <= 0;
		end else begin
			if (keyReady) begin
				case (BTN_OK)
					4'b0001: step <= 1;
					4'b0010: step <= 2;
					4'b0100: step <= 4;
					4'b1000: step <= 8;
					default: step <= 0;
				endcase
				wasReady <= 1;
			end else begin
				wasReady <= 0;
			end

			if (SW2) begin
				auto_clk <= 1;
			end else begin
				auto_clk <= 0;
			end

			if (auto_clk) begin
				if (counter == 24 || counter == 4) begin
					clkdiv <= counter;
				end else begin
					clkdiv <= 0;
				end
			end else begin
				if (counter < step) begin
					clkdiv <= counter;
				end else begin
					clkdiv <= 0;
				end
			end

			if (counter == 31) begin
				counter <= 0;
			end else begin
				counter <= counter + 1;
			end

			if (auto_clk) begin
				if (counter == 24 || counter == 4) begin
					Clk_CPU <= 1;
				end else begin
					Clk_CPU <= 0;
				end
			end else begin
				if (counter < step) begin
					Clk_CPU <= 1;
				end else begin
					Clk_CPU <= 0;
				end
			end

			if (counter == 31) begin
				counter <= 0;
			end else begin
				counter <= counter + 1;
			end
		end
	end

	// Output readn signal
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			readn <= 0;
		end else begin
			if (keyReady && wasReady) begin
				readn <= 1;
			end else begin
				readn <= 0;
			end
		end
	end

endmodule

