module processing_system7_v5_5_w_atc #
  (
   parameter         C_FAMILY                         = "rtl",

   parameter integer C_AXI_ID_WIDTH                   = 4,


   parameter integer C_AXI_DATA_WIDTH                 = 64,


   parameter integer C_AXI_WUSER_WIDTH                = 1


   )
  (

   input  wire                                  ARESET,
   input  wire                                  ACLK,


   input  wire                                  cmd_w_valid,
   input  wire                                  cmd_w_check,
   input  wire [C_AXI_ID_WIDTH-1:0]             cmd_w_id,
   output wire                                  cmd_w_ready,


   output wire                                  cmd_b_push,
   output wire                                  cmd_b_error,
   output reg  [C_AXI_ID_WIDTH-1:0]             cmd_b_id,
   input  wire                                  cmd_b_full,


   input  wire [C_AXI_ID_WIDTH-1:0]             S_AXI_WID,
   input  wire [C_AXI_DATA_WIDTH-1:0]           S_AXI_WDATA,
   input  wire [C_AXI_DATA_WIDTH/8-1:0]         S_AXI_WSTRB,
   input  wire                                  S_AXI_WLAST,
   input  wire [C_AXI_WUSER_WIDTH-1:0]          S_AXI_WUSER,
   input  wire                                  S_AXI_WVALID,
   output wire                                  S_AXI_WREADY,


   output wire [C_AXI_ID_WIDTH-1:0]             M_AXI_WID,
   output wire [C_AXI_DATA_WIDTH-1:0]           M_AXI_WDATA,
   output wire [C_AXI_DATA_WIDTH/8-1:0]         M_AXI_WSTRB,
   output wire                                  M_AXI_WLAST,
   output wire [C_AXI_WUSER_WIDTH-1:0]          M_AXI_WUSER,
   output wire                                  M_AXI_WVALID,
   input  wire                                  M_AXI_WREADY
   );

  reg [C_AXI_ID_WIDTH-1:0]  state;
  reg [C_AXI_ID_WIDTH-1:0]  next_state;
  reg [C_AXI_DATA_WIDTH-1:0]  wdata_reg;
  reg [C_AXI_DATA_WIDTH/8-1:0]  wstrb_reg;
  reg  wlast_reg;
  reg [C_AXI_WUSER_WIDTH-1:0]  wuser_reg;
  reg  wvalid_reg;
  reg  wready_reg;
  reg  bvalid_reg;
  reg  bready_reg;
  reg  berror_reg;

  parameter IDLE = 2'b00;
  parameter SEND_DATA = 2'b01;
  parameter SEND_BRESP = 2'b10;

  always @(posedge ACLK or posedge ARESET) begin
    if (ARESET) begin
      state <= IDLE;
      wdata_reg <= 0;
      wstrb_reg <= 0;
      wlast_reg <= 0;
      wuser_reg <= 0;
      wvalid_reg <= 0;
      wready_reg <= 0;
      bvalid_reg <= 0;
      bready_reg <= 0;
      berror_reg <= 0;
    end else begin
      state <= next_state;
      if (wvalid_reg && M_AXI_WREADY) begin
        wdata_reg <= S_AXI_WDATA;
        wstrb_reg <= S_AXI_WSTRB;
        wlast_reg <= S_AXI_WLAST;
        wuser_reg <= S_AXI_WUSER;
        wvalid_reg <= S_AXI_WVALID;
        wready_reg <= 1;
      end else begin
        wready_reg <= 0;
      end
      if (M_AXI_WREADY && wvalid_reg) begin
        wvalid_reg <= 0;
      end
      if (cmd_w_valid && cmd_w_check && !cmd_b_full) begin
        next_state <= SEND_DATA;
      end else if (state == SEND_DATA && M_AXI_WREADY) begin
        next_state <= SEND_BRESP;
      end else if (state == SEND_BRESP && bready_reg) begin
        next_state <= IDLE;
      end
      if (state == SEND_DATA) begin
        M_AXI_WID <= S_AXI_WID;
        M_AXI_WDATA <= wdata_reg;
        M_AXI_WSTRB <= wstrb_reg;
        M_AXI_WLAST <= wlast_reg;
        M_AXI_WUSER <= wuser_reg;
        M_AXI_WVALID <= wvalid_reg;
      end
      if (state == SEND_BRESP) begin
        cmd_b_push <= 1;
        cmd_b_id <= S_AXI_WID;
        cmd_b_error <= berror_reg;
        bvalid_reg <= 1;
      end
      if (bready_reg) begin
        bvalid_reg <= 0;
      end
    end
  end

  assign cmd_w_ready = (state == IDLE) && !cmd_b_full;
  assign S_AXI_WREADY = (state == SEND_DATA) && M_AXI_WREADY;
  assign M_AXI_WREADY = (state == SEND_DATA) && S_AXI_WVALID;
  assign bready_reg = cmd_b_push && cmd_b_full;

endmodule

module submulor_0_stage_signed_12_bit(
	input signed [11:0] a,
	input signed [11:0] b,
	input signed [11:0] c,
	input signed [11:0] d,
	output [11:0] out
	);

	// Perform the subtraction (d - a)
	signed [11:0] sub_result;
	sub_result = d - a;

	// Perform the multiplication ((d - a) * b)
	signed [23:0] mul_result;
	mul_result = sub_result * b;

	// Perform the bitwise OR operation with c
	out = mul_result[11:0] | c;

endmodule

module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
    localparam DEPTH = 1 << DEPTH_BITS;

    reg [DEPTH_BITS-1:0] index;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg empty, full;

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            index <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            if (write && !full) begin
                mem[index] <= din;
                index <= (index + 1) % DEPTH;
                if (index == 0) full <= 1;
                empty <= 0;
            end else if (read && !empty) begin
                index <= (index + DEPTH - 1) % DEPTH;
                if (index == DEPTH - 1) empty <= 1;
                full <= 0;
            end
        end
    end

    assign empty_n = ~empty;
    assign full_n = ~full;
    assign dout = mem[index];
endmodule

