module gray_Nbits #(parameter N = 4) (
    input wire clk,
    input wire reset,
    input wire enable,
    output wire [N-1:0] gray_out
);

    parameter SIZE = N + 1;
    parameter Zeros = 0;

    reg [SIZE-1:0] state;
    reg [N-1:0] toggle;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= {Zeros, 1'b0};
        end else if (enable) begin
            state[0] <= state[0] ^ toggle[0];
            for (int i = 1; i < N; i++) begin
                state[i] <= state[i] ^ toggle[i] ^ toggle[i-1];
            end
        end
    end

    always @(state) begin
        toggle[0] = 1'b1;
        for (int i = 1; i < N; i++) begin
            toggle[i] = state[i-1] & ~state[i];
        end
    end

    assign gray_out = state[1:N];

endmodule

module partsel_00453(
  input [3:0] ctrl,
  input [2:0] s0,
  input [2:0] s1,
  input [2:0] s2,
  input [2:0] s3,
  input signed [31:0] x0,
  input signed [31:0] x1,
  input signed [31:0] x2,
  input signed [31:0] x3,
  output [127:0] y
);

  // Intermediate signals
  wire [31:0] a, b, c, d, e, f, g, h;
  wire [31:0] i, j, k, l, m, n, o, p;

  // Arithmetic operations
  assign a = x0 + x1;
  assign b = x2 - x3;
  assign c = x0 * x2;
  assign d = x1 / x3;

  // Logical operations
  assign e = x0 & x1;
  assign f = x2 | x3;
  assign g = x0 ^ x2;
  assign h = ~x1;

  // Bitwise operations
  assign i = x0 << 2;
  assign j = x1 >> 3;
  assign k = x2 >>> 4;
  assign l = x3 & 32'hFFFF;

  // Control signal processing
  always @(*) begin
    case (ctrl)
      4'b0000: y = {a, b};
      4'b0001: y = {c, d};
      4'b0010: y = {e, f};
      4'b0011: y = {g, h};
      4'b0100: y = {i, j};
      4'b0101: y = {k, l};
      4'b0110: y = {m, n};
      4'b0111: y = {o, p};
      4'b1000: y = {a, c};
      4'b1001: y = {b, d};
      4'b1010: y = {e, g};
      4'b1011: y = {f, h};
      4'b1100: y = {i, k};
      4'b1101: y = {j, l};
      4'b1110: y = {m, o};
      4'b1111: y = {n, p};
      default: y = 128'b0;
    endcase
  end

endmodule

