module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);

    input                           clk;
    input                           rst;
    input [ADDR_WIDTH-1:0]          raddr;
    input                           re;
    input [ADDR_WIDTH-1:0]          waddr;
    input                           we;
    input [DATA_WIDTH-1:0]          din;
    output [DATA_WIDTH-1:0]         dout;

    reg [DATA_WIDTH-1:0] mem [0:2**ADDR_WIDTH-1];
    reg [DATA_WIDTH-1:0] dout_reg;

    initial begin
        if (CLEAR_ON_INIT) begin
            for (integer i = 0; i < 2**ADDR_WIDTH; i = i + 1) begin
                mem[i] = 0;
            end
        end
    end

    always @(posedge clk) begin
        if (we) begin
            mem[waddr] <= din;
        end
    end

    assign dout_reg = (ENABLE_BYPASS && re && (raddr == waddr) && we) ? din : mem[raddr];

    always @(posedge clk) begin
        dout <= dout_reg;
    end

endmodule

module BBFACosh(
    input  [63:0] in,
    output reg [63:0] out
);
    always @* begin
        real in_real, out_real;
        // Convert input bits to real number
        $bits2realfp(in, in_real);
        // Compute hyperbolic cosine
        out_real = acosh(in_real);
        // Convert result back to bits
        $realfp2bits(out_real, out);
    end
endmodule

module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0] SEQUENCE
);
    reg [7:0] fib_reg1, fib_reg2;
    reg [7:0] next_fib;
    reg [7:0] end_value;

    // Initialize Fibonacci sequence with 0 and 1
    initial begin
        fib_reg1 = 8'b00000000;
        fib_reg2 = 8'b00000001;
        end_value = 8'b10000000; // Example end value, can be changed
    end

    // Sequential logic to generate Fibonacci sequence
    always @(posedge CLK_IN or negedge RST_N) begin
        if (!RST_N) begin
            fib_reg1 <= 8'b00000000;
            fib_reg2 <= 8'b00000001;
        end else begin
            next_fib = fib_reg1 + fib_reg2;
            if (next_fib == end_value) begin
                fib_reg1 <= fib_reg2;
                fib_reg2 <= end_value;
            end else begin
                fib_reg1 <= fib_reg2;
                fib_reg2 <= next_fib;
            end
        end
    end

    // Output the current Fibonacci number
    assign SEQUENCE = fib_reg1 + fib_reg2;
endmodule

module instMem(
