    reg [31:0] mem [0:255];

    // Initialize memory from a text file on reset
    initial begin
        $readmemh("instructions.txt", mem);
    end

    // Combinational logic to output the instruction based on the address
    assign inst = mem[address[7:0]];

    // Synchronous reset to initialize memory contents
    always @(posedge clk or posedge reset) begin
        if (reset) begin
