            // but it ensures the memory is in a known state on reset.
            $readmemh("instructions.txt", mem);
        end
    end
endmodule

module memory(clk, reset, data_op, instruct_addr, data_addr, write_val, instruct_val, read_val); 
  parameter ADDR_WIDTH = 9; // 512 locations
  parameter DATA_WIDTH = 32;
  reg [DATA_WIDTH-1:0] mem [0:ADDR_WIDTH-1];
  reg [DATA_WIDTH-1:0] instruct_val;
  reg [DATA_WIDTH-1:0] read_val;

  // Initialize memory during reset
  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      // Initialize first 11 locations to 5
      for (int i = 0; i < 11; i++) begin
        mem[i] <= 32'd5;
      end
      // Initialize remaining locations to 0
      for (int i = 11; i < ADDR_WIDTH; i++) begin
        mem[i] <= 32'd0;
      end
      instruct_val <= 32'd0;
      read_val <= 32'd0;
    end else begin
      // Normal operation
      instruct_val <= mem[instruct_addr[ADDR_WIDTH-1:2]]; // 3 bits for 512 locations
      if (data_op) begin
        // Read operation
        read_val <= mem[data_addr[ADDR_WIDTH-1:2]];
      end else begin
        // Write operation
        mem[data_addr[ADDR_WIDTH-1:2]] <= write_val;
        read_val <= 32'd0; // No read value during write
      end
    end
  end
endmodule

