module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);

  // Internal signals
  reg [23:0] r_count;
  reg [1:0] state;
  reg [1:0] next_state;

  // State definitions
  parameter IDLE = 2'b00;
  parameter READY = 2'b01;
  parameter RELEASE = 2'b10;

  // State transition logic
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (i_ppfifo_rdy == 2'b11) begin
          next_state = READY;
        end
      end
      READY: begin
        if (i_h_blank || r_count >= i_ppfifo_size) begin
          next_state = RELEASE;
        end
      end
      RELEASE: begin
        if (i_ppfifo_rdy == 2'b11) begin
          next_state = IDLE;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  // Data processing logic
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      r_count <= 24'b0;
      o_ppfifo_act <= 2'b00;
      o_ppfifo_stb <= 1'b0;
      o_ppfifo_data <= 24'b0;
    end else begin
      case (state)
        IDLE: begin
          o_ppfifo_act <= 2'b00;
          o_ppfifo_stb <= 1'b0;
          o_ppfifo_data <= 24'b0;
        end
        READY: begin
          if (!i_h_blank && i_data_en) begin
            o_ppfifo_act <= 2'b11;
            o_ppfifo_stb <= 1'b1;
            o_ppfifo_data <= i_rgb;
            r_count <= r_count + 1;
          end else begin
            o_ppfifo_act <= 2'b00;
            o_ppfifo_stb <= 1'b0;
            o_ppfifo_data <= 24'b0;
          end
        end
        RELEASE: begin
          o_ppfifo_act <= 2'b00;
          o_ppfifo_stb <= 1'b0;
          o_ppfifo_data <= 24'b0;
          r_count <= 24'b0;
        end
        default: begin
          o_ppfifo_act <= 2'b00;
          o_ppfifo_stb <= 1'b0;
          o_ppfifo_data <= 24'b0;
        end
      endcase
    end
  end

  // Output the clock directly
  assign o_ppfifo_clk = clk;

endmodule

module expression_00541(a0, a1, a2, a3, a4, a5, b0, b1, b2, b3, b4, b5, y);
  input [3:0] a0;
  input [4:0] a1;
  input [5:0] a2;
  input signed [3:0] a3;
  input signed [4:0] a4;
  input signed [5:0] a5;
  input [3:0] b0;
  input [4:0] b1;
  input [5:0] b2;
  input signed [3:0] b3;
  input signed [4:0] b4;
  input signed [5:0] b5;
  output [89:0] y;

  // Local parameters for constants and intermediate results
  localparam [3:0] p0 = 4'd10;
  localparam [4:0] p1 = 5'd20;
  localparam [5:0] p2 = 6'd30;
  localparam [3:0] p3 = 4'd40;
  localparam [4:0] p4 = 5'd50;
  localparam [5:0] p5 = 6'd60;
  localparam [3:0] p6 = 4'd70;
  localparam [4:0] p7 = 5'd80;
  localparam [5:0] p8 = 6'd90;
  localparam [3:0] p9 = 4'd100;
  localparam [4:0] p10 = 5'd110;
  localparam [5:0] p11 = 6'd120;
  localparam [3:0] p12 = 4'd130;
  localparam [4:0] p13 = 5'd140;
  localparam [5:0] p14 = 6'd150;
  localparam [3:0] p15 = 4'd160;
  localparam [4:0] p16 = 5'd170;
  localparam [5:0] p17 = 6'd180;

  // Internal signals
  wire [3:0] y0, y1, y2, y3, y4, y5, y6, y7, y8, y9, y10, y11, y12, y13, y14, y15, y16, y17;

  // Combinational logic to compute each segment of the output
  assign y0 = a0 + b0;
  assign y1 = a1 - b1;
  assign y2 = a2 * b2;
  assign y3 = a3 / b3;
  assign y4 = a4 % b4;
  assign y5 = a5 << p0;
  assign y6 = a5 >> p1;
  assign y7 = a5 & b5;
  assign y8 = a5 | b5;
  assign y9 = a5 ^ b5;
  assign y10 = a5 == b5;
  assign y11 = a5 != b5;
  assign y12 = a5 < b5;
  assign y13 = a5 > b5;
  assign y14 = a5 <= b5;
  assign y15 = a5 >= b5;
  assign y16 = $signed(a5) + $signed(b5);
  assign y17 = $unsigned(a5) - $unsigned(b5);

  // Concatenate all segments to form the final 90-bit output
  assign y = {y17, y16, y15, y14, y13, y12, y11, y10, y9, y8, y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

