module routing_buffer #(parameter DATA_WIDTH = 8, parameter INSERT_REGISTER = 1) (
  input clock, resetn, 
  input [DATA_WIDTH-1:0] i_datain,
  input i_datain_valid,
  output reg o_datain_stall,
  output reg [DATA_WIDTH-1:0] o_dataout,
  input i_dataout_stall,
  output reg o_dataout_valid
);

  reg [DATA_WIDTH-1:0] data_reg;
  reg data_valid_reg;

  always @(posedge clock or negedge resetn) begin
    if (!resetn) begin
      o_datain_stall <= 1'b0;
      o_dataout_valid <= 1'b0;
      if (INSERT_REGISTER) begin
        data_reg <= {DATA_WIDTH{1'b0}};
        data_valid_reg <= 1'b0;
      end
    end else begin
      o_datain_stall <= (i_datain_valid && !data_valid_reg) || (INSERT_REGISTER && i_datain_valid && i_dataout_stall);
      o_dataout_valid <= data_valid_reg && !i_dataout_stall;
      if (INSERT_REGISTER && o_dataout_valid) begin
        data_reg <= data_reg;
        data_valid_reg <= 1'b0;
      end else if (i_datain_valid && !o_datain_stall) begin
        data_reg <= i_datain;
        data_valid_reg <= 1'b1;
      end
      o_dataout <= data_reg;
    end
  end

endmodule

