module clk_div(
    input wire clk_100MHz,
    input wire reset,
    output wire clk_100Hz
);
    reg [31:0] ticks;
    reg clk_out;

    always @(posedge clk_100MHz or posedge reset) begin
        if (reset) begin
            ticks <= 32'd499999;
            clk_out <= 1'b0;
        end else begin
            ticks <= ticks - 1;
            if (ticks == 0) begin
                clk_out <= ~clk_out;
                ticks <= 32'd499999;
            end
        end
    end

    assign clk_100Hz = clk_out;
endmodule

module iiitb_freqdiv(en, clkin, n, clkout);
    input clkin;
    input [3:0] n;
    input en;
    output reg clkout;

    reg [3:0] pc, nc; // Counters for frequency division
    reg [3:0] n_div2; // Half of the divisor for comparison

    always @(posedge clkin or negedge en) begin
        if (!en) begin
            // Reset counters and output when divider is disabled
            pc <= 4'b0000;
            nc <= 4'b0000;
            clkout <= 1'b0;
        end else begin
            // Increment counters on rising and falling edges of clkin
            pc <= pc + 1;
            nc <= nc + 1;

            // Calculate n/2 for comparison
            n_div2 <= n >> 1;

            // Determine output based on counter values and divisor
            if (pc == n_div2) begin
                clkout <= ~clkout;
                pc <= 4'b0000; // Reset counter for next cycle
            end
            if (nc == n_div2 + (n[0])) begin
                clkout <= ~clkout;
                nc <= 4'b0000; // Reset counter for next cycle
            end
        end
    end
endmodule

module subs(
    input wire [7:0] Q,
    input wire [7:0] R,
    input wire EnSubs,
    output wire [7:0] Qout
);
    wire [7:0] borrow;
    wire [7:0] Qout_temp;

    // Calculate borrow for subtraction
    assign borrow[0] = ~Q[0] & R[0];
    generate
        genvar i;
        for (i = 1; i < 8; i++) begin : borrow_calc
            assign borrow[i] = (~Q[i] & R[i] & ~borrow[i-1]) | (Q[i-1] & borrow[i-1]);
        end
    endgenerate

    // Calculate Qout_temp using XOR and AND operations
    generate
        genvar j;
        for (j = 0; j < 8; j++) begin : qout_calc
            assign Qout_temp[j] = (EnSubs & (~Q[j] ^ R[j] ^ borrow[j])) | (~EnSubs & Q[j]);
        end
    endgenerate

    // Assign Qout based on the enable signal
    assign Qout = Qout_temp;
endmodule

