module DelayLoop(MR, Timeout, Clock);
    input MR, Clock;
    output reg Timeout;

    parameter Divider = 100000; // Configurable delay in clock cycles
    reg [26:0] counter; // 27-bit counter to track clock cycles

    // Combinational logic to set the Timeout signal
    always @(*) begin
        Timeout = (counter == Divider);
    end

    // Sequential logic to control the counter's reset and increment operations
    always @(posedge Clock) begin
        if (MR) begin
            counter <= 27'b0; // Reset counter on MR high
            Timeout <= 1'b0; // Clear Timeout signal on reset
        end else if (counter < Divider) begin
            counter <= counter + 1; // Increment counter on each clock cycle
        end
    end
endmodule

