    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;

    // State machine states
    localparam ZERO = 2'b00;
    localparam ONE = 2'b01;
    localparam TWO = 2'b10;
    reg [1:0] state;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            s_ready <= 1;
            m_valid <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                        load_p1 <= 1;
                        s_ready <= 0;
                    end
                end
                ONE: begin
                    if (load_p1) begin
                        data_p1 <= s_data;
                        load_p1 <= 0;
                    end
                    if (m_ready) begin
                        state <= TWO;
                        load_p2 <= 1;
                    end
                end
                TWO: begin
                    if (load_p2) begin
                        data_p2 <= data_p1;
                        load_p2 <= 0;
                    end
                    if (m_ready) begin
                        m_data <= data_p2;
                        m_valid <= 1;
                        state <= ZERO;
                        s_ready <= 1;
                        m_valid <= 0;
                    end
                end
                default: state <= ZERO;
            endcase
        end
    end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk, arstn, din, dout, mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0] din;
output reg [DATA_WIDTH-1:0] dout;

reg [DATA_WIDTH-1:0] counter;
parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;
reg [1:0] state;

always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        counter <= 0;
        state <= ADD_STATE;
        dout <= 0;
    end else begin
        case (state)
            ADD_STATE: begin
                if (mode) begin
                    counter <= din + 2;
                    state <= INC_STATE;
                end else begin
                    counter <= din + 1;
                end
            end
            INC_STATE: begin
                if (!mode) begin
                    counter <= 0;
                    state <= ADD_STATE;
                end else begin
                    counter <= counter + 1;
                end
            end
            default: begin
                counter <= 0;
                state <= ADD_STATE;
            end
        endcase
        dout <= counter;
    end
end

endmodule

