    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
    localparam DEPTH = 1 << DEPTH_BITS;

    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [DEPTH_BITS-1:0] wr_ptr, rd_ptr;

    assign empty_n = (wr_ptr == rd_ptr);
    assign full_n = ((wr_ptr + 1) % DEPTH == rd_ptr);

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
        end else begin
            if (write && !full_n) begin
                mem[wr_ptr] <= din;
                wr_ptr <= (wr_ptr + 1) % DEPTH;
            end
            if (read && !empty_n) begin
                dout <= mem[rd_ptr];
                rd_ptr <= (rd_ptr + 1) % DEPTH;
            end
        end
    end
endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);

    // Define states for the FSM
    localparam S_IDLE = 2'b00;
    localparam S_RUN = 2'b01;
    localparam S_DONE = 2'b10;

    // Internal signals
    reg [1:0] state, state_n;
    reg [DWIDTH-1:0] cnt_val, cnt_val_n;
    reg run, run_n;
    reg done, done_n;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= state_n;
        end
    end

    // Counter value register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_val <= 0;
        end else begin
            cnt_val <= cnt_val_n;
        end
    end

    // Next state logic
    always @(*) begin
        state_n = state;
        cnt_val_n = cnt_val;
        run_n = run;
        done_n = done;

        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
            end
            S_RUN: begin
                if (cnt_i == cnt_val) begin
                    state_n = S_DONE;
                end
            end
            S_DONE: begin
                state_n = S_IDLE;
            end
            default: begin
                state_n = S_IDLE;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        run_o = run_n;
        done_o = done_n;
        case (state)
            S_IDLE: begin
                run = 0;
                done = 0;
            end
            S_RUN: begin
                run = 1;
                done = 0;
            end
            S_DONE: begin
                run = 0;
                done = 1;
            end
            default: begin
                run = 0;
                done = 0;
            end
        endcase
    end

endmodule

