module render_sinescroll #(
    parameter CORDW=16,       
    parameter GREET_FILE="",  
    parameter FONT_FILE="",   
    parameter SIN_FILE="",    
    parameter SIN_SHIFT=3,    
    parameter FB_WIDTH=320,   
    parameter FB_HEIGHT=180   
    ) (
    input  wire logic clk,                      
    input  wire logic rst,                      
    input  wire logic oe,                       
    input  wire logic start,                    
    output      logic signed [CORDW-1:0] x, y,  
    output      logic pix,                      
    output      logic drawing,                  
    output      logic done                      
    );

    // Parameters and constants
    localparam CHAR_WIDTH = 8;
    localparam CHAR_HEIGHT = 16;
    localparam CHAR_SIZE = CHAR_WIDTH * CHAR_HEIGHT;
    localparam FB_SIZE = FB_WIDTH * FB_HEIGHT;

    // Internal signals
    logic [CORDW-1:0] char_x, char_y;
    logic [CORDW-1:0] sine_value;
    logic [CORDW-1:0] char_data [0:CHAR_SIZE-1];
    logic [CORDW-1:0] fb [0:FB_SIZE-1];
    logic [CORDW-1:0] char_addr;
    logic [CORDW-1:0] fb_addr;
    logic [CORDW-1:0] char_count;
    logic [CORDW-1:0] frame_count;
    logic [CORDW-1:0] sine_index;
    logic [CORDW-1:0] sine_table [0:255];
    logic [CORDW-1:0] font_data [0:255];
    logic [CORDW-1:0] greet_data [0:255];
    logic [CORDW-1:0] state;
    logic [CORDW-1:0] next_state;

    // State definitions
    localparam IDLE = 0;
    localparam LOAD_CHAR = 1;
    localparam ADJUST_Y = 2;
    localparam CLIP = 3;
    localparam DRAW_CHAR = 4;
    localparam NEXT_CHAR = 5;
    localparam DONE = 6;

    // Sine table initialization
    initial begin
        $readmemh(SIN_FILE, sine_table);
    end

    // Font data initialization
    initial begin
        $readmemh(FONT_FILE, font_data);
    end

    // Greet data initialization
    initial begin
        $readmemh(GREET_FILE, greet_data);
    end

    // State machine
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = LOAD_CHAR;
                end
            end
            LOAD_CHAR: begin
                // Load character data from font ROM
                char_data[char_count] = font_data[greet_data[char_count]];
                char_count <= char_count + 1;
                if (char_count == CHAR_SIZE) begin
                    next_state = ADJUST_Y;
                end
            end
            ADJUST_Y: begin
                // Adjust y position based on sine wave
                sine_index = (frame_count >> SIN_SHIFT) & 255;
                sine_value = sine_table[sine_index];
                char_y = sine_value;
                next_state = CLIP;
            end
            CLIP: begin
                // Clip character to visible area
                if (char_x >= 0 && char_x < FB_WIDTH && char_y >= 0 && char_y < FB_HEIGHT) begin
                    next_state = DRAW_CHAR;
                end else begin
                    next_state = NEXT_CHAR;
                end
            end
            DRAW_CHAR: begin
                // Draw character pixel by pixel
                // (Implementation details depend on pixel drawing logic)
                next_state = NEXT_CHAR;
            end
            NEXT_CHAR: begin
                // Move to next character
                char_count <= char_count + 1;
                if (char_count == CHAR_SIZE) begin
                    next_state = DONE;
                end else begin
                    next_state = ADJUST_Y;
                end
            end
            DONE: begin
                // Drawing complete
                done <= 1;
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            x <= 0;
            y <= 0;
            pix <= 0;
            drawing <= 0;
        end else begin
            x <= char_x;
            y <= char_y;
            pix <= 1; // Placeholder for pixel drawing logic
            drawing <= 1;
        end
    end

endmodule

module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);

  parameter DEPTH = 512;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  reg [ADDR_WIDTH-1:0] value;
  reg [ADDR_WIDTH-1:0] value_1;
  reg maybe_full;
  reg [31:0] ram [0:DEPTH-1];

  assign io_enq_ready = ~maybe_full;
  assign io_deq_valid = (value_1 != value) || maybe_full;

  always @(posedge clock or posedge reset) begin
    if (reset) begin
      value <= 0;
      value_1 <= 0;
      maybe_full <= 0;
    end else begin
      if (io_enq_valid && io_enq_ready && do_enq) begin
        ram[value] <= io_enq_bits;
        value <= (value + 1) % DEPTH;
        if (value == value_1) begin
          maybe_full <= 1;
        end
      end
      if (io_deq_valid && io_deq_ready && do_deq) begin
        value_1 <= (value_1 + 1) % DEPTH;
        if (maybe_full) begin
          maybe_full <= 0;
        end
      end
    end
  end

endmodule

