module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);

	// Define the state encoding
	localparam IDLE = 3'b000,
				STATE1 = 3'b001,
				STATE2 = 3'b010,
				STATE3 = 3'b011,
				STATE4 = 3'b100,
				STATE5 = 3'b101,
				STATE6 = 3'b110,
				STATE7 = 3'b111;

	// Internal state register
	reg [2:0] state;

	// Next state logic
	always @(posedge clk) begin
		if (start) begin
			state <= IDLE; // Reset to IDLE on start
		end else begin
			case (state)
				IDLE: state <= STATE1;
				STATE1: state <= STATE2;
				STATE2: state <= STATE3;
				STATE3: state <= STATE4;
				STATE4: state <= STATE5;
				STATE5: state <= STATE6;
				STATE6: state <= STATE7;
				STATE7: state <= IDLE; // Wrap around to IDLE
				default: state <= IDLE; // Default to IDLE
			endcase
		end
	end

	// Direction output logic
	always @(*) begin
