  parameter [31:0] p0 = 32'd1;
  parameter [31:0] p1 = 32'd2;
  parameter [31:0] p2 = 32'd3;
  parameter [31:0] p3 = 32'd4;

  // Intermediate wires
  wire [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;

