    case (ctrl)
      4'd0: begin
        x4 = x0 + p0;
        x5 = x1 + p1;
        x6 = x2 + p2;
        x7 = x3 + p3;
      end
      4'd1: begin
        x4 = x0 - p0;
        x5 = x1 - p1;
        x6 = x2 - p2;
        x7 = x3 - p3;
      end
      4'd2: begin
        x4 = x0 * p0;
        x5 = x1 * p1;
        x6 = x2 * p2;
