module zint
(
  input  wire       clk,
  input  wire       zpos,
  input  wire       res,
  input  wire       wait_n,
  input  wire       int_start_frm,
  input  wire       int_start_lin,
  input  wire       int_start_dma,
  input  wire       int_start_wtp,
  input  wire       vdos,           
  input  wire       intack,
`ifdef PENT_312
  output wire       boost_start,
`endif
  input  wire [7:0] intmask,
  output wire [7:0] im2vect,
  output wire int_n
);
  reg [1:0] int_state;
  reg [2:0] int_priority;
  reg [7:0] int_vector;
  reg [7:0] int_masked;
  reg [7:0] int_request;
  reg [7:0] int_acknowledge;
  reg [7:0] int_enable;
  reg [7:0] int_pending;
  reg [7:0] int_processed;
  reg [7:0] int_boost;

  // Internal logic for interrupt handling
  always @(posedge clk or posedge res) begin
    if (res) begin
      int_state <= 2'b00;
      int_priority <= 3'b000;
      int_vector <= 8'b00000000;
      int_masked <= 8'b00000000;
      int_request <= 8'b00000000;
      int_acknowledge <= 8'b00000000;
      int_enable <= 8'b00000000;
      int_pending <= 8'b00000000;
      int_processed <= 8'b00000000;
      int_boost <= 8'b00000000;
    end else begin
      // Update interrupt state and priority
      int_state <= int_state + 1;
      int_priority <= int_priority + 1;

      // Generate interrupt request
      int_request <= int_start_frm | int_start_lin | int_start_dma | int_start_wtp;

      // Mask interrupts
      int_masked <= int_request & intmask;

      // Acknowledge interrupt
      int_acknowledge <= int_masked & intack;

      // Enable interrupts
      int_enable <= int_masked & ~int_processed;

      // Set pending interrupts
      int_pending <= int_enable;

      // Process interrupts
      int_processed <= int_processed | int_acknowledge;

      // Generate interrupt vector
      int_vector <= int_priority;

      // Boost signal logic
`ifdef PENT_312
      int_boost <= vdos;
      boost_start <= int_boost;
`endif

      // Output interrupt request
      int_n <= ~int_pending;
    end
  end

  // Output interrupt vector
  assign im2vect = int_vector;
endmodule

