module FFlr(
    input wire clk,
    input wire [31:0] f,
    output reg [31:0] g
);
    reg [31:0] len_raw, len, f_masked, f_incr, res, g_reg1, g_reg2;

    always @(posedge clk) begin
        // Compute len_raw by subtracting 255 from bits 30:23 of f
        len_raw = f[30:23] - 255;

        // Determine len based on specific conditions
        if (len_raw < 0) begin
            len = 0;
        end else if (len_raw > 31) begin
            len = 31;
        end else begin
            len = len_raw;
        end

        // Create f_masked by clearing bits beyond the position determined by len
        f_masked = f & ((1 << len) - 1);

        // Increment f_masked at the first set bit beyond the position determined by len
        f_incr = f_masked | (1 << (len + 1));

        // Select between f_masked and f_incr based on the value of f
        if (f[31] == 1'b1) begin
            res = f_incr;
        end else begin
            res = f_masked;
        end

        // Combine the sign of f with the modified lower bits to form the result
        if (f[31] == 1'b1) begin
            res[31] = 1'b1;
            res[30:0] = ~res[30:0] + 1;
        end else begin
            res[31] = 1'b0;
        end

        // Pipeline the result into g through two registers
        g_reg1 <= res;
        g_reg2 <= g_reg1;
        g <= g_reg2;
    end
endmodule

