module main(
    input X4,
    input X3,
    input X2,
    input X1,
    input X0,
    output F
);

    // Intermediate signals
    wire X0_not, X1_not, X0_and_X1, X0_xor_X1, decoder_out;

    // NOT gates
    assign X0_not = ~X0;
    assign X1_not = ~X1;

    // AND gate
    assign X0_and_X1 = X0 & X1;

    // XOR gate
    assign X0_xor_X1 = X0 ^ X1;

    // Decoder logic (simplified for 2 inputs)
    assign decoder_out = X0_and_X1 | X0_xor_X1;

    // Multiplexer logic
    assign F = (X4 & X3 & X2) ? X0_not : 
              (X4 & X3 & ~X2) ? X1_not : 
              (X4 & ~X3 & X2) ? decoder_out : 
              (X4 & ~X3 & ~X2) ? X0 : 
              (~X4 & X3 & X2) ? X1 : 
              (~X4 & X3 & ~X2) ? X0_not : 
              (~X4 & ~X3 & X2) ? X1_not : 
              (~X4 & ~X3 & ~X2) ? decoder_out;

endmodule

