module p_adder #(parameter N=8) (
	input [N-1:0] A, B,
	input Cin,
	output [N-1:0] S,
	output Cout
	);

	// Internal wire to hold the carry for each bit position
	wire [N:0] carry;

	// Generate the carry for each bit position
	assign carry[0] = Cin;
	generate
		for (genvar i = 0; i < N; i++) begin : add_bits
			assign carry[i+1] = carry[i] & (A[i] | B[i]);
		end
	endgenerate

	// Generate the sum for each bit position
	assign S = A ^ B ^ carry[0];
	assign Cout = carry[N];

endmodule

module mul8x7u_6PC (
