input [6:0] B;
output [14:0] O;

wire [14:0] partial_products [0:6];
wire [14:0] sum;

// Compute partial products
assign partial_products[0] = A & {B, 1'b0};
assign partial_products[1] = A & {B[5:0], 1'b0};
assign partial_products[2] = A & {B[4:0], 1'b0};
assign partial_products[3] = A & {B[3:0], 1'b0};
assign partial_products[4] = A & {B[2:0], 1'b0};
assign partial_products[5] = A & {B[1:0], 1'b0};
assign partial_products[6] = A & {B[0], 1'b0};

// Sum partial products with carry handling
assign sum = partial_products[0] + partial_products[1] + partial_products[2] + 
            partial_products[3] + partial_products[4] + partial_products[5] + 
            partial_products[6];

// Output the sum as the result
assign O = sum;

endmodule

