module ALU(
    output [31:0] ALU_o,
    input signed  [31:0] A, B,
    input  [3:0]  ALUSel
);

    wire [31:0] B_comp;
    wire [31:0] SLL;
    wire [31:0] SRL;
    wire [31:0] SRA;
    wire [31:0] XOR;
    wire [31:0] AND;
    wire [31:0] OR;
    wire [31:0] SLT;
    wire [4:0] shift_amount;

    assign B_comp = ~B + 1;
    assign shift_amount = B[4:0];

    COMP32b comp32b_inst (
        .A(A),
        .B(B),
        .SLT(SLT)
    );

    assign SLL = A << shift_amount;
    assign SRL = A >> shift_amount;
    assign SRA = $signed(A) >>> shift_amount;
    assign XOR = A ^ B;
    assign AND = A & B;
    assign OR = A | B;

    always @(*) begin
        case (ALUSel[2:0])
            3'b000: ALU_o = SLL;
            3'b001: ALU_o = SRL;
            3'b010: ALU_o = SRA;
            3'b011: ALU_o = XOR;
            3'b100: ALU_o = AND;
            3'b101: ALU_o = OR;
            3'b110: ALU_o = ALUSel[3] ? A + B : A + B_comp;
            3'b111: ALU_o = SLT;
            default: ALU_o = 32'b0;
        endcase
    end

endmodule

