    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
    reg [3:0] comp;  // Comparator register
    reg [3:0] count; // Count register
    reg pulse_reg;   // Pulse register

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
            pulse_reg <= 0;
        end else if (clk_en) begin
            if (button) begin
                count <= count + 1;
                if (count >= comp) begin
                    pulse_reg <= 1;
                    count <= 0;
                    comp <= comp - DEC_COUNT;
                    if (comp < MIN_COUNT) begin
                        comp <= MIN_COUNT;
                    end
                end
            end else begin
                pulse_reg <= 0;
                count <= 0;
                comp <= MAX_COUNT - 1;
            end
        end
    end

    assign pulse = pulse_reg;
endmodule

