module partsel_00023(
  input [3:0] ctrl,
  input [2:0] s0,
  input [2:0] s1,
  input [2:0] s2,
  input [2:0] s3,
  input signed [31:0] x0,
  input signed [31:0] x1,
  input signed [31:0] x2,
  input signed [31:0] x3,
  output [127:0] y
);

  // Local parameters for constant values
  localparam p0 = 32'd10;
  localparam p1 = 32'd20;
  localparam p2 = 32'd30;
  localparam p3 = 32'd40;

  // Internal wires for intermediate results
  wire [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;

  // Arithmetic and logical operations based on control and selection signals
  always @(*) begin
    case (ctrl)
      4'd0: begin
        x4 = x0 + x1;
        x5 = x2 - x3;
        x6 = x0 & x1;
        x7 = x2 | x3;
      end
      4'd1: begin
        x4 = x0 * x1;
        x5 = x2 / x3;
        x6 = x0 ^ x1;
        x7 = x2 << x3;
      end
      4'd2: begin
        x4 = x0 % x1;
        x5 = x2 >> x3;
        x6 = ~x0;
        x7 = x1;
      end
      default: begin
        x4 = 32'd0;
        x5 = 32'd0;
        x6 = 32'd0;
        x7 = 32'd0;
      end
    endcase

    // Selection of intermediate results based on selection signals
    x8 = (s0 == 3'b000) ? x4 : (s0 == 3'b001) ? x5 : (s0 == 3'b010) ? x6 : x7;
    x9 = (s1 == 3'b000) ? x4 : (s1 == 3'b001) ? x5 : (s1 == 3'b010) ? x6 : x7;
    x10 = (s2 == 3'b000) ? x4 : (s2 == 3'b001) ? x5 : (s2 == 3'b010) ? x6 : x7;
    x11 = (s3 == 3'b000) ? x4 : (s3 == 3'b001) ? x5 : (s3 == 3'b010) ? x6 : x7;

    // Final concatenation of intermediate results to produce the output
    y = {x11, x10, x9, x8};
  end

endmodule

