module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg [1:0] state;
    reg [1:0] next_state;
    reg s_ready_t;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;

    // State definitions
    parameter ZERO = 2'b00;
    parameter ONE = 2'b01;
    parameter TWO = 2'b10;

    // Combinational logic for next state and control signals
    always @(*) begin
        next_state = state;
        s_ready_t = 1'b0;
        load_p1 = 1'b0;
        load_p2 = 1'b0;
        load_p1_from_p2 = 1'b0;

        case (state)
            ZERO:
                if (s_valid && !m_ready)
                    next_state = ONE;
                else if (s_valid && m_ready)
                    next_state = TWO;
            ONE:
                if (m_ready)
                    next_state = TWO;
            TWO:
                if (!m_ready)
                    next_state = ONE;
        endcase

        if (state == ZERO && s_valid && !m_ready)
            s_ready_t = 1'b1;
        if (state == ONE && m_ready)
            load_p1 = 1'b1;
        if (state == TWO && !m_ready)
            load_p1_from_p2 = 1'b1;
    end

    // Sequential logic for state and control signals
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            s_ready_t <= 1'b0;
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            state <= next_state;
            s_ready <= s_ready_t;
            if (load_p1)
                data_p1 <= s_data;
            if (load_p1_from_p2)
                data_p2 <= data_p1;
            if (state == TWO && m_ready)
                m_data <= data_p2;
            if (state == TWO && m_ready)
                m_valid <= 1'b1;
            else
                m_valid <= 1'b0;
        end
    end

endmodule

