module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
    );

    // Define state parameters
    parameter S1 = 3'b000;
    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;

    // State register
    reg [2:0] state;

    // Next state register
    reg [2:0] next;

    // Output assignment
    assign z = (state == S6) ? 1'b1 : 1'b0;

    // Synchronous state update
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S1;  // Asynchronous reset to state S1
        end else begin
            state <= next;  // Synchronous update to next state
        end
    end

    // Combinational logic to determine next state
    always @(*) begin
        case (state)
            S1: next = (x) ? S2 : S1;
            S2: next = (x) ? S3 : S1;
            S3: next = (x) ? S4 : S1;
            S4: next = (x) ? S5 : S1;
            S5: next = (x) ? S6 : S1;
            S6: next = (x) ? S6 : S1;  // Stay in S6 if x is 0
            default: next = S1;  // Default to S1 if state is invalid
        endcase
    end

endmodule

