module leddec16(
    input wire [1:0] dig,
    input wire [15:0] data,
    output wire [3:0] anode,
    output wire [6:0] seg
);

    // Define the segment patterns for each hexadecimal digit
    reg [6:0] seg_patterns [0:15];
    initial begin
        seg_patterns[0] = 7'b1111110; // 0
        seg_patterns[1] = 7'b0110000; // 1
        seg_patterns[2] = 7'b1101101; // 2
        seg_patterns[3] = 7'b1111001; // 3
        seg_patterns[4] = 7'b0110011; // 4
        seg_patterns[5] = 7'b1011011; // 5
        seg_patterns[6] = 7'b1011111; // 6
        seg_patterns[7] = 7'b1110000; // 7
        seg_patterns[8] = 7'b1111111; // 8
        seg_patterns[9] = 7'b1111011; // 9
        seg_patterns[10] = 7'b1110111; // A
        seg_patterns[11] = 7'b1011101; // B
        seg_patterns[12] = 7'b1111100; // C
        seg_patterns[13] = 7'b1001111; // D
        seg_patterns[14] = 7'b1111000; // E
        seg_patterns[15] = 7'b1110001; // F
    end

    // Extract the four bits to be displayed based on the digit select
    reg [3:0] display_bits;
    always @(*) begin
        case (dig)
            2'b00: display_bits = data[3:0];
            2'b01: display_bits = data[7:4];
            2'b10: display_bits = data[11:8];
            2'b11: display_bits = data[15:12];
            default: display_bits = 4'b0000;
        endcase
    end

    // Generate the segment output
    assign seg = seg_patterns[display_bits];

    // Generate the anode output
    reg [3:0] anode_enable;
    always @(*) begin
        anode_enable = 4'b0000;
        case (dig)
            2'b00: if (display_bits != 4'b0000) anode_enable[0] = 1'b1;
            2'b01: if (display_bits != 4'b0000 || data[3:0] != 4'b0000) anode_enable[1] = 1'b1;
            2'b10: if (display_bits != 4'b0000 || data[7:4] != 4'b0000 || data[3:0] != 4'b0000) anode_enable[2] = 1'b1;
            2'b11: if (display_bits != 4'b0000 || data[11:8] != 4'b0000 || data[7:4] != 4'b0000 || data[3:0] != 4'b0000) anode_enable[3] = 1'b1;
        endcase
    end

    assign anode = ~anode_enable;

endmodule

module bsg_fifo_1r1w_small_width_p109_els_p2_ready_THEN_valid_p1
(
  clk_i,
  reset_i,
  v_i,
  ready_o,
  data_i,
  v_o,
  data_o,
  yumi_i
);
  parameter width_p = 109;
  parameter els_p = 2;

  input [width_p-1:0] data_i;
  output [width_p-1:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input yumi_i;
  output ready_o;
  output v_o;

  reg [width_p-1:0] mem [0:els_p-1];
  reg [els_p-1:0] wr_ptr;
  reg [els_p-1:0] rd_ptr;
  reg full;
  reg empty;

  assign ready_o = ~full;
  assign v_o = ~empty;

  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      full <= 0;
      empty <= 1;
    end else begin
      if (v_i && ~full) begin
        mem[wr_ptr] <= data_i;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == els_p - 1) begin
          wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
          full <= 1;
        end
        empty <= 0;
      end
      if (yumi_i && ~empty) begin
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == els_p - 1) begin
          rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
          empty <= 1;
        end
        full <= 0;
      end
    end
  end

  always @(posedge clk_i) begin
    if (v_i && ~full) begin
      mem[wr_ptr] <= data_i;
    end
    if (yumi_i && ~empty) begin
      data_o <= mem[rd_ptr];
    end
  end
endmodule

module muladd_3_stage_unsigned_17_bit_xor_reduction(
	input  [16:0] a,
	input  [16:0] b,
	input  [16:0] c,
	output [16:0] out,
	input clk);

reg [33:0] stage0, stage1, stage2;

always @(posedge clk) begin
    // Stage 0: Compute the product of a and b, then add c
    stage0 <= a * b + c;

    // Stage 1: Pass the result of stage0 to stage1
    stage1 <= stage0;

    // Stage 2: Pass the result of stage1 to stage2
    stage2 <= stage1;
end

// Final XOR reduction to produce a single-bit output
assign out = stage2[33] ^ stage2[32] ^ stage2[31] ^ stage2[30] ^ stage2[29] ^ stage2[28] ^
             stage2[27] ^ stage2[26] ^ stage2[25] ^ stage2[24] ^ stage2[23] ^ stage2[22] ^
