module IF_stage #(parameter MEM_WIDTH=8, parameter WIDTH, parameter OFF_WIDTH=6)(clk, reset, addr, instr, jump, stall, jumpOffset);
	input clk, reset, jump, stall;
	output [WIDTH-1:0] instr;
	output [MEM_WIDTH-1:0] addr;
	input [OFF_WIDTH-1:0] jumpOffset;

	// Program Counter (PC) register
	reg [MEM_WIDTH-1:0] pc;

	// Instruction Memory
	reg [WIDTH-1:0] instruction_memory [0:2**MEM_WIDTH-1];

	// Sign Extend Unit
	function [MEM_WIDTH-1:0] signExtend;
		input [OFF_WIDTH-1:0] offset;
		begin
			signExtend = {OFF_WIDTH{offset[OFF_WIDTH-1]}}, offset;
		end
	endfunction

	// Address calculation
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			pc <= 0;
		end else if (!stall) begin
			if (jump) begin
				pc <= signExtend(jumpOffset);
			end else begin
				pc <= pc + 1;
			end
		end
	end

	// Instruction Memory access
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			instr <= 0;
		end else begin
			addr <= pc;
			instr <= instruction_memory[pc];
		end
	end

endmodule

