module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2(FIFO_DEPTH)-1:0]usedw;
output reg empty;
output reg full;

reg [clog2(FIFO_DEPTH)-1:0] wr_ptr;
reg [clog2(FIFO_DEPTH)-1:0] rd_ptr;
reg [DATA_WIDTH-1:0] mem [0:FIFO_DEPTH-1];

parameter clog2 = function (int arg) return (int) (log(arg)/log(2) + 0.5); endfunction;

always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        usedw <= 0;
        empty <= 1;
        full <= 0;
    end else begin
        if (wrreq && !full) begin
            mem[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == FIFO_DEPTH - 1) begin
                wr_ptr <= 0;
            end
            usedw <= usedw + 1;
            if (usedw == FIFO_DEPTH) begin
                full <= 1;
            end else begin
                full <= 0;
            end
        end
        if (rdreq && !empty) begin
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == FIFO_DEPTH - 1) begin
                rd_ptr <= 0;
            end
            usedw <= usedw - 1;
            if (usedw == 0) begin
                empty <= 1;
            end else begin
                empty <= 0;
            end
        end
    end
end

assign data_out = mem[rd_ptr];
assign empty = (usedw == 0);
assign full = (usedw == FIFO_DEPTH);

endmodule

