module xfcp_interface_uart
(
    input  wire         clk,
    input  wire         rst,

    input  wire         uart_rxd,
    output wire         uart_txd,

    input  wire [7:0]   down_xfcp_in_tdata,
    input  wire         down_xfcp_in_tvalid,
    output wire         down_xfcp_in_tready,
    input  wire         down_xfcp_in_tlast,
    input  wire         down_xfcp_in_tuser,

    output wire [7:0]   down_xfcp_out_tdata,
    output wire         down_xfcp_out_tvalid,
    input  wire         down_xfcp_out_tready,
    output wire         down_xfcp_out_tlast,
    output wire         down_xfcp_out_tuser,

    input  wire [15:0]  prescale
);

    parameter FIFO_DEPTH = 256;
    parameter DATA_WIDTH = 8;

    wire [DATA_WIDTH-1:0] tx_fifo_data_out;
    wire tx_fifo_valid_out;
    wire tx_fifo_ready_out;
    wire tx_fifo_last_out;

    wire [DATA_WIDTH-1:0] rx_fifo_data_out;
    wire rx_fifo_valid_out;
    wire rx_fifo_ready_out;
    wire rx_fifo_last_out;

    wire [DATA_WIDTH-1:0] cobs_encoded_data;
    wire cobs_encoded_valid;
    wire cobs_encoded_ready;

    wire [DATA_WIDTH-1:0] cobs_decoded_data;
    wire cobs_decoded_valid;
    wire cobs_decoded_ready;

    // TX FIFO
    fifo #(.WIDTH(DATA_WIDTH), .DEPTH(FIFO_DEPTH)) tx_fifo
    (
        .clk(clk),
        .rst(rst),
        .din(down_xfcp_in_tdata),
        .wr_en(down_xfcp_in_tvalid & down_xfcp_in_tready),
        .rd_en(tx_fifo_ready_out),
        .dout(tx_fifo_data_out),
        .full(tx_fifo_ready_out),
        .empty(tx_fifo_valid_out),
        .almost_full(tx_fifo_ready_out),
        .almost_empty(tx_fifo_valid_out)
    );

    // COBS Encoder
    cobs_encoder #(.WIDTH(DATA_WIDTH)) cobs_encoder_inst
    (
        .clk(clk),
        .rst(rst),
        .din(tx_fifo_data_out),
        .valid(tx_fifo_valid_out),
        .ready(cobs_encoded_ready),
        .dout(cobs_encoded_data),
        .valid_out(cobs_encoded_valid)
    );

    // UART Core
    uart_core #(.DATA_WIDTH(DATA_WIDTH), .PRESCALE(prescale)) uart_core_inst
    (
        .clk(clk),
        .rst(rst),
        .tx_data(cobs_encoded_data),
        .tx_valid(cobs_encoded_valid),
        .tx_ready(cobs_encoded_ready),
        .tx_done(),
        .rx_data(uart_rxd),
        .rx_valid(rx_fifo_ready_out),
        .rx_ready(rx_fifo_data_out),
        .rx_done()
    );

    // COBS Decoder
    cobs_decoder #(.WIDTH(DATA_WIDTH)) cobs_decoder_inst
    (
        .clk(clk),
        .rst(rst),
        .din(rx_fifo_data_out),
        .valid(rx_fifo_valid_out),
        .ready(cobs_decoded_ready),
        .dout(cobs_decoded_data),
        .valid_out(cobs_decoded_valid)
    );

    // RX FIFO
    fifo #(.WIDTH(DATA_WIDTH), .DEPTH(FIFO_DEPTH)) rx_fifo
    (
        .clk(clk),
        .rst(rst),
        .din(cobs_decoded_data),
        .wr_en(cobs_decoded_valid & cobs_decoded_ready),
        .rd_en(down_xfcp_out_tready),
        .dout(rx_fifo_data_out),
        .full(rx_fifo_ready_out),
        .empty(rx_fifo_valid_out),
        .almost_full(rx_fifo_ready_out),
        .almost_empty(rx_fifo_valid_out)
    );

    // Output Management
    assign down_xfcp_out_tdata = rx_fifo_data_out;
    assign down_xfcp_out_tvalid = rx_fifo_valid_out;
    assign down_xfcp_out_tlast = rx_fifo_last_out;
    assign down_xfcp_out_tuser = 1'b0; // Assuming no user signal is needed

    // Input Management
    assign down_xfcp_in_tready = tx_fifo_ready_out;

endmodule

