module ltcdrw
  (
   input   [63:0] in_data,
   output  [63:0] out_data
   );

  wire [31:0] ldrw_out1;
  wire [31:0] ldrw_out2;

  // Split the input into two 32-bit segments
  wire [7:0] cell0 = in_data[7:0];
  wire [7:0] cell1 = in_data[15:8];
  wire [7:0] cell2 = in_data[23:16];
  wire [7:0] cell3 = in_data[31:24];
  wire [7:0] cell4 = in_data[39:32];
  wire [7:0] cell5 = in_data[47:40];
  wire [7:0] cell6 = in_data[55:48];
  wire [7:0] cell7 = in_data[63:56];

  // Process each 32-bit segment using two ldrw instances
  ldrw ldrw_inst1 (
    .in_data({cell0, cell1, cell2, cell3}),
    .out_data(ldrw_out1)
  );

  ldrw ldrw_inst2 (
    .in_data({cell4, cell5, cell6, cell7}),
    .out_data(ldrw_out2)
  );

  // Concatenate the 32-bit outputs to form the 64-bit output
  assign out_data = {ldrw_out1, ldrw_out2};

endmodule

