module mux8to1(Q, S, i1, i2, i3, i4, i5, i6, i7, i8);
  input i1, i2, i3, i4, i5, i6, i7, i8;
  input [2:0] S;
  output Q;

  wire [7:0] select_lines;
  wire [7:0] gated_inputs;

  // Decoder to generate select lines
  assign select_lines = 1 << S;

  // AND gates to gate inputs with select lines
  assign gated_inputs[0] = i1 & select_lines[0];
  assign gated_inputs[1] = i2 & select_lines[1];
  assign gated_inputs[2] = i3 & select_lines[2];
  assign gated_inputs[3] = i4 & select_lines[3];
  assign gated_inputs[4] = i5 & select_lines[4];
  assign gated_inputs[5] = i6 & select_lines[5];
  assign gated_inputs[6] = i7 & select_lines[6];
  assign gated_inputs[7] = i8 & select_lines[7];

  // OR gate to combine gated inputs
  assign Q = |gated_inputs;
endmodule

