module mul8u_13QR (
    A,
    B,
    O
);

input [7:0] A;
input [7:0] B;
output [15:0] O;

// Internal signals for the shift-and-add process
wire [15:0] partial_products [7:0];
wire [15:0] sum;

// Generate partial products
assign partial_products[0] = A[0] ? B : 8'b0;
assign partial_products[1] = A[1] ? (B << 1) : 8'b0;
assign partial_products[2] = A[2] ? (B << 2) : 8'b0;
assign partial_products[3] = A[3] ? (B << 3) : 8'b0;
assign partial_products[4] = A[4] ? (B << 4) : 8'b0;
assign partial_products[5] = A[5] ? (B << 5) : 8'b0;
assign partial_products[6] = A[6] ? (B << 6) : 8'b0;
assign partial_products[7] = A[7] ? (B << 7) : 8'b0;

// Sum the partial products
assign sum = partial_products[0] + partial_products[1] + partial_products[2] + 
            partial_products[3] + partial_products[4] + partial_products[5] + 
            partial_products[6] + partial_products[7];

// Assign the output
assign O = sum;

endmodule

