module fa(sum, cout, a, b, cin);
  input a, b, cin;
  output sum, cout;

  wire w0, w1, w2;

  // First XOR operation: a XOR b
  assign w0 = a ^ b;

  // First AND operation: a AND b
  assign w1 = a & b;

  // Second AND operation: w0 AND cin
  assign w2 = w0 & cin;

  // Sum output: w0 XOR cin
  assign sum = w0 ^ cin;

  // Carry-out: w1 OR w2
  assign cout = w1 | w2;
endmodule

