module testbench;
  // Parameters
  parameter WIDTH = 3;

  // Signals
  reg [WIDTH-1:0] A, B;
  wire A_greater, A_equal, A_less;
  integer i, error;

  // Instantiate the comparator module
  comparator_3bit comparator (
    .A(A),
    .B(B),
    .A_greater(A_greater),
    .A_equal(A_equal),
    .A_less(A_less)
  );

  // Initial block to set up the test environment
  initial begin
    // Initialize error count
    error = 0;

    // Run 100 test cases
    for (i = 0; i < 100; i = i + 1) begin
      // Generate random 3-bit values for A and B
      A = $random % (1 << WIDTH);
      B = $random % (1 << WIDTH);

      // Check the comparison results
      if ((A > B) != A_greater) begin
        $display("Error: A = %d, B = %d, A_greater = %b, Expected = %b", A, B, A_greater, A > B);
        error = error + 1;
      end
      if ((A == B) != A_equal) begin
        $display("Error: A = %d, B = %d, A_equal = %b, Expected = %b", A, B, A_equal, A == B);
        error = error + 1;
      end
      if ((A < B) != A_less) begin
        $display("Error: A = %d, B = %d, A_less = %b, Expected = %b", A, B, A_less, A < B);
        error = error + 1;
      end
    end

    // Display the test results
    if (error == 0) begin
      $display("Test passed: No errors found.");
    end else begin
      $display("Test failed: %0d errors found.", error);
    end

    // Finish the simulation
    $finish;
  end
endmodule

module muland_2_stage_signed_9_bit(
