reg [17:0] stage0;
reg [17:0] stage1;

always @(posedge clk) begin
    // Stage 0: Capture the product of a and b, then AND with c
    stage0 <= a * b & c;
end

always @(posedge clk) begin
    // Stage 1: Update stage1 with the result from stage0
    stage1 <= stage0;
end

