module bsg_fifo_1rw_large_width_p62_els_p64_verbose_p0
(
  clk_i,
  reset_i,
  data_i,
  v_i,
  enq_not_deq_i,
  full_o,
  empty_o,
  data_o
);
  parameter width_p = 62;
  parameter els_p = 64;
  parameter verbose_p = 0;

  input [width_p-1:0] data_i;
  output [width_p-1:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input enq_not_deq_i;
  output full_o;
  output empty_o;

  reg [width_p-1:0] mem [0:els_p-1];
  reg [5:0] wr_ptr;
  reg [5:0] rd_ptr;
  reg wr_en;
  reg rd_en;
  reg [1:0] last_op; // 00: idle, 01: enqueue, 10: dequeue

  assign full_o = (wr_ptr == rd_ptr) && (last_op == 2'b01);
  assign empty_o = (wr_ptr == rd_ptr) && (last_op == 2'b10);

  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      wr_ptr <= 6'b0;
      rd_ptr <= 6'b0;
      last_op <= 2'b00;
    end else begin
      wr_en <= v_i && enq_not_deq_i;
      rd_en <= v_i && !enq_not_deq_i;
      if (wr_en) begin
        mem[wr_ptr] <= data_i;
        wr_ptr <= wr_ptr + 1;
        last_op <= 2'b01;
      end else if (rd_en) begin
        rd_ptr <= rd_ptr + 1;
        last_op <= 2'b10;
      end
    end
  end

  always @(posedge clk_i) begin
    if (rd_en && !empty_o) begin
      data_o <= mem[rd_ptr];
    end
  end

endmodule

module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );

  localparam SEED = 32'h12345678; // Example seed value, not used in the module

  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_x_d, M_y_d, M_z_d, M_w_d;

  // Initialize M_w_d with a constant and the seed
  initial begin
    M_w_d = 32'h87654321; // Example constant
    M_x_d = seed;
    M_y_d = seed;
    M_z_d = seed;
  end

  // Combinational logic to compute the next state values
  always @(*) begin
    M_x_d = M_y;
    M_y_d = M_z;
    M_z_d = M_w;
    // Feedback term t derived from M_x_q
    reg [31:0] t = M_x[31] ^ M_x[27] ^ M_x[26] ^ M_x[23] ^ M_x[16];
    M_w_d = M_w ^ t;
  end

  // Synchronous update of the registers on the next signal
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      M_x <= seed;
      M_y <= seed;
      M_z <= seed;
      M_w <= M_w_d; // Initialize M_w with M_w_d
    end else if (next) begin
      M_x <= M_x_d;
      M_y <= M_y_d;
      M_z <= M_z_d;
      M_w <= M_w_d;
    end
  end

  // Output the current state of M_w_q
  assign num = M_w;

endmodule

module submuland_2_stage_unsigned_10_bit(
