reg [19:0] stage1;

always @(posedge clk) begin
    // Stage 0: Perform (d - a) * b
    stage0 <= ((d - a) * b) & c;
end

always @(posedge clk) begin
    // Stage 1: Pass the result from stage0 to stage1
    stage1 <= stage0;
end

assign out = stage1[19:10]; // Output the upper 10 bits of stage1

endmodule

