    input clk;
    input clrn;
    input aload; 
    input sclr; 
    input sload; 
    input asdata; 
    input ena; 
    input devclrn; 
    input devpor; 

    output q;

    reg q_reg;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] control;
    reg [1:0] next_control;
    reg [1:0] violation;
    reg [1:0] next_violation;

    // State encoding
    parameter RESET = 2'b00;
    parameter CLEAR = 2'b01;
    parameter LOAD = 2'b10;
    parameter NORMAL = 2'b11;

    // Control encoding
    parameter ASYNC_RESET = 2'b00;
    parameter ASYNC_CLEAR = 2'b01;
    parameter ASYNC_LOAD = 2'b10;
    parameter ASYNC_ENA = 2'b11;

    // Violation encoding
    parameter NO_VIOLATION = 2'b00;
    parameter SETUP_VIOLATION = 2'b01;
    parameter HOLD_VIOLATION = 2'b10;

    // State transition logic
    always @(posedge clk or negedge clrn) begin
        if (!clrn) begin
            state <= RESET;
        end else begin
            state <= next_state;
        end
    end

    // Control logic
    always @(*) begin
        next_control = control;
        if (aload) begin
            next_control = ASYNC_LOAD;
        end else if (sclr) begin
            next_control = ASYNC_CLEAR;
        end else if (clrn) begin
            next_control = ASYNC_RESET;
        end else if (ena) begin
            next_control = ASYNC_ENA;
        end
    end

    // Output logic
    always @(*) begin
        q = q_reg;
        if (state == LOAD) begin
            q = asdata;
        end
    end

    // Timing constraint enforcement
    specify
        // Setup time
        path (clk, asdata, q) = (setup_time) iff (next_control == ASYNC_LOAD);
        // Hold time
        path (clk, asdata, q) = (hold_time) iff (next_control == ASYNC_LOAD);
    endspecify

    // Power-up state
    initial begin
        q_reg = 0;
        state = RESET;
        control = ASYNC_RESET;
        violation = NO_VIOLATION;
    end

endmodule

