module fsm_trafic_light(clk, reset, red, yellow, green);
  input clk, reset;
  output reg red, yellow, green;

  // Define the states
  typedef enum reg [1:0] {RED, GREEN, YELLOW1, YELLOW2} state_t;
  state_t current_state, next_state;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= RED;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    red = 0;
    yellow = 0;
    green = 0;

    case (current_state)
      RED: begin
        red = 1;
        next_state = GREEN;
      end
      GREEN: begin
        green = 1;
        next_state = YELLOW1;
      end
      YELLOW1: begin
        yellow = 1;
        next_state = RED;
      end
      YELLOW2: begin
        yellow = 1;
        next_state = RED;
      end
      default: begin
        current_state = RED;
      end
    endcase
  end

  // Yellow light is active in two non-consecutive states
  always @(*) begin
    if (current_state == YELLOW1) begin
      yellow = 1;
    end else if (current_state == YELLOW2) begin
      yellow = 1;
    end
  end

endmodule

