module lpm_or #(
    parameter lpm_width = 8,
    parameter lpm_size = 4
) (
    input  [(lpm_size * lpm_width)-1:0] data,
    output [lpm_width-1:0] result
);

    // Parameter validation
    initial begin
        if (lpm_width <= 0 || lpm_size <= 0) begin
            $error("lpm_width and lpm_size must be greater than zero");
            $finish;
        end
    end

    // Temporary register to store the OR result
    reg [lpm_width-1:0] or_result;

    // Combinational logic to compute the OR operation
    always @(*) begin
        or_result = 0;
        for (int i = 0; i < lpm_size; i = i + 1) begin
            or_result = or_result | data[(i * lpm_width) +: lpm_width];
        end
    end

    // Assign the OR result to the output
    assign result = or_result;

endmodule

module mul3bc(input[2:0] x, y, output[5:0] out);
