  assign partial_product0 = x << 0;
  assign partial_product1 = (y[1] ? (x << 1) : 0);
  assign partial_product2 = (y[2] ? (x << 2) : 0);

  // Sum the partial products to get the final result
  assign sum = partial_product0 + partial_product1 + partial_product2;

  // Assign the sum to the output
  assign out = sum;
endmodule

