module adc_gearbox_8x4 (
  input  wire         clk1x,
  input  wire         reset_n_1x,

  input  wire [127:0] adc_q_in_1x,
  input  wire [127:0] adc_i_in_1x,
  input  wire         valid_in_1x,

  input  wire         enable_1x,

  input  wire         clk2x,

  input  wire         swap_iq_2x,
  output wire [127:0] adc_out_2x,
  output wire         valid_out_2x
);

  reg [127:0] adc_q_reg;
  reg [127:0] adc_i_reg;
  reg [127:0] adc_out_reg;
  reg valid_out_reg;
  reg [3:0] toggle_reg;
  reg [3:0] count_reg;

  always @(posedge clk1x or negedge reset_n_1x) begin
    if (!reset_n_1x) begin
      adc_q_reg <= 128'b0;
      adc_i_reg <= 128'b0;
      valid_out_reg <= 1'b0;
      toggle_reg <= 4'b0;
      count_reg <= 4'b0;
    end else if (enable_1x && valid_in_1x) begin
      adc_q_reg <= adc_q_in_1x;
      adc_i_reg <= adc_i_in_1x;
      toggle_reg <= toggle_reg + 1;
      count_reg <= count_reg + 1;
      if (count_reg == 4'b1111) begin
        count_reg <= 4'b0000;
        valid_out_reg <= 1'b1;
      end else begin
        valid_out_reg <= 1'b0;
      end
    end else begin
      valid_out_reg <= 1'b0;
    end
  end

  always @(posedge clk2x or negedge reset_n_1x) begin
    if (!reset_n_1x) begin
      adc_out_reg <= 128'b0;
    end else if (valid_out_reg) begin
      if (swap_iq_2x) begin
        adc_out_reg[127:96] <= adc_i_reg[127:96];
        adc_out_reg[95:64] <= adc_q_reg[127:96];
        adc_out_reg[63:32] <= adc_i_reg[63:32];
        adc_out_reg[31:0] <= adc_q_reg[63:32];
      end else begin
        adc_out_reg[127:96] <= adc_q_reg[127:96];
        adc_out_reg[95:64] <= adc_i_reg[127:96];
        adc_out_reg[63:32] <= adc_q_reg[63:32];
        adc_out_reg[31:0] <= adc_i_reg[63:32];
      end
    end
  end

  assign adc_out_2x = adc_out_reg;
  assign valid_out_2x = valid_out_reg;

endmodule

