module addmulsub_3_stage_unsigned_14_bit_xor_reduction(
	input  [13:0] a,
	input  [13:0] b,
	input  [13:0] c,
	input  [13:0] d,
	output [13:0] out,
	input clk);

reg [13:0] stage0;
reg [27:0] stage1;
reg [27:0] stage2;
reg [13:0] xor_result;

always @(posedge clk) begin
    // Stage 0: Addition of a and b
    stage0 <= a + b;

    // Stage 1: Multiplication of stage0 and c
    stage1 <= stage0 * c;

    // Stage 2: Subtraction of d from stage1
    stage2 <= stage1 - d;
end

always @(posedge clk) begin
    // XOR reduction of the 28-bit result of stage2
    xor_result <= stage2[27] ^ stage2[26] ^ stage2[25] ^ stage2[24] ^
                  stage2[23] ^ stage2[22] ^ stage2[21] ^ stage2[20] ^
                  stage2[19] ^ stage2[18] ^ stage2[17] ^ stage2[16] ^
                  stage2[15] ^ stage2[14] ^ stage2[13] ^ stage2[12] ^
                  stage2[11] ^ stage2[10] ^ stage2[9]  ^ stage2[8]  ^
                  stage2[7]  ^ stage2[6]  ^ stage2[5]  ^ stage2[4]  ^
                  stage2[3]  ^ stage2[2]  ^ stage2[1]  ^ stage2[0];
end

assign out = xor_result;

endmodule

