module sum22bit(a, b, kIn, sum);
    input [21:0] a;
    input [21:0] b;
    input [1:0] kIn;
    output [22:0] sum;

    wire [21:0] sum_int;
    wire [21:0] carry_int;
    wire [21:0] carry_out;

    // Generate carry lookahead logic
    generate
        genvar i;
        for (i = 0; i < 22; i = i + 1) begin : carry_loops
            assign carry_int[i] = (i == 0) ? kIn[0] : carry_int[i - 1] | (a[i] & b[i]);
        end
    endgenerate

    // Generate sum using XOR and carry
    generate
        genvar j;
        for (j = 0; j < 22; j = j + 1) begin : sum_loops
            assign sum_int[j] = a[j] ^ b[j] ^ carry_int[j];
        end
    endgenerate

    // Generate final carry-out
    assign carry_out = carry_int[21];

    // Combine sum and carry-out to produce final sum
    assign sum = {carry_out, sum_int};

