module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
    localparam IDLE = 3'b000,
               START_BIT = 3'b001,
               DATA_BITS = 3'b010,
               PARITY_BIT = 3'b011,
               STOP_BIT = 3'b100;

    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] bit_counter;
    reg [7:0] shift_reg;
    reg parity;
    reg [3:0] bit_period_counter;
    reg [3:0] bit_period;

    // Calculate bit period for 9600 baud rate
    assign bit_period = 16'd10416; // Assuming 16MHz clock

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_counter <= 3'b000;
            shift_reg <= 8'b00000000;
            parity <= 1'b0;
            bit_period_counter <= 4'b0000;
            done <= 1'b0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (start) begin
                        shift_reg <= data_in;
                        parity <= ^data_in;
                        bit_counter <= 3'b000;
                        next_state <= START_BIT;
                    end else begin
                        next_state <= IDLE;
                    end
                end
                START_BIT: begin
                    data_out <= 1'b0;
                    bit_period_counter <= bit_period_counter + 1;
                    if (bit_period_counter == bit_period) begin
                        bit_period_counter <= 4'b0000;
                        next_state <= DATA_BITS;
                    end
                end
                DATA_BITS: begin
                    data_out <= shift_reg[7];
                    shift_reg <= {shift_reg[6:0], 1'b0};
                    bit_counter <= bit_counter + 1;
                    bit_period_counter <= bit_period_counter + 1;
                    if (bit_counter == 3'b111) begin
                        bit_counter <= 3'b000;
                        next_state <= PARITY_BIT;
                    end else if (bit_period_counter == bit_period) begin
                        bit_period_counter <= 4'b0000;
                    end
                end
                PARITY_BIT: begin
                    data_out <= parity;
                    bit_period_counter <= bit_period_counter + 1;
                    if (bit_period_counter == bit_period) begin
                        bit_period_counter <= 4'b0000;
                        next_state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    data_out <= 1'b1;
                    bit_period_counter <= bit_period_counter + 1;
                    if (bit_period_counter == bit_period) begin
                        bit_period_counter <= 4'b0000;
                        next_state <= IDLE;
                        done <= 1'b1;
                    end
                end
            endcase
        end
    end
endmodule

module muladd_3_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;
reg [15:0] stage2;

always @(posedge clk) begin
    // Stage 0: Compute (a * b) + c and store in stage0
    stage0 <= a * b + c;
end

always @(posedge clk) begin
    // Stage 1: Pass stage0's result to stage1
    stage1 <= stage0;
end

always @(posedge clk) begin
    // Stage 2: Pass stage1's result to stage2
    stage2 <= stage1;
end

always @(posedge clk) begin
    // Output the result from stage2
    out <= stage2[7:0];
end

endmodule

