module addr_decode #(
  parameter int unsigned NoIndices = 32'd0, 
  parameter int unsigned NoRules   = 32'd0, 
  parameter type         addr_t    = logic, 
  parameter type         rule_t    = logic, 

  parameter int unsigned IdxWidth  = (NoIndices > 32'd1) ? $clog2(NoIndices) : 32'd1,
  parameter type         idx_t     = logic [IdxWidth-1:0]
) (
  input  addr_t               addr_i,           
  input  rule_t [NoRules-1:0] addr_map_i,       
  output idx_t                idx_o,            
  output logic                dec_valid_o,      
  output logic                dec_error_o,      

  input  logic                en_default_idx_i, 
  input  idx_t                default_idx_i     
);

  typedef struct packed {
    addr_t start;
    addr_t end;
    idx_t  index;
  } rule_struct_t;

  rule_struct_t [NoRules-1:0] rules;
  assign rules = addr_map_i;

  logic [NoRules-1:0] match;
  logic [IdxWidth-1:0] decoded_idx;
  logic valid, error;

  always_comb begin
    match = 0;
    decoded_idx = 0;
    valid = 0;
    error = 0;

    for (int i = 0; i < NoRules; i++) begin
      if (addr_i >= rules[i].start && addr_i <= rules[i].end) begin
        match[i] = 1;
        decoded_idx = rules[i].index;
      end
    end

    // Check for overlapping rules
    for (int i = 0; i < NoRules; i++) begin
      for (int j = i + 1; j < NoRules; j++) begin
        if (rules[i].start < rules[j].end && rules[j].start < rules[i].end) begin
          $display("Error: Overlapping address ranges detected between rule %0d and rule %0d", i, j);
          error = 1;
        end
      end
    end

    // Check if each rule's start address is less than its end address
    for (int i = 0; i < NoRules; i++) begin
      if (rules[i].start >= rules[i].end) begin
        $display("Error: Invalid address range for rule %0d, start >= end", i);
        error = 1;
      end
    end

    // Ensure only one rule matches
    if (match.sum() != 1) begin
      $display("Error: More than one rule matches the address");
      error = 1;
    end

    // Set outputs
    if (match.sum() == 1) begin
      idx_o = decoded_idx;
      dec_valid_o = 1;
      dec_error_o = 0;
    end else if (en_default_idx_i) begin
      idx_o = default_idx_i;
      dec_valid_o = 1;
      dec_error_o = 0;
    end else begin
      idx_o = 0;
      dec_valid_o = 0;
      dec_error_o = 1;
    end
  end

endmodule

