module key_filter(clk, rst_n, key_pin, key_status, key_event);
    input clk;
    input rst_n;
    input key_pin;
    output reg key_status;
    output reg key_event;

    // Internal states
    localparam IDLE = 2'b00;
    localparam PRESS = 2'b01;
    localparam STEADY = 2'b10;
    localparam RELEASE = 2'b11;

    reg [1:0] state, next_state;
    reg [2:0] press_count, release_count;
    reg [1:0] key_reg;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            key_status <= IDLE;
            key_event <= 0;
            press_count <= 0;
            release_count <= 0;
            key_reg <= 2'b00;
        end else begin
            state <= next_state;
            key_status <= state;
            if (key_event) begin
                key_event <= 0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        key_event = 0;
        case (state)
            IDLE: begin
                key_reg <= {key_reg[1], key_pin};
                if (key_reg == 2'b01) begin
                    next_state = PRESS;
                    press_count <= 0;
                end
            end
            PRESS: begin
                press_count <= press_count + 1;
                if (press_count >= 3) begin
                    next_state = STEADY;
                end
            end
            STEADY: begin
                key_reg <= {key_reg[1], key_pin};
                if (key_reg == 2'b10) begin
                    next_state = RELEASE;
                    release_count <= 0;
                end
            end
            RELEASE: begin
                release_count <= release_count + 1;
                if (release_count >= 3) begin
                    next_state = IDLE;
                    key_event = 1;
                end
            end
        endcase
    end

endmodule

module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
  reg [31:0] temp_result;
  reg temp_zero;

  always @(*) begin
    case (alu_ctrl)
      4'b0000: temp_result = x + y;  // Addition
      4'b0001: temp_result = x - y;  // Subtraction
      4'b0010: temp_result = x * y;  // Multiplication
      4'b0011: temp_result = x / y;  // Division
      4'b0100: temp_result = x & y;  // AND
      4'b0101: temp_result = x | y;  // OR
      4'b0110: temp_result = x ^ y;  // XOR
      4'b0111: temp_result = x < y;  // Less than
      default: temp_result = 32'b0;  // Default to 0
    endcase

    temp_zero = (temp_result == 32'b0);
  end

  assign result = temp_result;
  assign zero = temp_zero;
endmodule

