                  apb_wdata,
                  apb_rdata,
                  apb_ready,
                  apb_addr,
  				  apb_tranerr
                 );

  input     [7:0]       addr;
  input                 data_valid;  
  input     [31:0]      data;
  input                 data_dir;
  output [31:0]      read_out_data;
  output            transaction_done;

  input                 apb_clk;
  input                 apb_reset;
  output                apb_write;
  output                apb_selx;
  output                apb_en;
  output   [31:0]       apb_wdata;
  input    [31:0]       apb_rdata;
  input                 apb_ready;
  output   [7:0]        apb_addr;
  output   				apb_tranerr;

  // State definitions
  localparam IDLE = 2'b00;
  localparam SETUP = 2'b01;
  localparam ACCESS = 2'b10;

  // Internal signals
  reg [1:0] state, next_state;
  reg [31:0] timeout_count;
  reg [31:0] read_out_data_reg;
  reg transaction_done_reg;
  reg apb_write_reg;
  reg apb_selx_reg;
  reg apb_en_reg;
  reg [31:0] apb_wdata_reg;
  reg [7:0] apb_addr_reg;
  reg apb_tranerr_reg;

  // State transition logic
  always @(posedge apb_clk or posedge apb_reset) begin
    if (apb_reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (data_valid) begin
          next_state = SETUP;
        end
      end
      SETUP: begin
        next_state = ACCESS;
      end
      ACCESS: begin
        if (apb_ready) begin
          next_state = IDLE;
        end else if (timeout_count >= 1000000) begin // Example timeout value
          next_state = IDLE;
          apb_tranerr_reg = 1;
        end
      end
    endcase
  end

  // Timeout counter logic
  always @(posedge apb_clk or posedge apb_reset) begin
    if (apb_reset) begin
      timeout_count <= 0;
    end else begin
      if (state == ACCESS && !apb_ready) begin
        timeout_count <= timeout_count + 1;
      end else begin
        timeout_count <= 0;
      end
    end
  end

  // Output logic
  always @(*) begin
    read_out_data_reg = 32'b0;
    transaction_done_reg = 1'b0;
    apb_write_reg = 1'b0;
    apb_selx_reg = 1'b0;
    apb_en_reg = 1'b0;
    apb_wdata_reg = 32'b0;
    apb_addr_reg = 8'b0;
    apb_tranerr_reg = 1'b0;

    case (state)
      IDLE: begin
        if (data_valid) begin
          apb_addr_reg = addr;
          apb_wdata_reg = data;
          apb_write_reg = data_dir;
          apb_selx_reg = 1;
          apb_en_reg = 1;
        end
      end
      SETUP: begin
        // No action needed in SETUP state
      end
      ACCESS: begin
        if (apb_ready) begin
          read_out_data_reg = apb_rdata;
          transaction_done_reg = 1;
        end
      end
    endcase
  end

  // Assign outputs
  assign read_out_data = read_out_data_reg;
  assign transaction_done = transaction_done_reg;
  assign apb_write = apb_write_reg;
  assign apb_selx = apb_selx_reg;
  assign apb_en = apb_en_reg;
  assign apb_wdata = apb_wdata_reg;
  assign apb_addr = apb_addr_reg;
  assign apb_tranerr = apb_tranerr_reg;

endmodule

module data_path(
    output [31:0] IR_OUT,
    output MOC,
    output Cond,
    input SE,
    input [1:0] size,
    input FR_ld,
    input RF_ld,
    input IR_ld,
    input MAR_ld,
    input MDR_ld,
    input R_W,
    input MOV,
    input MA_1, MA_0, MB_1, MB_0, MC_2, MC_1, MC_0, MD, ME,
    input [4:0] OP,
    input clk, clr
    );

    // Constants
    parameter PC = 32'h00000000;
    parameter LR = 32'h00000000;
    parameter ZERO = 32'h00000000;

    // Registers
    reg [31:0] IR;
    reg [31:0] MAR;
    reg [31:0] MDR;
    reg [31:0] FR;

    // Internal signals
    wire [31:0] ALU_out;
    wire [31:0] shifter_out;
    wire [31:0] mux_A_out;
    wire [31:0] mux_B_out;
    wire [31:0] sign_extender_out;
    wire [31:0] ram_out;

    // ALU
    assign ALU_out = (OP == 5'b00000) ? FR + shifter_out : // ADD
                     (OP == 5'b00001) ? FR - shifter_out : // SUB
                     (OP == 5'b00010) ? FR & shifter_out : // AND
                     (OP == 5'b00011) ? FR | shifter_out : // OR
                     (OP == 5'b00100) ? FR ^ shifter_out : // XOR
                     (OP == 5'b00101) ? FR << shifter_out : // SHL
                     (OP == 5'b00110) ? FR >> shifter_out : // SHR
                     (OP == 5'b00111) ? FR >>> shifter_out : // SAR
                     ZERO;

    // Shifter
    assign shifter_out = (SE) ? {sign_extender_out, 2'b00} : {shifter_out[30:0], 1'b0};

    // Sign Extender
    assign sign_extender_out = (size == 2'b00) ? {24'b0, FR[7:0]} : // 8-bit
                               (size == 2'b01) ? {16'b0, FR[15:0]} : // 16-bit
                               FR; // 32-bit

    // Multiplexers
    assign mux_A_out = (MA_1) ? ALU_out : (MA_0) ? shifter_out : FR;
    assign mux_B_out = (MB_1) ? ALU_out : (MB_0) ? shifter_out : FR;

    // RAM
    ram_256 ram (
        .clk(clk),
        .addr(MAR),
        .data_in(mux_B_out),
        .write(R_W),
        .data_out(ram_out)
    );

    // Register File
    reg_file RF (
        .clk(clk),
        .clr(clr),
        .ld(RF_ld),
        .A(mux_A_out),
        .B(mux_B_out),
        .C(mux_C_out),
        .D(mux_D_out),
        .E(mux_E_out),
        .F(FR)
    );

    // Control Logic
    always @(posedge clk or posedge clr) begin
        if (clr) begin
            IR <= ZERO;
            MAR <= ZERO;
            MDR <= ZERO;
            FR <= ZERO;
        end else begin
            if (IR_ld) begin
                IR <= ram_out;
            end
            if (MAR_ld) begin
                MAR <= mux_A_out;
            end
            if (MDR_ld) begin
                MDR <= mux_B_out;
            end
            if (FR_ld) begin
                FR <= mux_B_out;
            end
        end
    end

    // Outputs
    assign IR_OUT = IR;
    assign MOC = (OP == 5'b00000) ? 1'b1 : 1'b0; // Example condition
    assign Cond = (OP == 5'b00001) ? 1'b1 : 1'b0; // Example condition

endmodule

