module VGA_Sig_Gen(
    input CLK,
    input RESET,
    input RE,
    input [15:0] CONFIG_COLOURS,
    output DPR_CLK,
    output [14:0] VGA_ADDR,
    input VGA_DATA,
    output reg VGA_HS,
    output reg VGA_VS,
    output reg [7:0] VGA_COLOUR
);

    // Parameters for VGA timing
    parameter H_TOTAL = 800;  // Total horizontal pixels
    parameter H_DISPLAY = 640;  // Displayable horizontal pixels
    parameter H_SYNC_PORCH = 16;  // Horizontal sync porch
    parameter H_SYNC_WIDTH = 96;  // Horizontal sync width

    parameter V_TOTAL = 525;  // Total vertical pixels
    parameter V_DISPLAY = 480;  // Displayable vertical pixels
    parameter V_SYNC_PORCH = 10;  // Vertical sync porch
    parameter V_SYNC_WIDTH = 2;  // Vertical sync width

    // Internal registers and counters
    reg [9:0] h_counter;
    reg [8:0] v_counter;
    reg [7:0] color_reg;

    // State machine states
    typedef enum reg [1:0] {IDLE, H_SYNC, V_SYNC, ACTIVE} state_t;
    state_t state, next_state;

    // Assign DPR_CLK to CLK
    assign DPR_CLK = CLK;

    // State transition logic
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            state <= IDLE;
            h_counter <= 0;
            v_counter <= 0;
            VGA_HS <= 0;
            VGA_VS <= 0;
            VGA_COLOUR <= 0;
        end else begin
            state <= next_state;
            if (state == ACTIVE) begin
                VGA_ADDR <= h_counter[9:0] + v_counter[8:0] * H_DISPLAY;
                VGA_COLOUR <= color_reg;
            end else begin
                VGA_ADDR <= 0;
                VGA_COLOUR <= 0;
            end
            if (h_counter == H_TOTAL - 1) begin
                h_counter <= 0;
                if (v_counter == V_TOTAL - 1) begin
                    v_counter <= 0;
                end else begin
                    v_counter <= v_counter + 1;
                end
            end else begin
                h_counter <= h_counter + 1;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                VGA_HS <= 0;
                VGA_VS <= 0;
                if (RE) begin
                    next_state = H_SYNC;
                end
            end
            H_SYNC: begin
                VGA_HS <= 1;
                VGA_VS <= 0;
                if (h_counter == H_SYNC_PORCH + H_SYNC_WIDTH - 1) begin
                    next_state = V_SYNC;
                end
            end
            V_SYNC: begin
                VGA_HS <= 0;
                VGA_VS <= 1;
                if (v_counter == V_SYNC_PORCH + V_SYNC_WIDTH - 1) begin
                    next_state = ACTIVE;
                end
            end
            ACTIVE: begin
                VGA_HS <= 0;
                VGA_VS <= 0;
                if (h_counter == H_DISPLAY - 1) begin
                    next_state = H_SYNC;
                end
            end
        endcase
    end

    // Color selection logic
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            color_reg <= 0;
        end else begin
            if (state == ACTIVE) begin
                color_reg <= VGA_DATA;
            end
        end
    end

endmodule

module APB_master(
    input Transfer,              
    input Wr_Rd,                 
    input [4:0] Address,         
    input [31:0] write_data,     
    output reg [31:0] read_data, 
    input PCLK,                  
    input PRESETn,               
    input PREADY,                
    input [31:0] PRDATA,         
    input PSLVERR,               
    output reg [4:0] PADDR,      
    output reg PSELx,            
    output reg PENABLE,          
    output reg PWRITE,           
    output reg [31:0] PWDATA
);

    // State definitions
    localparam IDLE = 2'b00,
               SETUP = 2'b01,
               ACCESS = 2'b10;

    reg [1:0] state, next_state;

    // State transition logic
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (Transfer) begin
                    next_state = SETUP;
                end
            end
            SETUP: begin
                next_state = ACCESS;
            end
            ACCESS: begin
                if (PREADY) begin
                    next_state = IDLE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        PSELx = 0;
        PENABLE = 0;
        PWRITE = Wr_Rd;
        PWDATA = write_data;
        PADDR = Address;
        read_data = 32'b0;

        case (state)
            IDLE: begin
                PSELx = 0;
                PENABLE = 0;
            end
            SETUP: begin
                PSELx = 1;
                PENABLE = 0;
            end
            ACCESS: begin
                PSELx = 1;
                PENABLE = 1;
                if (Wr_Rd) begin
                    PWDATA = write_data;
                end
                if (PREADY) begin
                    if (Wr_Rd) begin
                        // No action needed for write
                    end else begin
                        read_data = PRDATA;
                    end
                end
            end
            default: begin
                PSELx = 0;
                PENABLE = 0;
            end
        endcase
    end

endmodule

module BBFASin(
    input  [63:0] in,
    output reg [63:0] out
);
    real in_real, out_real;

    // Convert the 64-bit floating-point input to a real number
    assign in_real = $bitstoreal(in);

    // Compute the arcsine of the real number
    assign out_real = $asin(in_real);

    // Convert the result back to a 64-bit floating-point format
    always @(*) begin
        out = $realtobits(out_real);
    end
endmodule

module mux_256x1 (in, sel, out);
  input [255:0] in;
  input [7:0] sel;
  output out;

  wire [127:0] upper_half;
  wire [127:0] lower_half;
  wire [63:0] upper_quarter;
  wire [63:0] lower_quarter;
  wire [31:0] upper_eighth;
  wire [31:0] lower_eighth;
  wire [15:0] upper_sixteenth;
  wire [15:0] lower_sixteenth;
  wire [7:0] upper_thirtysecond;
  wire [7:0] lower_thirtysecond;
  wire [3:0] upper_sixtyfourth;
  wire [3:0] lower_sixtyfourth;
  wire [1:0] upper_twelfth eighth;
  wire [1:0] lower_twelfth_eighth;
  wire [0:0] upper_twentyfifth_sixteenth;
  wire [0:0] lower_twentyfifth_sixteenth;

  // First level of multiplexing
  generate
    genvar i;
    for (i = 0; i < 128; i = i + 1) begin : upper_half_mux
      assign upper_half[i] = in[i];
    end
    for (i = 0; i < 128; i = i + 1) begin : lower_half_mux
      assign lower_half[i] = in[i + 128];
    end
  endgenerate

  // Second level of multiplexing
  generate
    genvar j;
    for (j = 0; j < 64; j = j + 1) begin : upper_quarter_mux
      assign upper_quarter[j] = upper_half[j];
    end
    for (j = 0; j < 64; j = j + 1) begin : lower_quarter_mux
      assign lower_quarter[j] = lower_half[j];
    end
  endgenerate

  // Third level of multiplexing
  generate
    genvar k;
    for (k = 0; k < 32; k = k + 1) begin : upper_eighth_mux
      assign upper_eighth[k] = upper_quarter[k];
    end
    for (k = 0; k < 32; k = k + 1) begin : lower_eighth_mux
      assign lower_eighth[k] = lower_quarter[k];
    end
  endgenerate

  // Fourth level of multiplexing
  generate
    genvar l;
    for (l = 0; l < 16; l = l + 1) begin : upper_sixteenth_mux
      assign upper_sixteenth[l] = upper_eighth[l];
    end
    for (l = 0; l < 16; l = l + 1) begin : lower_sixteenth_mux
      assign lower_sixteenth[l] = lower_eighth[l];
    end
  endgenerate

  // Fifth level of multiplexing
  generate
    genvar m;
    for (m = 0; m < 8; m = m + 1) begin : upper_thirtysecond_mux
      assign upper_thirtysecond[m] = upper_sixteenth[m];
    end
    for (m = 0; m < 8; m = m + 1) begin : lower_thirtysecond_mux
      assign lower_thirtysecond[m] = lower_sixteenth[m];
    end
  endgenerate

  // Sixth level of multiplexing
  generate
    genvar n;
    for (n = 0; n < 4; n = n + 1) begin : upper_sixtyfourth_mux
      assign upper_sixtyfourth[n] = upper_thirtysecond[n];
    end
    for (n = 0; n < 4; n = n + 1) begin : lower_sixtyfourth_mux
      assign lower_sixtyfourth[n] = lower_thirtysecond[n];
    end
  endgenerate

  // Seventh level of multiplexing
  generate
    genvar o;
    for (o = 0; o < 2; o = o + 1) begin : upper_twelfth_eighth_mux
      assign upper_twelfth_eighth[o] = upper_sixtyfourth[o];
    end
    for (o = 0; o < 2; o = o + 1) begin : lower_twelfth_eighth_mux
      assign lower_twelfth_eighth[o] = lower_sixtyfourth[o];
    end
  endgenerate

  // Eighth level of multiplexing
  generate
    genvar p;
    for (p = 0; p < 1; p = p + 1) begin : upper_twentyfifth_sixteenth_mux
      assign upper_twentyfifth_sixteenth[p] = upper_twelfth_eighth[p];
    end
    for (p = 0; p < 1; p = p + 1) begin : lower_twentyfifth_sixteenth_mux
      assign lower_twentyfifth_sixteenth[p] = lower_twelfth_eighth[p];
    end
  endgenerate

  // Final selection based on the 8th bit of the select signal
  assign out = sel[7] ? lower_twentyfifth_sixteenth[0] : upper_twentyfifth_sixteenth[0];
endmodule

module FIFO_arp_server_arpTableInsertFifo_V_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

parameter DATA_WIDTH = 81;
parameter ADDR_WIDTH = 3;
parameter FIFO_DEPTH = 5;

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output [DATA_WIDTH-1:0] q;

reg [DATA_WIDTH-1:0] SRL_SIG [0:FIFO_DEPTH-1];

always @(posedge clk) begin
    if (ce) begin
        // Shift all data one position down
        for (integer i = FIFO_DEPTH-1; i > 0; i = i - 1) begin
            SRL_SIG[i] <= SRL_SIG[i-1];
        end
        // Insert new data at the beginning
        SRL_SIG[0] <= data;
    end
end

// Directly access the data at the given address
assign q = SRL_SIG[a];

endmodule

