module FIFO_toe_ackDelayFifoReadCount_V_V (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

parameter DATA_WIDTH = 8;
parameter ADDR_WIDTH = 4;
parameter FIFO_DEPTH = 1 << ADDR_WIDTH;

input clk;
input reset;
output reg if_empty_n;
input if_read_ce;
input if_read;
output reg[DATA_WIDTH - 1:0] if_dout;
output reg if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;

reg [DATA_WIDTH - 1:0] mem [0:FIFO_DEPTH - 1];
reg [ADDR_WIDTH - 1:0] wr_ptr;
reg [ADDR_WIDTH - 1:0] rd_ptr;
reg full;
reg empty;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        full <= 0;
        empty <= 1;
    end else begin
        if (if_write_ce && if_write && !full) begin
            mem[wr_ptr] <= if_din;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == FIFO_DEPTH - 1) begin
                wr_ptr <= 0;
            end
            if (wr_ptr == rd_ptr) begin
                full <= 1;
            end
            empty <= 0;
        end else if (if_read_ce && if_read && !empty) begin
            if_dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == FIFO_DEPTH - 1) begin
                rd_ptr <= 0;
            end
            if (rd_ptr == wr_ptr) begin
                empty <= 1;
            end
            full <= 0;
        end
    end
end

assign if_empty_n = ~empty;
assign if_full_n = ~full;

endmodule

module FunctionUnit(
    input [BITS-1:0] A,
    input [BITS-1:0] B,
    input [4:0] FS, 
    input [4:0] SH, 
    output wire statC,
    output wire statN,
    output wire statV,
    output wire statZ,
    output wire [BITS-1:0] Out
);
    parameter BITS = 32;

    wire [BITS-1:0] alu_out;
    wire [BITS-1:0] shift_out;
    wire [4:0] shift_amount;
    wire [BITS-1:0] final_out;
    wire [BITS-1:0] alu_cin;
    wire [BITS-1:0] alu_cout;
    wire [BITS-1:0] alu_overflow;
    wire [BITS-1:0] alu_zero;

    // ALU
    assign alu_cin = (FS == 5'b00000) ? 1'b0 : 1'b1; // ALU operation select
    assign alu_out = (FS == 5'b00000) ? A + B : A - B; // Placeholder for ALU operations
    assign alu_cout = (FS == 5'b00000) ? (A + B) >= 32'hFFFFFFFF : (A - B) < 32'h00000000;
    assign alu_overflow = (FS == 5'b00000) ? (A[31] & B[31] & ~alu_out[31]) | (~A[31] & ~B[31] & alu_out[31]) : 1'b0;
    assign alu_zero = (FS == 5'b00000) ? (alu_out == 32'h00000000) : (alu_out == 32'hFFFFFFFF);

    // Barrel Shifter
    assign shift_amount = (FS == 5'b00000) ? SH : 5'b00000; // Placeholder for shift amount
    assign shift_out = (FS == 5'b00000) ? A << shift_amount : A >> shift_amount; // Placeholder for shift operations

    // Mux to select between ALU and Shift output
    assign final_out = (FS == 5'b00000) ? alu_out : shift_out;

    // Status flags
    assign statC = alu_cout;
    assign statN = final_out[BITS-1];
    assign statV = alu_overflow;
    assign statZ = final_out == 32'h00000000;

    // Output
    assign Out = final_out;
endmodule

module NOR4X0_RVT (A1,A2,A3,A4,Y);
output  Y;
input   A1,A2,A3,A4;

wire    Y_nor;

NOR #1 (A1, A2, A3, A4, Y_nor);

assign Y = Y_nor;

// Timing specifications
specify
  // Pin-to-pin delays for A1 to Y
  if (A1 == 0) begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $error("Timing violation: A1=0, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $info("Timing satisfied: A1=0, Y=0");
  end else begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $info("Timing satisfied: A1=1, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $error("Timing violation: A1=1, Y=0");
  end

  // Pin-to-pin delays for A2 to Y
  if (A2 == 0) begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $error("Timing violation: A2=0, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $info("Timing satisfied: A2=0, Y=0");
  end else begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $info("Timing satisfied: A2=1, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $error("Timing violation: A2=1, Y=0");
  end

  // Pin-to-pin delays for A3 to Y
  if (A3 == 0) begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $error("Timing violation: A3=0, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $info("Timing satisfied: A3=0, Y=0");
  end else begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $info("Timing satisfied: A3=1, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $error("Timing violation: A3=1, Y=0");
  end

  // Pin-to-pin delays for A4 to Y
  if (A4 == 0) begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $error("Timing violation: A4=0, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $info("Timing satisfied: A4=0, Y=0");
  end else begin
    @ (posedge Y_nor) #1 if (Y_nor == 1) $info("Timing satisfied: A4=1, Y=1");
    @ (posedge Y_nor) #1 if (Y_nor == 0) $error("Timing violation: A4=1, Y=0");
  end
endspecify

endmodule

