module onetwentyeighth(
    input [31:0] a_re,
    input [31:0] a_img,
    output [31:0] a1_re,
    output [31:0] a1_img
);

    // Extract the upper byte (bits 30 to 23) and the lower 24 bits (bits 22 to 0) of the real part
    wire [7:0] a_re_upper = a_re[30:23];
    wire [23:0] a_re_lower = a_re[22:0];

    // Extract the upper byte (bits 30 to 23) and the lower 24 bits (bits 22 to 0) of the imaginary part
    wire [7:0] a_img_upper = a_img[30:23];
    wire [23:0] a_img_lower = a_img[22:0];

    // Decrement the upper byte by 7
    wire [7:0] a1_re_upper = a_re_upper - 8'd7;
    wire [7:0] a1_img_upper = a_img_upper - 8'd7;

    // Combine the decremented upper byte with the original lower 24 bits
    assign a1_re = {a1_re_upper, a_re_lower};
    assign a1_img = {a1_img_upper, a_img_lower};

endmodule

module cyclonev_bias_logic (
    input  clk,
    input  shiftnld,
    input  captnupdt,
    output mainclk,
    output updateclk,
    output capture,
    output update
    );

reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @(posedge clk or posedge shiftnld) begin
    if (shiftnld) begin
        mainclk_tmp <= 0;
        updateclk_tmp <= 0;
        capture_tmp <= 0;
        update_tmp <= 0;
    end else begin
        case ({captnupdt, shiftnld})
            2'b00: begin
                mainclk_tmp <= 0;
                updateclk_tmp <= 0;
                capture_tmp <= 0;
                update_tmp <= 0;
            end
            2'b01: begin
                mainclk_tmp <= 1;
                updateclk_tmp <= 0;
                capture_tmp <= 0;
                update_tmp <= 0;
            end
            2'b10: begin
                mainclk_tmp <= 0;
                updateclk_tmp <= 1;
                capture_tmp <= 1;
                update_tmp <= 0;
            end
            2'b11: begin
                mainclk_tmp <= 0;
                updateclk_tmp <= 0;
                capture_tmp <= 0;
                update_tmp <= 1;
            end
        endcase
    end
end

assign mainclk = mainclk_tmp & 1'b1;
assign updateclk = updateclk_tmp & 1'b1;
assign capture = capture_tmp & 1'b1;
assign update = update_tmp & 1'b1;

endmodule

