input wire E,
input wire F,
input wire G,
input wire H,
input wire S0,
input wire S1,
input wire S2,
output wire Y
);

// Intermediate signals to hold the AND results
wire and_AB, and_AC, and_AD, and_AE, and_AF, and_AG, and_AH;
wire and_BC, and_BD, and_BE, and_BF, and_BG, and_BH;
wire and_CD, and_CE, and_CF, and_CG, and_CH;
wire and_DE, and_DF, and_DG, and_DH;
