assign and_AC = B & ~S0 & ~S1 & S2;
assign and_AD = C & ~S0 & S1 & ~S2;
assign and_AE = D & ~S0 & S1 & S2;
assign and_AF = E & S0 & ~S1 & ~S2;
assign and_AG = F & S0 & ~S1 & S2;
assign and_AH = G & S0 & S1 & ~S2;
assign and_AH = H & S0 & S1 & S2;

assign and_BC = B & ~S0 & ~S1 & ~S2;
assign and_BD = C & ~S0 & ~S1 & S2;
assign and_BE = D & ~S0 & S1 & ~S2;
assign and_BF = E & ~S0 & S1 & S2;
assign and_BG = F & S0 & ~S1 & ~S2;
assign and_BH = G & S0 & ~S1 & S2;
assign and_BH = H & S0 & ~S1 & S2;

assign and_CD = C & ~S0 & ~S1 & ~S2;
assign and_CE = D & ~S0 & ~S1 & S2;
assign and_CF = E & ~S0 & S1 & ~S2;
assign and_CG = F & ~S0 & S1 & S2;
assign and_CH = G & S0 & ~S1 & ~S2;
assign and_CH = H & S0 & ~S1 & S2;

