module CLA2 (
	input[1:0] a,b,
	input c_in,
	output g_out,p_out,
	output[1:0] s
	);

	// Instantiate ADD submodule for each bit
	ADD add0 (.a(a[0]), .b(b[0]), .c_in(c_in), .g(g0), .p(p0), .s(s[0]));
	ADD add1 (.a(a[1]), .b(b[1]), .c_in(g0), .g(g1), .p(p1), .s(s[1]));

	// Instantiate G_P submodule to compute final carry and propagate
	G_P gp (.g0(g0), .g1(g1), .p0(p0), .p1(p1), .g_out(g_out), .p_out(p_out));

