            5'b10001: data = shift_reg;
            5'b10010: data = shift_reg;
            5'b10011: data = shift_reg;
            5'b10100: data = shift_reg;
            5'b10101: data = shift_reg;
            5'b10110: data = shift_reg;
            5'b10111: data = shift_reg;
            5'b11000: data = shift_reg;
            5'b11001: data = shift_reg;
            5'b11010: data = shift_reg;
            5'b11011: data = shift_reg;
            5'b11100: data = shift_reg;
            5'b11101: data = shift_reg;
            5'b11110: data = shift_reg;
