  assign N[2] = A_doubled[1];
  assign N[3] = A_doubled[1];
  assign N[4] = A_doubled[2];
  assign N[5] = A_doubled[2];
  assign N[6] = A_doubled[3];
  assign N[7] = A_doubled[3];
  assign N[8] = A_doubled[4];
  assign N[9] = A_doubled[4];
  assign N[10] = A_doubled[5];
  assign N[11] = A_doubled[5];
  assign N[12] = A_doubled[6];
  assign N[13] = A_doubled[6];
  assign N[14] = A_doubled[7];
  assign N[15] = A_doubled[7];
  assign N[16] = B_doubled[0];
  assign N[17] = B_doubled[0];
  assign N[18] = B_doubled[1];
  assign N[19] = B_doubled[1];
  assign N[20] = B_doubled[2];
  assign N[21] = B_doubled[2];
  assign N[22] = B_doubled[3];
  assign N[23] = B_doubled[3];
  assign N[24] = B_doubled[4];
  assign N[25] = B_doubled[4];
  assign N[26] = B_doubled[5];
  assign N[27] = B_doubled[5];
  assign N[28] = B_doubled[6];
  assign N[29] = B_doubled[6];
  assign N[30] = B_doubled[7];
  assign N[31] = B_doubled[7];

  // Ripple carry adder
  assign sum[0] = N[0] ^ N[1];
  assign N[32] = N[0] & N[1];
  assign sum[1] = N[2] ^ N[3] ^ N[32];
  assign N[33] = (N[2] & N[3]) | (N[32] & (N[2] ^ N[3]));
  assign sum[2] = N[4] ^ N[5] ^ N[33];
  assign N[34] = (N[4] & N[5]) | (N[33] & (N[4] ^ N[5]));
  assign sum[3] = N[6] ^ N[7] ^ N[34];
  assign N[35] = (N[6] & N[7]) | (N[34] & (N[6] ^ N[7]));
  assign sum[4] = N[8] ^ N[9] ^ N[35];
  assign N[36] = (N[8] & N[9]) | (N[35] & (N[8] ^ N[9]));
  assign sum[5] = N[10] ^ N[11] ^ N[36];
  assign N[37] = (N[10] & N[11]) | (N[36] & (N[10] ^ N[11]));
  assign sum[6] = N[12] ^ N[13] ^ N[37];
  assign N[38] = (N[12] & N[13]) | (N[37] & (N[12] ^ N[13]));
  assign sum[7] = N[14] ^ N[15] ^ N[38];
  assign N[39] = (N[14] & N[15]) | (N[38] & (N[14] ^ N[15]));
  assign sum[8] = N[16] ^ N[17] ^ N[39];
  assign N[40] = (N[16] & N[17]) | (N[39] & (N[16] ^ N[17]));
  assign sum[9] = N[18] ^ N[19] ^ N[40];
  assign N[41] = (N[18] & N[19]) | (N[40] & (N[18] ^ N[19]));
  assign sum[10] = N[20] ^ N[21] ^ N[41];
  assign N[42] = (N[20] & N[21]) | (N[41] & (N[20] ^ N[21]));
  assign sum[11] = N[22] ^ N[23] ^ N[42];
  assign N[43] = (N[22] & N[23]) | (N[42] & (N[22] ^ N[23]));
  assign sum[12] = N[24] ^ N[25] ^ N[43];
  assign N[44] = (N[24] & N[25]) | (N[43] & (N[24] ^ N[25]));
  assign sum[13] = N[26] ^ N[27] ^ N[44];
  assign N[45] = (N[26] & N[27]) | (N[44] & (N[26] ^ N[27]));
  assign sum[14] = N[28] ^ N[29] ^ N[45];
  assign N[46] = (N[28] & N[29]) | (N[45] & (N[28] ^ N[29]));
  assign sum[15] = N[30] ^ N[31] ^ N[46];
  assign N[47] = (N[30] & N[31]) | (N[46] & (N[30] ^ N[31]));

  // Output the sum
  assign O = {sum[8], sum[7:0]};

endmodule

