module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);

reg [31:0] raw_data;
reg [15:0] pix_cnt, line_cnt, data_cnt;
reg [31:0] h_total, v_total;
reg [31:0] h_front, h_pulse, h_back, h_disp;
reg [31:0] v_front, v_pulse, v_back, v_disp;
reg [31:0] h_sync_start, h_sync_end;
reg [31:0] v_sync_start, v_sync_end;
reg [31:0] h_active_start, h_active_end;
reg [31:0] v_active_start, v_active_end;

integer file_handle;
integer file_size;
integer i;

always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		pix_cnt <= 0;
		line_cnt <= 0;
		data_cnt <= 0;
		hsync <= H_POL;
		vsync <= V_POL;
		data <= 0;
	end else begin
		if (line_cnt == v_total) begin
			line_cnt <= 0;
			pix_cnt <= 0;
		end else begin
			if (pix_cnt == h_total) begin
				pix_cnt <= 0;
				line_cnt <= line_cnt + 1;
			end else begin
				if (pix_cnt >= h_sync_start && pix_cnt < h_sync_end) begin
					hsync <= ~H_POL;
				end else begin
					hsync <= H_POL;
				end

				if (line_cnt >= v_sync_start && line_cnt < v_sync_end) begin
					vsync <= ~V_POL;
				end else begin
					vsync <= V_POL;
				end

				if (pix_cnt >= h_active_start && pix_cnt < h_active_end && line_cnt >= v_active_start && line_cnt < v_active_end) begin
					data_cnt <= data_cnt + 1;
					if (data_cnt == file_size) begin
						data_cnt <= 0;
					end
					data <= raw_data[data_cnt];
				end else begin
					data <= 0;
				end

				pix_cnt <= pix_cnt + 1;
			end
		end
	end
end

initial begin
	h_front = H_FRONT;
	h_pulse = H_PULSE;
	h_back = H_BACK;
	h_disp = H_DISP;
	v_front = V_FRONT;
	v_pulse = V_PULSE;
	v_back = V_BACK;
	v_disp = V_DISP;

	h_total = h_front + h_pulse + h_back + h_disp;
	v_total = v_front + v_pulse + v_back + v_disp;

	h_sync_start = h_front;
	h_sync_end = h_front + h_pulse;
	h_active_start = h_front + h_pulse + h_back;
	h_active_end = h_front + h_pulse + h_back + h_disp;

	file_handle = $fopen(FILE, "rb");
	if (file_handle == 0) begin
		$display("Error opening file %s", FILE);
		$finish;
	end

	file_size = $fsize(FILE);
	if (file_size % (BITS / 8) != 0) begin
		$display("File size is not a multiple of pixel size");
		$finish;
	end

	raw_data = 0;
	for (i = 0; i < file_size; i = i + (BITS / 8)) begin
		raw_data = {raw_data, $fread(raw_data, file_handle)};
	end

	$fclose(file_handle);
end

assign pclk = xclk;
assign href = (pix_cnt >= h_sync_start && pix_cnt < h_sync_end) ? ~H_POL : H_POL;

endmodule

