module RC_8_8_5_approx_fa_170_0(IN1, IN2, Out);
  input [7:0] IN1;
  input [7:0] IN2;
  output [8:0] Out;

  wire [4:0] approx_sum_4;
  wire [4:0] approx_carry_4;
  wire [2:0] exact_sum_2;
  wire [2:0] exact_carry_2;
  wire [3:0] final_sum;
  wire final_carry;

  // Approximate Full Adder for the first 5 bits
  approx_fa_170_0 approx_adder_1(IN1[4:0], IN2[4:0], approx_sum_4, approx_carry_4);

  // Exact Full Adder for the next 3 bits
  FullAdder exact_adder_1(IN1[3:0], IN2[3:0], approx_carry_4, exact_sum_2, exact_carry_2);

  // Combine the results from the approximate and exact adders
  assign final_sum = {approx_sum_4[3:0], exact_sum_2};
  assign final_carry = approx_carry_4[4] | exact_carry_2;

  // Final output
  assign Out = {final_carry, final_sum};

endmodule

module buffer32bit(out, inp);
