module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
    reg [inputWidth-1:0] maxValue;
    reg [(numInput-1):0] inDataBuffer;
    reg [31:0] counter;
    reg [31:0] maxIndex;

    always @(posedge i_clk) begin
        if (i_valid) begin
            // Reset counter and valid output when new data is available
            counter <= 0;
            o_data_valid <= 0;
            // Load the first input into the buffer and set the initial maximum
            inDataBuffer[0] <= i_data[(inputWidth-1):0];
            maxValue <= i_data[(inputWidth-1):0];
            maxIndex <= 0;
        end else if (counter < numInput) begin
            // Load the next input into the buffer
            inDataBuffer[counter] <= i_data[(counter*inputWidth+inputWidth-1):(counter*inputWidth)];
            // Compare the current input with the current maximum
            if (inDataBuffer[counter] > maxValue) begin
                maxValue <= inDataBuffer[counter];
                maxIndex <= counter;
            end
            counter <= counter + 1;
        end else begin
            // Output the index of the maximum value and set the valid output
            o_data <= maxIndex;
            o_data_valid <= 1;
        end
    end
endmodule

