module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);

reg [3:0] S, NS; // Current and next state registers
reg [7:0] in1, in2, in3, out; // Registers to store scan code data
reg [7:0] scan_code; // Register to hold the current scan code

// State definitions
parameter IDLE = 4'b0000;
parameter CAPT1 = 4'b0001;
parameter CAPT2 = 4'b0010;
parameter CAPT3 = 4'b0011;
parameter CAPT4 = 4'b0100;
parameter DISPLAY = 4'b0101;

// State transition logic
always @(posedge PS2_CLK) begin
	S <= NS;
end

// Next state logic
always @(*) begin
	case (S)
		IDLE: NS = CAPT1;
		CAPT1: NS = CAPT2;
		CAPT2: NS = CAPT3;
		CAPT3: NS = CAPT4;
		CAPT4: NS = DISPLAY;
		DISPLAY: NS = IDLE;
		default: NS = IDLE;
	endcase
end

// Scan code capture logic
always @(posedge PS2_CLK) begin
	if (S == CAPT1) in1 <= scan_code;
	else if (S == CAPT2) in2 <= scan_code;
	else if (S == CAPT3) in3 <= scan_code;
	else if (S == CAPT4) out <= scan_code;
end

// LEDR output logic
always @(*) begin
	LEDR = {S, NS};
end

// HEX0 and HEX1 output logic
always @(*) begin
	case (S)
		IDLE: HEX0 = 7'b0000000;
		CAPT1: HEX0 = in1;
		CAPT2: HEX0 = in2;
		CAPT3: HEX0 = in3;
		CAPT4: HEX0 = out;
		DISPLAY: HEX0 = in3;
		default: HEX0 = 7'b0000000;
	endcase
	HEX1 = S;
end

// Keyboard decoder module instantiation
keyboard_decoder keyboard (
	.clk(PS2_CLK),
	.data(PS2_DAT),
	.scan_code(scan_code)
);

// Seven-segment display driver module instantiation
