    input stall, 
    input ena,                
    output reg [width - 1:0] q,   
    output reg aclrout
);

    reg [width - 1:0] reg_d;
    reg reg_ena;

    // Asynchronous clear
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            reg_d <= 0;
            aclrout <= 1;
        end else begin
            aclrout <= 0;
        end
    end

    // Device-level power-on reset
    always @(posedge clk or posedge devpor) begin
        if (!devpor) begin
            reg_d <= 0;
        end
    end

    // Data loading control
    always @(posedge clk) begin
        if (!stall && ena) begin
            reg_d <= d;
        end
    end

    // Output buffering and timing
