module addmulor_0_stage_signed_11_bit(
	input signed [10:0] a,
	input signed [10:0] b,
	input signed [10:0] c,
	input signed [10:0] d,
	output [10:0] out
	);
	// Perform addition of a and d
	signed [21:0] add_result = a + d;

	// Perform multiplication of the addition result by b
	signed [32:0] mul_result = add_result * b;

	// Perform bitwise OR operation with c
	signed [10:0] or_result = mul_result[10:0] | c;

	// Assign the final result to the output
	assign out = or_result;
endmodule

