module gtx_tx_reset_controller(
    input wire clk,
    input wire ref_clk,
    input wire powerup_channel,
    output reg tx_running,
    output reg txreset,
    output reg txuserrdy,
    output reg txpmareset,
    output reg txpcsreset,
    output reg pllpd,
    output reg pllreset,
    output reg plllocken,
    input wire plllock,
    output reg resetsel,
    input wire txresetdone
);

    // State definitions
    typedef enum reg [2:0] {
        IDLE,
        PLL_RESET,
        PLL_LOCK_WAIT,
        TX_RESET,
        TX_RESET_WAIT,
        TX_PMA_RESET,
        TX_PMA_RESET_WAIT,
        TX_PCS_RESET,
        TX_PCS_RESET_WAIT
    } state_t;

    state_t state, next_state;
    reg [2:0] ref_clk_counter;
    reg [2:0] tx_reset_counter;
    reg [2:0] tx_pma_reset_counter;
    reg [2:0] tx_pcs_reset_counter;

    // Meta-registered signals for clock domain crossing
    reg [2:0] ref_clk_counter_reg;
    reg [2:0] tx_reset_counter_reg;
    reg [2:0] tx_pma_reset_counter_reg;
    reg [2:0] tx_pcs_reset_counter_reg;

    // State transition logic
    always @(posedge clk) begin
        state <= next_state;
    end

    // Counter logic for reference clock detection
    always @(posedge ref_clk) begin
        if (powerup_channel == 0) begin
            ref_clk_counter <= 0;
        end else begin
            ref_clk_counter <= ref_clk_counter + 1;
        end
    end

    // Meta-registered counters for clock domain crossing
    always @(posedge clk) begin
        ref_clk_counter_reg <= ref_clk_counter;
    end

    // State machine logic
    always @(*) begin
        next_state = state;
        tx_running = 0;
        txreset = 1;
        txuserrdy = 0;
        txpmareset = 1;
        txpcsreset = 1;
        pllpd = 1;
        pllreset = 1;
        plllocken = 0;
        resetsel = 0;

        case (state)
            IDLE:
                if (powerup_channel == 0) begin
                    next_state = PLL_RESET;
                end
            PLL_RESET:
                begin
                    pllreset = 0;
                    plllocken = 1;
                    next_state = PLL_LOCK_WAIT;
                end
            PLL_LOCK_WAIT:
                if (plllock) begin
                    next_state = TX_RESET;
                end
            TX_RESET:
                begin
                    txreset = 0;
                    next_state = TX_RESET_WAIT;
                end
            TX_RESET_WAIT:
                if (txresetdone) begin
                    next_state = TX_PMA_RESET;
                end
            TX_PMA_RESET:
                begin
                    txpmareset = 0;
                    next_state = TX_PMA_RESET_WAIT;
                end
            TX_PMA_RESET_WAIT:
                if (txresetdone) begin
                    next_state = TX_PCS_RESET;
                end
            TX_PCS_RESET:
                begin
                    txpcsreset = 0;
                    next_state = TX_PCS_RESET_WAIT;
                end
            TX_PCS_RESET_WAIT:
                if (txresetdone) begin
                    tx_running = 1;
                    next_state = IDLE;
                end
        endcase
    end

endmodule

