module ControlFSM (clk, reset, irq, read, write, iack, ir, alu_flags,
    addr_sel, load_sel, count_sel, count_up, top_enable, alu_enable, alu_op);
    input clk, reset;
    input irq;              
    input [7:0] ir;         
    input [2:0] alu_flags;     
    output reg read, write, iack;                   
    output reg [1:0] addr_sel, load_sel, count_sel; 
    output reg count_up, top_enable, alu_enable;    
    output reg [5:0] alu_op;
    reg [3:0] ustate;
    reg [21:0] ucode [0:255]; // Assuming 256 microinstructions, each 22 bits

    // Load microcode from external file during initialization
    initial begin
        $readmemh("microcode.hex", ucode);
    end

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ustate <= 4'b0000;
        end else begin
            ustate <= nx_ustate;
        end
    end

    // Next state determination
    reg [3:0] nx_ustate;
    always @(*) begin
        case (ustate)
            4'b0000: begin
                // Example transition logic
                if (irq) begin
                    nx_ustate = 4'b0001;
                end else begin
                    nx_ustate = 4'b0010;
                end
            end
            4'b0001: begin
                // Example transition logic
                nx_ustate = 4'b0010;
            end
            4'b0010: begin
                // Example transition logic
                nx_ustate = 4'b0000;
            end
            default: nx_ustate = 4'b0000;
        endcase
    end

    // Output control logic
    always @(*) begin
        case (ustate)
            4'b0000: begin
                read = 1'b0;
                write = 1'b0;
                iack = 1'b0;
                addr_sel = 2'b00;
                load_sel = 2'b00;
                count_sel = 2'b00;
                count_up = 1'b0;
                top_enable = 1'b0;
                alu_enable = 1'b0;
                alu_op = 6'b000000;
            end
            4'b0001: begin
                read = 1'b1;
                write = 1'b0;
                iack = 1'b1;
                addr_sel = 2'b01;
                load_sel = 2'b01;
                count_sel = 2'b01;
                count_up = 1'b1;
                top_enable = 1'b1;
                alu_enable = 1'b0;
                alu_op = 6'b000001;
            end
            4'b0010: begin
                read = 1'b0;
                write = 1'b1;
                iack = 1'b0;
                addr_sel = 2'b10;
                load_sel = 2'b10;
                count_sel = 2'b10;
                count_up = 1'b0;
                top_enable = 1'b0;
                alu_enable = 1'b1;
                alu_op = 6'b000010;
            end
            default: begin
                read = 1'b0;
                write = 1'b0;
                iack = 1'b0;
                addr_sel = 2'b00;
                load_sel = 2'b00;
                count_sel = 2'b00;
                count_up = 1'b0;
                top_enable = 1'b0;
                alu_enable = 1'b0;
                alu_op = 6'b000000;
            end
        endcase
    end
endmodule

