module addr_decode #(
  parameter int unsigned NoIndices = 32'd0,
  parameter int unsigned NoRules   = 32'd0,
  parameter type         addr_t    = logic,
  parameter type         rule_t    = logic,
  parameter int unsigned IdxWidth  = cf_math_pkg::idx_width(NoIndices),
  parameter type         idx_t     = logic [IdxWidth-1:0]
) (
  input  addr_t               addr_i,
  input  rule_t [NoRules-1:0] addr_map_i,
  output idx_t                idx_o,
  output logic                dec_valid_o,
  output logic                dec_error_o,
  input  logic                en_default_idx_i,
  input  idx_t                default_idx_i
);

  // Internal signals
  logic [NoRules-1:0] matched_rules;
  logic [IdxWidth-1:0] decoded_idx;
  logic valid_match;

  // Assertions for formal verification
  initial begin
    assert (NoIndices > 0) else $error("NoIndices must be greater than 0");
    assert (NoRules > 0) else $error("NoRules must be greater than 0");
    assert (NoIndices <= 2**IdxWidth) else $error("NoIndices must fit within the index width");
  end

  // Combinational logic to decode the address
  always_comb begin
    matched_rules = {NoRules{1'b0}};
    decoded_idx = default_idx_i;
    valid_match = 1'b0;

    for (int i = 0; i < NoRules; i++) begin
      if (addr_i >= addr_map_i[i].start && addr_i <= addr_map_i[i].end) begin
        matched_rules[i] = 1'b1;
        decoded_idx = addr_map_i[i].index;
        valid_match = 1'b1;
      end
    end

    // Check for overlapping address ranges
    for (int i = 0; i < NoRules; i++) begin
      for (int j = i + 1; j < NoRules; j++) begin
        assert (!(addr_map_i[i].start <= addr_map_i[j].end && addr_map_i[j].start <= addr_map_i[i].end)) else $error("Overlapping address ranges detected");
      end
    end

    // Check if indices are within valid bounds
    for (int i = 0; i < NoRules; i++) begin
      assert (addr_map_i[i].index < NoIndices) else $error("Index out of bounds");
    end

    // Output signals
    idx_o = valid_match ? decoded_idx : (en_default_idx_i ? default_idx_i : idx_o);
    dec_valid_o = valid_match;
    dec_error_o = !valid_match && !en_default_idx_i;
  end

endmodule

