module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
input startGameEn; 
input [7:0]user_x; 
input [6:0]user_y; 
input [7:0]enemy_x; 
input [6:0]enemy_y; 
input [160*120-1:0] enem_grid; 
output reg [7:0] x; 
output reg [6:0] y; 
output reg[2:0] colour;

reg clear;

always @(posedge clk) begin
    if (startGameEn) begin
        x <= 8'd0;
        y <= 7'd0;
        clear <= 1'b1;
    end else if (clear) begin
        clear <= 1'b0;
    end else if (x < 8'd160) begin
        if (y < 7'd120) begin
            if (x == user_x && y == user_y) begin
                colour <= 3'd1; // User color
            } else if (x == enemy_x && y == enemy_y) begin
                colour <= 3'd2; // Enemy color
            } else if (enem_grid[(y * 160) + x] == 1'b1) begin
                colour <= 3'd3; // Grid color
            end else begin
                colour <= 3'd0; // Background color
            end
            y <= y + 1;
        end else begin
            y <= 7'd0;
            x <= x + 1;
        end
    end
end

endmodule

module Start_UP_Handler(
    input wire i_CLK,
    output wire o_RST
);
    // Parameters for clock frequency and initial reset time
    parameter g_Clock_Frequency = 50000000; // 50 MHz
    parameter g_Initial_Reset_Time = 100000; // 100,000 cycles

    // Calculate the number of clock cycles for the initial reset
    parameter c_Initial_Reset_Clocks = g_Initial_Reset_Time;

    // Registers to manage the reset state and counter
    reg r_RST;
    reg [31:0] r_RST_Counter;

    // Always block to handle the clock edge and update the reset state
    always @(posedge i_CLK) begin
        if (r_RST_Counter < c_Initial_Reset_Clocks) begin
            r_RST_Counter <= r_RST_Counter + 1;
        end else begin
            r_RST <= 0; // De-assert reset after the counter reaches the threshold
        end
    end

    // Output the reset state
    assign o_RST = r_RST;
endmodule

