    reg [7:0] timeCount;
    reg [7:0] timeoutCounter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STANDBY;
            timeCount <= 0;
            timeoutCounter <= 0;
            inches <= 0;
            sonar_trigger <= 0;
            READY <= 0;
        end else begin
            state <= next_state;
            if (state == COUNT_PULSE) begin
                timeCount <= timeCount + 1;
            end
            if (timeoutCounter < 255) begin
                timeoutCounter <= timeoutCounter + 1;
            end
        end
    end

    always @(*) begin
        next_state = state;
        sonar_trigger = 0;
        READY = 0;
        case (state)
            STANDBY: begin
                if (do_measure) begin
                    next_state = START_MEASURE;
                end
            end
            START_MEASURE: begin
                sonar_trigger = 1;
                if (sonar_pulse) begin
                    next_state = WAIT_FOR_PULSE;
                end
            end
            WAIT_FOR_PULSE: begin
                if (!sonar_pulse) begin
                    next_state = COUNT_PULSE;
                end
            end
            COUNT_PULSE: begin
                if (!sonar_pulse) begin
                    inches <= timeCount * 0.0138; // Assuming 1 inch = 73.744 microseconds
                    next_state = STANDBY;
                end
                if (timeoutCounter == 255) begin
                    next_state = STANDBY;
                end
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            READY <= 0;
        end else begin
            if (state == STANDBY) begin
                READY <= 1;
            end
        end
    end
endmodule

