module voting (a0, a1, a2, a3, a4, out);

input    [2:0]   a0, a1, a2, a3, a4;
output reg [2:0]   out;

reg [2:0] sum0, sum1, sum2;
reg [2:0] max_sum;
reg [1:0] error_count;

// Full adders to calculate the sum of votes for each bit position
assign {error_count[1], sum0} = a0 + a1 + a2 + a3 + a4;
assign {error_count[0], sum1} = {a0[1], a1[1], a2[1], a3[1], a4[1]};
assign {error_count[0], sum2} = {a0[2], a1[2], a2[2], a3[2], a4[2]};

// Determine the maximum sum and detect errors
always @(*) begin
    max_sum = sum0;
    out = 3'b000;
    if (sum1 > max_sum) begin
        max_sum = sum1;
        out = 3'b001;
    end
    if (sum2 > max_sum) begin
        max_sum = sum2;
        out = 3'b010;
    end
    if (error_count != 3'b000) begin
        out = 3'b111; // Error detected
    end
end

endmodule

module soc_system_mm_interconnect_4_cmd_mux_002
(
    input                       sink0_valid,
    input [129-1   : 0]  sink0_data,
    input [11-1: 0]  sink0_channel,
    input                       sink0_startofpacket,
    input                       sink0_endofpacket,
    output                      sink0_ready,

    input                       sink1_valid,
    input [129-1   : 0]  sink1_data,
    input [11-1: 0]  sink1_channel,
    input                       sink1_startofpacket,
    input                       sink1_endofpacket,
    output                      sink1_ready,

    output                      src_valid,
    output [129-1    : 0] src_data,
    output [11-1 : 0] src_channel,
    output                      src_startofpacket,
    output                      src_endofpacket,
    input                       src_ready,

    input clk,
    input reset
);

    // Internal signals
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] grant;
    reg [1:0] next_grant;
    reg [129-1:0] payload;
    reg [11-1:0] channel;
    reg startofpacket;
    reg endofpacket;
    reg [1:0] packet_count;
    reg [1:0] next_packet_count;

    // State definitions
    parameter IDLE = 2'b00;
    parameter SEND_DATA = 2'b01;
    parameter SEND_EOP = 2'b10;

    // Next state logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next grant logic
    always @(*) begin
        if (sink0_valid && sink0_ready) begin
            next_grant = 2'b00;
        end else if (sink1_valid && sink1_ready) begin
            next_grant = 2'b01;
        end else begin
            next_grant = grant;
        end
    end

    // Next packet count logic
    always @(*) begin
        if (startofpacket) begin
            next_packet_count = 2'b00;
        end else if (endofpacket) begin
            next_packet_count = packet_count + 1;
        end else begin
            next_packet_count = packet_count;
        end
    end

    // State transition logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (sink0_valid && sink0_ready) begin
                    next_state = SEND_DATA;
                end else if (sink1_valid && sink1_ready) begin
                    next_state = SEND_DATA;
                end else begin
                    next_state = IDLE;
                end
            end
            SEND_DATA: begin
                if (src_ready) begin
                    next_state = SEND_DATA;
                end else begin
                    next_state = SEND_EOP;
                end
            end
            SEND_EOP: begin
                if (src_ready) begin
                    next_state = IDLE;
                end else begin
                    next_state = SEND_EOP;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Payload and control signal assignment
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            payload <= 129'b0;
            channel <= 12'b0;
            startofpacket <= 1'b0;
            endofpacket <= 1'b0;
        end else begin
            if (state == SEND_DATA) begin
                payload <= (grant == 2'b00) ? sink0_data : sink1_data;
                channel <= (grant == 2'b00) ? sink0_channel : sink1_channel;
                startofpacket <= (grant == 2'b00) ? sink0_startofpacket : sink1_startofpacket;
                endofpacket <= (grant == 2'b00) ? sink0_endofpacket : sink1_endofpacket;
            end
        end
    end

    // Ready signal assignment
    assign sink0_ready = (state == IDLE || state == SEND_EOP);
    assign sink1_ready = (state == IDLE || state == SEND_EOP);

    // Output signal assignment
    assign src_valid = (state == SEND_DATA || state == SEND_EOP);
    assign src_data = payload;
    assign src_channel = channel;
    assign src_startofpacket = startofpacket;
    assign src_endofpacket = endofpacket;

endmodule

module file_writer(input_a, input_a_stb, clk, rst, input_a_ack);

  input     clk;
  input     rst;
  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;

  reg       [63:0] value;
  reg       [1:0]  state;
  reg       [1:0]  next_state;
  reg       s_input_a_ack;
  integer   file_handle;

  parameter IDLE = 2'b00;
  parameter CAPTURE = 2'b01;
  parameter WRITE = 2'b10;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      value <= 64'b0;
      s_input_a_ack <= 1'b0;
      file_handle = $fopen("resp_z", "a");
    end else begin
      state <= next_state;
      if (s_input_a_ack) begin
        value <= input_a;
        s_input_a_ack <= 1'b0;
      end
    end
  end

  always @(*) begin
    next_state = state;
    s_input_a_ack = 1'b0;
    case (state)
      IDLE: begin
        if (input_a_stb) begin
          next_state = CAPTURE;
          s_input_a_ack = 1'b1;
        end
      end
      CAPTURE: begin
        next_state = WRITE;
      end
      WRITE: begin
        $fdisplay(file_handle, "%h", value[63:32]);
        $fdisplay(file_handle, "%h", value[31:0]);
        $fclose(file_handle);
        next_state = IDLE;
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  assign input_a_ack = s_input_a_ack;

endmodule

module DT_16_16_28_approx_fa_21_174(IN1, IN2, Out);
