module CIRCUIT2(a, b, c, x, z, Clk, Rst);
    input [31:0] a, b, c;
    input Clk, Rst;
    output [31:0] x, z;

    reg [31:0] x_reg, z_reg;
    reg [31:0] add_ab, add_ac, sub_ab;
    reg [1:0] cmp_result;

    // Arithmetic operations
    assign add_ab = a + b;
    assign add_ac = a + c;
    assign sub_ab = a - b;

    // Comparator to compare add_ab and add_ac
    assign cmp_result = (add_ab > add_ac) ? 2'b00 : (add_ab < add_ac) ? 2'b11 : 2'b10;

    // Multiplexers to select the result based on comparison
    reg [31:0] sel_result;
    always @(*) begin
        case (cmp_result)
            2'b00: sel_result = add_ab;
            2'b11: sel_result = add_ac;
            2'b10: sel_result = sub_ab;
            default: sel_result = 32'b0;
        endcase
    end

    // Shifters to shift the selected result
    reg [31:0] shifted_result;
    always @(*) begin
        if (cmp_result == 2'b00) begin
            shifted_result = {sel_result[30:0], 1'b0}; // Left shift by 1
        end else if (cmp_result == 2'b11) begin
            shifted_result = {1'b0, sel_result[31:1]}; // Right shift by 1
        end else begin
            shifted_result = sel_result; // No shift
        end
    end

    // Registers to store the final outputs
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            x_reg <= 32'b0;
            z_reg <= 32'b0;
        end else begin
            x_reg <= shifted_result;
            z_reg <= shifted_result;
        end
    end

    // Outputs
    assign x = x_reg;
    assign z = z_reg;
endmodule

