module pre_norm_fmul(clk, fpu_op, opa, opb, fracta, fractb, exp_out, sign,
		sign_exe, inf, exp_ovf, underflow);
input		clk;
input	[2:0]	fpu_op;
input	[31:0]	opa, opb;
output	[23:0]	fracta, fractb;
output	[7:0]	exp_out;
output		sign, sign_exe;
output		inf;
output	[1:0]	exp_ovf;
output	[2:0]	underflow;

reg	[23:0]	fracta_reg, fractb_reg;
reg	[7:0]	exp_out_reg;
reg		sign_reg, sign_exe_reg;
reg		inf_reg;
reg	[1:0]	exp_ovf_reg;
reg	[2:0]	underflow_reg;

wire	[30:0] fracta_wire, fractb_wire;
wire	[7:0] exp_out_wire;
wire		sign_wire, sign_exe_wire;
wire		inf_wire;
wire	[1:0] exp_ovf_wire;
wire	[2:0] underflow_wire;

// Combinational logic for immediate calculations
assign {sign_wire, exp_out_wire, fracta_wire, fractb_wire, inf_wire, exp_ovf_wire, underflow_wire} = 
    (fpu_op == 3'b000) ? mul_logic(opa, opb) : div_logic(opa, opb);

// Sequential logic with registers to store intermediate results
always @(posedge clk) begin
    fracta_reg <= fracta_wire;
    fractb_reg <= fractb_wire;
    exp_out_reg <= exp_out_wire;
    sign_reg <= sign_wire;
    sign_exe_reg <= sign_exe_wire;
    inf_reg <= inf_wire;
    exp_ovf_reg <= exp_ovf_wire;
    underflow_reg <= underflow_wire;
end

// Output assignments
assign fracta = fracta_reg;
assign fractb = fractb_reg;
assign exp_out = exp_out_reg;
assign sign = sign_reg;
assign sign_exe = sign_exe_reg;
assign inf = inf_reg;
assign exp_ovf = exp_ovf_reg;
assign underflow = underflow_reg;

// Function to handle multiplication logic
function {sign_wire, exp_out_wire, fracta_wire, fractb_wire, inf_wire, exp_ovf_wire, underflow_wire} mul_logic;
    input [31:0] opa, opb;
    reg [30:0] fracta_mul, fractb_mul;
    reg [7:0] exp_out_mul;
    reg sign_mul, sign_exe_mul;
    reg inf_mul;
    reg [1:0] exp_ovf_mul;
    reg [2:0] underflow_mul;

    // Extract sign, exponent, and fraction
    sign_mul = opa[31] ^ opb[31];
    exp_out_mul = opa[30:23] + opb[30:23] - 8'd127;
    fracta_mul = {1'b0, opa[22:0]};
    fractb_mul = {1'b0, opb[22:0]};

    // Perform multiplication
    {fracta_mul, fractb_mul} = fracta_mul * fractb_mul;

    // Normalize the result
    while (fracta_mul[31] == 0) begin
        fracta_mul = {fracta_mul[30:0], 1'b0};
        exp_out_mul = exp_out_mul - 1;
    end
    while (fracta_mul[31] == 1 && fracta_mul[30] == 0) begin
        fracta_mul = {1'b0, fracta_mul[31:1]};
        exp_out_mul = exp_out_mul + 1;
    end

    // Handle overflow and underflow
    if (exp_out_mul > 127) begin
        exp_ovf_mul = 2'b11;
        inf_mul = 1'b1;
        exp_out_mul = 8'd127;
        fracta_mul = 31'b0;
    end else if (exp_out_mul < -126) begin
        underflow_mul = 3'b111;
        exp_out_mul = 8'd0;
        fracta_mul = 31'b0;
    end else begin
        exp_ovf_mul = 2'b00;
        inf_mul = 1'b0;
        underflow_mul = 3'b000;
    end

    // Assign outputs
    sign_wire = sign_mul;
    exp_out_wire = exp_out_mul;
    fracta_wire = fracta_mul[30:7];
    fractb_wire = fractb_mul[30:7];
    inf_wire = inf_mul;
    exp_ovf_wire = exp_ovf_mul;
    underflow_wire = underflow_mul;
endfunction

// Function to handle division logic
function {sign_wire, exp_out_wire, fracta_wire, fractb_wire, inf_wire, exp_ovf_wire, underflow_wire} div_logic;
    input [31:0] opa, opb;
    reg [30:0] fracta_div, fractb_div;
    reg [7:0] exp_out_div;
    reg sign_div, sign_exe_div;
    reg inf_div;
    reg [1:0] exp_ovf_div;
    reg [2:0] underflow_div;

    // Extract sign, exponent, and fraction
    sign_div = opa[31] ^ opb[31];
    exp_out_div = opa[30:23] - opb[30:23] + 8'd127;
    fracta_div = {1'b0, opa[22:0]};
    fractb_div = {1'b0, opb[22:0]};

    // Perform division
    if (fractb_div == 0) begin
        inf_div = 1'b1;
        exp_out_div = 8'd127;
        fracta_div = 31'b0;
    end else begin
        {fracta_div, fractb_div} = fracta_div / fractb_div;

        // Normalize the result
        while (fracta_div[31] == 0) begin
            fracta_div = {fracta_div[30:0], 1'b0};
            exp_out_div = exp_out_div - 1;
        end
        while (fracta_div[31] == 1 && fracta_div[30] == 0) begin
            fracta_div = {1'b0, fracta_div[31:1]};
            exp_out_div = exp_out_div + 1;
        end

        // Handle overflow and underflow
        if (exp_out_div > 127) begin
            exp_ovf_div = 2'b11;
            inf_div = 1'b1;
            exp_out_div = 8'd127;
            fracta_div = 31'b0;
        end else if (exp_out_div < -126) begin
            underflow_div = 3'b111;
            exp_out_div = 8'd0;
            fracta_div = 31'b0;
        end else begin
            exp_ovf_div = 2'b00;
            inf_div = 1'b0;
            underflow_div = 3'b000;
        end
    end

    // Assign outputs
    sign_wire = sign_div;
    exp_out_wire = exp_out_div;
    fracta_wire = fracta_div[30:7];
    fractb_wire = fractb_div[30:7];
    inf_wire = inf_div;
    exp_ovf_wire = exp_ovf_div;
    underflow_wire = underflow_div;
endfunction
