module FPAddSub_reduced(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    input operation,
    output reg [31:0] result,
    output reg [4:0] flags
);

    reg [31:0] pipe_1, pipe_2, pipe_3;
    reg [31:0] sign_a, sign_b, sign_result;
    reg [8:0] exp_a, exp_b, exp_result;
    reg [23:0] mant_a, mant_b, mant_result;
    reg [23:0] mant_add_result;
    reg [23:0] mant_normalized;
    reg [4:0] flags_reg;

    // Stage 1: Sign and Exponent Processing
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sign_a <= 0;
            sign_b <= 0;
            exp_a <= 0;
            exp_b <= 0;
        end else begin
            sign_a <= a[31];
            sign_b <= b[31];
            exp_a <= a[30:23];
            exp_b <= b[30:23];
        end
    end

    // Stage 2: Mantissa Addition
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mant_a <= 0;
            mant_b <= 0;
            mant_add_result <= 0;
        end else begin
            mant_a <= a[22:0];
            mant_b <= b[22:0];
            if (exp_a == exp_b) begin
                mant_add_result <= mant_a + mant_b;
            end else if (exp_a > exp_b) begin
                mant_add_result <= mant_a + (mant_b << (exp_a - exp_b));
            end else begin
                mant_add_result <= (mant_a << (exp_b - exp_a)) + mant_b;
            end
        end
    end

    // Stage 3: Normalization
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mant_normalized <= 0;
        end else begin
            mant_normalized <= mant_add_result;
            while (mant_normalized[23] == 0) begin
                mant_normalized <= mant_normalized << 1;
            end
        end
    end

    // Stage 4: Result Packaging
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 0;
            flags_reg <= 0;
        end else begin
            result <= {sign_result, exp_result, mant_normalized};
            flags_reg <= 0; // Placeholder for flags logic
        end
    end

endmodule

