module FPAddSub_d(
    input ZeroSum,
    input [8:0] NormE,
    input [22:0] NormM,
    input R,
    input S,
    input G,
    input Sa,
    input Sb,
    input Ctrl,
    input MaxAB,
    input NegE,
    input [4:0] InputExc,
    output reg [31:0] P,
    output reg [4:0] Flags
);

    reg [8:0] ExpA, ExpB, ExpR;
    reg [22:0] MantA, MantB, MantR;
    reg [22:0] MantR_adjusted;
    reg SignR;
    reg [4:0] Flags_reg;

    // Extract exponent and mantissa from inputs
    assign ExpA = NormE;
    assign MantA = NormM;
    assign ExpB = NormE;
    assign MantB = NormM;

    // Determine the result sign
    assign SignR = Sa ^ Sb;

    // Perform the addition or subtraction
    always @(*) begin
        if (Ctrl) begin
            // Subtraction
            MantR = MantA - MantB;
        end else begin
            // Addition
            MantR = MantA + MantB;
        end
    end

    // Adjust the exponent and mantissa for rounding
    always @(*) begin
        if (MantR[22]) begin
            // Mantissa is negative, adjust accordingly
            MantR_adjusted = MantR - 1;
            ExpR = ExpA;
        end else begin
            // Mantissa is positive, adjust accordingly
            MantR_adjusted = MantR + 1;
            ExpR = ExpB;
        end
    end

    // Check for overflow and underflow
    always @(*) begin
        if (ExpR > 255) begin
            Flags_reg[0] = 1; // Overflow
        end else if (ExpR < 0) begin
            Flags_reg[1] = 1; // Underflow
        end
    end

    // Set flags based on input exceptions
    always @(*) begin
        Flags_reg[2] = InputExc[0]; // Divide by zero
        Flags_reg[3] = InputExc[1]; // Invalid operation
        Flags_reg[4] = InputExc[2]; // Inexact result
    end

    // Construct the final result
    always @(*) begin
        P = {SignR, ExpR, MantR_adjusted[21:0]};
    end

    // Assign flags to output
    assign Flags = Flags_reg;

endmodule

