    reg rco0, rco1, rco2;
    wire c_out0, c_out1, c_out2;

    // BCD counter for the least significant digit
    bcd_counter bcd0 (
        .clk(clk),
        .enable(enable & ~rco0),
        .grst(grst),
        .count(digit0),
        .cout(c_out0)
    );

    // BCD counter for the second least significant digit
    bcd_counter bcd1 (
        .clk(clk),
        .enable(enable & rco0 & ~rco1),
        .grst(grst),
        .count(digit1),
        .cout(c_out1)
    );

    // BCD counter for the third least significant digit
    bcd_counter bcd2 (
        .clk(clk),
        .enable(enable & rco1 & ~rco2),
        .grst(grst),
        .count(digit2),
        .cout(c_out2)
    );

    // BCD counter for the most significant digit
    bcd_counter bcd3 (
        .clk(clk),
        .enable(enable & rco2),
        .grst(grst),
        .count(digit3),
        .cout(cout)
    );

    // Register to hold the carryover signals
    always @(posedge clk or posedge grst) begin
        if (grst) begin
            rco0 <= 1'b0;
            rco1 <= 1'b0;
            rco2 <= 1'b0;
        end else begin
            rco0 <= c_out0;
            rco1 <= c_out1;
            rco2 <= c_out2;
        end
    end

    // Concatenate the four 4-bit digits to form the 16-bit count
    assign count = {digit3, digit2, digit1, digit0};
