module bcd_counter(
    input clk,
    input enable,
    input grst,
    output reg [3:0] count,
    output reg cout
);
    always @(posedge clk or posedge grst) begin
        if (grst) begin
            count <= 4'b0000;
            cout <= 1'b0;
        end else if (enable) begin
            if (count == 4'b1001) begin
                count <= 4'b0000;
                cout <= 1'b1;
            end else begin
                count <= count + 1;
                cout <= 1'b0;
            end
        end
    end
endmodule

