assign sums[1] = partial_products[2] + partial_products[3];
assign sums[2] = partial_products[4] + partial_products[5];
assign sums[3] = partial_products[6] + partial_products[7];

assign final_sum = sums[0] + sums[1] + sums[2] + sums[3];

