 output [1:0] o_sum;
 output o_carry;

 wire [1:0] sum_bits;
 wire [1:0] carry_bits;

 // Calculate the sum bits using XOR
 assign sum_bits[0] = i_a[0] ^ i_b[0] ^ i_carry;
 assign sum_bits[1] = i_a[1] ^ i_b[1] ^ carry_bits[0];

 // Calculate the carry bits using AND-OR
 assign carry_bits[0] = (i_a[0] & i_b[0]) | (i_a[0] & i_carry) | (i_b[0] & i_carry);
 assign carry_bits[1] = (i_a[1] & i_b[1]) | (i_a[1] & carry_bits[0]) | (i_b[1] & carry_bits[0]);

 // Assign the final sum and carry
 assign o_sum = sum_bits;
 assign o_carry = carry_bits[1];
