module registers(clk, read1, read2, data1, data2, regwrite, wrreg, wrdata, rst, of_control);
	input clk, rst;
	input [1:0] of_control;
	input [4:0] read1, read2;
	output reg [31:0] data1, data2;
	input regwrite;
	input [4:0] wrreg;
	input [31:0] wrdata;

	reg [31:0] regfile [0:31];

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			for (integer i = 0; i < 32; i = i + 1) begin
				regfile[i] <= 32'b0;
			end
		end else if (regwrite) begin
			case (of_control)
				2'b00: regfile[wrreg] <= wrdata; // Direct write
				2'b01: regfile[wrreg] <= regfile[wrreg] + wrdata; // Add and write
				2'b10: regfile[wrreg] <= regfile[wrreg] - wrdata; // Subtract and write
				2'b11: regfile[wrreg] <= regfile[wrreg] & wrdata; // AND and write
				default: regfile[wrreg] <= regfile[wrreg]; // No change
			endcase
		end
	end

	assign data1 = regfile[read1];
	assign data2 = regfile[read2];
endmodule

