module addmuland_1_stage_signed_14_bit(
	input signed [13:0] a,
	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out,
	input clk);

reg [27:0] intermediate_result;

always @(posedge clk) begin
	// Perform addition of a and b
	signed [27:0] add_result = a + b;

	// Perform multiplication of the addition result by c
	signed [27:0] mul_result = add_result * c;

	// Perform bitwise AND operation with d
	intermediate_result = mul_result & d;
end

assign out = intermediate_result[13:0];

endmodule

module tb_ALU();
  // Parameters
  parameter CLK_PERIOD = 10; // Clock period in time units
  parameter RESET_ASSERTION_TIME = 27; // Reset assertion time in time units
  parameter TEST_VECTOR_COUNT = 10001; // Number of test vectors
  parameter TEST_VECTOR_WIDTH = 27; // Width of each test vector

  // Signals
  reg clk;
  reg reset;
  reg [TEST_VECTOR_WIDTH-1:0] testvectors[TEST_VECTOR_COUNT-1:0];
  wire [TEST_VECTOR_WIDTH-1:0] Result;
  wire zeroflag;
  integer error_count;
  integer test_count;

  // ALU instance
  ALU alu (
    .clk(clk),
    .reset(reset),
    .A(testvectors[test_count][26:16]),
    .B(testvectors[test_count][15:5]),
    .op(testvectors[test_count][4:0]),
    .Result(Result),
    .zeroflag(zeroflag)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #CLK_PERIOD/2 clk = ~clk;
  end

  // Testbench initialization
  initial begin
    // Read test vectors from file
    $readmemb("test_vectors.mem", testvectors);
    reset = 1;
    #RESET_ASSERTION_TIME;
    reset = 0;
    error_count = 0;
    test_count = 0;
  end

  // Testbench main loop
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      test_count <= 0;
    end else if (test_count < TEST_VECTOR_COUNT) begin
      // Apply inputs to ALU
      // Check outputs against expected results
      if (Result !== testvectors[test_count][26:5]) begin
        $display("Error at test vector %0d: Expected %h, got %h", test_count, testvectors[test_count][26:5], Result);
        error_count <= error_count + 1;
      end
      // Move to the next test vector
      test_count <= test_count + 1;
    end
  end

  // Testbench finalization
  initial begin
    #CLK_PERIOD * 1000; // Wait for all tests to complete
    $display("Total tests completed: %0d", test_count);
    $display("Total errors: %0d", error_count);
    $finish;
  end
endmodule

