module TOP_sim(
    input clk,
    input rst
);
    // Define the data width for the registers and RAM
    parameter DATA_WIDTH = 8;

    // Define the control signals
    reg [2:0] control_signal;

    // Define the registers
    reg [DATA_WIDTH-1:0] ACC, BR, CU, IR, MAR, MBR, MR, PC;

    // Define the RAM
    reg [DATA_WIDTH-1:0] RAM [0:255];

    // ALU module
    wire [DATA_WIDTH-1:0] ALU_result;
    wire ALU_zero_flag, ALU_carry_flag;

    ALU alu_inst (
        .A(ACC),
        .B(BR),
        .control_signal(control_signal),
        .result(ALU_result),
        .zero_flag(ALU_zero_flag),
        .carry_flag(ALU_carry_flag)
    );

    // RAM module
    wire [DATA_WIDTH-1:0] RAM_data_out;

    RAM ram_inst (
        .clk(clk),
        .addr(MAR),
        .data_in(MBR),
        .write_enable(control_signal[2]),
        .data_out(RAM_data_out)
    );

    // Control Unit module
    ControlUnit cu_inst (
        .clk(clk),
        .rst(rst),
        .IR(IR),
        .control_signal(control_signal)
    );

    // Data path connections
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all registers to zero
            ACC <= 0;
            BR <= 0;
            CU <= 0;
            IR <= 0;
            MAR <= 0;
            MBR <= 0;
            MR <= 0;
            PC <= 0;
        end else begin
            // Data path logic based on control signals
            case (control_signal)
                3'b000: begin // No operation
                    // No action
                end
                3'b001: begin // Load instruction
                    IR <= RAM_data_out;
                end
                3'b010: begin // Execute ALU operation
                    ACC <= ALU_result;
                end
                3'b011: begin // Store data
                    MAR <= PC;
                    MBR <= ACC;
                end
                3'b100: begin // Jump
                    PC <= MAR;
                end
                default: begin
                    // Default action
                end
            endcase
        end
    end
endmodule

module add_saturate(
    input wire [15:0] a_i,
    input wire [15:0] b_i,
    output wire [15:0] s_o
);
    // Sign-extend inputs to 17 bits
    wire [16:0] ext_a = {a_i[15], a_i};
    wire [16:0] ext_b = {b_i[15], b_i};

    // Perform the addition
    wire [17:0] ext_sum = ext_a + ext_b;

    // Apply saturation
    assign s_o = (ext_sum > 32767) ? 32767 : (ext_sum < -32768) ? -32768 : ext_sum[15:0];
endmodule

