module memMod(clk, next, reset, inFlip, outFlip, inAddr, outAddr, dataIn, dataOut);
   input clk, next, reset, inFlip, outFlip;
   input [logDepth-1:0] inAddr, outAddr;
   input [width-1:0] dataIn;
   output reg [width-1:0] dataOut;

   // Internal FIFO for timing and flow control
   reg [width-1:0] fifo [0:15];
   integer i;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         for (i = 0; i < 16; i = i + 1) begin
            fifo[i] <= 0;
         end
      end else begin
         if (inFlip && next) begin
            fifo[0] <= dataIn;
         end
         if (outFlip && next) begin
            dataOut <= fifo[15];
            for (i = 1; i < 16; i = i + 1) begin
               fifo[i-1] <= fifo[i];
            end
         end
      end
   end

endmodule

