module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);

parameter TOTAL_COLS = 640;
parameter TOTAL_ROWS = 480;
parameter H_ACTIVE_START = 64;
parameter H_ACTIVE_END = 640 - 96;
parameter V_ACTIVE_START = 31;
parameter V_ACTIVE_END = 480 - 2;

reg [9:0] col_count;
reg [9:0] row_count;

always @(posedge i_clk) begin
    if (col_count == TOTAL_COLS - 1) begin
        col_count <= 0;
        if (row_count == TOTAL_ROWS - 1) begin
            row_count <= 0;
        end else begin
            row_count <= row_count + 1;
        end
    end else begin
        col_count <= col_count + 1;
    end

    o_col_count <= col_count;
    o_row_count <= row_count;

    o_hsync <= (col_count < H_ACTIVE_START) || (col_count > H_ACTIVE_END);
    o_vsync <= (row_count < V_ACTIVE_START) || (row_count > V_ACTIVE_END);
end

endmodule

