    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
    parameter CONF_ADDR_BASE = 32'h10000000;
    parameter CONF_ADDR_MASK = 32'h0FFFFFFF;

    reg [31:0] sel_sram;
    reg [31:0] sel_conf;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            sel_sram <= 0;
            sel_conf <= 0;
        end else begin
            if (cpu_data_en) begin
                if ((cpu_data_addr & CONF_ADDR_MASK) == CONF_ADDR_BASE) begin
                    sel_conf <= cpu_data_addr;
                end else begin
                    sel_sram <= cpu_data_addr;
                end
            end
        end
    end

    assign data_sram_en = cpu_data_en & (sel_sram != 0);
    assign data_sram_wen = cpu_data_wen & (sel_sram != 0);
    assign data_sram_addr = sel_sram;
    assign data_sram_wdata = cpu_data_wdata;
    assign cpu_data_rdata = (sel_sram != 0) ? data_sram_rdata : conf_rdata;

    assign conf_en = cpu_data_en & (sel_conf != 0);
    assign conf_wen = cpu_data_wen & (sel_conf != 0);
    assign conf_addr = sel_conf;
    assign conf_wdata = cpu_data_wdata;
