  input                             i_pslverr
);

  // Internal signals
  reg                               r_busy;
  reg                               r_psel;
  reg                               r_penable;
  reg                               r_pwrite;
  reg  [ADDRESS_WIDTH-1:0]          r_paddr;
  reg  [2:0]                        r_pprot;
  reg  [BUS_WIDTH/8-1:0]            r_pstrb;
  reg  [BUS_WIDTH-1:0]              r_pwdata;
  reg  [BUS_WIDTH-1:0]              r_prdata;
  reg  [1:0]                        r_bus_status;
  reg  [BUS_WIDTH-1:0]              r_bus_read_data;

  // State definition
  typedef enum reg [1:0] {
    IDLE,
    SETUP,
    ACCESS,
    RESPONSE
  } state_t;
  state_t r_state, r_next_state;

  // State transition logic
  always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      r_state <= IDLE;
    end else begin
      r_state <= r_next_state;
    end
  end

  // Next state logic
  always @(*) begin
    r_next_state = r_state;
    case (r_state)
      IDLE: begin
        if (i_bus_valid) begin
          r_next_state = SETUP;
        end
      end
      SETUP: begin
        r_next_state = ACCESS;
      end
      ACCESS: begin
        if (i_pready) begin
          r_next_state = RESPONSE;
        end
      end
      RESPONSE: begin
        r_next_state = IDLE;
      end
      default: begin
        r_next_state = IDLE;
      end
    endcase
  end

  // Control signal generation
  always @(*) begin
    o_bus_ready = (r_state == IDLE);
    o_bus_status = 2'b00;
    o_bus_read_data = r_prdata;
    o_psel = (r_state == ACCESS);
    o_penable = (r_state == ACCESS);
    o_paddr = r_paddr;
    o_pprot = 3'b000; // Assuming no protection required
    o_pwrite = r_pwrite;
    o_pstrb = r_pstrb;
    o_pwdata = r_pwdata;

    case (r_state)
      IDLE: begin
        r_psel = 1'b0;
        r_penable = 1'b0;
        r_pwrite = 1'b0;
        r_pstrb = 4'b0000;
        r_pwdata = 32'b0;
      end
      SETUP: begin
        r_paddr = i_bus_address;
        r_pwrite = (i_bus_access == 2'b01); // Write
        r_pstrb = i_bus_strobe;
        r_pwdata = i_bus_write_data;
      end
      ACCESS: begin
        // Wait for i_pready
      end
      RESPONSE: begin
        r_prdata = i_prdata;
        if (i_pslverr) begin
          o_bus_status = 2'b10; // Error
        end else begin
          o_bus_status = 2'b01; // Success
        end
      end
      default: begin
        // Default case
      end
    endcase
  end

endmodule

