module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output reg [7 : 0] q
);
    reg [3 : 0] wp, rp; // Write and read pointers
    reg [15 : 0] mem [0 : 15]; // 16x8 memory array
    reg w_flag, r_flag; // Write and read flags

    // Always block for write operation
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 4'b0000;
            rp <= 4'b0000;
            w_flag <= 1'b0;
            r_flag <= 1'b0;
        end else if (wrreq && !full) begin
            mem[wp] <= data;
            wp <= wp + 1;
            if (wp == 4'b1111) begin
                wp <= 4'b0000;
                w_flag <= 1'b1;
            end else begin
                w_flag <= 1'b0;
            end
        end
    end

    // Always block for read operation
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            rp <= 4'b0000;
            r_flag <= 1'b0;
        end else if (rdreq && !empty) begin
            q <= mem[rp];
            rp <= rp + 1;
            if (rp == 4'b1111) begin
                rp <= 4'b0000;
                r_flag <= 1'b1;
            end else begin
                r_flag <= 1'b0;
            end
        end
    end

    // Combinational logic to determine buffer status
    assign full = (wp == rp && w_flag) || (wp == rp + 1);
    assign empty = (wp == rp && !w_flag) || (wp == rp + 16);

endmodule

