module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAY_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);

    // Internal signals
    reg [DATA_WIDTH-1:0] addends [0:LENGTH-1];
    reg [DATA_WIDTH-1:0] sums [0:LENGTH/2-1];
    reg [DATA_WIDTH-1:0] final_sum;
    reg [DELAY_STAGES-1:0] delay_reg;

    // Split the input addends into individual elements
    generate
        genvar i;
        for (i = 0; i < LENGTH; i = i + 1) begin : split_addends
            assign addends[i] = in_addends[i*DATA_WIDTH +: DATA_WIDTH];
        end
    endgenerate

    // Recursive adder tree
    generate
        genvar j;
        for (j = 0; j < DELAY_STAGES; j = j + 1) begin : adder_tree
            if (j == 0) begin
                generate
                    genvar k;
                    for (k = 0; k < LENGTH/2; k = k + 1) begin : adder_level
                        assign sums[k] = addends[2*k] + addends[2*k + 1];
                    end
                endgenerate
            end else begin
                generate
                    genvar l;
                    for (l = 0; l < LENGTH/(2**(j+1)); l = l + 1) begin : adder_level
                        assign sums[l] = sums[2*l] + sums[2*l + 1];
                    end
                endgenerate
            end
        end
    endgenerate

    // Final sum assignment
    assign final_sum = sums[0];

    // Delay register to control pipelining
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            delay_reg <= {DELAY_STAGES{1'b0}};
        end else if (in_advance) begin
            delay_reg <= {delay_reg[DELAY_STAGES-2:0], final_sum[DATA_WIDTH-1]};
        end
    end

    // Output the final sum after the delay
    assign out_sum = delay_reg[DATA_WIDTH-1];

endmodule

