assign sum[3] = pA3 ^ pB3 ^ carry[2];

assign carry[4] = carry[3] | (pA4 & pB4) | (pA4 & carry[3]);
assign sum[4] = pA4 ^ pB4 ^ carry[3];

assign carry[5] = carry[4] | (pA5 & pB5) | (pA5 & carry[4]);
assign sum[5] = pA5 ^ pB5 ^ carry[4];

// Final sum and carry-out
assign r5 = sum[5];
assign r4 = sum[4];
assign r3 = sum[3];
