module add16u_1JH(A, B, O);
  input [15:0] A, B;
  output [16:0] O;

  wire [15:0] sum;
  wire [15:0] carry;

  // Calculate sum and carry using ripple-carry adder
  assign sum = A + B;
  assign carry = (A & B) | (A & sum) | (B & sum);

  // Assign specific bits of the output
  assign O[0] = A[0] ^ B[0] ^ carry[0];
  assign O[1] = A[1] ^ B[1] ^ carry[1];
  assign O[2] = 1'b0; // Constant assignment
  assign O[3] = 1'b1; // Constant assignment
  assign O[4] = A[4] ^ B[4] ^ carry[4];

  // Assign remaining bits of the output
  assign O[5:16] = sum[5:16] | carry[5:16];

endmodule

module Combination(a, b, c, out);
    input a, b, c;
    output out;

    wire w1, w2;

    // AND gate to produce w1
    assign w1 = a & b & c;

    // NOT gate to produce w2
    assign w2 = ~c;

    // OR gate to produce the final output
    assign out = w1 | w2;
endmodule

module partsel_00126(
  input [3:0] ctrl,
  input [2:0] s0,
  input [2:0] s1,
  input [2:0] s2,
  input [2:0] s3,
  input signed [31:0] x0,
  input signed [31:0] x1,
  input signed [31:0] x2,
  input [31:0] x3,
  output [127:0] y
);

  // Local parameters for constants
  parameter [31:0] C1 = 32'd10;
  parameter [31:0] C2 = 32'd20;
  parameter [31:0] C3 = 32'd30;

  // Intermediate wires for partial results
  wire [31:0] a, b, c, d, e, f, g, h;
  wire [31:0] i, j, k, l, m, n, o, p;

  // Arithmetic and bitwise operations based on control signals
  always @(*) begin
    case (ctrl)
      4'b0000: begin
        a = x0 + C1;
        b = x1 - C2;
        c = x2 ^ C3;
        d = x3 & C1;
      end
      4'b0001: begin
        a = x0 - C1;
        b = x1 + C2;
        c = x2 & C3;
        d = x3 ^ C1;
      end
      4'b0010: begin
        a = x0 ^ C1;
        b = x1 & C2;
        c = x2 + C3;
        d = x3 - C1;
      end
      4'b0011: begin
        a = x0 & C1;
        b = x1 ^ C2;
        c = x2 - C3;
        d = x3 + C1;
      end
      4'b0100: begin
        a = x0 << s0;
        b = x1 >> s1;
        c = x2 | C3;
        d = x3 & C1;
      end
      4'b0101: begin
        a = x0 >> s0;
        b = x1 << s1;
        c = x2 & C3;
        d = x3 | C1;
      end
      4'b0110: begin
        a = x0 | C1;
        b = x1 & C2;
        c = x2 << s3;
        d = x3 >> s2;
      end
      4'b0111: begin
        a = x0 & C1;
        b = x1 | C2;
        c = x2 >> s3;
        d = x3 << s2;
      end
      4'b1000: begin
        a = x0 + x1;
        b = x2 + x3;
        c = x0 - x1;
        d = x2 - x3;
      end
      4'b1001: begin
        a = x0 - x1;
        b = x2 - x3;
        c = x0 + x1;
        d = x2 + x3;
      end
      4'b1010: begin
        a = x0 ^ x1;
        b = x2 ^ x3;
        c = x0 & x1;
        d = x2 & x3;
      end
      4'b1011: begin
        a = x0 & x1;
        b = x2 & x3;
        c = x0 ^ x1;
        d = x2 ^ x3;
      end
      4'b1100: begin
        a = x0 << s0;
        b = x2 << s2;
        c = x0 >> s1;
        d = x2 >> s3;
      end
      4'b1101: begin
        a = x0 >> s0;
        b = x2 >> s2;
        c = x0 << s1;
        d = x2 << s3;
      end
      4'b1110: begin
        a = x0 | x1;
        b = x2 | x3;
        c = x0 & x1;
        d = x2 & x3;
      end
      4'b1111: begin
        a = x0 & x1;
        b = x2 & x3;
        c = x0 | x1;
        d = x2 | x3;
      end
      default: begin
        a = 32'd0;
        b = 32'd0;
        c = 32'd0;
        d = 32'd0;
      end
    endcase

    // Slicing and combining intermediate results based on selector signals
    i = (s0 == 3'b000) ? a : b;
    j = (s1 == 3'b000) ? c : d;
    k = (s2 == 3'b000) ? i : j;
    l = (s3 == 3'b000) ? k : l;

    // Final output
    y = {l, k, j, i};
  end

endmodule

module multi_seven_seg_6 (
    input clk,
    input rst,
    input [15:0] value,
    output reg [6:0] segs,
    output reg [3:0] sel
  );

  parameter NUM_DIGITS = 4;
  parameter DIGIT_WIDTH = 4;
  parameter SEGMENT_WIDTH = 7;

  reg [3:0] digit_counter;
  reg [3:0] digit_value;
  reg [6:0] segment_value;

  // Seven-segment decoder
  always @(*) begin
    case (digit_value)
      4'b0000: segment_value = 7'b1111110; // 0
      4'b0001: segment_value = 7'b0110000; // 1
      4'b0010: segment_value = 7'b1101101; // 2
      4'b0011: segment_value = 7'b1111001; // 3
      4'b0100: segment_value = 7'b0110011; // 4
      4'b0101: segment_value = 7'b1011011; // 5
      4'b0110: segment_value = 7'b1011111; // 6
      4'b0111: segment_value = 7'b1110000; // 7
      4'b1000: segment_value = 7'b1111111; // 8
      4'b1001: segment_value = 7'b1111011; // 9
      default: segment_value = 7'b1111111; // Blank
    endcase
  end

  // Digit decoder
  always @(*) begin
    case (digit_counter)
      4'b0000: sel = 4'b0001; // Select first digit
      4'b0001: sel = 4'b0010; // Select second digit
      4'b0010: sel = 4'b0100; // Select third digit
      4'b0011: sel = 4'b1000; // Select fourth digit
      default: sel = 4'b0000; // Blank
    endcase
  end

  // Counter to cycle through digits
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      digit_counter <= 4'b0000;
    end else begin
      if (digit_counter == NUM_DIGITS - 1) begin
        digit_counter <= 4'b0000;
      end else begin
        digit_counter <= digit_counter + 1;
      end
    end
  end

  // Extract the current digit from the input value
  always @(*) begin
    case (digit_counter)
      4'b0000: digit_value = value[15:12];
      4'b0001: digit_value = value[11:8];
      4'b0010: digit_value = value[7:4];
      4'b0011: digit_value = value[3:0];
      default: digit_value = 4'b0000;
    endcase
  end

  // Assign the segment value to the output
  assign segs = segment_value;

endmodule

