module uart(
    input wire [7:0] din,
    input wire wr_en,
    input wire clk,
    output wire tx,
    output wire tx_busy,
    input wire rx,
    output wire rdy,
    input wire rdy_clr,
    output wire [7:0] dout
);

    // Parameters
    parameter CLK_FREQ = 50_000_000; // System clock frequency in Hz
    parameter BAUD_RATE = 9600; // Desired baud rate

    // Internal signals
    reg [7:0] tx_data;
    reg tx_start;
    reg [3:0] tx_bit_count;
    reg [23:0] baud_counter;
    reg rx_start;
    reg [3:0] rx_bit_count;
    reg [23:0] rx_baud_counter;
    reg [7:0] rx_data;
    reg rx_error;

    // Baud rate generator
    always @(posedge clk) begin
        if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
            baud_counter <= 0;
        end else begin
            baud_counter <= baud_counter + 1;
        end
    end

    // Transmitter
    always @(posedge clk) begin
        if (wr_en && !tx_busy) begin
            tx_data <= din;
            tx_start <= 1;
            tx_busy <= 1;
        end else if (tx_start) begin
            if (tx_bit_count == 8) begin
                tx_start <= 0;
                tx_busy <= 0;
            end else begin
                tx_bit_count <= tx_bit_count + 1;
                tx <= tx_data[7];
                tx_data <= {tx_data[6:0], 1'b0};
            end
        end
    end

    // Receiver
    always @(posedge clk) begin
        if (rx_start) begin
            if (rx_baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                rx_baud_counter <= 0;
                if (rx_bit_count < 8) begin
                    rx_data[rx_bit_count] <= rx;
                    rx_bit_count <= rx_bit_count + 1;
                end else begin
                    rx_start <= 0;
                    rdy <= 1;
                end
            end else begin
                rx_baud_counter <= rx_baud_counter + 1;
            end
        end else if (rx) begin
            rx_start <= 1;
            rx_bit_count <= 0;
            rx_error <= 0;
        end
    end

    // Clear ready signal
    always @(posedge clk) begin
        if (rdy_clr) begin
            rdy <= 0;
        end
    end

    // Output data
    assign dout = rx_data;

endmodule

module Multiplication(
    input wire [7:0] Input1,
    input wire [7:0] Input2,
    input wire Op,
    output wire [7:0] Output1,
    output wire [7:0] Output2,
    output wire N
);
    wire [15:0] SignedMult;
    wire [15:0] MultAns;

    // Perform signed multiplication
    assign SignedMult = $signed(Input1) * $signed(Input2);

    // Select between signed and unsigned multiplication based on Op
    assign MultAns = Op ? $unsigned(Input1) * $unsigned(Input2) : SignedMult;

    // Assign lower and upper 8 bits of MultAns to Output1 and Output2
    assign Output1 = MultAns[7:0];
    assign Output2 = MultAns[15:8];

    // Determine the sign bit N when signed multiplication is active
    assign N = Op ? MultAns[15] : 0;
endmodule

module fft2(
    input [31:0] a_re,
    input [31:0] a_img,
    input [31:0] b_re,
    input [31:0] b_img,
    input clk,
    output [31:0] x0_re,
    output [31:0] x0_img,
    output [31:0] x1_re,
    output [31:0] x1_img
);

    reg [31:0] a_re_reg, a_img_reg, b_re_reg, b_img_reg;
    reg [31:0] x0_re_reg, x0_img_reg, x1_re_reg, x1_img_reg;
    reg [31:0] scaled_a_re, scaled_a_img, scaled_b_re, scaled_b_img;
    reg [31:0] temp_re, temp_img;

