    always @(posedge clk) begin
        a_re_reg <= a_re;
        a_img_reg <= a_img;
        b_re_reg <= b_re;
        b_img_reg <= b_img;
    end

    // Scale inputs
    assign scaled_a_re = a_re_reg * 2;
    assign scaled_a_img = a_img_reg * 2;
    assign scaled_b_re = b_re_reg * 2;
    assign scaled_b_img = b_img_reg * 2;

    // Buffer module to manage data preparation
    buf11 buf11_inst (
        .in_re(scaled_a_re),
        .in_img(scaled_a_img),
        .out_re(temp_re),
        .out_img(temp_img)
    );

    // Complex adder to compute final outputs
    complex_adder complex_adder_inst (
        .a_re(temp_re),
        .a_img(temp_img),
        .b_re(scaled_b_re),
        .b_img(scaled_b_img),
        .x_re(x0_re_reg),
        .x_img(x0_img_reg)
    );

    // Buffer module to manage data preparation
    buf11 buf12_inst (
        .in_re(scaled_b_re),
        .in_img(scaled_b_img),
        .out_re(temp_re),
        .out_img(temp_img)
    );

    // Complex adder to compute final outputs
    complex_adder complex_adder_inst2 (
        .a_re(temp_re),
        .a_img(temp_img),
        .b_re(scaled_a_re),
        .b_img(scaled_a_img),
        .x_re(x1_re_reg),
        .x_img(x1_img_reg)
    );

    // Register outputs to synchronize with clock
