module motor_rpm_count(
	input clk,
	input motor_rot_pulse,
	output wire [15:0] rpm_output
);
	// Internal registers
	reg [31:0] pulse_count;
	reg last_scan_value;
	reg [15:0] pulse_count_qty;
	reg [15:0] output_count_qty;

	// Initialize pulse_count to 50,000,000 - 1
	parameter COUNTDOWN_VALUE = 32'd49999999;

	always @(posedge clk) begin
		// Update last_scan_value with the current state of motor_rot_pulse
		last_scan_value <= motor_rot_pulse;

		// Check for rising edge on motor_rot_pulse
		if (motor_rot_pulse && !last_scan_value) begin
			pulse_count_qty <= pulse_count_qty + 16'd1;
		end

		// Decrement pulse_count
		if (pulse_count > 0) begin
			pulse_count <= pulse_count - 1;
		end else begin
			// When pulse_count reaches zero, store the pulse_count_qty as output_count_qty
			output_count_qty <= pulse_count_qty;
			// Reset pulse_count and pulse_count_qty for the next cycle
			pulse_count <= COUNTDOWN_VALUE;
			pulse_count_qty <= 16'd0;
		end
	end

	// Assign the output_count_qty to rpm_output
	assign rpm_output = output_count_qty;
endmodule

module edge_detect (
  input clk,
  input rst_n,
  input a,
  output reg rise,
  output reg down
);
  reg a_prev;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_prev <= 0;
      rise <= 0;
      down <= 0;
    end else begin
      a_prev <= a;
      if (a && !a_prev) begin
        rise <= 1;
        down <= 0;
      end else if (!a && a_prev) begin
        rise <= 0;
        down <= 1;
      end else begin
        rise <= 0;
        down <= 0;
      end
    end
  end
endmodule

