module I_SQRT_2(
    input wire [31:0] n,
    input wire CLK,
    input wire RST_n,
    input wire EN,
    input wire SEL,
    output wire VAL,
    output wire Z,
    output wire [31:0] out_sqrt
);

    reg [31:0] x_0 = 32'h3FF00000; // Initial guess for sqrt(2) in floating-point format
    reg [31:0] x_i;
    reg [31:0] x_next;
    reg [31:0] sqrt;
    reg [31:0] out_sqrt_reg;
    reg val_comb, z_comb;
    reg val_ff, z_ff;

    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            x_i <= 32'h0;
            sqrt <= 32'h0;
            val_ff <= 0;
            z_ff <= 0;
        end else if (EN) begin
            if (n == 32'h0) begin
                sqrt <= 32'h0;
                val_comb <= 0;
                z_comb <= 1;
            end else begin
                if (x_next >= x_i) begin
                    sqrt <= x_i;
                    val_comb <= 1;
                    z_comb <= 0;
                end else begin
                    val_comb <= 0;
                    z_comb <= 0;
                end
            end
        end
    end

    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            out_sqrt_reg <= 32'h0;
        end else if (EN) begin
            out_sqrt_reg <= sqrt;
        end
    end

    assign out_sqrt = out_sqrt_reg;
    assign VAL = val_ff;
    assign Z = z_ff;

    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            val_ff <= 0;
            z_ff <= 0;
        end else begin
            val_ff <= val_comb;
            z_ff <= z_comb;
        end
    end

    assign x_i_mux = SEL ? x_next : x_i;
    assign x_next = (x_i + (n << 16) / x_i) >> 1;

endmodule

