      8'b00000001: begin
        y0 = u0 << 2;
        y1 = u1 >> 1;
        y2 = u2 ^ u3;
        y3 = u4 | u5;
        y4 = s0 << 2;
        y5 = s1 >> 1;
        y6 = s2 ^ s3;
        y7 = s4 | s5;
      end
      // Add more cases as needed for different control values
      default: begin
        y0 = 16'b0;
        y1 = 16'b0;
        y2 = 16'b0;
        y3 = 16'b0;
        y4 = 16'b0;
        y5 = 16'b0;
        y6 = 16'b0;
        y7 = 16'b0;
      end
    endcase
  end

