module NV_NVDLA_HLS_shiftrightsatsu (
   data_in
  ,shift_num
  ,data_out
  ,sat_out
  );
parameter IN_WIDTH = 49;
parameter SHIFT_WIDTH = 6;
parameter OUT_WIDTH = 32;

input [IN_WIDTH-1:0] data_in;
input [SHIFT_WIDTH-1:0] shift_num;
output [OUT_WIDTH-1:0] data_out;
output sat_out;

wire [IN_WIDTH:0] shifted_data;
wire [OUT_WIDTH-1:0] extended_data;
wire [OUT_WIDTH-1:0] saturated_data;
wire [OUT_WIDTH-1:0] rounded_data;
wire [OUT_WIDTH-1:0] clamped_data;
wire [OUT_WIDTH-1:0] final_data;
wire sat_flag;

// Perform the right shift with sign extension
assign shifted_data = {data_in[IN_WIDTH-1], data_in} >> shift_num;

// Extend the shifted data to match the output width
assign extended_data = {shifted_data[OUT_WIDTH-1], shifted_data[OUT_WIDTH-1:0]};

// Determine if saturation is needed
assign sat_flag = (shifted_data[OUT_WIDTH] != shifted_data[OUT_WIDTH-1]) && (shift_num != 0);

// Handle saturation by clamping to the maximum or minimum value
assign clamped_data = sat_flag ? {OUT_WIDTH{shifted_data[OUT_WIDTH]}} : extended_data;

// Round the clamped data if necessary
assign rounded_data = clamped_data + (clamped_data[OUT_WIDTH-2] ? 1 : 0);

// Select the final output based on saturation
assign final_data = sat_flag ? {OUT_WIDTH{shifted_data[OUT_WIDTH]}} : rounded_data;

// Assign the outputs
assign data_out = final_data;
assign sat_out = sat_flag;

endmodule

