    wire [N-1: 0] sum;

    // Full adder for the least significant bit
    full_adder fa0(A[0], B[0], 0, sum[0], carry[1]);

    // Generate full adders for the remaining bits
    generate
        genvar i;
        for (i = 1; i < N; i++) begin : full_adder_loop
            full_adder fa(i, A[i], B[i], sum[i], carry[i+1]);
        end
