reg [31:0] variable_pulse_threshold;
reg [31:0] slow_pulse_threshold;
reg [31:0] fast_pulse_threshold;

// Calculate thresholds based on the variable pulse index
always @(*) begin
	variable_pulse_threshold = 24000000 - (variable_pulse_index * 2000000 / 15);
	slow_pulse_threshold = 18000000;
	fast_pulse_threshold = 4800000;
end

// Counter increment logic
always @(posedge clk or posedge reset) begin
	if (reset) begin
		counter <= 32'b0;
	end else begin
		counter <= counter + 32'b1;
	end
end

// Output pulse generation logic
assign slow_pulse = (counter >= slow_pulse_threshold) ? 1'b1 : 1'b0;
assign fast_pulse = (counter >= fast_pulse_threshold) ? 1'b1 : 1'b0;
assign variable_pulse = (counter >= variable_pulse_threshold) ? 1'b1 : 1'b0;

endmodule

