module FSM_game(
input wire iRST,
input wire iCLK,
input wire [1:0] iA,
input wire [1:0] iB,
output wire oA,
output wire oB
);

// State definitions
localparam DRAW = 3'b000,
           B_LEAD = 3'b001,
           B_WIN = 3'b010,
           A_LEAD = 3'b011,
           A_WIN = 3'b100;

// Internal signals
reg [2:0] sSTATE, sNEXT_STATE;
reg [1:0] sWIN;

// State transition logic
always @(*) begin
    case (sSTATE)
        DRAW: begin
            if (iA == 2'b11 && iB == 2'b00) sNEXT_STATE = A_WIN;
            else if (iA == 2'b00 && iB == 2'b11) sNEXT_STATE = B_WIN;
            else if (iA == 2'b11 && iB == 2'b11) sNEXT_STATE = DRAW;
            else sNEXT_STATE = DRAW;
        end
        B_LEAD: begin
            if (iA == 2'b11) sNEXT_STATE = A_WIN;
            else if (iB == 2'b11) sNEXT_STATE = B_WIN;
            else sNEXT_STATE = B_LEAD;
        end
        B_WIN: sNEXT_STATE = B_WIN;
        A_LEAD: begin
            if (iA == 2'b11) sNEXT_STATE = A_WIN;
            else if (iB == 2'b11) sNEXT_STATE = B_WIN;
            else sNEXT_STATE = A_LEAD;
        end
        A_WIN: sNEXT_STATE = A_WIN;
        default: sNEXT_STATE = DRAW;
    endcase
end

// State update logic
always @(posedge iCLK or posedge iRST) begin
    if (iRST) sSTATE <= DRAW;
    else sSTATE <= sNEXT_STATE;
end

// Output logic
always @(*) begin
    case (sSTATE)
        B_WIN: sWIN = 2'b10;
        A_WIN: sWIN = 2'b01;
        default: sWIN = 2'b00;
    endcase
end

// Assign outputs
assign oA = sWIN[0];
assign oB = sWIN[1];

endmodule

