  parameter FRACTION_WIDTH = 8;
  parameter FP_WIDTH = 32;
  parameter FP_FRACTION_WIDTH = 23;

  // Clock and reset signals
  reg clk;
  reg rst_n;

  // Input signals
  reg [WIDTH-1:0] fixed_point_in;
  reg start;

  // Output signals
  wire [WIDTH-1:0] fixed_point_out;
  wire valid;
  wire [FP_WIDTH-1:0] floating_point_out;
  wire [FP_WIDTH-1:0] floating_point_out_valid;

  // DUT instance
  fixed_point_reciprocal #(
    .WIDTH(WIDTH),
    .FRACTION_WIDTH(FRACTION_WIDTH),
    .FP_WIDTH(FP_WIDTH),
    .FP_FRACTION_WIDTH(FP_FRACTION_WIDTH)
  ) dut (
    .clk(clk),
    .rst_n(rst_n),
    .fixed_point_in(fixed_point_in),
    .start(start),
    .fixed_point_out(fixed_point_out),
    .valid(valid),
    .floating_point_out(floating_point_out),
    .floating_point_out_valid(floating_point_out_valid)
  );

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Reset generation
  initial begin
    rst_n = 0;
    #10 rst_n = 1;
  end

  // Test sequence
  initial begin
    // Initialize inputs
    fixed_point_in = 0;
    start = 0;

    // Wait for reset to be released
    #20;

    // Test case 1: Normal case
    fixed_point_in = 16'h0001; // 1.0 in fixed-point
    start = 1;
    #10 start = 0;
    #20;

    // Test case 2: Edge case - division by zero
    fixed_point_in = 16'h0000; // 0.0 in fixed-point
    start = 1;
    #10 start = 0;
    #20;

    // Test case 3: Large number
    fixed_point_in = 16'h7FFF; // 127.0 in fixed-point
    start = 1;
    #10 start = 0;
    #20;

    // Test case 4: Small number
    fixed_point_in = 16'h0001; // 1.0 in fixed-point
    start = 1;
    #10 start = 0;
    #20;

    // Finish simulation
    $finish;
  end

  // Helper functions for conversion
  function [FP_WIDTH-1:0] fixed_to_float;
    input [WIDTH-1:0] fixed_point;
    begin
