    end
  endfunction

  function [WIDTH-1:0] float_to_fixed;
    input [FP_WIDTH-1:0] floating_point;
    begin
      float_to_fixed = $rtoi(floating_point * (2**FRACTION_WIDTH));
    end
  endfunction

  // Monitor outputs
  initial begin
    $monitor("At time %t, fixed_point_out = %h, valid = %b, floating_point_out = %h, floating_point_out_valid = %b",
