module array_mul4bit(a, b, prod);
  input [3:0] a;
  input [3:0] b;
  output reg [7:0] prod;

  wire [3:0] _and [0:3];
  wire [7:0] _sum [0:3];
  wire [7:0] _carry [0:3];

  // Generate all 16 AND products
  generate
    genvar i, j;
    for (i = 0; i < 4; i = i + 1) begin : and_gen
      for (j = 0; j < 4; j = j + 1) begin : and_inst
        assign _and[i][j] = a[i] & b[j];
      end
    end
  endgenerate

  // Compute partial sums and carries
  generate
    genvar k;
    for (k = 0; k < 4; k = k + 1) begin : add_gen
      if (k == 0) begin
        half_adder _ha (.a(_and[0][k]), .b(_and[1][k]), .sum(_sum[k]), .carry(_carry[k]));
      end else if (k == 1) begin
        full_adder _fa1 (.a(_sum[k-1]), .b(_and[2][k]), .cin(_carry[k-1]), .sum(_sum[k]), .carry(_carry[k]));
      end else if (k == 2) begin
        full_adder _fa2 (.a(_sum[k-1]), .b(_and[3][k]), .cin(_carry[k-1]), .sum(_sum[k]), .carry(_carry[k]));
      end else begin
        full_adder _fa3 (.a(_sum[k-1]), .b(0), .cin(_carry[k-1]), .sum(prod[k]), .carry(prod[k+1]));
      end
    end
  endgenerate

  // Final carry out
  assign prod[7] = _carry[3];

endmodule

module half_adder(a, b, sum, carry);
  input a, b;
  output sum, carry;

  assign sum = a ^ b;
  assign carry = a & b;
endmodule

module full_adder(a, b, cin, sum, carry);
  input a, b, cin;
  output sum, carry;

  wire sum1, carry1;
  half_adder ha1 (.a(a), .b(b), .sum(sum1), .carry(carry1));
  half_adder ha2 (.a(sum1), .b(cin), .sum(sum), .carry(carry));
endmodule

module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
);

    reg [15:0] bit_position;
    reg [31:0] remaining_value;
    reg [15:0] result;

    always @(*) begin
        // Initialize registers
        bit_position = 16'd0;
        remaining_value = x;
        result = 16'd0;

        // Iterate through each bit of the input
        for (int i = 15; i >= 0; i--) begin
            // Shift the result left and add the current bit position
            result = (result << 1) | (bit_position[0]);
            // Shift the remaining value left by 2
            remaining_value = remaining_value << 2;

            // If the remaining value is greater than or equal to the result, subtract the result
            if (remaining_value >= result) begin
                remaining_value = remaining_value - result;
                // Set the current bit position to 1
                bit_position = bit_position | (1 << i);
            end else begin
                // Set the current bit position to 0
                bit_position = bit_position & ~(1 << i);
            end
        end

        // Assign the final result to the output
        y = result;
    end

endmodule

module gf180mcu_fd_sc_mcu9t5v0__oai31_4( A3, ZN, A2, A1, B );
input A1, A2, A3, B;
output ZN;

// Invert the input signals
wire not_A1, not_A2, not_A3, not_B;
not not_A1 (A1);
not not_A2 (A2);
not not_A3 (A3);
not not_B (B);

// Compute the logical AND of the inverted A signals
wire ZN_row1;
and ZN_row1 (ZN_row1, not_A1, not_A2, not_A3);

// Compute the logical OR of ZN_row1 and the inverted B signal
or ZN (ZN, ZN_row1, not_B);

endmodule

