module rx_dcoffset 
  #(parameter WIDTH=16,
    parameter ADDR=8'd0,
    parameter alpha_shift=20)
   (input clk, input rst, 
    input set_stb, input [7:0] set_addr, input [31:0] set_data,
    input [WIDTH-1:0] in, output [WIDTH-1:0] out);

  reg [WIDTH-1:0] dcoffset;
  reg [WIDTH:0] integrator;
  reg [WIDTH-1:0] sign_bit;
  reg [WIDTH-1:0] rounded_value;
  reg [WIDTH-1:0] corrected_output;

  // Sub-module for rounding
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      rounded_value <= 0;
    end else begin
      sign_bit <= in[WIDTH-1];
      integrator <= integrator + sign_bit;
      rounded_value <= integrator[WIDTH] ? integrator[WIDTH-1:0] + 1 : integrator[WIDTH-1:0];
    end
  end

  // Sub-module for addition with clipping
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      corrected_output <= 0;
    end else begin
      corrected_output <= in - rounded_value;
      // Clipping to ensure the output remains within the valid range
      if (corrected_output[WIDTH]) begin
        corrected_output <= {1'b0, {WIDTH{1'b1}}};
      end else if (~corrected_output[WIDTH-1]) begin
        corrected_output <= {1'b0, {WIDTH{1'b0}}};
      end
    end
  end

  // Setup mode
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      dcoffset <= 0;
    end else if (set_stb && set_addr == ADDR) begin
      dcoffset <= set_data[WIDTH-1:0];
    end
  end

  // Output assignment
  assign out = corrected_output;

endmodule

