module mii_if(
	input	aclk,
	input	aresetn,

	output	reg [7:0] tx_tdata,
	output	reg tx_tvalid,
	output	reg tx_tlast,
	input	tx_tready, 

	input	[7:0] rx_tdata,
	input	rx_tvalid,
	input	rx_tlast,
	output	reg rx_tready,

	output	mii_tx_clk,
	input	mii_tx_en,
	input	mii_tx_er,
	input	[3:0] mii_tx_data,

	output	mii_rx_clk,
	output	reg mii_rx_dv,
	output	reg mii_rx_er,
	output	reg [3:0] mii_rx_data,

	output	mii_crs,
	output	mii_col
);

reg [7:0] tx_buffer;
reg tx_valid_reg;
reg tx_last_reg;
reg [3:0] tx_data_reg;
reg tx_crs;
reg tx_col;

reg [7:0] rx_buffer;
reg rx_valid_reg;
reg rx_last_reg;
reg [3:0] rx_data_reg;

reg mii_tx_clk_reg;
reg mii_rx_clk_reg;

reg [3:0] mii_tx_data_reg;
reg mii_rx_data_reg;

reg mii_crs_reg;
reg mii_col_reg;

reg [3:0] tx_state;
reg [3:0] rx_state;

reg [7:0] tx_timer;
reg [7:0] rx_timer;

parameter IDLE = 4'b0000;
parameter STROBE = 4'b0001;
parameter INTER_FRAME_GAP = 4'b0010;
parameter UNDERFLOW = 4'b0011;
parameter RECOVERY = 4'b0100;

always @(posedge aclk or negedge aresetn) begin
	if (!aresetn) begin
		tx_tdata <= 8'b0;
		tx_tvalid <= 1'b0;
		tx_tlast <= 1'b0;
		tx_valid_reg <= 1'b0;
		tx_last_reg <= 1'b0;
		tx_data_reg <= 4'b0;
		tx_crs <= 1'b0;
		tx_col <= 1'b0;

		rx_tready <= 1'b0;
		rx_buffer <= 8'b0;
		rx_valid_reg <= 1'b0;
		rx_last_reg <= 1'b0;
		rx_data_reg <= 4'b0;

		mii_tx_clk <= 1'b0;
		mii_rx_clk <= 1'b0;
		mii_tx_data <= 4'b0;
		mii_rx_data <= 4'b0;
		mii_crs <= 1'b0;
		mii_col <= 1'b0;

		tx_state <= IDLE;
		rx_state <= IDLE;
		tx_timer <= 8'b0;
		rx_timer <= 8'b0;
	end else begin
		case (tx_state)
			IDLE: begin
				if (tx_tvalid && tx_tready) begin
					tx_buffer <= tx_tdata;
					tx_valid_reg <= tx_tvalid;
					tx_last_reg <= tx_tlast;
					tx_data_reg <= tx_tdata[3:0];
					tx_crs <= 1'b0;
					tx_col <= 1'b0;
					tx_state <= STROBE;
				end
			end
			STROBE: begin
				mii_tx_clk <= ~mii_tx_clk;
				if (mii_tx_clk) begin
					mii_tx_data <= tx_data_reg;
					if (tx_last_reg && tx_timer == 8'd1) begin
						tx_state <= IDLE;
					end else begin
						tx_timer <= tx_timer + 1;
					end
				end
			end
			default: begin
				tx_state <= IDLE;
			end
		endcase

		case (rx_state)
			IDLE: begin
				if (mii_rx_dv) begin
					rx_buffer <= mii_rx_data;
					rx_valid_reg <= 1'b1;
					rx_last_reg <= mii_rx_dv;
					rx_data_reg <= mii_rx_data;
					rx_state <= STROBE;
				end
			end
			STROBE: begin
				mii_rx_clk <= ~mii_rx_clk;
				if (mii_rx_clk) begin
					if (rx_last_reg && rx_timer == 8'd1) begin
						rx_state <= IDLE;
					end else begin
						rx_timer <= rx_timer + 1;
					end
				end
			end
			default: begin
				rx_state <= IDLE;
			end
		endcase
	end
end

assign tx_tdata = tx_buffer;
assign tx_tvalid = tx_valid_reg;
assign tx_tlast = tx_last_reg;

assign rx_tready = 1'b1;

assign mii_tx_clk = mii_tx_clk_reg;
assign mii_rx_clk = mii_rx_clk_reg;

assign mii_tx_data = mii_tx_data_reg;
assign mii_rx_data = mii_rx_data_reg;

assign mii_crs = mii_crs_reg;
assign mii_col = mii_col_reg;

endmodule

