  wire [15:0] s6_shifted = {s6, 8'b0};
  wire [15:0] s7_shifted = {s7, 7'b0};

  wire [15:0] intermediate0 = u0_shifted + s0_shifted;
  wire [15:0] intermediate1 = u1_shifted - s1_shifted;
  wire [15:0] intermediate2 = u2_shifted & s2_shifted;
  wire [15:0] intermediate3 = u3_shifted | s3_shifted;
  wire [15:0] intermediate4 = u4_shifted ^ s4_shifted;
  wire [15:0] intermediate5 = u5_shifted << 2;
  wire [15:0] intermediate6 = u6_shifted >> 3;
  wire [15:0] intermediate7 = u7_shifted ^ s7_shifted;

  assign y = {intermediate0, intermediate1, intermediate2, intermediate3, intermediate4, intermediate5, intermediate6, intermediate7};
endmodule

