module UART_rx(
    input wire clk,
    input wire reset,
    input wire rx_data_in,
    output reg [7:0] rx_data_out
);

    parameter BAUD_RATE = 9600; // Example baud rate
    parameter CLK_FREQ = 50000000; // Example clock frequency
    parameter OVERSAMPLE = 16; // Oversampling factor

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [7:0] received_data;
    reg oversample_counter;
    reg bit_timer;
    reg [3:0] baud_counter;

    // State definitions
    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter DATA = 4'b0010;
    parameter STOP = 4'b0011;

    // Baud rate counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            baud_counter <= 4'b0000;
        end else if (baud_counter == (CLK_FREQ / (BAUD_RATE * OVERSAMPLE) - 1)) begin
            baud_counter <= 4'b0000;
        end else begin
            baud_counter <= baud_counter + 1;
        end
    end

    // Oversample counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            oversample_counter <= 1'b0;
        end else if (oversample_counter == (OVERSAMPLE - 1)) begin
            oversample_counter <= 1'b0;
        end else begin
            oversample_counter <= 1'b1;
        end
    end

    // Bit timer
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_timer <= 1'b0;
        end else if (bit_timer == (CLK_FREQ / (BAUD_RATE * OVERSAMPLE) - 1)) begin
            bit_timer <= 1'b0;
        end else begin
            bit_timer <= 1'b1;
        end
    end

    // State machine
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 4'b0000;
            received_data <= 8'b00000000;
        end else begin
            case (state)
                IDLE: begin
                    if (rx_data_in == 1'b0) begin
                        state <= START;
                        bit_count <= 4'b0000;
                        received_data <= 8'b00000000;
                    end
                end
                START: begin
                    if (oversample_counter == 1'b0) begin
                        state <= DATA;
                        bit_count <= 4'b0000;
                    end
                end
                DATA: begin
                    if (oversample_counter == 1'b0) begin
                        received_data[bit_count] <= rx_data_in;
                        bit_count <= bit_count + 1;
                        if (bit_count == 4'b1111) begin
                            state <= STOP;
                        end
                    end
                end
                STOP: begin
                    if (oversample_counter == 1'b0) begin
                        rx_data_out <= received_data;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

module serial(clk, reset, rxD, sout, signal, counter);
  parameter n = 30;
  parameter count = 4;

  input clk;      
  input reset;    
  input rxD;   

  output reg [n-1:0] sout; 
  output reg signal;   
  output reg [31:0] counter;

  reg [7:0] s_in;
  reg [1:0] delay;
  reg [31:0] counter_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      sout <= 0;
      signal <= 0;
      counter <= 0;
      counter_reg <= 0;
      s_in <= 0;
      delay <= 0;
    end else begin
      if (counter_reg < count) begin
        counter_reg <= counter_reg + 1;
        s_in <= {s_in[6:0], rxD};
      end else begin
        counter_reg <= 0;
        sout <= {s_in, {n-8{1'b0}}};
        if (delay == 0) begin
          signal <= 1;
          delay <= 1;
        end else begin
          signal <= 0;
          delay <= 0;
        end
      end
    end
  end

  assign counter = counter_reg;
endmodule

