module rx_tb;
  parameter REF_CLK_PERIOD = 10; // in ns
  parameter BAUD_PERIOD = 100; // in ns
  parameter REF_CLK_BAUD_RATIO = REF_CLK_PERIOD / BAUD_PERIOD;
  parameter NUM_SAMPLES = 10;

  reg ref_clk;
  reg reset;
  wire [7:0] par_out;
  wire Rx_valid;
  wire err_par;
  wire err_stop;

  reg [7:0] sample_data [0:NUM_SAMPLES-1];
  reg [2:0] sample_index;
  reg [2:0] bit_index;
  reg [15:0] baud_counter;
  reg [15:0] ref_clk_counter;

  // Initialize sample data
  initial begin
    for (int i = 0; i < NUM_SAMPLES; i++) begin
      sample_data[i] = i; // Example data: 0, 1, 2, ..., 9
    end
  end

  // Reference clock generation
  always #(REF_CLK_PERIOD / 2) ref_clk = ~ref_clk;

  // Baud clock generation
  always @(posedge ref_clk) begin
    if (reset) begin
      baud_counter <= 0;
    end else begin
      baud_counter <= baud_counter + 1;
      if (baud_counter == REF_CLK_BAUD_RATIO - 1) begin
        baud_counter <= 0;
      end
    end
  end

  // UART Rx testbench
  always @(posedge ref_clk) begin
    if (reset) begin
      sample_index <= 0;
      bit_index <= 0;
      ser_in <= 0;
    end else begin
      if (bit_index == 7) begin
        ser_in <= sample_data[sample_index];
        sample_index <= sample_index + 1;
        bit_index <= 0;
      end else begin
        ser_in <= ser_in << 1;
        bit_index <= bit_index + 1;
      end
    end
  end

  // UART Rx module instantiation
  UART_Rx uart_rx (
    .ser_in(ser_in),
    .reset(reset),
    .ref_clk(ref_clk),
    .par_out(par_out),
    .Rx_valid(Rx_valid),
    .err_par(err_par),
    .err_stop(err_stop)
  );

  // Testbench control
  initial begin
    reset = 1;
    #10 reset = 0;
    #1000 $finish;
  end

  // Monitor UART Rx outputs
  initial begin
    $monitor("At time %t, par_out = %h, Rx_valid = %b, err_par = %b, err_stop = %b", $time, par_out, Rx_valid, err_par, err_stop);
  end
