module NAND3C(Y,A,B,C);
  input A,B,C;
  output Y;

  wire notA, notB, andAB, nandABC;

  // Invert A and B
  not (notA, A);
  not (notB, B);

  // AND the inverted A and B
  and (andAB, notA, notB);

  // NAND the result with inverted C
  nand (nandABC, andAB, C);

  // Assign the final output
  assign Y = nandABC;
endmodule

