module ACC_v2 #(
    parameter PE_SIZE           = 14,
    parameter DATA_WIDTH        = 8,
    parameter PSUM_WIDTH        = 32,
    parameter SLICING_IDX       = 32,
    parameter WEIGHT_ROW_NUM    = 70,
    parameter WEIGHT_COL_NUM    = 294
)
(
    input   clk,
    input   rst_n,
    input   [PE_SIZE-1:0]   psum_en_row_i,              
    input   [PSUM_WIDTH*PE_SIZE-1:0]    psum_row_i,
    output  [DATA_WIDTH*PE_SIZE-1:0]    ofmap_row_o,
    output                              ofmap_valid_o   
);

    localparam FIFO_DEPTH = 16;
    localparam ACCUM_WIDTH = PSUM_WIDTH * PE_SIZE;
    localparam OFMAP_WIDTH = DATA_WIDTH * PE_SIZE;

    reg [ACCUM_WIDTH-1:0] accum_reg;
    reg [PE_SIZE-1:0] valid_reg;
    reg [PE_SIZE-1:0] valid_cnt;
    reg [PE_SIZE-1:0] psum_en_row_reg;

    wire [ACCUM_WIDTH-1:0] psum_row_reg;
    wire [PE_SIZE-1:0] psum_en_row_d;
    wire [PE_SIZE-1:0] valid_d;

    // Register psum_row_i and psum_en_row_i
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            psum_row_reg <= {PE_SIZE{0}};
            psum_en_row_reg <= {PE_SIZE{0}};
        end else begin
            psum_row_reg <= psum_row_i;
            psum_en_row_reg <= psum_en_row_i;
        end
    end

    // Accumulate partial sums
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accum_reg <= {ACCUM_WIDTH{0}};
        end else begin
            if (psum_en_row_reg != 0) begin
                accum_reg <= accum_reg + psum_row_reg;
            end
        end
    end

    // Valid signal generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_reg <= {PE_SIZE{0}};
            valid_cnt <= 0;
        end else begin
            if (psum_en_row_reg != 0) begin
                valid_reg <= valid_reg | psum_en_row_reg;
                valid_cnt <= valid_cnt + 1;
            end
        end
    end

    // Output valid signal
    assign ofmap_valid_o = (valid_cnt == PE_SIZE);

    // Output feature map row
    assign ofmap_row_o = accum_reg;

endmodule

