module ControlUnit(input[5:0] opcode,
		input[5:0] funct,
		output reg reg_dst,
		output reg reg_write,
		output reg[1:0] alu_src,
		output reg[3:0] alu_op,
		output reg branch,
		output reg mem_write,
		output reg mem_to_reg,
        	output reg zero_sign_ext,
		output reg mult_op,
		output reg mfhi,
		output reg mflo);

always @(*) begin
    // Default values for control signals
    reg_dst = 0;
    reg_write = 0;
    alu_src = 0;
    alu_op = 4'b0000; // Default ALU operation (add)
    branch = 0;
    mem_write = 0;
    mem_to_reg = 0;
    zero_sign_ext = 0;
    mult_op = 0;
    mfhi = 0;
    mflo = 0;

    case (opcode)
        6'b000000: begin // R-type instruction
            reg_dst = 1;
            reg_write = 1;
            case (funct)
                6'b100000: alu_op = 4'b0000; // add
                6'b100010: alu_op = 4'b0001; // sub
                6'b100100: alu_op = 4'b0010; // and
                6'b100101: alu_op = 4'b0011; // or
                6'b011000: mult_op = 1; // mult
                6'b011010: mult_op = 1; // div
                6'b011001: mfhi = 1; // mfhi
                6'b011011: mflo = 1; // mflo
                default: ; // do nothing
            endcase
        end
        6'b100011: begin // lw
            reg_write = 1;
            mem_to_reg = 1;
            zero_sign_ext = 1;
        end
        6'b101011: begin // sw
            mem_write = 1;
        end
        6'b000100: begin // beq
            branch = 1;
        end
        default: ; // do nothing for other opcodes
    endcase
end

endmodule

module BranchLogic (zf, cf, nf, sel, branch, branch_out, flag_reg);
