        case (sel)
            2'b00: flag = zf;
            2'b01: flag = cf;
            2'b10: flag = nf;
            default: flag = 3'b000; // Default case should not happen
        endcase
    end

    // Compute the branch_out based on the flag and branch input
    assign branch_out = branch && flag;

    // Update the flag_reg based on the selected condition
    assign flag_reg = flag;
endmodule

