module chose(output reg [17:0]choout,
				input [16:0]choin,
				input resreg,
				input clk);
reg [16:0] chotmp;

always @(posedge clk) begin
    if (resreg == 0) begin
        // Directly assign choin to choout, duplicating the 16th bit
        choout[17:0] <= {choin[16], choin};
    end else begin
        // Invert the lower 16 bits of choin
        chotmp <= ~choin;
        // Add 1 to perform two's complement
        chotmp <= chotmp + 1;
        // Assign the result to the lower 16 bits of choout
        choout[15:0] <= chotmp;
        // Set the upper two bits of choout to the inverse of choin's 16th bit
        choout[17:16] <= ~choin[16];
    end
end

endmodule

