module ALU_Control(
    input wire [5:0] OP_5to0,
    input wire [1:0] ALU_op,
    output wire [3:0] Operation
);

    // Intermediate signals
    wire s1, s2;

    // Decode OP_5to0 and ALU_op to generate s1 and s2
    assign s1 = OP_5to0[5] & OP_5to0[3];
    assign s2 = OP_5to0[4] & OP_5to0[2];

    // Generate the Operation control signal based on s1, s2, and ALU_op
    assign Operation = (s1 & s2 & ALU_op[1]) ? 4'b1000 : // Addition with carry-in
                       (s1 & ~s2 & ALU_op[1]) ? 4'b1001 : // Addition without carry-in
                       (~s1 & s2 & ALU_op[1]) ? 4'b1010 : // Subtraction with borrow-in
                       (~s1 & ~s2 & ALU_op[1]) ? 4'b1011 : // Subtraction without borrow-in
                       (s1 & s2 & ~ALU_op[1]) ? 4'b1100 : // Logical AND
                       (s1 & ~s2 & ~ALU_op[1]) ? 4'b1101 : // Logical OR
                       (~s1 & s2 & ~ALU_op[1]) ? 4'b1110 : // Logical XOR
                       (~s1 & ~s2 & ~ALU_op[1]) ? 4'b1111 : // Logical NOT
                       4'b0000; // Default case

endmodule

module alu_control (alu_op, func, alu_ctrl);
    input [2:0] alu_op;
    input [2:0] func;
    output [2:0] alu_ctrl;

    wire [2:0] alu_op_not = ~alu_op;
    wire [2:0] func_not = ~func;

    wire and1 = alu_op[2] & func[2];
    wire and2 = alu_op[1] & func[1];
    wire and3 = alu_op[0] & func[0];
    wire and4 = alu_op_not[2] & func_not[2];
    wire and5 = alu_op_not[1] & func_not[1];
    wire and6 = alu_op_not[0] & func_not[0];
    wire and7 = alu_op[2] & func_not[2];
    wire and8 = alu_op_not[2] & func[2];
    wire and9 = alu_op[1] & func_not[1];
    wire and10 = alu_op_not[1] & func[1];
    wire and11 = alu_op[0] & func_not[0];
    wire and12 = alu_op_not[0] & func[0];

    wire or1 = and1 | and2 | and3;
    wire or2 = and4 | and5 | and6;
    wire or3 = and7 | and8 | and9;
    wire or4 = and10 | and11 | and12;

    assign alu_ctrl[2] = or1;
    assign alu_ctrl[1] = or2;
    assign alu_ctrl[0] = or3 | or4;
endmodule

