module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);

always @(*) begin
    reg [3:0] digits[3:0];
    reg [3:0] carry;
    integer i;

    // Initialize digits and carry
    for (i = 0; i < 4; i = i + 1) begin
        digits[i] = 0;
    end
    carry = 0;

    // Process each bit of the input
    for (i = 0; i < INPUT_BIT_WIDTH; i = i + 1) begin
        // Add carry to the least significant digit
        digits[0] = digits[0] + carry + (Input[i] ? 1 : 0);

        // Adjust digits if any digit is greater than or equal to 10
        for (integer j = 0; j < 4; j = j + 1) begin
            if (digits[j] >= 10) begin
                digits[j] = digits[j] - 10;
                carry = 1;
            end else begin
                carry = 0;
            end
        end

        // Shift digits left and set the least significant bit of each higher digit
        for (integer j = 3; j > 0; j = j - 1) begin
            digits[j] = {digits[j-1][3], digits[j][3:1]};
        end

        // Place the current input bit in the least significant bit of the lowest digit
        digits[0] = {digits[0][2:0], Input[i]};
    end

    // Assign the final BCD digits to the outputs
    Digit3 = digits[3];
    Digit2 = digits[2];
    Digit1 = digits[1];
    Digit0 = digits[0];
end

endmodule

