    output        GAIN,
    output        LDAC,
    output        CLR,
    output        PD,
    output        A0,
    output        A1
);

    // State definitions
    typedef enum reg [2:0] {
        IDLE,
        INIT,
        PREPARE_DATA,
        WRITE_DATA,
        UPDATE_DAC,
        DONE
    } state_t;

    state_t state, next_state;

    // Registers for data storage
    reg [7:0] data_reg [0:3];
    reg [1:0] channel_reg;

    // Control signals
    reg [1:0] channel_counter;
    reg [1:0] num_of_channels_reg;

    // Internal signals
    reg [7:0] data_out;
    reg [1:0] gain_out;
    reg ldac_out;
    reg clr_out;
    reg pd_out;
    reg [1:0] a_out;

    // State transition logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE:
                if (start) begin
                    next_state = INIT;
                end
            INIT:
                next_state = PREPARE_DATA;
            PREPARE_DATA:
                next_state = WRITE_DATA;
            WRITE_DATA:
                next_state = UPDATE_DAC;
            UPDATE_DAC:
                next_state = DONE;
            DONE:
                if (start) begin
                    next_state = INIT;
                end
        endcase
    end

    // Data preparation logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            data_reg[0] <= 8'b0;
            data_reg[1] <= 8'b0;
            data_reg[2] <= 8'b0;
            data_reg[3] <= 8'b0;
            channel_reg <= 2'b00;
        end else begin
            case (state)
                PREPARE_DATA:
                    case (channel_reg)
                        2'b00: data_reg[0] <= ch0;
                        2'b01: data_reg[1] <= ch1;
                        2'b10: data_reg[2] <= ch2;
                        2'b11: data_reg[3] <= ch3;
                    endcase
                    channel_reg <= channel_reg + 1;
                    if (channel_reg == num_of_channels_reg) begin
                        channel_reg <= 2'b00;
                    end
            endcase
        end
    end

    // Output logic
    always @(*) begin
        case (state)
            IDLE:
                ready = 1'b0;
                CS = 1'b1;
                WR = 1'b0;
                DATA = 8'b0;
                GAIN = 2'b00;
                LDAC = 1'b0;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = 1'b0;
                A1 = 1'b0;
            INIT:
                ready = 1'b0;
                CS = 1'b0;
                WR = 1'b0;
                DATA = 8'b0;
                GAIN = 2'b00;
                LDAC = 1'b0;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = 1'b0;
                A1 = 1'b0;
            PREPARE_DATA:
                ready = 1'b0;
                CS = 1'b0;
                WR = 1'b0;
                DATA = 8'b0;
                GAIN = 2'b00;
                LDAC = 1'b0;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = 1'b0;
                A1 = 1'b0;
            WRITE_DATA:
                ready = 1'b0;
                CS = 1'b0;
                WR = 1'b1;
                DATA = data_reg[channel_counter];
                GAIN = 2'b00;
                LDAC = 1'b0;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = channel_counter[0];
                A1 = channel_counter[1];
            UPDATE_DAC:
                ready = 1'b0;
                CS = 1'b0;
                WR = 1'b0;
                DATA = 8'b0;
                GAIN = 2'b00;
                LDAC = 1'b1;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = 1'b0;
                A1 = 1'b0;
            DONE:
                ready = 1'b1;
                CS = 1'b1;
                WR = 1'b0;
                DATA = 8'b0;
                GAIN = 2'b00;
                LDAC = 1'b0;
                CLR = 1'b0;
                PD = 1'b0;
                A0 = 1'b0;
                A1 = 1'b0;
        endcase
    end

    // Power management logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            pd_out <= 1'b0;
        end else begin
            pd_out <= pwr;
        end
    end

    // Clear logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            clr_out <= 1'b0;
        end else begin
            clr_out <= clear;
        end
    end

    // Number of channels logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            num_of_channels_reg <= 2'b00;
        end else begin
            num_of_channels_reg <= num_of_channels;
        end
    end

    // Channel counter logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            channel_counter <= 2'b00;
        end else begin
            case (state)
                WRITE_DATA:
                    channel_counter <= channel_counter + 1;
                    if (channel_counter == num_of_channels_reg) begin
                        channel_counter <= 2'b00;
                    end
            endcase
        end
    end

    // Assign outputs
    assign CS = 1'b0;
    assign WR = data_out[7];
    assign DATA = data_out[6:0];
    assign GAIN = gain_out;
    assign LDAC = ldac_out;
    assign CLR = clr_out;
    assign PD = pd_out;
    assign A0 = a_out[0];
    assign A1 = a_out[1];

endmodule

