  reg [15:0] rdDataReg;    // Register to hold read data
  reg [9:0]  wrAddrReg;    // Register to hold write address
  reg [15:0] wrDataReg;    // Register to hold write data

  // Assign read data output
  assign io_rdData = rdDataReg;

  // Always block for sequential write operations
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      // Reset memory and registers
      mem <= '{default: 16'b0};
      rdDataReg <= 16'b0;
      wrAddrReg <= 10'b0;
      wrDataReg <= 16'b0;
    end else begin
      if (io_wrEna) begin
        // Write operation
        mem[io_Addr] <= io_dataIn;
        wrAddrReg <= io_Addr;
        wrDataReg <= io_dataIn;
      end else begin
        // Read operation
        rdDataReg <= mem[io_Addr];
      end
    end
  end
endmodule

