module NBCD_exces_3(N, VCC, GND, Cout, Y, egal, mare);
input [3:0] N;
input VCC;
input GND;
output Cout;
output [3:0] Y;
output egal;
output mare;

// Internal signals
wire [3:0] S;
wire [3:0] mic;

// Comparator4 module to compare N with 0x05 (binary 0101)
assign mic = N ^ 4'b0101;

// Sum4 module to compute the carry-out signal
assign S = N + 4'b0101;

// Decoding logic using AND gates
assign Y[0] = (S[0] & mic[0]) | (S[1] & mic[1]) | (S[2] & mic[2]) | (S[3] & mic[3]);
assign Y[1] = (S[1] & mic[1]) | (S[2] & mic[2]) | (S[3] & mic[3]);
assign Y[2] = (S[2] & mic[2]) | (S[3] & mic[3]);
assign Y[3] = (S[3] & mic[3]);

// Carry-out signal Cout
assign Cout = S[4];

// Equality flag egal
assign egal = (N == 4'b0101);

// Greater-than flag mare
assign mare = (N > 4'b0101);

endmodule

