module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);

   reg [counterSize-1:0] counts[numOfCounters-1:0];
   reg [counterSize-1:0] terminalCounts[numOfCounters-1:0];
   reg [counterSize-1:0] enable[numOfCounters-1:0];

   // Initialize all counters and enable signals
   initial begin
      for (integer i = 0; i < numOfCounters; i = i + 1) begin
         counts[i] <= 0;
         terminalCounts[i] <= 0;
         enable[i] <= 0;
      end
   end

   // Generate loop to instantiate and connect counters
   generate
      for (integer i = 0; i < numOfCounters; i = i + 1) begin : counter_chain
         always @(posedge clk or posedge reset) begin
            if (reset) begin
               counts[i] <= 0;
               terminalCounts[i] <= 0;
            end else begin
               if (i == 0) begin
                  // First counter is always enabled
                  enable[i] <= 1;
               end else begin
                  // Subsequent counters are enabled by the previous counter's terminal count
                  enable[i] <= terminalCounts[i-1];
               end
               if (enable[i]) begin
                  counts[i] <= counts[i] + 1;
                  if (counts[i] == (1 << counterSize) - 1) begin
                     terminalCounts[i] <= 1;
                  end else begin
                     terminalCounts[i] <= 0;
                  end
               end
            end
         end
      end
   endgenerate

   // Output the count value of the last counter
   assign outCount = counts[numOfCounters-1];

endmodule

