  wire mem_done;
  wire [3:0] mem_addr;
  wire [7:0] mem_write_data;
  wire mem_write_enable;

  // Instantiate the memory module
  memory mem_inst (
    .clk(clk),
    .reset(reset),
    .addr(addr),
    .data_in(data_in),
    .MemRead(MemRead),
    .MemWrite(MemWrite),
    .data_out(data_out),
    .mem_done(mem_done),
    .mem_addr(mem_addr),
    .mem_write_data(mem_write_data),
    .mem_write_enable(mem_write_enable)
  );

  // Instantiate the ram module
  ram ram_inst (
    .clk(clk),
    .addr(mem_addr),
    .data_in(mem_write_data),
    .write_enable(mem_write_enable),
    .data_out(ram_data_out)
  );

  // Internal signal for ram data output
  wire [7:0] ram_data_out;

  // Clock generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Test sequence
  initial begin
    // Reset the system
    reset = 1;
    #10 reset = 0;

    // Store operation
    MemWrite = 1;
    MemRead = 0;
    addr = 4'b0000;
    data_in = 8'b10101010;
    #10;
    MemWrite = 0;
    #10;
    if (mem_done && data_out == data_in) begin
      $display("Store operation successful");
    end else begin
      $display("Store operation failed");
    end

    // Load operation
    MemWrite = 0;
    MemRead = 1;
    addr = 4'b0000;
    #10;
    MemRead = 0;
    #10;
    if (mem_done && data_out == data_in) begin
      $display("Load operation successful");
    end else begin
      $display("Load operation failed");
    end

    // Reset test
    reset = 1;
    #10 reset = 0;
    if (!mem_done) begin
      $display("Reset test successful");
    end else begin
      $display("Reset test failed");
    end

    $finish;
  end
