    input wire clk,
    input wire rst,
    output reg active,
    output reg hsync,
    output reg vsync,
    output wire [9:0] xaddr,
    output wire [9:0] yaddr
);

    // Parameters for VGA display
    parameter H_ACTIVE = 640;  // Horizontal active pixels
    parameter H_FRONT = 16;   // Horizontal front porch
    parameter H_SYNC = 96;    // Horizontal sync pulse width
    parameter H_BACK = 48;    // Horizontal back porch
    parameter H_TOTAL = 800;  // Total horizontal pixels

    parameter V_ACTIVE = 480;  // Vertical active lines
    parameter V_FRONT = 10;   // Vertical front porch
    parameter V_SYNC = 2;     // Vertical sync pulse width
    parameter V_BACK = 33;    // Vertical back porch
    parameter V_TOTAL = 525;  // Total vertical lines

    reg [9:0] h_count_reg;
    reg [9:0] v_count_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            h_count_reg <= 0;
            v_count_reg <= 0;
        end else begin
            if (h_count_reg == H_TOTAL - 1) begin
                h_count_reg <= 0;
                if (v_count_reg == V_TOTAL - 1) begin
                    v_count_reg <= 0;
                end else begin
                    v_count_reg <= v_count_reg + 1;
                end
            end else begin
                h_count_reg <= h_count_reg + 1;
            end
        end
    end

    assign xaddr = h_count_reg;
    assign yaddr = v_count_reg;

    assign hsync = (h_count_reg >= H_ACTIVE + H_FRONT) && (h_count_reg < H_ACTIVE + H_FRONT + H_SYNC);
    assign vsync = (v_count_reg >= V_ACTIVE + V_FRONT) && (v_count_reg < V_ACTIVE + V_FRONT + V_SYNC);

    assign active = (h_count_reg < H_ACTIVE) && (v_count_reg < V_ACTIVE);

endmodule

