module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );

  reg [WIDTH-1:0] lfsr_reg;

  always @(posedge clk_i or posedge rst_i) begin
    if (rst_i) begin
      lfsr_reg <= SEED;
    end else if (next_i) begin
      reg feedback_bit;
      feedback_bit = 1'b0;
      for (int i = 0; i < WIDTH; i = i + 1) begin
        if (TAPS[i] == 1'b1) begin
          feedback_bit = feedback_bit ^ lfsr_reg[i];
        end
      end
      lfsr_reg <= {feedback_bit, lfsr_reg[WIDTH-1:1]};
    end
  end

  assign output_o = lfsr_reg;

endmodule

