module TopModule (
    input [3:0] x,
    input [3:0] y,
    output reg [4:0] sum
);

    // Full adder components
    wire carry_out;
    wire [3:0] adder_out;

    // Full adder for the least significant bit
    full_adder fa0 (
        .a(x[0]),
        .b(y[0]),
        .cin(1'b0),
        .sum(adder_out[0]),
        .cout(carry_out)
    );

    // Full adder for the second least significant bit
    full_adder fa1 (
        .a(x[1]),
        .b(y[1]),
        .cin(carry_out),
        .sum(adder_out[1]),
        .cout(carry_out)
    );

    // Full adder for the third least significant bit
    full_adder fa2 (
        .a(x[2]),
        .b(y[2]),
        .cin(carry_out),
        .sum(adder_out[2]),
        .cout(carry_out)
    );

    // Full adder for the most significant bit
    full_adder fa3 (
        .a(x[3]),
        .b(y[3]),
        .cin(carry_out),
        .sum(adder_out[3]),
        .cout(carry_out)
    );

    // Assign the final sum and carry out
    assign sum = {carry_out, adder_out};

endmodule

