            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena_reg <= 3'b000;
        end else begin
            if (ones == 4'b1001) begin
                ones <= 4'b0000;
                if (tens == 4'b1001) begin
                    tens <= 4'b0000;
                    if (hundreds == 4'b1001) begin
                        hundreds <= 4'b0000;
                        thousands <= thousands + 1;
                    end else begin
                        hundreds <= hundreds + 1;
                    end
                end else begin
                    tens <= tens + 1;
                end
            end else begin
                ones <= ones + 1;
            end
            ena_reg <= (ones == 4'b1001) ? 3'b100 : (tens == 4'b1001) ? 3'b010 : (hundreds == 4'b1001) ? 3'b001 : 3'b000;
        end
    end

    assign ena = ena_reg;
    assign q = {thousands, hundreds, tens, ones};

endmodule

