    reg aircon_reg;
    reg fan_reg;

    // Logic to control the heater, air conditioner, and fan
    always @(*) begin
        heater_reg = 0;
        aircon_reg = 0;
        fan_reg = 0;

        if (mode == 1) begin // Heating mode
            if (too_cold) begin
                heater_reg = 1;
                fan_reg = 1;
            end
        end else if (mode == 0) begin // Cooling mode
            if (too_hot) begin
                aircon_reg = 1;
