    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            q <= 16'b0;
            for (integer i = 0; i < 16; i = i + 1) begin
                dffs[i] <= 1'b0;
            end
        end else begin
            if (byteena[1]) begin
                dffs[15:8] <= d[15:8];
            end
            if (byteena[0]) begin
                dffs[7:0] <= d[7:0];
            end
            q <= {dffs[15], dffs[14], dffs[13], dffs[12], dffs[11], dffs[10], dffs[9], dffs[8], dffs[7], dffs[6], dffs[5], dffs[4], dffs[3], dffs[2], dffs[1], dffs[0]};
