module TopModule (
    input  clk,
    input  x,
    output z
);

    reg dff1, dff2, dff3;
    wire xor_out, and_out, or_out, nor_out;

    // XOR gate
    assign xor_out = x ^ dff1;

    // AND gate
    assign and_out = x & ~dff2;

    // OR gate
    assign or_out = x | ~dff3;

    // D flip-flops
    always @(posedge clk) begin
        dff1 <= xor_out;
        dff2 <= and_out;
        dff3 <= or_out;
    end

    // NOR gate
    assign nor_out = ~(dff1 | dff2 | dff3);

    // Output
    assign z = nor_out;

endmodule

