module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // Define one-hot encoded states
    localparam [1:0] STATE_A = 2'b001;
    localparam [1:0] STATE_B = 2'b010;

    // State register
    reg [1:0] state;

    // Output register
    reg z_reg;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= STATE_A; // Reset to state A
            z_reg <= 0;      // Reset output to 0
        end else begin
            case (state)
                STATE_A: begin
                    if (x) begin
                        state <= STATE_B;
                        z_reg <= 1;
                    end else begin
                        state <= STATE_A;
                        z_reg <= 0;
                    end
                end
                STATE_B: begin
                    if (x) begin
                        state <= STATE_B;
                        z_reg <= 0;
                    end else begin
                        state <= STATE_B;
                        z_reg <= 1;
                    end
                end
                default: begin
                    state <= STATE_A; // Default to state A
                    z_reg <= 0;      // Default output to 0
                end
            endcase
        end
    end

    // Output assignment
    assign z = z_reg;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // Internal state to store the current bit of the input
    reg current_bit;
    // Internal state to store the sign bit
    reg sign_bit;
    // Internal state to store the output bit
    reg output_bit;
    // Internal state to track if the conversion is in progress
    reg conversion_in_progress;

    // Moore state machine states
    localparam IDLE = 2'b00;
    localparam RECEIVE_BIT = 2'b01;
    localparam COMPLEMENT = 2'b10;
    localparam OUTPUT_BIT = 2'b11;

    // Current state of the Moore state machine
    reg [1:0] state;

    // Next state of the Moore state machine
    reg [1:0] next_state;

    // Assign the output bit to the z port
    assign z = output_bit;

    // Moore state machine logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= IDLE;
            current_bit <= 1'b0;
            sign_bit <= 1'b0;
            output_bit <= 1'b0;
            conversion_in_progress <= 1'b0;
        end else begin
            state <= next_state;
            current_bit <= x;
            if (conversion_in_progress) begin
                case (state)
                    RECEIVE_BIT: begin
                        if (current_bit) begin
                            sign_bit <= 1'b1;
                        end
                    end
                    COMPLEMENT: begin
                        output_bit <= ~current_bit;
                    end
                    OUTPUT_BIT: begin
                        // Output bit is already set in the COMPLEMENT state
                    end
                endcase
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (!areset) begin
                    next_state = RECEIVE_BIT;
                    conversion_in_progress = 1'b1;
                end
            end
            RECEIVE_BIT: begin
                if (conversion_in_progress) begin
                    next_state = COMPLEMENT;
                end
            end
            COMPLEMENT: begin
                if (conversion_in_progress) begin
                    next_state = OUTPUT_BIT;
                end
            end
            OUTPUT_BIT: begin
                if (conversion_in_progress) begin
                    next_state = RECEIVE_BIT;
                end
            end
        endcase
    end

endmodule

