    assign out_both[99] = 0;
    generate
        for (genvar i = 0; i < 99; i = i + 1) begin : out_both_loop
            assign out_both[i] = in[i] & in[i + 1];
        end
    endgenerate

    // Calculate out_any
    assign out_any[0] = 0;
    generate
        for (genvar i = 1; i < 100; i = i + 1) begin : out_any_loop
            assign out_any[i] = in[i] | in[i - 1];
        end
    endgenerate

    // Calculate out_different
    assign out_different[99] = in[99] ^ in[0];
    generate
        for (genvar i = 0; i < 99; i = i + 1) begin : out_different_loop
            assign out_different[i] = in[i] ^ in[i + 1];
