module TopModule (
    input c,
    input d,
    output reg [3:0] mux_in
);

    // Internal signals for 2-to-1 multiplexers
    reg [1:0] mux_out_2to1_1;
    reg [1:0] mux_out_2to1_2;
    reg [1:0] mux_out_2to1_3;

    // 2-to-1 multiplexers
    always @(*) begin
        mux_out_2to1_1 = (c == 1'b0) ? 2'b00 : 2'b11;
        mux_out_2to1_2 = (c == 1'b0) ? 2'b01 : 2'b10;
        mux_out_2to1_3 = (c == 1'b1) ? 2'b11 : 2'b01;
    end

    // 4-to-1 multiplexer
    always @(*) begin
        case ({c, d})
            2'b00: mux_in = {mux_out_2to1_1, 2'b00};
            2'b01: mux_in = {mux_out_2to1_2, 2'b00};
            2'b11: mux_in = {mux_out_2to1_3, 2'b11};
            2'b10: mux_in = {mux_out_2to1_1, 2'b01};
            default: mux_in = 4'b0000;
        endcase
    end

endmodule

module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // Calculate out_both
    assign out_both[0] = 1'b0; // No left neighbour for in[0]
    assign out_both[1] = in[0] & in[1];
    assign out_both[2] = in[1] & in[2];
    assign out_both[3] = in[2] & in[3];

    // Calculate out_any
    assign out_any[0] = in[0] | in[1]; // No right neighbour for in[0]
    assign out_any[1] = in[1] | in[2];
    assign out_any[2] = in[2] | in[3];
    assign out_any[3] = in[3] | in[0];

    // Calculate out_different
    assign out_different[0] = in[0] ^ in[3]; // Wrap around for in[0]
    assign out_different[1] = in[1] ^ in[0];
    assign out_different[2] = in[2] ^ in[1];
    assign out_different[3] = in[3] ^ in[2];

endmodule

module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    // Internal state variables
    reg [1:0] state;
    reg [1:0] count;

    // State definitions
    parameter IDLE = 2'b00;
    parameter ENABLE = 2'b01;
    parameter COUNT = 2'b10;
    parameter DONE = 2'b11;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            count <= 2'b00;
            shift_ena <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    if (shift_ena) begin
                        state <= ENABLE;
                        count <= 2'b00;
                    end
                end
                ENABLE: begin
                    state <= COUNT;
                    count <= 2'b01;
                end
                COUNT: begin
                    if (count < 2'b11) begin
                        state <= COUNT;
                        count <= count + 1;
                    end else begin
                        state <= DONE;
                        shift_ena <= 1'b0;
                    end
                end
                DONE: begin
                    state <= DONE;
                    shift_ena <= 1'b0;
                end
                default: begin
                    state <= IDLE;
                    shift_ena <= 1'b1;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam SEARCH_1 = 2'b01;
    localparam SEARCH_2 = 2'b10;
    localparam SEARCH_3 = 2'b11;

    // State register
    reg [1:0] state;

    // Intermediate signals
    reg [1:0] shift_reg;

    // Output register
    reg start_shifting_reg;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            shift_reg <= 2'b00;
            start_shifting_reg <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data == 1'b1) begin
                        state <= SEARCH_1;
                        shift_reg <= 2'b01;
                    end else begin
                        state <= IDLE;
                        shift_reg <= 2'b00;
                    end
                end
                SEARCH_1: begin
                    if (data == 1'b1) begin
                        state <= SEARCH_2;
                        shift_reg <= 2'b11;
                    end else begin
                        state <= IDLE;
                        shift_reg <= 2'b00;
                    end
                end
                SEARCH_2: begin
                    if (data == 1'b0) begin
                        state <= SEARCH_3;
                        shift_reg <= 2'b10;
                    end else begin
                        state <= IDLE;
                        shift_reg <= 2'b00;
                    end
                end
                SEARCH_3: begin
                    if (data == 1'b1) begin
                        state <= SEARCH_1;
                        shift_reg <= 2'b11;
                        start_shifting_reg <= 1'b1;
                    end else begin
                        state <= IDLE;
                        shift_reg <= 2'b00;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Output logic
    assign start_shifting = start_shifting_reg;

endmodule

