module TopModule (
    input  [5:0] y,
    input  w,
    output Y1,
    output Y3
);

    // State encoding
    parameter A = 6'b000001,
               B = 6'b000010,
               C = 6'b000100,
               D = 6'b001000,
               E = 6'b010000,
               F = 6'b100000;

    // Current state
    reg [5:0] current_state;

    // Next state
    reg [5:0] next_state;

    // Output signals
    assign Y1 = (current_state == A || current_state == B || current_state == C || current_state == D);
    assign Y3 = (current_state == A || current_state == C || current_state == E || current_state == F);

    // State transition logic
    always @(*) begin
        case (current_state)
            A: begin
                if (w == 1'b0) next_state = B;
                else next_state = A;
            end
            B: begin
                if (w == 1'b0) next_state = C;
                else next_state = D;
            end
            C: begin
                if (w == 1'b0) next_state = E;
                else next_state = D;
            end
            D: begin
                if (w == 1'b0) next_state = F;
                else next_state = A;
            end
            E: begin
                if (w == 1'b0) next_state = E;
                else next_state = D;
            end
            F: begin
                if (w == 1'b0) next_state = C;
                else next_state = D;
            end
            default: next_state = A; // Reset to state A
        endcase
    end

    // State register
    always @(posedge w) begin
        current_state <= next_state;
    end

endmodule

module TopModule (
    input  in,
    input  [1:0] state,
    output [1:0] next_state,
    output out
);

always_comb begin
    case (state)
        2'b00: begin // State A
            next_state = (in == 1'b0) ? 2'b00 : 2'b01;
