module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // Define states
    typedef enum reg [2:0] {
        IDLE,
        START_BIT,
        DATA_BITS,
        STOP_BIT
    } state_t;

    state_t state, next_state;
    reg [7:0] data;
    reg [2:0] bit_count;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data <= 8'b0;
            bit_count <= 3'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in == 1'b0) begin
                    next_state = START_BIT;
                end
            end
            START_BIT: begin
                if (bit_count == 3'b0) begin
                    next_state = DATA_BITS;
                end
            end
            DATA_BITS: begin
                if (bit_count == 3'b1000) begin
                    next_state = STOP_BIT;
                end
            end
            STOP_BIT: begin
                if (in == 1'b1) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Data capture logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data <= 8'b0;
        end else begin
            if (state == DATA_BITS) begin
                data <= {data[6:0], in};
            end
        end
    end

    // Bit count logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 3'b0;
        end else begin
            if (state == START_BIT && bit_count == 3'b0) begin
                bit_count <= 3'b1;
            end else if (state == DATA_BITS) begin
                bit_count <= bit_count + 1;
            end else if (state == STOP_BIT) begin
                bit_count <= 3'b0;
            end
        end
    end

    // Done signal
    assign done = (state == IDLE && in == 1'b1);

endmodule

