    if (reset) begin
        current_state <= STATE_A;
    end else begin
        current_state <= next_state;
    end
end

// State table
always @(*) begin
    case (current_state)
        STATE_A: begin
            if (w) next_state = STATE_B;
            else next_state = STATE_A;
        end
        STATE_B: begin
            if (w) next_state = STATE_C;
