module TopModule (
    input  clk,
    input  reset,
    input  in,
    output disc,
    output flag,
    output err
);

    // State definitions
    typedef enum reg [2:0] {
        IDLE,
        ONE,
        TWO,
        THREE,
        FOUR,
        FIVE,
        SIX,
        SEVEN,
        EIGHT
    } state_t;

    state_t state, next_state;

    // Internal signals
    reg [2:0] count_ones;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        disc = 0;
        flag = 0;
        err = 0;
        count_ones = 0;

        case (state)
            IDLE: begin
                if (in == 1'b0) begin
                    next_state = ONE;
                end
            end
            ONE: begin
                if (in == 1'b1) begin
                    count_ones = 1;
                    next_state = TWO;
                end else begin
                    next_state = IDLE;
                end
            end
            TWO: begin
                if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = THREE;
                end else begin
                    next_state = IDLE;
                end
            end
            THREE: begin
                if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = FOUR;
                end else begin
                    next_state = IDLE;
                end
            end
            FOUR: begin
                if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = FIVE;
                end else begin
                    next_state = IDLE;
                end
            end
            FIVE: begin
                if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = SIX;
                end else begin
                    next_state = IDLE;
                end
            end
            SIX: begin
                if (in == 1'b0) begin
                    disc = 1;
                    next_state = IDLE;
                end else if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = SEVEN;
                end
            end
            SEVEN: begin
                if (in == 1'b0) begin
                    flag = 1;
                    next_state = IDLE;
                end else if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = EIGHT;
                end
            end
            EIGHT: begin
                if (in == 1'b0) begin
                    err = 1;
                    next_state = IDLE;
                end else if (in == 1'b1) begin
                    count_ones = count_ones + 1;
                    next_state = EIGHT;
                end
            end
        endcase

        if (count_ones >= 7) begin
            err = 1;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  ena,
    output pm,
    output [7:0] hh,
    output [7:0] mm,
    output [7:0] ss
);

    // Internal registers for hours, minutes, and seconds
    reg [5:0] hours;
    reg [5:0] minutes;
    reg [5:0] seconds;

    // Internal register for AM/PM indicator
    reg pm_reg;

    // BCD to 7-segment decoder for hours, minutes, and seconds
    reg [3:0] bcd_to_7seg_hh;
    reg [3:0] bcd_to_7seg_mm;
    reg [3:0] bcd_to_7seg_ss;

    // BCD to 7-segment decoder for AM/PM indicator
    reg [1:0] bcd_to_7seg_pm;

    // BCD to 7-segment decoder for hours, minutes, and seconds
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            hours <= 6'b000000; // 12 in BCD
            minutes <= 6'b000000; // 00 in BCD
            seconds <= 6'b000000; // 00 in BCD
            pm_reg <= 1'b0; // AM
        end else if (ena) begin
            if (seconds == 6'b111111) begin // 59 in BCD
                seconds <= 6'b000000; // 00 in BCD
                if (minutes == 6'b110111) begin // 59 in BCD
                    minutes <= 6'b000000; // 00 in BCD
                    if (hours == 6'b010011) begin // 12 in BCD
                        hours <= 6'b000001; // 1 in BCD
                        pm_reg <= ~pm_reg; // Toggle AM/PM
                    end else begin
                        hours <= hours + 1; // Increment hours
                    end
                end else begin
                    minutes <= minutes + 1; // Increment minutes
                end
            end else begin
                seconds <= seconds + 1; // Increment seconds
            end
        end
    end

    // BCD to 7-segment decoder for hours, minutes, and seconds
    assign bcd_to_7seg_hh = hours[5:2];
    assign bcd_to_7seg_mm = minutes[5:2];
    assign bcd_to_7seg_ss = seconds[5:2];

    // BCD to 7-segment decoder for AM/PM indicator
    assign bcd_to_7seg_pm = pm_reg ? 2'b00 : 2'b01;

    // Assign outputs
    assign hh = bcd_to_7seg_hh;
    assign mm = bcd_to_7seg_mm;
    assign ss = bcd_to_7seg_ss;
    assign pm = bcd_to_7seg_pm;

endmodule

module TopModule (
