    typedef enum logic [1:0] {
        WALK_LEFT,
        WALK_RIGHT
    } state_t;

    // State and next state signals
    state_t state, next_state;

    // Output signals
    assign walk_left = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah = ~ground;

    // State transition logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            WALK_LEFT: begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                end
            end
            WALK_RIGHT: begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                end
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    reg [255:0] next_q;

    // Function to calculate the number of live neighbors for a given cell
    function [3:0] count_live_neighbors;
        input [255:0] grid;
        input [4:0] row, col;
        begin
            count_live_neighbors = 0;
            for (int i = -1; i <= 1; i++) begin
                for (int j = -1; j <= 1; j++) begin
                    if (i == 0 && j == 0) continue;
                    int neighbor_row = (row + i + 16) % 16;
                    int neighbor_col = (col + j + 16) % 16;
                    count_live_neighbors += grid[(neighbor_row * 16) + neighbor_col];
                end
            end
        end
    endfunction

    // Always block to update the grid on the positive edge of the clock
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (int i = 0; i < 16; i++) begin
                for (int j = 0; j < 16; j++) begin
                    int cell_index = (i * 16) + j;
                    int live_neighbors = count_live_neighbors(q, i, j);
                    if (q[cell_index] == 1) begin
                        if (live_neighbors == 2 || live_neighbors == 3) begin
                            next_q[cell_index] = 1;
                        end else begin
                            next_q[cell_index] = 0;
                        end
                    end else begin
                        if (live_neighbors == 3) begin
                            next_q[cell_index] = 1;
                        end else begin
                            next_q[cell_index] = 0;
                        end
                    end
                end
            end
            q <= next_q;
        end
    end

endmodule

