module TopModule (
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);

    // State definitions
    typedef enum reg [1:0] {
        IDLE,
        START_BIT,
        DATA_BITS,
        STOP_BIT
    } state_t;

    state_t state, next_state;
    reg [7:0] received_byte;
    reg [2:0] bit_count;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            out_byte <= 8'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in == 1'b0) begin
                    next_state = START_BIT;
                end
            end
            START_BIT: begin
                if (bit_count == 0) begin
                    next_state = DATA_BITS;
                    bit_count <= 3'b100; // 8 bits
                end
            end
            DATA_BITS: begin
                if (bit_count > 0) begin
                    received_byte[bit_count - 1] <= in;
                    bit_count <= bit_count - 1;
                end else begin
                    next_state = STOP_BIT;
                end
            end
            STOP_BIT: begin
                if (in == 1'b1) begin
                    out_byte <= received_byte;
                    done <= 1'b1;
                    next_state = IDLE;
                end
            end
        endcase
    end

endmodule

