    localparam A = 3'b000,
               B = 3'b001,
               C = 3'b010,
               D = 3'b011;

    // State register
    reg [1:0] state;

    // Next state logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= A;
        end else begin
            case (state)
                A: begin
                    if (r == 3'b000) begin
                        state <= A;
                    end else if (r[0] == 1'b1) begin
                        state <= B;
                    end else if (r[1] == 1'b1) begin
                        state <= C;
                    end else if (r[2] == 1'b1) begin
                        state <= D;
                    end
                end
                B: begin
                    if (r[0] == 1'b1) begin
                        state <= B;
                    end else begin
                        state <= A;
                    end
                end
                C: begin
                    if (r[1] == 1'b1) begin
                        state <= C;
                    end else begin
                        state <= A;
                    end
                end
                D: begin
                    state <= A;
                end
                default: state <= A;
            endcase
        end
    end

    // Output logic
    always @(*) begin
        g = 3'b000;
        case (state)
            A: begin
                if (r[0] == 1'b1) begin
                    g[0] = 1'b1;
                end else if (r[1] == 1'b1) begin
                    g[1] = 1'b1;
                end else if (r[2] == 1'b1) begin
                    g[2] = 1'b1;
                end
            end
            B: begin
                g[0] = 1'b1;
            end
            C: begin
                g[1] = 1'b1;
            end
            D: begin
                // No grant in state D
            end
            default: begin
                // No grant in default state
            end
        endcase
    end

