    typedef enum logic [1:0] {
        STATE_LOW,
        STATE_BETWEEN_S2_S1,
        STATE_BETWEEN_S1_S0,
        STATE_HIGH
    } state_t;

    state_t current_state, next_state;

    // Output signals
    assign fr2 = (current_state == STATE_BETWEEN_S1_S0) || (current_state == STATE_HIGH);
    assign fr1 = (current_state == STATE_BETWEEN_S1_S0) || (current_state == STATE_BETWEEN_S2_S1);
    assign fr0 = (current_state == STATE_BETWEEN_S1_S0) || (current_state == STATE_BETWEEN_S2_S1) || (current_state == STATE_LOW);
    assign dfr = (current_state == STATE_BETWEEN_S1_S0) || (current_state == STATE_BETWEEN_S2_S1);

    // State transition logic
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
        end else begin
            current_state <= next_state;
        end
    end

    always_comb begin
        next_state = current_state;
        case (current_state)
            STATE_LOW:
                if (s == 3'b000) begin
                    next_state = STATE_LOW;
                end else if (s == 3'b001) begin
                    next_state = STATE_BETWEEN_S2_S1;
                end else if (s == 3'b010) begin
