                    next_state = STATE_LOW;
                end else if (s == 3'b001) begin
                    next_state = STATE_BETWEEN_S2_S1;
                end else if (s == 3'b010) begin
                    next_state = STATE_BETWEEN_S1_S0;
                end else if (s == 3'b111) begin
                    next_state = STATE_HIGH;
                end
            STATE_BETWEEN_S1_S0:
                if (s == 3'b000) begin
                    next_state = STATE_LOW;
                end else if (s == 3'b001) begin
                    next_state = STATE_BETWEEN_S2_S1;
                end else if (s == 3'b010) begin
                    next_state = STATE_BETWEEN_S1_S0;
                end else if (s == 3'b111) begin
                    next_state = STATE_HIGH;
                end
            STATE_HIGH:
                if (s == 3'b000) begin
                    next_state = STATE_LOW;
                end else if (s == 3'b001) begin
                    next_state = STATE_BETWEEN_S2_S1;
                end else if (s == 3'b010) begin
                    next_state = STATE_BETWEEN_S1_S0;
                end else if (s == 3'b111) begin
                    next_state = STATE_HIGH;
                end
        endcase
    end

