assign shift_ena = (state == 10'b0000000011 || state == 10'b0000000101 || state == 10'b0000000111 || state == 10'b0000001001);

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    // Define states
    typedef enum reg [2:0] {
        IDLE,
        DETECT_PATTERN,
        SHIFT_DATA,
        WAIT_COUNTING,
        TIMER_DONE,
        AWAIT_ACK
    } state_t;

    state_t state, next_state;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        shift_ena = 0;
        counting = 0;
        done = 0;

        case (state)
            IDLE: begin
                if (data == 1'b1 && data == 1'b1 && data == 1'b0 && data == 1'b1) begin
                    next_state = DETECT_PATTERN;
                end
            end
            DETECT_PATTERN: begin
                shift_ena = 1;
                next_state = SHIFT_DATA;
            end
            SHIFT_DATA: begin
                shift_ena = 1;
                if (data == 1'b0) begin
                    next_state = WAIT_COUNTING;
                end
            end
            WAIT_COUNTING: begin
                counting = 1;
                if (done_counting) begin
                    next_state = TIMER_DONE;
                end
            end
            TIMER_DONE: begin
                done = 1;
                if (ack) begin
                    next_state = IDLE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Define states
    typedef enum reg [1:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;

    // Moore state machine logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        walk_left = 0;
        walk_right = 0;
        aaah = 0;
        digging = 0;

        case (current_state)
            WALK_LEFT:
                begin
                    if (ground == 0) begin
                        next_state = FALLING;
                    end else if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (dig && ground) begin
                        next_state = DIGGING;
                    end
                    walk_left = 1;
                end

            WALK_RIGHT:
                begin
                    if (ground == 0) begin
                        next_state = FALLING;
                    end else if (bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (dig && ground) begin
                        next_state = DIGGING;
                    end
                    walk_right = 1;
                end

            FALLING:
                begin
                    aaah = 1;
                    if (ground == 1) begin
                        next_state = current_state;
                    end
                end

            DIGGING:
                begin
                    if (ground == 0) begin
                        next_state = FALLING;
                    end
                    digging = 1;
                end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // Constants
    parameter PHT_SIZE = 128;
    parameter PHT_ENTRY_WIDTH = 2;

    // PHT and Global History Register
    reg [PHT_ENTRY_WIDTH-1:0] pht [0:PHT_SIZE-1];
    reg [6:0] global_history;

    // Prediction logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            global_history <= 7'b0;
        end else if (predict_valid) begin
            // Predict taken if counter is 2 (strongly taken)
            predict_taken <= (pht[(predict_pc ^ global_history) % PHT_SIZE] == 2'b11);
            // Update global history
            global_history <= (predict_taken) ? (global_history << 1) | 1'b1 : (global_history << 1);
        end
    end

    // Training logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            // Initialize PHT to 2'b00 (weakly not taken)
            for (integer i = 0; i < PHT_SIZE; i = i + 1) begin
                pht[i] <= 2'b00;
            end
        end else if (train_valid) begin
            // Update PHT entry
            pht[(train_pc ^ train_history) % PHT_SIZE] <= (train_taken) ? (pht[(train_pc ^ train_history) % PHT_SIZE] + 1) : (pht[(train_pc ^ train_history) % PHT_SIZE] - 1);
            // Recover global history if mispredicted
            if (train_mispredicted) begin
                global_history <= train_history;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output [23:0] out_bytes,
    output done
);

    // State definitions
    typedef enum reg [1:0] {
        IDLE,
        RECEIVE_BYTE1,
        RECEIVE_BYTE2,
        RECEIVE_BYTE3
    } state_t;

    state_t state, next_state;
    reg [23:0] message;
    reg [1:0] byte_count;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            message <= 24'b0;
            byte_count <= 2'b0;
            out_bytes <= 24'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            if (done) begin
                out_bytes <= message;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in[3] == 1'b1) begin
                    next_state = RECEIVE_BYTE1;
                    message[23:16] = in;
                    byte_count = 2'b01;
                end
            end
            RECEIVE_BYTE1: begin
                if (in[3] == 1'b1) begin
                    next_state = RECEIVE_BYTE2;
                    message[15:8] = in;
                    byte_count = 2'b10;
                end
            end
            RECEIVE_BYTE2: begin
                if (in[3] == 1'b1) begin
                    next_state = RECEIVE_BYTE3;
                    message[7:0] = in;
                    byte_count = 2'b11;
                end
            end
            RECEIVE_BYTE3: begin
                if (in[3] == 1'b1) begin
                    next_state = RECEIVE_BYTE1;
                    message[23:16] = message[15:8];
                    message[15:8] = message[7:0];
                    message[7:0] = in;
                    byte_count = 2'b01;
                end
            end
        endcase
    end

    // Done signal logic
    always @(*) begin
        done = (byte_count == 2'b11);
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Define states
    typedef enum reg [1:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING,
        SPLATTERED
    } state_t;

    state_t current_state, next_state;
    reg [4:0] fall_counter;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            fall_counter <= 0;
        end else begin
            current_state <= next_state;
            if (current_state == FALLING) begin
                if (ground) begin
                    fall_counter <= 0;
                end else begin
                    fall_counter <= fall_counter + 1;
                end
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        walk_left = 0;
        walk_right = 0;
        aaah = 0;
        digging = 0;

        case (current_state)
            WALK_LEFT:
                begin
                    walk_left = 1;
                    if (ground) begin
                        if (bump_left) begin
                            next_state = WALK_RIGHT;
                        end else if (dig) begin
                            next_state = DIGGING;
                        end else if (!ground) begin
                            next_state = FALLING;
                        end
                    end
                end
            WALK_RIGHT:
                begin
                    walk_right = 1;
                    if (ground) begin
                        if (bump_right) begin
                            next_state = WALK_LEFT;
                        end else if (dig) begin
                            next_state = DIGGING;
                        end else if (!ground) begin
                            next_state = FALLING;
                        end
                    end
                end
            FALLING:
                begin
                    aaah = 1;
                    if (ground) begin
                        if (fall_counter >= 20) begin
                            next_state = SPLATTERED;
                        end else begin
                            next_state = WALK_LEFT; // or WALK_RIGHT based on previous direction
                        end
                    end
                end
            DIGGING:
                begin
                    digging = 1;
                    if (!ground) begin
                        next_state = FALLING;
                    end
                end
            SPLATTERED:
                begin
                    walk_left = 0;
                    walk_right = 0;
                    aaah = 0;
                    digging = 0;
                end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    // States for the state machine
    typedef enum reg [2:0] {
        IDLE,
        DETECT_PATTERN,
        READ_DELAY,
        COUNTING,
        DONE
    } state_t;

    state_t state, next_state;
    reg [3:0] delay;
    reg [31:0] counter;
    reg [3:0] remaining_time;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (data == 1'b1 && data == 1'b1 && data == 1'b0 && data == 1'b1) begin
                    next_state = DETECT_PATTERN;
                end
            end
            DETECT_PATTERN: begin
                next_state = READ_DELAY;
            end
            READ_DELAY: begin
                next_state = COUNTING;
            end
            COUNTING: begin
                if (counter == 0) begin
                    next_state = DONE;
                end
            end
            DONE: begin
                if (ack) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Delay reading logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            delay <= 4'b0000;
        end else if (state == DETECT_PATTERN) begin
            delay <= {data, delay[3:1]};
        end
    end

    // Counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 32'd0;
            remaining_time <= 4'd0;
        end else if (state == COUNTING) begin
            if (counter == 0) begin
                remaining_time <= delay;
            end else begin
                counter <= counter - 1;
                remaining_time <= remaining_time - 1;
            end
        end
    end

    // Output logic
    assign count = (state == COUNTING) ? remaining_time : 4'bxxxx;
    assign counting = (state == COUNTING);
    assign done = (state == DONE);

endmodule

