module TopModule (
  input clk,
  input [7:0] d,
  input reset,
  output reg [7:0] q
);

  reg [7:0] dffs [0:7];

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      for (integer i = 0; i < 8; i = i + 1) begin
        dffs[i] <= 8'h34;
