module TopModule (
  input clk,
  input reset,
  output [3:1] ena,
  output reg [15:0] q
);

  reg [3:0] digit_ones;
  reg [3:0] digit_tens;
  reg [3:0] digit_hundreds;
  reg [3:0] digit_thousands;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      digit_ones <= 4'b0000;
      digit_tens <= 4'b0000;
      digit_hundreds <= 4'b0000;
      digit_thousands <= 4'b0000;
    end else begin
      digit_ones <= digit_ones + 1;
      if (digit_ones == 4'b1010) begin
        digit_ones <= 4'b0000;
        digit_tens <= digit_tens + 1;
      end
      if (digit_tens == 4'b1010) begin
        digit_tens <= 4'b0000;
        digit_hundreds <= digit_hundreds + 1;
      end
      if (digit_hundreds == 4'b1010) begin
        digit_hundreds <= 4'b0000;
        digit_thousands <= digit_thousands + 1;
      end
    end
  end

  assign q[3:0] = digit_ones;
  assign q[7:4] = digit_tens;
  assign q[11:8] = digit_hundreds;
  assign q[15:12] = digit_thousands;

  assign ena[1] = digit_tens != 4'b0000;
  assign ena[2] = digit_hundreds != 4'b0000;
  assign ena[3] = digit_thousands != 4'b0000;

endmodule

