module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out_sop,
  output out_pos
);

  // Internal wire to represent the sum of products form
  wire sop;

  // Internal wire to represent the product of sums form
  wire pos;

  // Logic to determine the sum of products form
  assign sop = (a & b & c & d) | // 7
               (a & b & ~c & d) | // 3 (not possible, but included for completeness)
               (a & ~b & c & d) | // 11 (not possible, but included for completeness)
               (~a & b & c & d);  // 15

  // Logic to determine the product of sums form
  assign pos = (~a | ~b | ~c | ~d) & // 0
               (~a | ~b | c | ~d) & // 1 (not possible, but included for completeness)
               (~a | b | ~c | ~d) & // 4 (not possible, but included for completeness)
               (~a | b | c | ~d) & // 5 (not possible, but included for completeness)
               (~a | ~b | ~c | d) & // 6 (not possible, but included for completeness)
               (a | ~b | ~c | ~d) & // 9 (not possible, but included for completeness)
               (a | b | ~c | ~d) & // 10 (not possible, but included for completeness)
               (a | ~b | c | d) & // 13 (not possible, but included for completeness)
               (a | b | c | d);     // 14 (not possible, but included for completeness)

  // Assign the final outputs
  assign out_sop = sop;
  assign out_pos = pos;

endmodule

