module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);

  // Internal signals
  reg heater_reg;
  reg aircon_reg;
  reg fan_reg;

  // Logic to control the heater, air conditioner, and fan
  always @(*) begin
    heater_reg = 0;
    aircon_reg = 0;
    fan_reg = 0;

    if (mode == 1) begin // Heating mode
      if (too_cold) begin
        heater_reg = 1;
      end
    end else if (mode == 0) begin // Cooling mode
      if (too_hot) begin
        aircon_reg = 1;
      end
    end

    // Turn on the fan if requested or if the heater/air conditioner is on
    if (fan_on || heater_reg || aircon_reg) begin
      fan_reg = 1;
    end
  end

  // Assign the internal signals to the output ports
  assign heater = heater_reg;
  assign aircon = aircon_reg;
  assign fan = fan_reg;

endmodule

