);

  reg q1, q2, q3; // Flip-flop outputs

  // XOR gate
  wire xor_out = x ^ q1;

  // AND gate
  wire and_out = x & ~q2;

  // OR gate
  wire or_out = x | ~q3;

  // D flip-flops
  always @(posedge clk) begin
    q1 <= xor_out;
    q2 <= and_out;
    q3 <= or_out;
  end

  // Three-input NOR gate
  assign z = ~(q1 | q2 | q3);

