  wire and2_out;
  wire or_out;

  // First layer: AND gates
  assign and1_out = a & b;
  assign and2_out = c & d;

  // Second layer: OR gate
  assign or_out = and1_out | and2_out;

  // Output assignments
  assign out = or_out;
  assign out_n = ~or_out;

