module TopModule (
  input clk,
  input d,
  output reg q
);

  reg q_rising;
  reg q_falling;

  // Capture the value on the rising edge of the clock
  always @(posedge clk) begin
    q_rising <= d;
  end

  // Capture the value on the falling edge of the clock
  always @(negedge clk) begin
    q_falling <= d;
  end

  // Combine the values to achieve dual-edge triggered behavior
  always @(posedge clk or negedge clk) begin
    q <= q_rising | q_falling;
  end

endmodule

module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);

  always @(*) begin
    case (state)
      4'b0001: begin // State A
        next_state = in ? 4'b1000 : 4'b0010;
        out = 0;
      end
      4'b0010: begin // State B
        next_state = in ? 4'b0100 : 4'b0010;
        out = 0;
      end
      4'b0100: begin // State C
        next_state = in ? 4'b1000 : 4'b0001;
        out = 0;
      end
      4'b1000: begin // State D
        next_state = in ? 4'b0100 : 4'b0010;
        out = 1;
      end
      default: begin
        next_state = 4'b0000;
        out = 0;
      end
    endcase
  end

endmodule

module TopModule (
