  always @(posedge clk) begin
    if (load) begin
      counter <= data;
      tc_reg <= 0;
    end else if (counter > 0) begin
      counter <= counter - 1;
      if (counter == 0) begin
        tc_reg <= 1;
      end
    end
  end

  assign tc = tc_reg;

endmodule

