  localparam [1:0] STATE_A = 2'b001;
  localparam [1:0] STATE_B = 2'b010;

  // State register
  reg [1:0] state;

  // Output register
  reg z_reg;

  // Next state logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= STATE_A; // Reset to state A
      z_reg <= 0;       // Reset output to 0
    end else begin
      case (state)
        STATE_A: begin
          if (x) begin
            state <= STATE_B;
            z_reg <= 1;
          end else begin
            state <= STATE_A;
            z_reg <= 0;
          end
        end
        STATE_B: begin
          if (x) begin
            state <= STATE_B;
            z_reg <= 0;
          end else begin
            state <= STATE_B;
            z_reg <= 1;
          end
        end
        default: state <= STATE_A; // Default to state A
      endcase
    end
  end

  // Output assignment
  assign z = z_reg;

endmodule

