  assign out_both[1] = in[0] & in[1];
  assign out_both[2] = in[1] & in[2];
  assign out_both[3] = in[2] & in[3];

  assign out_any[0] = in[0] | in[3]; // No right neighbour for in[3]
  assign out_any[1] = in[1] | in[0];
  assign out_any[2] = in[2] | in[1];
  assign out_any[3] = in[3] | in[2];

  assign out_different[0] = in[0] ^ in[3]; // Wrap around for in[3]
  assign out_different[1] = in[1] ^ in[0];
  assign out_different[2] = in[2] ^ in[1];
  assign out_different[3] = in[3] ^ in[2];

endmodule

module TopModule (
  input clk,
  input reset,
  output shift_ena
);

  // Internal state variables
  reg [1:0] state;
  reg [1:0] count;

  // State definitions
  parameter IDLE = 2'b00;
  parameter ENABLE = 2'b01;
  parameter COUNT = 2'b10;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      count <= 2'b00;
      shift_ena <= 1'b1;
    end else begin
      case (state)
        IDLE: begin
          if (shift_ena) begin
            state <= ENABLE;
            count <= 2'b00;
          end
        end
        ENABLE: begin
          state <= COUNT;
          count <= 2'b00;
        end
        COUNT: begin
          if (count < 2'b11) begin
            count <= count + 1;
          end else begin
            state <= IDLE;
            shift_ena <= 1'b0;
          end
        end
        default: state <= IDLE;
      endcase
    end
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  // State definitions
  typedef enum reg [1:0] {
    IDLE,
    FIRST_ONE,
    SECOND_ONE,
    ZERO,
    FIRST_ONE_AGAIN
  } state_t;

  state_t state, next_state;
  reg [1:0] shift_reg;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      start_shifting <= 0;
    end else begin
      state <= next_state;
      if (state == IDLE && data == 1'b1) begin
        start_shifting <= 0;
      end else if (state == IDLE && data == 1'b0) begin
        start_shifting <= 0;
      end else if (state == FIRST_ONE && data == 1'b1) begin
        start_shifting <= 0;
      end else if (state == FIRST_ONE && data == 1'b0) begin
        start_shifting <= 0;
      end else if (state == SECOND_ONE && data == 1'b0) begin
        start_shifting <= 0;
      end else if (state == SECOND_ONE && data == 1'b1) begin
        start_shifting <= 0;
      end else if (state == ZERO && data == 1'b1) begin
        start_shifting <= 0;
      end else if (state == ZERO && data == 1'b0) begin
        start_shifting <= 0;
      end else if (state == FIRST_ONE_AGAIN && data == 1'b1) begin
        start_shifting <= 1;
      end else if (state == FIRST_ONE_AGAIN && data == 1'b0) begin
        start_shifting <= 0;
      end
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (data == 1'b1) begin
          next_state = FIRST_ONE;
        end else begin
          next_state = IDLE;
        end
      end
      FIRST_ONE: begin
        if (data == 1'b1) begin
          next_state = SECOND_ONE;
        end else begin
          next_state = IDLE;
        end
      end
      SECOND_ONE: begin
        if (data == 1'b0) begin
          next_state = ZERO;
        end else begin
          next_state = IDLE;
        end
      end
      ZERO: begin
        if (data == 1'b1) begin
          next_state = FIRST_ONE_AGAIN;
        end else begin
          next_state = IDLE;
        end
      end
      FIRST_ONE_AGAIN: begin
        next_state = FIRST_ONE_AGAIN;
      end
    endcase
  end

endmodule

