module TopModule (
  input  [5:0] y,
  input        w,
  output       Y1,
  output       Y3
);

  // State encoding
  parameter A = 6'b000001;
  parameter B = 6'b000010;
  parameter C = 6'b000100;
  parameter D = 6'b001000;
  parameter E = 6'b010000;
  parameter F = 6'b100000;

  // Current state
  reg [5:0] current_state;

  // Next state
  reg [5:0] next_state;

  // Output signals
  assign Y1 = (current_state == A || current_state == C || current_state == E) ? 1'b1 : 1'b0;
  assign Y3 = (current_state == B || current_state == D || current_state == F) ? 1'b1 : 1'b0;

  // State transition logic
  always @(*) begin
    case (current_state)
      A: begin
        if (w == 1'b0) next_state = B;
        else next_state = A;
      end
      B: begin
        if (w == 1'b0) next_state = C;
        else next_state = D;
      end
      C: begin
        if (w == 1'b0) next_state = E;
        else next_state = D;
      end
      D: begin
        if (w == 1'b0) next_state = F;
        else next_state = A;
      end
      E: begin
        if (w == 1'b0) next_state = E;
        else next_state = D;
      end
      F: begin
        if (w == 1'b0) next_state = C;
        else next_state = D;
      end
      default: next_state = A; // Reset to state A
    endcase
  end

  // State register
  always @(posedge w) begin
    current_state <= next_state;
  end

endmodule

module TopModule (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output out
);

always @(*) begin
  case (state)
    2'b00: begin // State A
      next_state = (in == 0) ? 2'b00 : 2'b01;
      out = 0;
    end
    2'b01: begin // State B
      next_state = (in == 0) ? 2'b10 : 2'b01;
      out = 0;
    end
    2'b10: begin // State C
      next_state = (in == 0) ? 2'b00 : 2'b11;
      out = 0;
    end
    2'b11: begin // State D
      next_state = (in == 0) ? 2'b10 : 2'b01;
      out = 1;
    end
    default: begin
      next_state = 2'b00; // Default to State A
      out = 0;
    end
  endcase
end

endmodule

