  typedef enum reg [1:0] {
    STATE_B = 2'b11,
    STATE_A = 2'b00
  } state_t;

  // State register
  state_t current_state, next_state;

  // Output register
  reg out_reg;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= STATE_B;
      out_reg <= 1'b1;
    end else begin
      current_state <= next_state;
      out_reg <= out;
    end
  end

  // Next state logic
  always @(*) begin
