    out = out_reg;

    case (current_state)
      STATE_B: begin
        if (in == 1'b0) begin
          next_state = STATE_A;
        end
      end
      STATE_A: begin
        if (in == 1'b0) begin
          next_state = STATE_B;
        end
      end
      default: begin
        next_state = STATE_B;
        out = 1'b1;
      end
    endcase
  end

