  localparam A = 1'b0;
  localparam B = 1'b1;

  // State register
  reg state;

  // Output register
  reg out;

  // Moore machine logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= B; // Asynchronously reset to state B
    end else begin
      case (state)
        A: begin
          if (in == 1'b0) begin
            state <= B;
          end else begin
            state <= A;
          end
        end
        B: begin
          if (in == 1'b0) begin
            state <= B;
          end else begin
            state <= A;
          end
        end
        default: state <= B; // Default to state B
      endcase
    end
  end

  // Output logic
  always @(*) begin
    case (state)
      A: out = 1'b0;
      B: out = 1'b1;
      default: out = 1'b1; // Default output
    endcase
  end

endmodule

