        else next_state = STATE_B;
      end
      default: next_state = STATE_A; // Default to state A
    endcase
  end

  // Output logic
  always @(*) begin
    case (current_state)
      STATE_A: out = 1'b0;
      STATE_B: out = 1'b0;
      STATE_C: out = 1'b0;
      STATE_D: out = 1'b1;
      default: out = 1'b0; // Default output
    endcase
  end

