module TopModule (
  input clk,
  input load,
  input [511:0] data,
  output reg [511:0] q
);

  reg [511:0] cells;

  always @(posedge clk) begin
    if (load) begin
      cells <= data;
    end else begin
      q <= cells;
      cells <= #1 calculate_next_state(cells);
    end
  end

  function [511:0] calculate_next_state;
    input [511:0] current_state;
    integer i;
    begin
      calculate_next_state = 512'b0;
      for (i = 0; i < 512; i = i + 1) begin
        calculate_next_state[i] = calculate_cell_state(
          (i == 0) ? 0 : current_state[i-1],
          current_state[i],
          (i == 511) ? 0 : current_state[i+1]
        );
      end
    end
  endfunction

  function bit calculate_cell_state;
    input bit left, center, right;
    begin
      case ({left, center, right})
        3'b111: calculate_cell_state = 0;
        3'b110: calculate_cell_state = 1;
        3'b101: calculate_cell_state = 1;
        3'b100: calculate_cell_state = 0;
        3'b011: calculate_cell_state = 1;
        3'b010: calculate_cell_state = 1;
        3'b001: calculate_cell_state = 1;
        3'b000: calculate_cell_state = 0;
        default: calculate_cell_state = 0;
      endcase
    end
  endfunction

endmodule

