module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  // Internal state of the Moore FSM
  typedef enum logic [1:0] {
    WALK_LEFT,
    WALK_RIGHT
  } state_t;

  state_t current_state, next_state;

  // Moore output logic
  assign walk_left = (current_state == WALK_LEFT);
  assign walk_right = (current_state == WALK_RIGHT);

  // State transition logic
  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= WALK_LEFT;
    end else begin
      current_state <= next_state;
    end
  end

  always_comb begin
    next_state = current_state; // Default to stay in the same state

    case (current_state)
      WALK_LEFT:
        if (bump_left || bump_right) begin
          next_state = WALK_RIGHT;
        end
      WALK_RIGHT:
        if (bump_left || bump_right) begin
          next_state = WALK_LEFT;
        end
      default:
        next_state = WALK_LEFT; // Should never reach here
    endcase
  end

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  // State definitions
  typedef enum reg [1:0] {
    IDLE,
    LOOKING_FOR_FIRST_BYTE,
    RECEIVING_MESSAGE
  } state_t;

  state_t state, next_state;
  reg [2:0] byte_count;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      byte_count <= 3'b000;
      done <= 1'b0;
    end else begin
      state <= next_state;
      if (next_state == RECEIVING_MESSAGE && byte_count == 3'b011) begin
        done <= 1'b1;
      end else begin
        done <= 1'b0;
      end
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (in[3] == 1'b1) begin
          next_state = LOOKING_FOR_FIRST_BYTE;
          byte_count = 3'b001;
        end
      end
      LOOKING_FOR_FIRST_BYTE: begin
        if (in[3] == 1'b1) begin
          next_state = RECEIVING_MESSAGE;
          byte_count = 3'b010;
        end
      end
      RECEIVING_MESSAGE: begin
        if (byte_count < 3'b111) begin
          byte_count = byte_count + 3'b001;
        end
        if (byte_count == 3'b111) begin
          next_state = IDLE;
        end
      end
    endcase
  end

endmodule

module TopModule (
