  typedef enum reg [1:0] {
    IDLE,
    S1,
    S2
  } state_t;

  state_t state, next_state;

  // Output logic
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      z <= 0;
    end else begin
      z <= (state == S2);
    end
  end

  // State transition logic
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (x == 1) begin
          next_state = S1;
        end
      end
      S1: begin
        if (x == 0) begin
          next_state = S2;
        end else begin
          next_state = IDLE;
        end
      end
      S2: begin
        if (x == 1) begin
          next_state = S1;
        end else begin
          next_state = IDLE;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

endmodule

