module TopModule (
  input x,
  input y,
  output z
);

  wire a1_out, a2_out, b1_out, b2_out, or_out, and_out, xor_out;

  // Instantiate two A modules
  A a1 (.x(x), .y(y), .z(a1_out));
  A a2 (.x(x), .y(y), .z(a2_out));

  // Instantiate two B modules
  B b1 (.x(x), .y(y), .z(b1_out));
  B b2 (.x(x), .y(y), .z(b2_out));

  // Connect A1 and B1 outputs to an OR gate
  assign or_out = a1_out | b1_out;

  // Connect A2 and B2 outputs to an AND gate
  assign and_out = a2_out & b2_out;

  // Connect the OR and AND outputs to an XOR gate
  assign xor_out = or_out ^ and_out;

  // Assign the final output
  assign z = xor_out;

endmodule

module A (
  input x,
  input y,
  output z
);
  assign z = (x ^ y) & x;
endmodule

module B (
  input x,
  input y,
  output z
);
  // The behavior of module B is not specified in the waveform, so we will assume it is a simple pass-through
  assign z = x & y;
endmodule

