  localparam C = 2'b10;
  localparam D = 2'b11;

  // State register
  reg [1:0] state;

  // Internal signals
  reg [1:0] w_count;
  reg w_prev;

  // State transition and output logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= A;
      z <= 0;
      w_count <= 0;
      w_prev <= 0;
    end else begin
      case (state)
        A: begin
          if (s) begin
            state <= B;
            w_count <= 0;
            w_prev <= w;
          end else begin
            state <= A;
          end
        end
        B: begin
          w_count <= w_count + 1;
          w_prev <= w;
          if (w_count == 3) begin
            state <= C;
            w_count <= 0;
          end
        end
        C: begin
          if (w_prev == w) begin
            state <= D;
            z <= 0;
          end else begin
            state <= B;
          end
        end
        D: begin
          if (w_prev == w) begin
            state <= D;
            z <= 0;
          end else begin
            state <= B;
          end
        end
      endcase
    end
  end

