module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  // Define states
  typedef enum reg [2:0] {
    IDLE,
    START_BIT,
    DATA_BITS,
    STOP_BIT
  } state_t;

  // State register
  state_t state, next_state;

  // Internal signals
  reg [7:0] data_reg;
  reg [2:0] bit_count;

  // Next state logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // State transition logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (in == 0) begin
          next_state = START_BIT;
        end
      end
      START_BIT: begin
        if (bit_count == 0) begin
          data_reg = 0;
          bit_count = 7;
          next_state = DATA_BITS;
        end
      end
      DATA_BITS: begin
        data_reg = {data_reg[6:0], in};
        bit_count = bit_count - 1;
        if (bit_count == 0) begin
          next_state = STOP_BIT;
        end
      end
      STOP_BIT: begin
        if (in == 1) begin
          next_state = IDLE;
          done = 1;
        end else begin
          next_state = START_BIT;
        end
      end
    endcase
  end

  // Output logic
  assign done = (state == IDLE) && (in == 1);

