  reg [1:0] x_count;
  reg y_detected;

  // State register
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= STATE_A;
      x_count <= 2'b00;
      y_detected <= 1'b0;
      f <= 1'b0;
      g <= 1'b0;
    end else begin
      state <= next_state;
      f <= (state == STATE_B) ? 1'b1 : 1'b0;
      g <= (state == STATE_C || state == STATE_D || state == STATE_E) ? 1'b1 : 1'b0;
    end
