        if (resetn) begin
          next_state = STATE_B;
          x_count = 2'b00;
          y_detected = 1'b0;
        end
      end
      STATE_B: begin
        if (x) begin
          x_count <= x_count + 1;
        end else begin
          x_count <= 2'b00;
