        if (y_detected) begin
          next_state = STATE_D;
        end else if (x_count < 2'b11) begin
          x_count <= x_count + 1;
          if (x_count == 2'b11) begin
            next_state = STATE_E;
          end
        end else begin
          next_state = STATE_E;
        end
      end
      STATE_E: begin
        // Stay in state E
      end
    endcase
  end

