    TWO,
    THREE,
    FOUR,
    FIVE,
    SIX,
    SEVEN,
    EIGHT
  } state_t;

  state_t state, next_state;

  // Output signals
  reg disc_reg;
  reg flag_reg;
  reg err_reg;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    disc_reg = 0;
    flag_reg = 0;
    err_reg = 0;

    case (state)
      IDLE: begin
        if (in == 1) begin
          next_state = ONE;
        end
      end
      ONE: begin
        if (in == 1) begin
          next_state = TWO;
        end else begin
          next_state = IDLE;
        end
      end
      TWO: begin
        if (in == 1) begin
          next_state = THREE;
        end else begin
          next_state = IDLE;
        end
      end
      THREE: begin
        if (in == 1) begin
          next_state = FOUR;
        end else begin
          next_state = IDLE;
        end
      end
      FOUR: begin
        if (in == 1) begin
          next_state = FIVE;
        end else begin
          next_state = IDLE;
        end
      end
      FIVE: begin
        if (in == 1) begin
          next_state = SIX;
        end else begin
          next_state = IDLE;
        end
      end
      SIX: begin
        if (in == 1) begin
          next_state = SEVEN;
        end else begin
          next_state = IDLE;
        end
      end
      SEVEN: begin
        if (in == 1) begin
          next_state = EIGHT;
        end else begin
          next_state = IDLE;
        end
      end
      EIGHT: begin
        if (in == 0) begin
          next_state = IDLE;
          flag_reg = 1;
        end else begin
          next_state = SEVEN;
          err_reg = 1;
        end
      end
    endcase
  end

  // Output logic
  assign disc = disc_reg;
  assign flag = flag_reg;
  assign err = err_reg;

endmodule

module TopModule (
  input clk,
  input reset,
  input ena,
  output reg pm,
  output reg [7:0] hh,
  output reg [7:0] mm,
  output reg [7:0] ss
);

  reg [2:0] sec_cnt;
  reg [2:0] min_cnt;
  reg [3:0] hr_cnt;
  reg [1:0] state;

  parameter AM = 2'b00;
  parameter PM = 2'b01;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      sec_cnt <= 3'b000;
      min_cnt <= 3'b000;
      hr_cnt <= 4'b0000;
      state <= AM;
      pm <= 1'b0;
      hh <= 8'b00000000;
      mm <= 8'b00000000;
      ss <= 8'b00000000;
    end else begin
      if (ena) begin
        sec_cnt <= sec_cnt + 1;
        if (sec_cnt == 3'b111) begin
          sec_cnt <= 3'b000;
          min_cnt <= min_cnt + 1;
          if (min_cnt == 3'b111111) begin
            min_cnt <= 3'b000000;
            hr_cnt <= hr_cnt + 1;
            if (hr_cnt == 4'b1111) begin
              hr_cnt <= 4'b0000;
              state <= state == AM ? PM : AM;
            end
          end
        end
      end
      pm <= state;
      hh <= {hr_cnt[3], hr_cnt[2], hr_cnt[1], hr_cnt[0], 1'b0, 1'b0};
      mm <= {min_cnt[5], min_cnt[4], min_cnt[3], min_cnt[2], min_cnt[1], min_cnt[0], 1'b0, 1'b0};
      ss <= {sec_cnt[2], sec_cnt[1], sec_cnt[0], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
    end
  end

endmodule

module TopModule (
