endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // State definitions
  localparam A = 3'b000,
             B = 3'b001,
             C = 3'b010,
             D = 3'b011;

  // State register
  reg [1:0] state;

  // Output signals
  reg [2:0] g_reg;

  // State transition logic
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= A;
      g_reg <= 3'b000;
    end else begin
      case (state)
        A: begin
          if (r == 3'b000) state <= A;
          else if (r[0] == 1'b1) state <= B;
          else if (r[1] == 1'b1) state <= C;
          else if (r[2] == 1'b1) state <= D;
        end
        B: begin
          if (r[0] == 1'b1) state <= B;
          else state <= A;
        end
        C: begin
          if (r[1] == 1'b1) state <= C;
          else state <= A;
        end
        D: begin
          if (r == 3'b000) state <= A;
        end
        default: state <= A;
      endcase
    end
  end

  // Output logic
  always @(*) begin
    g_reg = 3'b000;
    case (state)
      B: g_reg[0] = 1'b1;
      C: g_reg[1] = 1'b1;
    endcase
  end

  // Assign outputs
  assign g = g_reg;

endmodule

module TopModule (
  input clk,
  input reset,
  input [2:0] s,
  output reg fr2,
  output reg fr1,
  output reg fr0,
  output reg dfr
);

  // State definitions
  typedef enum reg [1:0] {
    STATE_LOW,
    STATE_BETWEEN_S2_S1,
    STATE_BETWEEN_S1_S0,
    STATE_HIGH
  } state_t;

  state_t current_state, next_state;

  // Nominal flow rate inputs
  reg [2:0] nominal_flow;

  // Previous sensor state
  reg [2:0] prev_s;

  // Edge detection for sensor change
  reg [2:0] s_edge;

  // Initialize outputs
  assign fr2 = (current_state == STATE_HIGH) ? 1 : 0;
  assign fr1 = (current_state == STATE_BETWEEN_S2_S1) ? 1 : 0;
  assign fr0 = (current_state == STATE_BETWEEN_S1_S0) ? 1 : 0;
  assign dfr = (s_edge[2] || s_edge[1] || s_edge[0]) && (current_state == STATE_BETWEEN_S1_S0);

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= STATE_LOW;
      prev_s <= 3'b000;
    end else begin
      current_state <= next_state;
      prev_s <= s;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    case (current_state)
      STATE_LOW:
        if (s != 3'b000)
          next_state = STATE_BETWEEN_S2_S1;
      STATE_BETWEEN_S2_S1:
        if (s == 3'b000)
          next_state = STATE_LOW;
        else if (s == 3'b001)
          next_state = STATE_BETWEEN_S1_S0;
        else if (s == 3'b011)
          next_state = STATE_HIGH;
      STATE_BETWEEN_S1_S0:
        if (s == 3'b000)
          next_state = STATE_LOW;
        else if (s == 3'b001)
          next_state = STATE_BETWEEN_S2_S1;
        else if (s == 3'b011)
          next_state = STATE_HIGH;
      STATE_HIGH:
        if (s == 3'b000)
          next_state = STATE_LOW;
        else if (s == 3'b001)
          next_state = STATE_BETWEEN_S2_S1;
        else if (s == 3'b011)
          next_state = STATE_BETWEEN_S1_S0;
    endcase
  end

  // Edge detection logic
  always @(*) begin
    s_edge = s ^ prev_s;
  end

endmodule

module TopModule (
