  assign B3_next = (state == 10'b0000000011);
  assign S_next = (state == 10'b0000000001);
  assign S1_next = (state == 10'b0000000010);
  assign Count_next = (state == 10'b0000000101);
  assign Wait_next = (state == 10'b0000001000);

  // Output logic
  assign done = (state == 10'b0000001000);
  assign counting = (state == 10'b0000000101);
  assign shift_ena = (state == 10'b0000000110) || (state == 10'b0000000111) || (state == 10'b0000001000);

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);
  // Define states
  typedef enum reg [2:0] {
    IDLE,
    DETECT_PATTERN,
    SHIFT_DATA,
    WAIT_COUNTING,
    TIMER_DONE,
    AWAIT_ACK
  } state_t;

  state_t state, next_state;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    shift_ena = 0;
    counting = 0;
    done = 0;

    case (state)
      IDLE: begin
        if (data == 1'b1 && data == 1'b1 && data == 1'b0 && data == 1'b1) begin
          next_state = DETECT_PATTERN;
        end
      end
      DETECT_PATTERN: begin
        shift_ena = 1;
        next_state = SHIFT_DATA;
      end
      SHIFT_DATA: begin
        shift_ena = 1;
        if (data == 1'b0) begin
          next_state = WAIT_COUNTING;
        end
      end
      WAIT_COUNTING: begin
        counting = 1;
        if (done_counting) begin
          next_state = TIMER_DONE;
        end
      end
      TIMER_DONE: begin
        done = 1;
        if (ack) begin
          next_state = IDLE;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define states
  typedef enum reg [1:0] {
    WALK_LEFT,
    WALK_RIGHT,
    FALLING,
    DIGGING
  } state_t;

  state_t current_state, next_state;

  // Output signals
  assign walk_left = (current_state == WALK_LEFT) & ~falling;
  assign walk_right = (current_state == WALK_RIGHT) & ~falling;
  assign aaah = falling;
  assign digging = (current_state == DIGGING) & ground;

  // Falling flag
  reg falling;

  // State transition logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= WALK_LEFT;
      falling <= 0;
    end else begin
      current_state <= next_state;
      if (falling && ground) begin
        falling <= 0;
      end
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    falling = 0;
    case (current_state)
      WALK_LEFT:
        if (ground && dig) begin
          next_state = DIGGING;
        end else if (bump_right) begin
          next_state = WALK_RIGHT;
        end else if (!ground) begin
          next_state = FALLING;
          falling = 1;
        end
      WALK_RIGHT:
        if (ground && dig) begin
          next_state = DIGGING;
        end else if (bump_left) begin
          next_state = WALK_LEFT;
        end else if (!ground) begin
          next_state = FALLING;
          falling = 1;
        end
      FALLING:
        if (ground) begin
          falling = 0;
        end
      DIGGING:
        if (!ground) begin
          next_state = FALLING;
          falling = 1;
        end else if (!dig) begin
          next_state = current_state;
        end
    endcase
  end

endmodule

